/* 歴オタ図鑑 徳島県 100 か所。解説は当サイトの手書き（定説にもとづく）。位置はおおよそ。rel=れきし地図・偉人の墓とのつながり（自動）*/
RG.HK = RG.HK || {};
RG.HK["36"] = [{"id":"36_tokushima_jo","n":"徳島城（蜂須賀家25万石の居城と鷲の門）","yomi":"とくしまじょう","cat":"城","rank":"S","y":1585,"era":["azuchi","edo"],"sh":"国指定史跡","ad":"徳島市徳島町城内","st":"JR徳島駅から歩いて約10分（鷲の門までは約5分）","la":34.0753,"lo":134.5563,"hook":"緑色にかがやく «青石» の石垣。蜂須賀家が約280年守った城は、いまは門ひとつと石垣だけが静かに残る。","lead":"徳島城は、豊臣秀吉から阿波国をもらった蜂須賀家政が、城山という小さな山に築いた城です。江戸時代はずっと蜂須賀家の城でしたが、明治に取りこわされ、建物は残っていません。いまは «徳島中央公園» になっていて、復元された «鷲の門» と、青い石の石垣が見どころです。","story":["1585年、四国を平定した秀吉は、功のあった蜂須賀正勝に阿波を与えようとしました。ところが正勝は «わしは殿のそばにいたい» と辞退し、かわりに息子の家政が阿波の主になったと伝わります。家政はまず一宮城に入り、やがて吉野川の河口近く、海と川に守られた «渭山（いのやま）» に新しい城を築きました。","このあたりはもともと «渭津（いのつ）» と呼ばれていました。家政はここを «徳島» と名づけたといわれます。«徳» のある «島»。川に囲まれた土地にふさわしい、縁起のよい名前でした。これがいまの県名のもとになっています。","城の石垣をよく見てください。緑がかった平たい石がたくさん使われています。これは «緑色片岩»、地元では «阿波の青石» と呼ばれる石です。近くの山で取れる石を割って積んだので、ほかの城にはない独特の色になりました。なぜこんなに薄い板のような形なのでしょう? この石は層になってはがれやすい性質があるからです。","江戸時代、蜂須賀家は淡路も加えて25万石余りの大名になり、徳島は藍（あい）の取り引きでにぎわう城下町に育ちました。しかし1875年（明治8年）、城の建物は «鷲の門» を残して取りこわされます。その鷲の門も、1945年の空襲で焼けてしまいました。","1989年、徳島市ができて100年の記念に、市民の寄付で鷲の門が復元されました。駅前のビルの谷間に建つ白い門は、失われた城の «入口» として、いまも町の人に親しまれています。城山に登ると、本丸跡の広場から、かつて城下を守った川の流れが見わたせます。"],"tl":[["1585年","蜂須賀家政が阿波に入り、渭山で築城を始める"],["1600年","関ヶ原の戦い。息子の至鎮が東軍に加わり、阿波を安堵される"],["1615年","淡路が加わり、25万石余りの大藩に"],["1875年","鷲の門を残して城の建物が取りこわされる"],["1945年","徳島大空襲で鷲の門が焼失"],["1989年","市制100周年を記念し、鷲の門を復元"],["1992年","城跡の中に徳島市立徳島城博物館が開館"],["2006年","«徳島城跡» として国の史跡に指定"]],"who":[["蜂須賀家政","城を築いた阿波の初代の主。のちに «蓬庵（ほうあん）» と名乗る"],["蜂須賀正勝","家政の父。秀吉の古くからの家臣。阿波をもらうのを辞退したと伝わる"],["蜂須賀至鎮","家政の子。関ヶ原で東軍につき、初代藩主となる"],["蜂須賀茂韶","最後の藩主。明治になって城を手放した"]],"deep":["天守は城山のてっぺんの本丸ではなく、一段低い «東二の丸» に建っていたとされます。山頂より低い場所に天守を置く珍しい形で、理由には諸説があります。","石垣は、自然の岩山を生かした古い積み方の部分と、江戸時代にきれいに積み直した部分が混ざっています。場所ごとに石の積み方を見比べると、時代の差がわかります。","«鷲の門» の名前には、藩が幕府に «鷲を飼う小屋を建てる» と届け出て門を建てた、という言い伝えがあります。確かな史料で裏づけられた話ではありません。","城山は標高60mほどの小山で、山の上には縄文時代の貝塚（城山貝塚）も見つかっています。城ができるずっと前から人が暮らした場所でした。","藍は «阿波藍» として全国に売られ、徳島藩の大きな財源になりました。城下町の繁栄は、城よりもむしろ藍商人たちに支えられていたといわれます。","城跡にある徳島城博物館では、蜂須賀家の大名道具や、藩の船 «御召鯨船（おめしくじらぶね）千山丸» を見ることができます。"],"look":["復元された鷲の門（公園の入口）","青石を使った石垣、とくに «舌石（したいし）» と呼ばれる突き出た石","城山の本丸跡と、山の上の貝塚の説明板","徳島城博物館と、となりの表御殿庭園"],"q":["徳島城の石垣に多く使われている、緑色の石の名前は?","«阿波の青石»（緑色片岩）。地元の山で取れ、薄い板のように割れやすい石です。"],"koji":[],"myth":"正勝が阿波を辞退した話、«徳島» の命名、鷲の門の名前の由来は言い伝え。天守の位置の理由は諸説。","img":["徳島中央公園","蜂須賀家政","徳島藩"],"wp":"徳島城","rel":{"ev":[],"grave":[]},"ph":[["c:1/1a/Tokushima_castle_22.JPG",2048,1362,"徳島城"],["c:0/0a/Tokushima_Castle%2C_Tenshu.jpg",5976,3938],["c:c/c4/Tokushima_Castle%2C_Nishi_San-no-maru.jpg",5888,3796],["c:d/d8/Tokushima_Castle%2C_Nishi_Ni-no-maru.jpg",6016,4000],["c:0/0a/Tokushima_Castle%2C_Higashi_Ni-no-maru.jpg",5958,3912],["c:9/99/Tokushima_Central_park.JPG",3648,2736],["c:7/76/Tokushima_castle_museum02s3872.jpg",3872,2592],["c:e/ec/Tokushima_castle10s3872.jpg",3872,2592]]},{"id":"36_shozui_jo","n":"勝瑞城跡（三好氏の本拠・阿波の «都»）","yomi":"しょうずいじょうあと","cat":"城","rank":"S","y":1550,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"板野郡藍住町勝瑞","st":"JR高徳線勝瑞駅から歩いて約15分","la":34.1196,"lo":134.5498,"hook":"天下を動かした三好一族のふるさと。田んぼの下から、戦国大名の豪華な館と庭が眠りからさめた。","lead":"勝瑞城跡は、室町時代に阿波の守護・細川氏の守護所が置かれ、のちにその家臣の三好氏が本拠にした場所です。三好長慶の一族はここから京都へ出て、一時は天下を動かすほどの力をもちました。いまは見性寺というお寺と田畑が広がっていますが、発掘で大きな館や庭のあとが見つかっています。","story":["戦国時代、京都で «天下人» と呼ばれた最初の人物は、織田信長ではなく三好長慶だった、という見方があります。その三好氏の力のみなもとが、ここ阿波の勝瑞でした。吉野川の下流、川と水路に囲まれた平地に、守護の細川氏と三好氏の館が並び、町がひろがっていたのです。","勝瑞は瀬戸内海と京都・堺を結ぶ水運の要でした。船で運ばれた品物や情報が集まり、茶の湯や連歌を楽しむ文化人も出入りしたといわれます。のちの人が «阿波の都» と呼ぶのも大げさではありません。なぜ田んぼの真ん中に都が? 答えは、いまは見えなくなった «川の道» にあります。","長慶の弟・三好実休（義賢）は勝瑞にいて阿波を治め、兄の京都での戦いを支えました。1553年には主君の細川持隆を自害に追いこみ、阿波の実権をにぎります。実休は茶人としても名高く、名物の茶道具を多く持っていたと伝わります。","しかし実休は1562年、和泉の久米田の戦いで戦死。長慶も2年後に亡くなり、三好氏の勢いは弱まっていきます。1582年、土佐の長宗我部元親が攻めこみ、中富川の戦いで十河存保（実休の子）が敗れて、勝瑞は落ちました。","そのあと勝瑞は忘れられ、田畑の下に埋もれました。1990年代から発掘が進み、大きな建物の礎石、池のある庭、石を組んだ枯山水の庭、たくさんの陶磁器やかわらけが見つかりました。地面の下から、にぎやかだった宴の音が聞こえてきそうです。"],"tl":[["14世紀ごろ","阿波守護・細川氏の守護所が勝瑞に置かれたとされる（時期は諸説）"],["1553年","三好実休が主君・細川持隆を自害させ、阿波の実権をにぎる"],["1562年","実休が久米田の戦いで戦死"],["1582年","中富川の戦いで十河存保が長宗我部元親に敗れ、勝瑞が落ちる"],["1994年ごろ","本格的な発掘調査が始まる"],["2001年","«勝瑞城館跡» として国の史跡に指定"]],"who":[["三好長慶","三好氏の最盛期の当主。京都を中心に畿内を支配した"],["三好実休（義賢）","長慶の弟。勝瑞で阿波を治めた。茶人としても有名"],["十河存保","実休の子。長宗我部元親と戦い、勝瑞を失う"],["細川持隆","阿波の守護。実休によって自害に追いこまれた"],["長宗我部元親","土佐の戦国大名。勝瑞を攻め落とし四国の大半を手に入れた"]],"deep":["国の史跡の正式な名前は «勝瑞城館跡»。見性寺の周りの堀と土塁の «城» 部分と、その南にひろがる «館» 部分をあわせた名前です。","見性寺の境内に残る堀と土塁は、長宗我部軍にそなえて戦国時代の終わりに急いで造られた «詰めの城» とする説があります。館とは時期も役割もちがう、という見方です。","館跡からは、池のある庭、枯山水の庭、会所（宴や客をもてなす建物）とみられる礎石建物が見つかりました。武家の館に複数の庭があるのは、京都の将軍の御所にならったものと考えられています。","見性寺は三好氏の菩提寺で、境内には三好氏の墓とされる墓石が並びます。お寺はもともと別の場所にあり、江戸時代にここへ移ったと伝わります。","出土品には、中国や朝鮮の陶磁器、宴で一度だけ使って捨てる素焼きの皿 «かわらけ» が大量にあります。勝瑞の豊かさと、にぎやかな宴会の様子を物語ります。","三好氏は «阿波公方» と呼ばれる足利将軍家の一族を阿波の平島にかくまい、将軍候補として京都の政治に利用しました。のちの第14代将軍・足利義栄はこの一族の出身です。"],"look":["見性寺の境内に残る堀と土塁","三好氏の墓とされる墓所","館跡の庭園の復元・表示（整備された範囲）","近くの «勝瑞城館跡展示室» の出土品"],"q":["勝瑞を本拠にした三好実休の兄で、畿内を支配した人物は?","三好長慶。信長より前の «天下人» と見る研究者もいます。"],"koji":[],"myth":"守護所が置かれた時期、詰めの城の築かれた時期は諸説。«最初の天下人» は評価の一つ。","img":["三好長慶","三好実休","十河存保"],"wp":"勝瑞城","rel":{"ev":[],"grave":[]},"ph":[["c:7/76/Shozuijo09.jpg",1831,1348,"勝瑞城"],["c:a/a4/Shozuijo18.jpg",3072,1728],["c:3/30/%E4%B8%89%E5%A5%BD%E5%AE%9F%E4%BC%91.jpg",1701,3126],["c:7/72/Shozuijo19.jpg",2536,1957],["c:1/1e/Shozuijo16.jpg",2048,1536],["c:d/d4/Shozuijo13.jpg",2048,1536],["c:c/cb/Shozuijo12.jpg",2048,1536],["c:d/da/Shozuijo04.jpg",2048,1536]]},{"id":"36_hachisuka_bosho","n":"徳島藩主蜂須賀家墓所（万年山と興源寺）","yomi":"とくしまはんしゅはちすかけぼしょ","cat":"墓所","rank":"S","y":1620,"era":["edo"],"sh":"国指定史跡","ad":"徳島市下助任町（興源寺）・佐古山町（万年山）","st":"興源寺はJR徳島駅から歩いて約20分、万年山はJR佐古駅から歩いて約20分（山道を登る）","la":34.0785,"lo":134.529,"hook":"お寺には仏式の、山には中国風の «儒式» の墓。同じ大名家なのに、眠り方が二つある。","lead":"徳島藩を治めた蜂須賀家の歴代藩主や家族のお墓です。町中の興源寺と、町の西にある万年山（まんねんざん）の二か所に分かれていて、あわせて国の史跡になっています。江戸時代の大名家のお墓の移り変わりがよくわかる場所です。","story":["大名のお墓といえば、お寺の境内に並ぶ大きな石塔を思い浮かべるかもしれません。蜂須賀家もはじめはそうでした。初代藩主・至鎮が亡くなると、菩提寺の興源寺に葬られ、そのあとの藩主たちも同じ寺に眠りました。","ところが、江戸時代の半ばになると、山の上に新しいお墓がつくられ始めます。それが万年山の墓所です。ここには仏教ではなく、儒教の考え方にもとづく形の墓が多く見られます。«なぜお寺をはなれて、山に?» それは、儒学を重んじる考えが大名家にも広まったことと関係すると考えられています。","万年山は、徳島の町を見下ろす眉山の続きの山です。木々の間の坂道を登ると、石の柵に囲まれた墓が、ひな壇のように並んでいます。静かな森の中で、ここが一国の主たちの眠る場所だと気づくと、思わず背すじがのびます。","興源寺の墓所は、町中にありながら石垣と塀に囲まれ、重々しい空気が漂います。二つの墓所は、ひとつの大名家が約250年のあいだにどんな葬り方をしてきたかを、並べて見せてくれる貴重な場所です。どちらもお参りの場です。静かに見学しましょう。"],"tl":[["1620年","初代藩主・蜂須賀至鎮が亡くなり、興源寺に葬られる"],["1639年","藩祖・蜂須賀家政が亡くなる"],["江戸時代中期","万年山に儒教式の墓がつくられ始める"],["1869年","版籍奉還。藩主の時代が終わる"],["21世紀初め","興源寺と万年山の墓所が国の史跡に指定される"]],"who":[["蜂須賀至鎮","徳島藩の初代藩主。興源寺に眠る"],["蜂須賀家政","阿波の国づくりを始めた藩祖"],["蜂須賀重喜","第10代藩主。藩政改革を進めたが、幕府に隠居を命じられた"],["蜂須賀茂韶","最後の藩主。明治には政府の要職をつとめた"]],"deep":["大名家が儒教式の墓をつくる例は、水戸徳川家や岡山の池田家などにも見られます。蜂須賀家の万年山も、そうした江戸時代の «儒葬» の流れの中で考えられています。","二つの墓所は、仏式の寺院墓所と、山の上の墓所という、性格のちがう墓所がセットで残っている点が評価されました。","興源寺の名は、初代藩主・至鎮の法名 «興源院» にちなむと伝わります。つまり寺そのものが、至鎮をとむらうための寺でした。","万年山の墓所は山の斜面にあり、道は細く、足元が悪いところもあります。雨のあとや夕方は避け、歩きやすい靴で出かけるのが安心です。","第10代の重喜は秋田の佐竹家から養子に入った藩主で、身分にとらわれない人材登用などの改革を行いましたが、反発を受けて幕府から隠居を命じられました。","蜂須賀家は、もとは尾張の蜂須賀村（いまの愛知県あま市）の土豪でした。尾張出身の一族が、遠い阿波の山に眠っていることにも、戦国から江戸への大きな移り変わりが表れています。"],"look":["興源寺の藩主墓所の石塔群と囲いの塀","万年山の山腹に段々に並ぶ儒式の墓","墓の前の石の鳥居や柵など、仏式とのちがい","万年山から見下ろす徳島の町並み"],"q":["蜂須賀家の墓所が二か所に分かれているのはなぜ?","寺の仏式の墓所に加え、江戸時代中ごろから儒教式の墓を山の上の万年山につくるようになったためと考えられています。"],"koji":[],"myth":"万年山の使い始めの時期や、儒式に切り替えた理由には諸説。","img":["蜂須賀至鎮","蜂須賀重喜","徳島藩"],"wp":"徳島藩主蜂須賀家墓所","rel":{"ev":[],"grave":[]},"ph":[["c:f/f0/Kogenji_the_Hachisukas_Graveyard.JPG",2048,1362,"徳島藩主蜂須賀家墓所"],["c:e/eb/Mannenyama_Cemetery_06.JPG",4288,2848],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c7/Hachisuka_Yoshishige.jpg",2661,4803,"蜂須賀至鎮"],["c:a/a2/Hachisuka_Shigeyoshi.jpg",638,1223,"蜂須賀重喜"]]},{"id":"36_kogenji","n":"興源寺（蜂須賀家の菩提寺）","yomi":"こうげんじ","cat":"寺社","rank":"A","y":1620,"era":["edo"],"sh":"国指定史跡（徳島藩主蜂須賀家墓所の一部）","ad":"徳島市下助任町2丁目","st":"JR徳島駅から歩いて約20分","la":34.0829,"lo":134.5431,"hook":"住宅地の中に突然あらわれる大きな山門。その奥で、阿波の殿様たちが代々眠っている。","lead":"興源寺は、徳島藩を治めた蜂須賀家の菩提寺（家のお墓をまもり、供養するお寺）です。臨済宗のお寺で、境内には歴代藩主のお墓があり、国の史跡になっています。徳島の町中で、江戸時代の «殿様の寺» の雰囲気をいまに伝えています。","story":["助任川の近く、静かな住宅地を歩いていると、どっしりとした山門が目に入ります。ここが興源寺。江戸時代、徳島藩の殿様やその家族が亡くなると、この寺で盛大な葬儀が行われ、境内に葬られました。","寺の名前 «興源» は、初代藩主・蜂須賀至鎮の法名 «興源院» から取られたと伝わります。至鎮は関ヶ原の戦いで東軍につき、蜂須賀家が阿波を治め続ける道を開いた人物です。しかし35歳ほどの若さで亡くなりました。父の家政は、息子に先立たれた悲しみの中で、この寺を大切にしたことでしょう。","江戸時代の菩提寺は、ただのお寺ではありません。藩主の命日には家臣たちが集まり、藩の行事の場にもなりました。寺には藩から領地も与えられ、手厚く保護されました。«なぜそこまで?» それは、先祖をまつることが、藩主の家の正しさを示す大事な仕事だったからです。","明治になって藩がなくなると、寺を支えた仕組みも失われました。それでも墓所は守られ、21世紀に入って国の史跡に指定されました。境内の奥の墓所には、苔むした石塔が並び、ときが止まったような静けさが漂います。","境内を歩いたら、ぜひ徳島城の方角をふり返ってみてください。城から北へ少しはなれたこの寺は、城下町の北の守りとしての役割もあったといわれます。大きな寺を城下の外側に置き、いざというときの拠点にする考え方は、ほかの城下町にも見られるものです。"],"tl":[["1620年","初代藩主・蜂須賀至鎮が亡くなり、この寺に葬られる"],["江戸時代","蜂須賀家の菩提寺として藩の保護を受ける"],["1639年","藩祖・蜂須賀家政が亡くなる"],["1871年","廃藩置県。藩の保護がなくなる"],["21世紀初め","墓所が «徳島藩主蜂須賀家墓所» として国の史跡に"]],"who":[["蜂須賀至鎮","徳島藩の初代藩主。法名 «興源院» が寺の名のもとと伝わる"],["蜂須賀家政","至鎮の父。阿波の藩祖"],["蜂須賀家の歴代藩主","多くがこの寺に葬られた"]],"deep":["興源寺は臨済宗妙心寺派の寺です。蜂須賀家の菩提寺として、藩内の寺院の中でも特別な位置にありました。","寺の成り立ちには、至鎮の死後に菩提寺として整えられたという話と、もっと前からあった寺を改めたという話があり、はっきりしない点があります。","境内の藩主墓所は、町中にある大名墓所としては規模が大きく、石塔の形や大きさの変化から、時代ごとの葬り方のちがいが読みとれます。","蜂須賀家の墓所は、この寺と、西の万年山の二か所に分かれます。興源寺は仏式、万年山は儒教式の墓が中心で、二つを見比べるとおもしろい発見があります。","墓所の見学は寺の許可や公開日に左右されることがあります。お寺は信仰の場なので、事前に確認し、静かにお参りしましょう。"],"look":["どっしりとした山門","境内奥の蜂須賀家藩主墓所","石塔の形のちがい（時代による変化）","近くの助任川と、徳島城の方角"],"q":["興源寺の «興源» という名前は、だれの法名から来ていると伝わる?","初代徳島藩主・蜂須賀至鎮の法名 «興源院» です。"],"koji":[],"myth":"寺の創建の経緯は諸説。墓所の公開状況は時期により異なる。","img":["徳島藩主蜂須賀家墓所","蜂須賀至鎮","徳島藩"],"wp":"興源寺 (徳島市)","rel":{"ev":[],"grave":[]},"ph":[["c:f/f1/Tokushima_Kogenji_Gate.JPG",2048,1362,"興源寺 (徳島市)"],["c:f/f0/Kogenji_the_Hachisukas_Graveyard.JPG",2048,1362,"徳島藩主蜂須賀家墓所"],["c:c/c7/Hachisuka_Yoshishige.jpg",2661,4803,"蜂須賀至鎮"]]},{"id":"36_omote_goten","n":"旧徳島城表御殿庭園（上田宗箇の作庭）","yomi":"きゅうとくしまじょうおもてごてんていえん","cat":"大名屋敷","rank":"A","y":1600,"era":["azuchi","edo"],"sh":"国指定名勝","ad":"徳島市徳島町1丁目（徳島中央公園内）","st":"JR徳島駅から歩いて約10分","la":34.0745,"lo":134.5549,"hook":"水のない «海» と水のある池が並ぶ庭。武将で茶人の上田宗箇が、青石で描いた桃山の風景。","lead":"徳島城の表御殿（藩の政治をする御殿）にあった庭です。枯山水（水を使わず石と砂で水を表す庭）と、池のまわりを歩く庭が組み合わされています。武将であり茶人でもあった上田宗箇が作ったと伝わり、国の名勝になっています。","story":["徳島城博物館のとなりに、ひっそりと門があります。中に入ると、目の前に広がるのは大きな石の «海»。白い砂の上に、緑がかった青石がどっしりと置かれ、石の橋がかかっています。水は一滴もないのに、波の音が聞こえてきそうです。","この庭を作ったのは、上田宗箇だと伝わります。宗箇は豊臣秀吉に仕えた武将で、戦場でも勇名をはせましたが、茶の湯を古田織部に学んだ一流の茶人でもありました。関ヶ原の戦いで西軍につき領地を失ったあと、蜂須賀家を頼って阿波に身を寄せ、そのときにこの庭を作ったといわれます。","«なぜ負けた側の武将が、殿様の庭を?» 蜂須賀家と宗箇にはもともと縁があり、宗箇の茶人としての腕を家政が高く買っていたからだと考えられています。宗箇はのちに広島の浅野家に仕え、広島でも庭づくりにかかわりました。","庭の見どころは、長さ10mほどもある一枚の青石でできた石橋です。こんな大きな石を一枚で使うのは、全国でも珍しいことです。庭の池には城山の緑が映り、昔の殿様が御殿から眺めた景色が、いまもほぼそのまま残っています。","石の «海» のほとりに立つと、この庭が «眺めるための庭» であり、同時に «歩いて楽しむ庭» でもあることに気づきます。御殿の縁側から見たときにもっとも美しく見えるように石が置かれ、池のまわりの小道を歩くと、景色が次々と変わっていきます。殿様やお客たちは、この庭で季節の移ろいを楽しんだのでしょう。"],"tl":[["1585年","蜂須賀家政が阿波に入り、徳島城を築き始める"],["1600年ごろ","上田宗箇がこの庭を作ったと伝わる"],["江戸時代","表御殿の庭として藩主が用いる"],["1875年","城の建物が取りこわされ、庭だけが残る"],["1941年","国の名勝に指定"],["1992年","となりに徳島城博物館が開館"]],"who":[["上田宗箇","武将で茶人。この庭の作者と伝わる。上田宗箇流茶道の祖"],["蜂須賀家政","徳島城の主。宗箇を迎えた"],["古田織部","宗箇の茶の湯の師。武将茶人"]],"deep":["庭は «枯山水» と «築山泉水（池）» の二つの部分からなります。同じ敷地に両方がそろう構成は、桃山時代から江戸初期の大名庭園の特色を示しています。","使われている石の多くは、徳島特産の緑色片岩（青石）です。産地の近さを生かし、ほかの地方ではまねできない量の青石が使われました。","一枚石の石橋は長さ約10mといわれ、途中で割れている部分があります。割れた理由については、地震によるものとも伝えられますが、はっきりしません。","宗箇の作とする根拠は伝承によるもので、確かな記録で証明されているわけではありません。ただ、豪快な石組みは桃山時代の作風とよく合うと評価されています。","庭は有料で公開されています（博物館との共通券あり）。開園時間や休みは事前に確かめてください。"],"look":["一枚の青石でできた長い石橋","白砂と青石の枯山水","城山を背にした池のある庭","となりの徳島城博物館の蜂須賀家の展示"],"q":["この庭を作ったと伝わる、武将で茶人の人物は?","上田宗箇。古田織部に茶の湯を学び、広島でも庭づくりにかかわりました。"],"koji":[],"myth":"上田宗箇の作庭は伝承。石橋が割れた理由も確かではない。","img":["上田宗箇","徳島城","枯山水"],"wp":"旧徳島城表御殿庭園","rel":{"ev":[],"grave":[]},"ph":[["c:1/17/Tokushima_Castle_lordly_Front_Palace_Garden01s3200.jpg",3200,2142,"旧徳島城表御殿庭園"],["c:8/88/Tokushima_Castle_lordly_Front_Palace_Garden04s3872.jpg",3872,2592],["c:9/9a/Tokushima_Castle_lordly_Front_Palace_Garden03s3200.jpg",3200,2142],["c:d/d5/Ueda_Mondo.jpg",1368,1872,"上田宗箇"],["c:1/1a/Tokushima_castle_22.JPG",2048,1362,"徳島城"],["c:5/5c/Kare-sansui_zen_garden%2C_Ry%C5%8Dan-ji%2C_Kyoto_20190416_1.jpg",8120,5453,"枯山水"]]},{"id":"36_ryozenji","n":"霊山寺（四国八十八箇所の一番札所）","yomi":"りょうぜんじ","cat":"寺社","rank":"S","y":815,"era":["nara","heian","edo"],"sh":"","ad":"鳴門市大麻町板東","st":"JR高徳線板東駅から歩いて約10分","la":34.1597,"lo":134.5028,"hook":"1400kmの祈りの旅は、この山門から始まる。白衣に菅笠、金剛杖。«お遍路さん» が生まれる場所。","lead":"霊山寺は、四国を一周して88のお寺をめぐる «四国八十八箇所» の一番目のお寺です。多くのお遍路さんがここで白衣や杖をそろえ、旅を始めます。空海（弘法大師）がここで修行したと伝わり、四国遍路のスタート地点として親しまれています。","story":["朝早く、霊山寺の山門の前には、白い着物に菅笠をかぶった人たちが集まってきます。これから歩き始める人、車やバスでめぐる人。本堂の前で、少しぎこちなくお経を読む声が聞こえます。«さあ、ここから始まるんだ»。そんな緊張と期待が、境内にあふれています。","寺の伝えによれば、奈良時代に聖武天皇の願いで行基が開き、平安時代のはじめ、空海がこの地で修行したといいます。そのとき空海は、インドの霊鷲山（りょうじゅせん）でお釈迦さまが教えを説く姿を見たように感じ、この山を «竺和山 霊山寺» と名づけたと伝わります。インドを日本に移した、という意味がこめられています。","«なぜ徳島が一番?» と思う人もいるでしょう。四国遍路には決まった始まりはなく、どこから回ってもよいとされます。ただ、江戸時代に京都や大坂からの参拝者が船で阿波の撫養（むや）あたりに上がることが多く、そこから近いこの寺が一番になったという説があります。","寺は戦国時代の兵火や、明治時代の火事で多くの建物を失い、そのたびに建て直されてきました。本堂の天井には、たくさんの灯籠がつり下げられ、ほの暗い中にゆらめく光が、はるかな旅路を静かに照らしています。","境内の売店では白衣や納経帳（お参りの印をいただく帳面）がそろい、ここで «お遍路さん» の姿になる人が多くいます。ここから88番の大窪寺（香川県）まで、歩けばおよそ1400km、40日ほどの旅になります。"],"tl":[["奈良時代","聖武天皇の願いで行基が開いたと伝わる"],["815年ごろ","空海がこの地で修行し、寺の名をつけたと伝わる"],["戦国時代","兵火で建物を失ったと伝わる"],["1687年","真念『四国遍路道指南』が出版され、遍路が庶民に広まる"],["1891年","火事で本堂などを失う（のちに再建）"],["現在","一番札所として、一年中お遍路さんが訪れる"]],"who":[["空海（弘法大師）","四国遍路の信仰の中心。ここで修行したと伝わる"],["行基","奈良時代の僧。寺を開いたと伝わる"],["聖武天皇","寺の開創を願ったと伝わる天皇"],["真念","江戸時代の僧。遍路の案内書を出し、遍路を広めた"]],"deep":["本尊はお釈迦さま（釈迦如来）。八十八箇所の中でも、本尊が釈迦如来の寺は多くありません。寺の名の «霊鷲山» にちなむ選び方といえます。","四国遍路で徳島県（阿波）の23か寺は «発心の道場» と呼ばれます。ほとけの道を歩もうと心を起こす場所、という意味です。","「空海が開いた札所」という話の多くは寺の伝えで、四国遍路が88か所の形に定まったのは中世から近世にかけてと考えられています。どの時点で «一番» になったかにも諸説があります。","すぐ近くには、第一次世界大戦のときドイツ兵の捕虜を収容した «板東俘虜収容所» の跡があり、日本で初めてベートーヴェンの第九が全曲演奏された地として知られます。","阿波国一宮の大麻比古神社も歩いて行ける距離にあります。寺と神社がならぶこの一帯は、古くから阿波の信仰の中心地でした。"],"look":["本堂の天井に並ぶ無数の灯籠","山門と、池にかかる橋","多宝塔","遍路用品がそろう売店（旅の出発準備）"],"q":["四国遍路で、徳島県の札所は何の道場と呼ばれる?","«発心の道場»。高知は修行、愛媛は菩提、香川は涅槃の道場です。"],"koji":[{"w":"同行二人（どうぎょうににん）","m":"遍路はひとりで歩いても、いつも弘法大師がそばにいて一緒に歩いてくれる、という意味。菅笠に書かれることが多い"}],"myth":"行基の開基、空海の修行と命名は寺の伝え。一番になった理由は諸説。","img":["四国八十八箇所","空海","板東俘虜収容所"],"wp":"霊山寺 (鳴門市)","rel":{"ev":[],"grave":[]},"ph":[["c:0/09/Ryouzenji20210330_1.jpg",1600,964,"霊山寺 (鳴門市)"],["c:f/f5/Ry%C5%8Dzen-ji%2C_Fud%C5%8Dmy%C5%8D%C5%8D-do_001.jpg",3264,2448],["c:d/d8/Ry%C5%8Dzen-ji%2C_N%C5%8Dky%C5%8Dsho_001.jpg",2867,2150],["c:4/44/Ryouzenzi_04.jpg",10439,1600],["c:5/51/Ryouzemji_hondou20250311_1.jpg",2048,1497],["c:7/74/Ryouzenji_20230328_2.jpg",2001,1500],["c:f/f3/Ryouzenji_20230328_1.jpg",1983,1473],["c:d/dd/Ryouzenzi_bodaizyu.jpg",1199,1600]]},{"id":"36_henro_michi","n":"阿波遍路道（焼山寺道など国史跡の古道）","yomi":"あわへんろみち","cat":"街道","rank":"S","y":1687,"era":["heian","edo"],"sh":"国指定史跡","ad":"吉野川市・神山町・勝浦町・阿南市など","st":"焼山寺道はJR徳島線鴨島駅から第11番藤井寺まで歩いて約30分、そこから山道へ。登り口までは車・タクシーも便利","la":34.0455,"lo":134.358,"hook":"山道のわきに、ぽつんと立つ小さな石。そこに刻まれた «指さしの手» が、300年前の遍路を導いた。","lead":"阿波遍路道は、徳島県内の四国遍路の道のうち、昔の姿がよく残る山道が国の史跡になったものです。焼山寺道、鶴林寺道、太龍寺道などがあり、道しるべの石や、お遍路さんの墓などが残っています。いまも歩いて通ることができる、生きた文化財です。","story":["第11番の藤井寺の裏手から、急な山道が始まります。ここから第12番の焼山寺まで、およそ13km。尾根を越え、谷へ下り、また登る。標高差は合わせて1000mをこえるともいわれ、昔から «遍路ころがし»（遍路が転げ落ちるほどきつい道）と恐れられてきました。","道のところどころに、小さな石が立っています。«右 へんろみち» と刻まれた道しるべ、距離を示す «丁石»。中には手の形が彫られ、指で方向を示しているものもあります。«字が読めない人にもわかるように»。江戸時代、遍路が庶民に広まったとき、多くの人の善意で道しるべが立てられました。","大きな役割を果たしたのが、江戸時代の僧・真念です。1687年、四国遍路の案内書『四国遍路道指南（しるべ）』を出版し、自らも道しるべの石を各地に立てたといわれます。«真念石» と呼ばれる道しるべは、いまも四国の道ばたに残っています。","道のわきには、旅の途中で亡くなった遍路の墓もひっそりとあります。故郷を遠くはなれ、病や疲れで倒れた人たちを、地元の人々が葬ってきたのです。道を歩くとき、そうした人たちに静かに手を合わせる遍路の姿も見られます。","なぜこの道が国の史跡に? それは、車の道ができたあとも、昔ながらの山道と石造物がまとまって残り、四国遍路という信仰の旅の姿を伝えているからです。四国八十八箇所を世界遺産に、という運動の中でも、こうした古道の保存は大事な柱になっています。"],"tl":[["平安時代","空海ゆかりの地を修行者がめぐる信仰が生まれる"],["1687年","真念が『四国遍路道指南』を出版"],["江戸時代","道しるべや丁石が多く立てられ、庶民の遍路が盛んに"],["2010年","鶴林寺道・太龍寺道など «阿波遍路道» が国の史跡に指定"],["2010年代","焼山寺道などが追加指定される"]],"who":[["空海（弘法大師）","遍路信仰の中心"],["真念","江戸時代の僧。案内書を出版し道しるべを立てた"],["衛門三郎","伝説上の人物。空海を追って遍路したとされ、最初のお遍路さんともいわれる"]],"deep":["«阿波遍路道» は一本の道ではなく、県内の複数の区間をまとめた名前です。道そのものに加え、道しるべ、丁石、遍路墓などの石造物もふくめて評価されています。","焼山寺道のとちゅうには、衛門三郎の伝説にちなむ «杖杉庵（じょうしんあん）» があります。空海を追い続けた三郎がここで倒れ、空海に会えたという伝説です。","真念の案内書は、寺の順番、道のり、宿の情報などが書かれた、いわば江戸時代のガイドブックでした。これが遍路を身近な旅にしたと考えられています。","丁石の «丁» は長さの単位で、1丁は約109m。お寺までの残りの距離を示すものが多く、疲れた遍路の励みになりました。","焼山寺道は山の中の長い道で、途中に店や自動販売機はほとんどありません。歩くなら朝早く出発し、水と食料、雨具を持ち、日没前に着くよう計画してください。"],"look":["指さしの手が彫られた道しるべ","真念が立てたといわれる «真念石»","道ばたの遍路墓","焼山寺道の杖杉庵"],"q":["江戸時代に四国遍路のガイドブックを出版した僧はだれ?","真念。『四国遍路道指南』（1687年）を出し、道しるべの石も立てました。"],"koji":[],"myth":"衛門三郎の話は伝説。区間ごとの指定の年は資料で確かめてください。","img":["四国八十八箇所","焼山寺","衛門三郎"],"wp":"遍路道","rel":{"ev":[],"grave":[]},"ph":[["c:6/68/Henromichi_14.JPG",3815,2507,"遍路道"],["c:a/a1/Soemimizu_Henromichi_02.JPG",4912,3264],["c:e/e2/Shosanjimichi_06.jpg",3456,4608],["c:8/81/Henromichi_24.JPG",4608,3456],["c:1/1d/Oonetouge20211214_1.jpg",1589,1600],["c:2/24/Ookubojimiti_10tyou_20260808_1.jpg",2400,1028],["c:b/bf/Matuotouge_06.jpg",1600,1199],["c:9/9f/Ohennrosann_01.jpg",1600,1183,"四国八十八箇所"]]},{"id":"36_shosanji","n":"焼山寺（«遍路ころがし» の山寺）","yomi":"しょうさんじ","cat":"寺社","rank":"A","y":800,"era":["heian","edo"],"sh":"","ad":"名西郡神山町下分","st":"公共交通はとても少ないので車が便利。歩き遍路は藤井寺から山道で6〜8時間ほど","la":33.9998,"lo":134.3232,"hook":"炎を吐く大蛇が住んでいた山。その火を空海が封じて、寺の名は «焼山» になった。","lead":"焼山寺は四国八十八箇所の第12番札所で、標高700mほどの山の中にあります。前の札所・藤井寺からの山道がとてもきびしく、«遍路ころがし» と呼ばれてきました。大きな杉の木に囲まれた境内には、空海と大蛇の伝説が残っています。","story":["遍路ころがしの山道を歩き、最後の坂を登り切ると、見上げるような杉の大木が並ぶ参道があらわれます。汗をぬぐいながら山門をくぐると、ひんやりとした空気。«やっと着いた»。多くのお遍路さんが、ここで思わず座りこんでしまいます。","寺の伝えでは、昔この山には火を吐く大蛇がすみ、村人を苦しめていました。修行に来た空海が大蛇と向き合うと、大蛇は山を火の海にしました。空海が真言を唱えて水をまくと火は消え、大蛇は山の岩屋に封じこめられたといいます。«山が焼けた» ことから «焼山寺» と呼ばれるようになった、というのです。","もともとは修験者（山伏）の祖といわれる役行者（えんのぎょうじゃ）が開いた山だとも伝わります。山の奥深くの寺は、山で修行する人々の拠点でした。空海の伝説は、そうした山の信仰と結びついて語られてきたと考えられます。","«なぜ、こんなに不便な山の上にお寺が?» 昔の人にとって、けわしい山は神仏に近い場所でした。苦しい道を登ること自体が修行であり、たどり着いたときの安心が、信仰を深めたのです。","焼山寺道の途中には、最初のお遍路さんといわれる衛門三郎の伝説の場所もあります。欲深い長者だった三郎が、空海の托鉢の鉢を割ってしまい、そのあと子どもを次々に失って悔い、空海を追って四国を回ったという話です。","境内でひと休みしたら、次の第13番大日寺へ向かう下り道が待っています。昔の遍路は、焼山寺で一夜を明かしたり、ふもとの宿に泊まったりして体を休めました。山を下るにつれて、神山の里の棚田や、鮎喰川の清らかな流れが見えてきます。きびしい山を越えたあとの里の景色は、遍路にとって何よりのごほうびだったことでしょう。"],"tl":[["飛鳥〜奈良時代","役行者が山を開いたと伝わる"],["平安時代初め","空海が大蛇を封じ、寺を開いたと伝わる"],["江戸時代","阿波藩の保護を受け、遍路の難所として知られる"],["2010年代","藤井寺からの山道が «阿波遍路道 焼山寺道» として国の史跡に"]],"who":[["空海（弘法大師）","大蛇を封じ、寺を開いたと伝わる"],["役行者（役小角）","修験道の祖。山を開いたと伝わる"],["衛門三郎","伝説のお遍路さん。焼山寺道に伝説の地がある"]],"deep":["本尊は虚空蔵菩薩。山の上の寺に虚空蔵菩薩をまつる例は多く、空海が若いころ修行した «虚空蔵求聞持法» とのつながりがよく語られます。","境内の奥には、大蛇を封じこめたと伝わる岩屋があるといわれます。山道の奥にあるので、行くときは寺の案内に従ってください。","境内と参道の杉の大木は、長い年月、寺とともに守られてきたもので、山寺らしい景観の中心になっています。","藤井寺から焼山寺への道は、途中の «長戸庵»«柳水庵» などで一息つきながら歩くのが昔からの習いです。庵は遍路の休み場でした。","山の上にあるため、冬は雪や路面の凍結があります。車で行く場合も、季節と天気に注意してください。"],"look":["参道の杉の大木","山門と本堂","大蛇を封じたと伝わる岩屋（奥の院方面）","境内から見える四国山地の山なみ"],"q":["焼山寺という名前の由来になった伝説は?","火を吐く大蛇が山を焼いたが、空海がその火を消して大蛇を封じた、という伝説です。"],"koji":[],"myth":"大蛇封じ、役行者の開山、衛門三郎の話はいずれも伝承。","img":["四国八十八箇所","役小角","衛門三郎"],"wp":"焼山寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/Syouzanzi_01a.jpg",1600,1029,"焼山寺"],["c:e/e6/Shosan-ji%2C_Taishi-do_Hall_01.jpg",3264,2448],["c:7/72/Shosan-ji%2C_Auxiliary_J%C5%ABnisha_Shrine_03.jpg",2753,2065],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:9/94/Syouzanji_20260324_a.jpg",3405,1557],["c:1/14/Zyouzanji_20260324_1.jpg",3308,1133],["c:6/65/Syouzanji_20250715_3.jpg",2048,1536],["c:9/9d/Syouzanji_20250715_4.jpg",2048,1535]]},{"id":"36_tairyuji","n":"太龍寺と舎心ヶ嶽（若き空海の修行地）","yomi":"たいりゅうじとしゃしんがたけ","cat":"寺社","rank":"S","y":793,"era":["nara","heian"],"sh":"","ad":"阿南市加茂町龍山","st":"太龍寺ロープウェイ（那賀町側の山麓駅から約10分）が便利。山麓駅まではJR阿南駅などから車・バス","la":33.8826,"lo":134.5232,"hook":"断崖の上で、19歳の青年が100万回の真言を唱えた。のちの弘法大師・空海の、はじまりの山。","lead":"太龍寺は四国八十八箇所の第21番札所で、標高約600mの山の上にあります。空海が若いころ、近くの岩山 «舎心ヶ嶽（しゃしんがたけ）» で修行したことが、空海自身の書いた本に記されています。いまはロープウェイで登ることができ、«西の高野» とも呼ばれます。","story":["奈良時代の終わり、都の大学で学んでいた一人の青年が、学問の道を捨てて山に入りました。のちの空海です。彼はある修行者から «虚空蔵求聞持法（こくうぞうぐもんじほう）» という修行を教わります。真言を100万回唱えれば、見聞きしたことを決して忘れない力が得られる、というものでした。","空海は24歳のときに書いた『三教指帰（さんごうしいき）』の中で、«阿国大瀧嶽（あこくたいりゅうのたけ）に登り、よじのぼって修行した» と記しています。阿国は阿波の国。この «大瀧嶽» が、太龍寺の山だと考えられています。伝説ではなく本人の言葉で修行の地が語られている、とても貴重な場所です。","寺から少し歩いた舎心ヶ嶽には、南の空をじっと見つめて座る空海の像があります。足元は切り立った崖。ここで若い空海は、昼も夜も真言を唱え続けたといいます。«なぜそこまで?» 自分の力で、人びとを救う道を見つけたい。その思いが、彼を崖の上に座らせたのでしょう。","寺は «西の高野» と呼ばれ、高野山にならった堂塔が並びます。1992年には山の下からロープウェイが通じ、谷をわたるゴンドラからは、四国の深い山なみと、遠くの海まで見わたせます。","昔の遍路は、第20番鶴林寺から谷へ下り、那賀川をわたって、また山道を登ってここに来ました。その道は «太龍寺道» として国の史跡になり、いまも歩くことができます。"],"tl":[["793年ごろ","若い空海がこの山で修行したと考えられる（19歳ごろ）"],["797年","空海が『三教指帰』を著し、阿波の大瀧嶽での修行を記す"],["平安時代","寺が開かれたと伝わる（桓武天皇の願いとも）"],["1992年","太龍寺ロープウェイが開業"],["2010年","«阿波遍路道 太龍寺道» が国の史跡に"]],"who":[["空海（弘法大師）","青年時代にこの山で虚空蔵求聞持法を修行した"],["桓武天皇","寺の開創を後押ししたと伝わる"]],"deep":["『三教指帰』の序文には、«阿国大瀧嶽» と «土州室戸崎» で修行したとあります。室戸岬（高知県）の «御厨人窟（みくろど）» とならぶ、空海の修行地として知られます。","舎心ヶ嶽の «舎心» は、心を捨てて（あるいは心をすべてささげて）修行する、という意味で説明されます。","本尊は虚空蔵菩薩。空海が修めた «虚空蔵求聞持法» の本尊と同じで、この寺の由来を象徴しています。","境内の大師堂へ続く廊下の天井には、大きな龍の絵が描かれています。寺の名前の «龍» にちなむもので、参拝者がよく見上げる名所です。","太龍寺ロープウェイの全長は約2.8kmで、開業当時は西日本最長といわれました。途中で谷をわたる区間が長く、晴れた日の景色は格別です。"],"look":["舎心ヶ嶽の岩上に座る空海像（南を向く）","大師堂への廊下の天井の龍の絵","«西の高野» と呼ばれる境内の堂塔","ロープウェイからの山と谷の眺め"],"q":["空海が太龍寺の山での修行を書き残した本の名前は?","『三教指帰（さんごうしいき）』。24歳のころに書いた本で、«阿国大瀧嶽» での修行が記されています。"],"koji":[],"myth":"寺の開創（桓武天皇の勅願など）は寺の伝え。«大瀧嶽» を太龍寺山とするのは有力な説。","img":["空海","三教指帰","四国八十八箇所"],"wp":"太龍寺","rel":{"ev":[],"grave":[]},"ph":[["c:6/6e/Tairyuji_20231014_1a.jpg",1671,862,"太龍寺"],["c:0/06/Henromiti_21b.jpg",4608,3456],["c:d/d4/Tairyu-ji%2C_S%C5%8Drin_Tower_01.jpg",3264,2448],["c:3/32/Tairyu-ji%2C_Rokkaku-do_01.jpg",3264,2448],["c:3/3a/Tairyu-ji%2C_Main_Hall_02.jpg",3264,2448],["c:c/cf/Tairyu-ji%2C_Gumonji-do_01.jpg",3264,2448],["c:7/73/Tairyu-ji%2C_Daishi-do_01.jpg",3264,2448],["c:7/77/Tairyu-ji%2C_Chuk%C5%8D-do.jpg",3264,2448]]},{"id":"36_kakurinji","n":"鶴林寺（«お鶴さん» の山上伽藍）","yomi":"かくりんじ","cat":"寺社","rank":"A","y":800,"era":["heian","edo"],"sh":"","ad":"勝浦郡勝浦町生名","st":"公共交通は少なく車が便利。歩き遍路は第19番立江寺方面から山道を登る","la":33.9044,"lo":134.5218,"hook":"杉のこずえで、つがいの鶴が小さな仏さまを守っていた。その姿から、山の寺は «鶴林寺» になった。","lead":"鶴林寺は四国八十八箇所の第20番札所で、標高500mほどの山の上にあります。地元では «お鶴さん» と親しまれています。本堂の前には鶴の像が立ち、杉の大木に囲まれた境内は、山寺らしい静けさにつつまれています。","story":["寺の伝えによれば、空海がこの山で修行していたとき、二羽の鶴が杉の木のこずえで、小さな金色の地蔵菩薩を翼で守っているのを見つけました。空海は感動し、自分で地蔵菩薩の像を彫り、その小さな仏さまを胎内（像の体の中）に納めて本尊にしたといいます。","山の名前は «霊鷲山（りょうじゅさん）»。お釈迦さまが教えを説いたインドの山の名です。寺の名 «鶴林» も、お釈迦さまが亡くなったとき、周りの沙羅の林が鶴のように白くなったという話からとられたといわれます。二つの名前で、この山を仏の世界に見立てているのです。","«なぜ鶴?» 鶴は昔から、長生きやめでたさのしるしでした。本堂の前には、左右にオスとメスの鶴の像が立ち、お参りする人を迎えます。ここでは、狛犬ならぬ «狛鶴» が主役なのです。","戦国時代、長宗我部元親の軍が阿波に攻め入ったとき、多くの寺が焼かれました。鶴林寺も被害を受けたと伝わりますが、本尊の信仰は守られ、江戸時代には徳島藩主・蜂須賀家の保護を受けて建物がととのえられました。","ふもとから寺までの山道は «鶴林寺道» として国の史跡になっています。急な坂を登った先に広がる杉木立と山門は、昔のお遍路さんが見た景色そのものです。","境内に立って西を見ると、谷をはさんだ向かいの山に、次の第21番太龍寺の山が見えます。«あそこまで歩くのか» と思うと気が遠くなりますが、昔の遍路はその谷を下り、那賀川を渡ってまた登りました。鶴林寺・太龍寺・焼山寺は、阿波の三つの難所として «一に焼山、二にお鶴、三に太龍» と言い習わされてきたといわれます。"],"tl":[["平安時代初め","空海が開いたと伝わる（桓武天皇の願いとも）"],["戦国時代","長宗我部氏の侵攻で被害を受けたと伝わる"],["江戸時代","徳島藩主・蜂須賀家の保護を受ける"],["江戸時代後期","三重塔が建てられる"],["2010年","«阿波遍路道 鶴林寺道» が国の史跡に"]],"who":[["空海（弘法大師）","鶴に守られた地蔵を見つけ、寺を開いたと伝わる"],["蜂須賀家（徳島藩主）","江戸時代に寺を保護した"],["長宗我部元親","戦国時代に阿波へ攻め入った土佐の大名"]],"deep":["本尊は地蔵菩薩で、秘仏（ふだんは見られない仏さま）です。空海が彫った像の胎内に、鶴が守っていた小さな地蔵を納めたと伝わります。","境内の三重塔は江戸時代後期の建物で、山の上の寺に塔が残る例として貴重です。細かな彫刻にも注目してみてください。","寺の名 «鶴林» は、お釈迦さまが亡くなったとき沙羅双樹が白く変わったという «鶴林» の故事による、という説明が一般的です。","鶴林寺と太龍寺は、谷をはさんで向かい合う山にあります。鶴林寺から那賀川へ下り、太龍寺へ登り返す道は、昔から遍路の難所として知られます。","山の上は天気が変わりやすく、霧に包まれることもあります。車で行く場合も、細い山道なので運転に注意してください。"],"look":["本堂前のつがいの鶴の像","江戸時代後期の三重塔","杉の大木に囲まれた参道と山門","国史跡の鶴林寺道（山道）の石段や丁石"],"q":["鶴林寺の伝説で、二羽の鶴が守っていた仏さまは?","小さな金色の地蔵菩薩です。本尊の地蔵菩薩の胎内に納められたと伝わります。"],"koji":[],"myth":"鶴と地蔵の話、空海の開創は寺の伝え。«鶴林» の名の由来にも諸説。","img":["太龍寺","地蔵菩薩"],"wp":"四国八十八箇所","rel":{"ev":[],"grave":[]},"ph":[["c:9/9f/Ohennrosann_01.jpg",1600,1183,"四国八十八箇所"],["c:d/d5/Jikuwasan_Ryozenji_05.JPG",4288,2848],["c:3/30/Iyadaniji_06.JPG",4288,2848],["c:4/4c/Iyadaniji_04.JPG",4288,2848],["c:6/65/Ishiteji_05.JPG",4288,2848],["c:5/53/Idoji_02.JPG",4288,2848],["c:b/b0/Ichinomiyaji_01.JPG",4288,2848],["c:f/fe/Hotsumisakiji_05.JPG",4288,2848]]},{"id":"36_yakuoji","n":"薬王寺（日和佐の厄除け寺）","yomi":"やくおうじ","cat":"寺社","rank":"A","y":815,"era":["nara","heian"],"sh":"","ad":"海部郡美波町奥河内","st":"JR牟岐線日和佐駅から歩いて約10分","la":33.7336,"lo":134.5307,"hook":"石段の一段ごとに一円玉。厄年の人が «厄を落とし» ながら登る、日本有数の厄除け寺。","lead":"薬王寺は四国八十八箇所の第23番札所で、徳島県（阿波）の最後の札所です。厄除けのお寺として全国に知られ、厄年の人が石段に硬貨を置きながら登る風習があります。海に近い日和佐の町を見下ろす高台に建っています。","story":["山門をくぐると、本堂へ向かう石段が見えます。最初の33段は «女厄坂»、続く42段は «男厄坂»。女性の大厄は33歳、男性は42歳です。厄年の人は、一段ごとに一円玉などを置きながら登り、厄を少しずつ落としていくのだといいます。石段のあちこちで、硬貨が朝の光にきらりと光っています。","寺の伝えでは、奈良時代に聖武天皇の願いで行基が開き、平安時代のはじめ、42歳の厄年だった空海がここで厄除けの薬師如来を刻んだといいます。«自分の厄年に、人びとの厄を払う仏さまを» という話は、この寺が厄除けの寺として信仰される理由になりました。","さらに登ると、境内のいちばん上に朱色の «瑜祇塔（ゆぎとう）» がそびえています。昭和の時代に建てられた、あまり見かけない形の塔です。ここからは日和佐の町と、ウミガメがやってくる大浜海岸の方向が見わたせます。","«なぜ徳島の最後の札所が厄除け?» 徳島の23か寺を歩き終え、ここから先は長い海岸線を高知へ向かいます。次の第24番・最御崎寺（室戸岬）までは約75km。昔の遍路にとって、ここは «ひと区切り» と «新しい旅立ち» の場所でした。心身の厄を払って、次の国へ進んだのです。","境内の奥には «肩背負いの大師（かたせおいのたいし）» と呼ばれる像もあり、遍路の荷を背負うように人びとの苦しみを背負ってくださる大師として親しまれています。また、瑜祇塔の地下の «戒壇めぐり»（まっくらな通路を手さぐりで歩き、仏さまと縁を結ぶ）も人気です。暗闇を歩き終えて光の中に出ると、生まれ変わったような気持ちになるといいます。"],"tl":[["726年","行基が開いたと伝わる（聖武天皇の願い）"],["815年","空海が42歳の厄年に薬師如来を刻んだと伝わる"],["戦国時代","兵火で建物を失ったと伝わる"],["江戸時代","阿波最後の札所として遍路でにぎわう"],["1964年","瑜祇塔が建てられる"]],"who":[["空海（弘法大師）","厄除けの薬師如来を刻んだと伝わる"],["行基","寺を開いたと伝わる奈良時代の僧"],["聖武天皇","寺の開創を願ったと伝わる"]],"deep":["厄坂には、女厄坂（33段）、男厄坂（42段）に加え、還暦の厄にちなむ61段の坂もあります。段数そのものが厄年を表しているのが特徴です。","本尊は «厄除薬師如来»。薬師如来は病気を治す仏さまですが、ここでは «厄を除く» 仏さまとして信仰を集めてきました。","瑜祇塔は、密教の経典にもとづく珍しい形の塔で、上の層に五つの小さな屋根（相輪）がのった独特の姿をしています。","空海が42歳のときに四国八十八箇所を開いた、という話が広く語られますが、これは後の時代にまとまった伝説と考えられています。","日和佐は、アカウミガメが産卵に来る大浜海岸で知られます。寺の近くには «日和佐うみがめ博物館カレッタ» もあり、あわせて訪ねる人が多い町です。"],"look":["硬貨が置かれた女厄坂・男厄坂","高台にそびえる朱色の瑜祇塔","瑜祇塔からの日和佐の町の眺め","山門と本堂"],"q":["薬王寺の «男厄坂» は何段?","42段。男性の大厄の年齢と同じです。女厄坂は33段です。"],"koji":[{"w":"厄払い","m":"災いが起こりやすいとされる年（厄年）に、神仏に祈って災いを避けること"}],"myth":"行基の開基、空海が厄年に薬師を刻んだ話は寺の伝え。","img":["日和佐","厄年"],"wp":"四国八十八箇所","rel":{"ev":[],"grave":[]},"ph":[["c:9/9f/Ohennrosann_01.jpg",1600,1183,"四国八十八箇所"],["c:d/d5/Jikuwasan_Ryozenji_05.JPG",4288,2848],["c:3/30/Iyadaniji_06.JPG",4288,2848],["c:4/4c/Iyadaniji_04.JPG",4288,2848],["c:6/65/Ishiteji_05.JPG",4288,2848],["c:5/53/Idoji_02.JPG",4288,2848],["c:b/b0/Ichinomiyaji_01.JPG",4288,2848],["c:f/fe/Hotsumisakiji_05.JPG",4288,2848]]},{"id":"36_byodoji","n":"平等寺（阿南の遍路寺）","yomi":"びょうどうじ","cat":"寺社","rank":"B","y":815,"era":["heian","edo"],"sh":"","ad":"阿南市新野町秋山","st":"JR牟岐線新野駅から歩いて約25分","la":33.8597,"lo":134.5705,"hook":"空海が掘った井戸から、乳のように白い水がわいた。すべての人を «平等» に救う、と名づけられた寺。","lead":"平等寺は四国八十八箇所の第22番札所です。空海が井戸を掘ると白い水がわき出たという伝説があり、山の名も «白水山» といいます。«すべての人を分けへだてなく救う» という願いから «平等寺» と名づけられたと伝わります。","story":["太龍寺の山を下り、田畑の広がる新野の里を歩くと、山すそに平等寺の山門が見えてきます。これまでの山の上の寺とはちがい、どこかのどかな、里のお寺です。","寺の伝えでは、空海がここで修行していたとき、空に五色の雲がかかり、その中に梵字があらわれたといいます。空海が井戸を掘ると、乳のように白い水がわき出しました。空海はその水で身を清めて薬師如来を刻み、«人びとを平等に救いたい» と寺を «平等寺» と名づけたと伝わります。","その井戸は «弘法の霊水» と呼ばれ、いまも境内でくむことができます。病気にきくと信じられ、水をもらって帰るお遍路さんも少なくありません。","本堂の中には、昔、足の不自由な人がお参りし、歩けるようになったので置いていったと伝わる箱車（手押し車）が残されているといわれます。«なぜ車がお寺に?» それは、ここで祈った人びとの願いと感謝のしるしなのです。","平等寺から次の薬王寺までは、国道沿いや峠の道を20km以上歩きます。昔の遍路は、新野の里の遍路宿に泊まり、翌朝早く出発しました。遍路に食べ物や宿を無料で差し出す «お接待» の心は、このあたりでもいまに受けつがれ、道ばたで地元の人から «がんばってね» とみかんを手渡されることもあります。旅人を大切にする土地の人びとの温かさも、平等寺の周りの大切な «文化財» です。"],"tl":[["815年ごろ","空海が寺を開いたと伝わる"],["戦国時代","兵火で建物を失ったと伝わる"],["江戸時代","再興され、遍路の札所としてにぎわう"],["2010年","太龍寺からの «平等寺道» が阿波遍路道として国の史跡に"]],"who":[["空海（弘法大師）","井戸を掘り、薬師如来を刻んだと伝わる"],["お遍路さんたち","霊水や箱車の話を語り伝えてきた"]],"deep":["本尊は薬師如来。病気をなおす仏さまで、霊水の伝説と深く結びついています。","太龍寺から平等寺への道は «平等寺道» として国の史跡 «阿波遍路道» の一部になっています。峠をこえて里へ下る、変化のある道です。","«平等» という寺名は、身分や貧富にかかわらず、すべての人を分けへだてなく救うという仏教の考えを表したものと説明されます。","寺の «白水山» という山号は、空海の井戸から白い水がわいたという伝説によります。","新野は、太龍寺・平等寺・薬王寺を結ぶ遍路の道すじにあり、昔から遍路宿がありました。","第21番太龍寺からは山を下って約11km、次の第23番薬王寺までは約20kmあり、平等寺は阿波の南部を歩く遍路の中継点でした。","遍路の世界では、困っている人を助けたり、遍路に物をあげたりする «お接待» が大切にされてきました。平等寺の霊水を分けあう習わしも、そうした助け合いの心と結びついています。"],"look":["境内でくめる «弘法の霊水»","本堂への石段と本堂","本堂に伝わる箱車（公開状況は寺で確認）","山門と周囲の里の景色"],"q":["平等寺の山号 «白水山» の由来は?","空海が井戸を掘ると乳のように白い水がわいた、という伝説からです。"],"koji":[],"myth":"五色の雲、白い水の井戸、箱車の話は寺の伝え。","img":["四国八十八箇所","薬師如来","太龍寺"],"wp":"平等寺 (阿南市)","rel":{"ev":[],"grave":[]},"ph":[["c:1/1c/Byoudouji_hondou_20240220_1.jpg",1665,824,"平等寺 (阿南市)"],["c:6/6c/Byodo-ji%2C_View_from_the_Main_Hall_01.jpg",3264,2448],["c:9/97/Byodo-ji%2C_Goma-do_01.jpg",3264,2448],["c:5/59/Byodo-ji%2C_Daishi-do_01.jpg",3264,2448],["c:0/00/Shikoku-no-michi_11.jpg",3840,2384],["c:4/43/Henromichi-asebi_to_one-pass.jpg",2379,3840],["c:a/a1/Byodo-ji%2C_Sacred_Water_01.jpg",2851,2138],["c:d/d6/Byoudouji_20240416_1.jpg",2000,1500]]},{"id":"36_onzanji","n":"恩山寺（弘法大師の母の伝説）","yomi":"おんざんじ","cat":"寺社","rank":"A","y":815,"era":["nara","heian"],"sh":"","ad":"小松島市田野町","st":"JR牟岐線南小松島駅から車で約10分。歩きなら約1時間","la":33.9749,"lo":134.5703,"hook":"女人禁制の山に、母を迎えるため空海は祈った。息子を訪ねて四国に来た母は、ここで髪をおろした。","lead":"恩山寺は四国八十八箇所の第18番札所です。空海の母がこの寺を訪ね、ここで出家したという伝説があり、山の名も «母養山（ぼようざん）» といいます。親への感謝、«恩» をテーマにした、あたたかい伝説の残るお寺です。","story":["昔、この寺は女性が入ることを禁じられた «女人禁制» の寺でした。寺の伝えによれば、空海がここで修行していたとき、ふるさとの讃岐から母の玉依御前が、息子に会うためにはるばる訪ねてきました。けれども、女人禁制のため山に入ることができません。","«母に会いたい、母に来てほしい»。空海は山の下の滝にうたれ、7日間祈り続けたといいます。そしてついに女人禁制を解き、母を寺に迎えました。母はこの地で髪をおろして出家し、空海はその恩に感謝して寺の名を «恩山寺»、山の名を «母養山» にしたと伝わります。","境内には «大師御母公剃髪所（おんぼこうていはつじょ）» と呼ばれるお堂があり、母が切った髪が納められていると伝えられます。お堂の前で手を合わせる人の中には、自分の母親や家族を思いながら祈る人も多くいます。","«なぜこの話が、いまも大切にされるの?» 空海のような偉い僧も、母を思うひとりの息子だった。その親しみやすさが、遍路の人たちの心をとらえてきたのでしょう。恩山寺は、親子の絆を思い出させてくれるお寺です。","母と子の物語は、いまも寺を訪れる人びとに語り継がれています。遍路の人たちは、ここで自分の両親の名前を書いた納め札を納めることもあります。«ありがとう» となかなか言えなかった人が、この寺で初めて親への感謝を口にした――そんな話も聞かれる、心をやわらげるお寺です。"],"tl":[["奈良時代","行基が開いたと伝わる（聖武天皇の願い）"],["平安時代初め","空海が修行し、母を迎えたと伝わる"],["戦国時代","兵火にあったと伝わる"],["江戸時代","徳島藩の保護のもと再興される"]],"who":[["空海（弘法大師）","母を迎えるため女人禁制を解いたと伝わる"],["玉依御前","空海の母と伝わる女性。ここで出家したとされる"],["行基","寺を開いたと伝わる"]],"deep":["本尊は薬師如来。最初は «大日山密厳寺» という名だったと伝わり、空海の母の伝説によって寺名が変わったとされます。","空海の母の名を «玉依御前» とするのは伝承による呼び名で、確かな史料で裏づけられているわけではありません。","寺の近くの小松島は、源平の戦いで源義経が屋島へ向かうとき上陸した地として伝えられます。周辺には義経ゆかりの伝説も残っています。","山門を入ると参道の両側に木々が茂り、里の寺でありながら山寺の雰囲気があります。本堂のそばに大師堂、その先に剃髪所が並びます。","女人禁制は、昔の多くの山の寺で行われていたしきたりです。«女人禁制を解いた» という伝説は、四国遍路が女性にも開かれた旅であることの象徴として語られます。","恩山寺から次の第19番立江寺までは約4km。田畑と集落の間をぬう道で、空海の母の伝説を思いながら歩くと、ほどよい距離に感じられます。"],"look":["大師御母公剃髪所","本堂と大師堂","木々に包まれた参道","寺の周辺に残る義経伝説の地（小松島市内）"],"q":["恩山寺の山号 «母養山» は、だれにちなむ?","空海の母です。母がこの寺で出家したという伝説から名づけられたと伝わります。"],"koji":[{"w":"恩返し","m":"受けた恩にむくいること。恩山寺の名前にこめられた心"}],"myth":"空海の母の来訪・剃髪、女人禁制を解いた話、母の名 «玉依御前» はいずれも伝承。","img":["四国八十八箇所","空海","女人禁制"],"wp":"恩山寺","rel":{"ev":[],"grave":[]},"ph":[["c:a/a4/Onzanji_20260425_2.jpg",2400,1313,"恩山寺"],["c:e/e1/Kaneiso_benzaiten_20260425_2.jpg",3293,1873],["c:b/ba/Onzanji_20260516_1.jpg",1728,2897],["c:4/4f/Onzanji_2024_1.jpg",2721,1577],["c:b/b5/Onzanji_20241130_1.jpg",1500,2000],["c:9/9f/Onzanji_20260425_3.jpg",2400,1028],["c:b/be/Onzanji_20260425_4.jpg",2400,944],["c:8/81/Henromiti_19a.jpg",1600,1351]]},{"id":"36_tatsueji","n":"立江寺（阿波の関所寺）","yomi":"たつえじ","cat":"寺社","rank":"A","y":750,"era":["nara","heian","edo"],"sh":"","ad":"小松島市立江町","st":"JR牟岐線立江駅から歩いて約10分","la":33.9628,"lo":134.6122,"hook":"心に罪がある者は、この門から先へ進めない。四国の «関所寺» に伝わる、黒髪の物語。","lead":"立江寺は四国八十八箇所の第19番札所で、«阿波の関所» と呼ばれます。四国には «関所寺» が各県に一つずつあり、悪いことをした人はそこで足止めされる、といわれてきました。お寺には、罪を犯した女性の髪が鐘の緒に巻きついたという伝説が残っています。","story":["四国遍路では、昔から «関所寺» という言い伝えがあります。心に大きな罪をかかえた人は、関所寺でお参りしようとすると、仏さまのとがめを受けて先に進めなくなる、というのです。阿波の関所が、ここ立江寺です。","寺の伝えでは、江戸時代のはじめ、石見の国（いまの島根県）の «お京» という女性が、夫を殺して別の男と逃げ、遍路をしていました。お京が立江寺で鐘を鳴らそうとすると、鐘の緒が彼女の黒髪にからみつき、どうしてもはなれません。お京は罪をざんげし、髪は肉ごとはがれて緒に残ったといいます。","その髪は、いまも寺の «黒髪堂» に納められていると伝わります。お京はその後、寺の近くに庵を結び、罪をつぐなう日々を送ったといわれます。«なぜこんな怖い話が語られたの?» それは、遍路が罪を見つめ、心を洗い直す旅でもあったからでしょう。","本尊は、高さ一寸八分（約6cm）という小さな地蔵菩薩です。奈良時代、光明皇后の安産を願って行基が刻んだと伝わります。のちに空海がこの小さな像を、自分の彫った大きな地蔵菩薩の胎内に納めたといい、安産や子育ての仏さまとして親しまれてきました。","関所寺の話はこわく聞こえますが、本当の意味は «罪を責める» ことではなく、«罪に気づいて、心を改める機会をあたえる» ことだといわれます。お京も、鐘の前で自分の罪と向き合ったからこそ救われた、と語られてきました。立江寺の門前には昔から遍路宿が並び、駅にも近いため、いまも歩き遍路が一息つく町になっています。"],"tl":[["奈良時代","聖武天皇の願いで行基が開いたと伝わる"],["平安時代初め","空海が寺を移し、延命地蔵を刻んだと伝わる"],["江戸時代初め","お京の黒髪の伝説が生まれたとされる"],["江戸時代","徳島藩主・蜂須賀家の保護を受ける"],["1974年","火事で本堂を失う（のちに再建）"]],"who":[["行基","小さな地蔵菩薩を刻んだと伝わる"],["光明皇后","聖武天皇の皇后。安産祈願の伝説に登場"],["空海（弘法大師）","寺を整え、地蔵菩薩を刻んだと伝わる"],["お京","伝説の女性。鐘の緒に髪が巻きついたとされる"]],"deep":["関所寺は四国の各県に一つずつあるとされ、阿波は立江寺です。ほかの県でどの寺を関所寺と数えるかには、いくつかの説があります。","本堂の天井には多くの花や鳥の絵がえがかれていましたが、1974年の火事で本堂が焼けました。再建された本堂にも天井画がえがかれています。","«一寸八分» の地蔵は、ふだんは見ることのできない秘仏です。胎内仏として大きな像に納められている、と伝えられています。","お京の伝説は、罪と救いの物語として語られ、寺の «黒髪堂» はこの話にまつわるお堂です。実在の人物かどうかはわかりません。","本尊は «延命地蔵菩薩»。命をのばし、子どもを守る地蔵として信仰され、安産や子育ての願いをこめてお参りする人が多い寺です。"],"look":["お京の伝説にまつわる黒髪堂","本堂と、再建された天井画","山門と境内の池","駅から歩いて行ける門前の町並み"],"q":["四国遍路で、罪のある人が先に進めなくなるといわれるお寺を何と呼ぶ?","«関所寺»。阿波では立江寺がその一つとされています。"],"koji":[],"myth":"お京の話、一寸八分の地蔵の由来は伝承。関所寺の数え方には諸説。","img":["四国八十八箇所","光明皇后","行基"],"wp":"立江寺","rel":{"ev":[],"grave":[]},"ph":[["c:9/9f/Ohennrosann_01.jpg",1600,1183,"四国八十八箇所"],["c:2/27/Empress_K%C5%8Dmy%C5%8D_by_simomura_kanzan.jpg",597,800,"光明皇后"],["c:8/8d/Gyouki_1.jpg",400,300,"行基"]]},{"id":"36_idoji","n":"井戸寺（空海が一夜で掘った井戸）","yomi":"いどじ","cat":"寺社","rank":"B","y":815,"era":["asuka","heian"],"sh":"","ad":"徳島市国府町井戸","st":"JR徳島線府中駅から歩いて約15分","la":34.0841,"lo":134.4889,"hook":"のぞきこんで自分の顔が映れば無病息災。映らなければ…？ 空海が一夜で掘った «面影の井戸»。","lead":"井戸寺は四国八十八箇所の第17番札所です。水の悪さに困っていた村人のために、空海が錫杖（しゃくじょう、僧のつえ）で一夜にして井戸を掘ったという伝説があり、寺の名前にもなっています。その井戸は «面影の井戸» と呼ばれ、いまも境内に残っています。","story":["昔、このあたりの村は水が濁っていて、人びとはきれいな水に困っていました。そこへ通りかかった空海が、手にした錫杖で地面をつくと、一夜のうちに井戸ができ、澄んだ水があふれ出たといいます。この話から、寺は «井戸寺»、村は «井戸村» と呼ばれるようになったと伝わります。","境内の «日限大師（ひぎりだいし）» のお堂の中に、その井戸があります。井戸をのぞきこみ、水面に自分の顔が映れば病気や災いにあわない。もし映らなければ、3年のうちに災いがある――そんな言い伝えがあります。«映らなかったらどうしよう»。のぞく人の顔には、少しの緊張が浮かびます。","寺はもっと古く、飛鳥時代に天武天皇の願いで建てられたと伝わります。この一帯は阿波の国府（国の役所）が置かれた場所で、奈良時代には国分寺や国分尼寺も近くに建てられました。井戸寺のまわりは、古代の阿波の «都» だったのです。","山門は、徳島藩の家老の屋敷の門を移したといわれる、武家屋敷風の立派な門です。«お寺に武家の門?» 明治以降、使われなくなった屋敷の門が寺に移されることがありました。井戸寺の門も、そうした時代の移り変わりを伝えています。","井戸寺は、阿波の遍路で «徳島市内の札所めぐり» のしめくくりにあたるお寺です。第13番大日寺から第17番井戸寺までは寺と寺の距離が短く、一日で五つの札所を回る遍路も少なくありません。のどかな田園と住宅地の間を歩きながら、古代の国府の地名や小さな祠に出会えるのも、この区間の楽しみです。"],"tl":[["飛鳥時代","天武天皇の願いで寺が建てられたと伝わる"],["815年ごろ","空海が一夜で井戸を掘ったと伝わる"],["1582年","長宗我部氏の兵火で焼けたと伝わる"],["江戸時代","徳島藩主の保護で再興される"],["現在","«面影の井戸» をのぞく参拝者が絶えない"]],"who":[["空海（弘法大師）","錫杖で一夜にして井戸を掘ったと伝わる"],["天武天皇","寺の創建を願ったと伝わる"],["聖徳太子","本尊の七仏薬師如来を作ったと伝わる"]],"deep":["本尊は «七仏薬師如来»。七体の薬師如来をまつる珍しい形で、聖徳太子の作と伝えられますが、ふだんは見られない秘仏です。","井戸寺の周辺は阿波の国府が置かれた場所と考えられ、国府町の地名がそれを示しています。寺の歴史は、古代阿波の中心地の歴史と重なります。","«面影の井戸» の水面をのぞいて吉凶を占う言い伝えは、井戸の水が人の姿を映す «鏡» と考えられたこととつながると説明されます。","長宗我部元親の阿波侵攻で、県内の多くの寺が焼けたと伝わります。ただし、どの寺がいつ焼けたかをすべて確かな史料で確かめられるわけではありません。","井戸寺から次の第18番恩山寺までは約20km。徳島市街を通るため、昔も今も遍路が町の中を歩く区間です。"],"look":["日限大師堂の中の «面影の井戸»","武家屋敷風の山門","本堂（七仏薬師如来をまつる）","周辺の国府町の古代遺跡めぐり"],"q":["井戸寺の «面影の井戸» で、顔が映らなかったらどうなるという言い伝え?","3年のうちに災いがあるといわれます。顔が映れば無病息災とされます。"],"koji":[],"myth":"空海の井戸、天武天皇の勅願、聖徳太子の本尊作は寺の伝え。山門の由来も伝承。","img":["四国八十八箇所","阿波国分寺","天武天皇"],"wp":"井戸寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/78/Idoji20210629_1.jpg",1600,909,"井戸寺"],["c:d/d6/Idoji_05.JPG",4288,2848],["c:d/d5/Idoji_04.JPG",4288,2848],["c:0/0f/Ido-ji%2C_Bell_Tower_01.jpg",3264,2448],["c:5/56/Ido-ji%2C_Auxiliary_Benzaiten_Shrine_01.jpg",3264,2448],["c:d/d3/Ido-ji%2C_K%C5%8Dmy%C5%8D-den_Hall_01.jpg",3159,2369],["c:d/d4/Ido-ji%2C_Taishi-do_Hall_01.jpg",2462,1705],["c:c/c3/Idoji_20230829_1.jpg",1500,2000]]},{"id":"36_kirihataji","n":"切幡寺（機織り娘の伝説）","yomi":"きりはたじ","cat":"寺社","rank":"A","y":815,"era":["heian","edo","meiji"],"sh":"国の重要文化財（大塔）","ad":"阿波市市場町切幡","st":"JR徳島線阿波山川駅などから車で約15分。公共交通は少なく車が便利","la":34.1049,"lo":134.2896,"hook":"«布をください» と頼んだ旅の僧に、娘は織りかけの布を迷わず切って差し出した。333段の石段の上の物語。","lead":"切幡寺は四国八十八箇所の第10番札所です。空海に織りかけの布を切って差し出した娘の伝説があり、それが «切幡» という名前の由来です。333段の石段を登った先には、大阪から移された «大塔» が建ち、国の重要文化財になっています。","story":["寺の伝えによれば、昔、空海がこの山のふもとで修行していたとき、着物がほころびてしまいました。近くで機（はた）を織っていた娘に «布の切れはしを少し分けてもらえないか» と頼むと、娘は織りかけの布を、ためらうことなく機から切って差し出しました。","心を打たれた空海は、娘の願いを聞きました。娘は «亡き父母のために観音さまをまつりたい» と答えたといいます。空海は千手観音の像を刻み、娘を仏の道に入らせました。すると娘はその場で観音菩薩の姿に変わった――と伝わります。«切幡寺» の名は、この «機を切った» 話から来ています。","寺に向かうには、山のふもとから石段を登ります。その数、333段。«さんざん苦労して登る» と冗談まじりにいわれる長い石段です。夏の暑い日も冬の寒い日も、お遍路さんたちは息を切らしながら一段ずつ進みます。","登りきった先の本堂のさらに上に、どっしりとした二重の塔が建っています。これが «大塔»。じつはこの塔、もとは大阪の住吉大社の神宮寺（神社に付属する寺）に江戸時代のはじめに建てられたものでした。明治の神仏分離で寺がなくなるとき、この寺が買い取り、はるばる運んで建て直したのです。","«なぜ大阪の塔が徳島の山に?» 神仏分離で行き場を失った塔を、仏の教えとともに生かしたいという人びとの願いがあったのでしょう。大塔の前からは、吉野川が流れる阿波の平野がはるかに見わたせます。"],"tl":[["815年ごろ","空海が千手観音を刻み、寺を開いたと伝わる"],["1618年","大塔が大阪の住吉大社神宮寺に建てられる"],["明治時代初め","神仏分離で、大塔が切幡寺に移される"],["昭和時代","大塔が国の重要文化財に指定される"],["現在","333段の石段を登る遍路が絶えない"]],"who":[["空海（弘法大師）","千手観音を刻み、寺を開いたと伝わる"],["機織りの娘","布を切って差し出したと伝わる伝説の娘"],["住吉大社神宮寺","大塔がもともと建っていた寺"]],"deep":["大塔は、初重（一階）も二重（二階）も四角形という珍しい形の二重塔で、同じ形式の塔は全国でもほかにほとんど例がないといわれます。","大塔を大阪から運ぶのには長い年月がかかり、移築の完成は明治15年（1882年）ごろとされています。","本尊は千手観音で、«はた切り観音» とも呼ばれます。娘が観音さまに変わったという伝説にちなみ、女性の願いをかなえる観音としても親しまれてきました。","明治初めの神仏分離（神社と寺を分けた政策）で、各地の神社に付属していた寺は壊されたり、建物が売られたりしました。切幡寺の大塔は、その時代の生き残りです。","切幡寺は «女人即身成仏» の寺ともいわれます。女性がそのまま仏になれる、という教えを伝える寺として、多くの女性の信仰を集めてきました。","切幡寺から次の第11番藤井寺へは、吉野川をわたって南岸へ。昔は «潜水橋（せんすいきょう）» と呼ばれる、欄干のない低い橋をわたるのが名物でした。"],"look":["333段の石段","国の重要文化財の «大塔»","大塔の前からの吉野川と阿波の平野の眺め","本堂と、機織り娘の伝説にちなむ像"],"q":["切幡寺の大塔は、もともとどこに建っていた?","大阪の住吉大社の神宮寺です。明治の神仏分離のあと、この寺に移されました。"],"koji":[],"myth":"機織り娘の話は寺の伝え。","img":["四国八十八箇所","住吉大社","神仏分離"],"wp":"切幡寺","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/Kirihataji20210330_2.jpg",1600,1178,"切幡寺"],["c:e/eb/Kirihataji_Hassodaishi.JPG",3872,2592],["c:f/fb/Kirihata-ji%2C_Oku-dono_01.jpg",3264,2448],["c:6/6b/Kirihata-ji%2C_Ky%C5%8Dgi-ba_01.jpg",3264,2448],["c:e/e9/Kirihata-ji%2C_Fud%C5%8D-d%C5%8D_Hall_01.jpg",3264,2448],["c:6/61/Kirihata-ji%2C_Auxiliary_Benzaiten_and_Kokuzo_Bosatsu_01.jpg",3264,2448],["c:f/fa/Kirihata-ji%2C_Bell_Tower_01.jpg",2884,2163],["c:4/42/Kirihata-ji%2C_Main_Gate_01.jpg",2879,2159]]},{"id":"36_gokurakuji","n":"極楽寺（鳴門・長命杉）","yomi":"ごくらくじ","cat":"寺社","rank":"B","y":815,"era":["heian"],"sh":"","ad":"鳴門市大麻町檜","st":"JR高徳線板東駅から歩いて約25分。第1番霊山寺から歩いて約20分","la":34.1573,"lo":134.4893,"hook":"阿弥陀さまの光がまぶしすぎて、魚がとれなくなった。そこで人びとは、寺の前に山を築いた。","lead":"極楽寺は四国八十八箇所の第2番札所です。境内には、空海が植えたと伝わる «長命杉» がそびえ、幹にさわると長生きできるといわれます。安産の祈りでも知られ、朱色の山門と、極楽浄土を思わせる庭が迎えてくれます。","story":["一番札所の霊山寺を出て、田畑の中の道を20分ほど歩くと、朱色の山門が見えてきます。ここが第2番の極楽寺。遍路を始めたばかりの人にとって、«ふたつ目» のお寺は、少しずつ旅に慣れていく場所でもあります。","寺の伝えでは、空海がここで21日間修行し、阿弥陀如来の像を刻みました。ところがその像から放たれる光があまりに強く、遠くの鳴門の海まで届いたため、魚が驚いて逃げ、漁師たちは困ってしまいました。そこで本堂の前に山を築いて光をさえぎったといいます。寺の山号 «日照山（にっしょうざん）» は、この話にちなむとされます。","境内の大きな杉の木は «長命杉» と呼ばれ、空海が植えたと伝わります。樹齢はおよそ1200年といわれ、幹をなでて長生きを願う人が絶えません。«1200年も生きている木に、あやかりたい»。そんな気持ちで、多くの手がこの幹にふれてきました。","極楽寺は «安産大師» としても知られます。昔、藩主の奥方が安産を祈って無事に子を授かった、という言い伝えがあり、いまも安産を願う家族がお参りに訪れます。","山門をくぐると、左右に池と庭が広がり、その奥の石段を上ると本堂です。阿弥陀如来の «極楽浄土» を地上にあらわしたような、明るく晴れやかな境内です。","極楽寺の境内には、遍路の旅の安全を願う小さな石仏や、たくさんの千羽鶴も見られます。はじめて白衣を着たお遍路さんが、少し照れくさそうに本堂でお経を読む姿は、この寺の日常の風景です。ここから第3番金泉寺までは約2.6km。«まだ始まったばかり»。長い旅の最初の一歩を、長命杉がそっと見守っています。"],"tl":[["奈良時代","行基が開いたと伝わる"],["815年ごろ","空海が阿弥陀如来を刻んだと伝わる"],["戦国時代","兵火で焼けたと伝わる"],["江戸時代","現在の場所で再興されたと伝わる"],["現在","長命杉と安産の寺として親しまれる"]],"who":[["空海（弘法大師）","阿弥陀如来を刻み、長命杉を植えたと伝わる"],["行基","寺を開いたと伝わる"]],"deep":["本尊は阿弥陀如来。極楽浄土の仏さまで、寺の名前 «極楽寺» もここからきています。八十八箇所で阿弥陀如来を本尊とする寺は、それほど多くありません。","長命杉のまわりには柵があり、根を守るため近づきすぎないようにしています。囲いの外から、幹の太さと高さをじっくり見てみましょう。","«光が強すぎて漁ができなくなった» という話は、ほかの地方の寺にも似た伝説があり、仏像の霊力の強さを語る型の一つと考えられます。","寺はもともと別の場所にあり、戦国時代の兵火のあと現在地に移ったという話もあります。","霊山寺から極楽寺、金泉寺と続く鳴門・板野の札所は距離が短く、遍路の最初の一日でいくつものお寺をめぐれる区間です。"],"look":["樹齢約1200年と伝わる長命杉","朱色の山門","極楽浄土をイメージした池と庭","本堂への石段"],"q":["極楽寺の山号 «日照山» のもとになった伝説は?","本尊の阿弥陀如来の光が海まで届き、魚が逃げたので、山を築いて光をさえぎった、という話です。"],"koji":[],"myth":"光の伝説、長命杉を空海が植えた話、安産の由来は寺の伝え。","img":["四国八十八箇所","阿弥陀如来","霊山寺 (鳴門市)"],"wp":"極楽寺 (鳴門市)","rel":{"ev":[],"grave":[]},"ph":[["c:2/2e/Gokurakuzi04.jpg",1600,975,"極楽寺 (鳴門市)"],["c:2/22/Gokuraku-ji%2C_Taishi-do_Hall_001.jpg",3264,2448],["c:c/cc/Gokuraku-ji%2C_Bell_Tower_001.jpg",3264,2448],["c:a/a3/Gokuraku-ji%2C_Yakusi-do_Hall_001.jpg",3167,2375],["c:4/4c/Gokuraku-ji%2C_Kannon-do_Hall_001.jpg",3130,2347],["c:f/fc/Gokuraku-ji%2C_Benzaiten_at_Japanese_Garden_001.jpg",2870,2153],["c:0/05/Tyoumei_sugi_20230722_1.jpg",1207,2048],["c:a/aa/Gokurakuji20200330_1.jpg",1450,1600]]},{"id":"36_unpenji","n":"雲辺寺（四国霊場で一番高い札所）","yomi":"うんぺんじ","cat":"寺社","rank":"B","y":796,"era":["heian","kamakura"],"sh":"","ad":"三好市池田町白地","st":"香川県観音寺市側の雲辺寺ロープウェイ（約7分）が便利。徳島側からは車","la":34.0363,"lo":133.7226,"hook":"標高900mをこえる、四国霊場でいちばん空に近い札所。住所は徳島なのに、数えられるのは «讃岐»。","lead":"雲辺寺は四国八十八箇所の第66番札所で、八十八か所の中でもっとも高い場所（標高900m余り）にあります。お寺は徳島県にありますが、遍路では香川県（讃岐）の «涅槃の道場» の最初の札所として数えられます。境内には表情ゆたかな五百羅漢が並んでいます。","story":["阿波・讃岐・伊予の三つの国の境近く、雲辺寺山の山頂近くに、この寺はあります。昔の人は «遍路ころがし» の急な山道を何時間もかけて登りました。雲がすぐそこに流れていく高さで、«雲の辺りの寺»、雲辺寺という名前もうなずけます。","寺の伝えでは、延暦15年（796年）、まだ若かった空海がこの山に登り、堂を建てたのが始まりといいます。その後も空海はたびたび訪れ、寺をととのえたと伝わります。山の上の寺は学問の場としても栄え、«四国高野» とも呼ばれました。","«なぜ徳島の寺が讃岐の札所?» 雲辺寺は国境の山の上にあり、遍路は伊予の札所から香川の方へ進む道すじでここを通ります。お寺そのものは阿波の側にありながら、遍路の順番の上では讃岐の最初の寺となったのです。","境内には、五百羅漢の石像がずらりと並んでいます。笑う顔、怒る顔、考えこむ顔。«この中に、会いたい人に似た顔がある» といわれ、羅漢さんの顔を一つひとつ見て歩く人もいます。","いまは香川県観音寺市の側から長いロープウェイが通じ、山頂駅のまわりは晴れた日には瀬戸内海まで見わたせる展望地になっています。冬には雪が積もり、樹氷が見られることもあります。","山の上の寺は、昔から冬の寒さがきびしく、僧たちは雪の中で修行を続けました。いまも冬の早朝には、境内の木々が白く凍る樹氷が見られることがあり、その美しさを目当てに登る人もいます。ここから次の第67番大興寺へは、讃岐の平野へ一気に下る長い山道です。"],"tl":[["796年","空海が堂を建てたと伝わる"],["平安時代","山上の寺として栄え、«四国高野» と呼ばれたと伝わる"],["鎌倉時代","本尊の千手観音坐像が作られたと考えられる"],["1987年","雲辺寺ロープウェイが開業"],["現在","五百羅漢と山上の眺めで知られる"]],"who":[["空海（弘法大師）","若いころにこの山に堂を建てたと伝わる"],["遍路たち","伊予から讃岐へ向かう道すじで難所を越えた"]],"deep":["本尊は千手観音。鎌倉時代の千手観音坐像は国の重要文化財で、ふだんは見ることのできない秘仏です。","山頂の標高は920m余りで、寺の境内は900m前後にあります。八十八箇所の中でいちばん高い場所にある札所として知られます。","雲辺寺ロープウェイは、全長約2.6km。100人乗りの大きなゴンドラで、山麓から山頂まで約7分で結んでいます。","雲辺寺は四国の «関所寺» の一つに数えられることもあります（関所寺の数え方には諸説あり）。","山上は平地より気温が5度以上低いこともあり、冬は凍結や積雪で車の道が閉ざされる日があります。"],"look":["表情ゆたかな五百羅漢の石像","本堂と大師堂","山頂の展望地からの瀬戸内海・讃岐平野の眺め","ロープウェイから見る山の景色"],"q":["雲辺寺は徳島県にあるのに、遍路では何県の札所として数えられる?","香川県（讃岐）です。讃岐の «涅槃の道場» の最初の札所とされます。"],"koji":[],"myth":"空海の創建は寺の伝え。関所寺の数え方には諸説。","img":["四国八十八箇所","五百羅漢","雲辺寺ロープウェイ"],"wp":"雲辺寺","rel":{"ev":[],"grave":[]},"ph":[["c:4/43/Unpenji20211106_1.jpg",1600,1199,"雲辺寺"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:3/33/Unpenji_3kyoboku01.jpg",1768,1271],["c:2/2b/Unpenzi06.jpg",1600,1199],["c:8/84/Unpenji20211106_4.jpg",1600,1199],["c:8/87/Unpenji20210728_1.jpg",1600,1199],["c:6/6a/Unpenzi%C3%B8a.jpg",1600,1196],["c:9/9f/Ohennrosann_01.jpg",1600,1183,"四国八十八箇所"]]},{"id":"36_awa_kokubunji","n":"阿波国分寺（巨石の庭）","yomi":"あわこくぶんじ","cat":"寺社","rank":"A","y":741,"era":["nara","azuchi","edo"],"sh":"国指定名勝（庭園）","ad":"徳島市国府町矢野","st":"JR徳島線府中駅から歩いて約30分","la":34.0726,"lo":134.4733,"hook":"高さ4mの青石が天を突く。奈良時代の国の寺に、戦国の気迫が残る豪快な石の庭。","lead":"阿波国分寺は、奈良時代に聖武天皇の命令で全国に建てられた «国分寺» のひとつで、いまは四国八十八箇所の第15番札所です。境内の奥には、青石の巨石を立てて組んだ豪快な庭があり、国の名勝になっています。","story":["741年、聖武天皇は «国ごとに寺を建て、国の平和と豊かさを祈れ» と命じました。これが国分寺です。阿波の国分寺も、国府（国の役所）の近くに建てられ、七重の塔がそびえていたと考えられています。境内には、その塔の中心の柱を支えたとみられる大きな礎石が残っています。","平安時代以降、国の力が弱まると、全国の国分寺の多くはさびれていきました。阿波国分寺も戦国時代には兵火にあったと伝わり、江戸時代に蜂須賀家の保護のもと再興されました。八十八箇所では珍しい曹洞宗のお寺です。","本堂の裏手に回ると、息をのむ光景が広がります。高さ4mほどもある青石が天を突くように立ち、そのまわりを巨石が囲む石組み。池を中心に、石がぶつかり合うような力強い構成です。«この石を、どうやって運んで立てたの?» と思わず声が出ます。","庭がいつ、だれによって作られたかは、はっきりとはわかっていません。桃山時代から江戸時代初めの作風と考えられ、戦国の武将たちが好んだ豪快な石組みの特徴をよく示しています。長い間あまり知られていませんでしたが、調査のあと国の名勝に指定されました。","奈良時代の塔の礎石と、桃山の気迫あふれる庭。ひとつのお寺の中で、1000年近く離れた二つの時代の «力» に出会える。それが阿波国分寺のおもしろさです。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["奈良時代","阿波国分寺が建てられ、七重塔がそびえたと考えられる"],["戦国時代","兵火で荒れたと伝わる"],["桃山〜江戸初期","巨石の庭が作られたと考えられる"],["江戸時代","蜂須賀家の保護で再興"],["平成時代","庭園が国の名勝に指定される"]],"who":[["聖武天皇","国分寺建立を命じた天皇"],["行基","寺を開いたと伝わる"],["蜂須賀家（徳島藩主）","江戸時代に寺を再興した"]],"deep":["塔の心礎（しんそ、中心の柱を受ける石）とみられる大石が境内に残り、奈良時代の国分寺の規模をしのばせます。","庭の石はほとんどが阿波の青石（緑色片岩）です。薄い板状の石を縦に立てることで、ほかの庭にはない鋭く力強い姿になっています。","作庭者はわかっていません。作風から蜂須賀家の時代、桃山〜江戸初期の作とする見方がありますが、確かな記録は見つかっていません。","国分寺と対になる国分尼寺の跡は、西の石井町に残っています。国府町・石井町一帯は、古代阿波の政治と信仰の中心地でした。","八十八箇所の多くは真言宗ですが、阿波国分寺は曹洞宗。宗派がちがうのは、再興の歴史と関係すると考えられています。","庭の見学は拝観料が必要で、時間が決まっています。本堂の修理などで見学のしかたが変わることもあるので、事前に確かめましょう。","国分寺の多くは、国府の近くの見晴らしのよい場所に建てられました。阿波国分寺も、吉野川の南の平野を見わたす位置にあり、国の役所と寺が一体となって国を治める仕組みを示しています。"],"look":["高さ約4mの青石が立つ庭園","七重塔の心礎とみられる大石","本堂と大師堂","近くの阿波国分尼寺跡や井戸寺とあわせた古代阿波めぐり"],"q":["国分寺を全国に建てるよう命じた天皇は?","聖武天皇。741年に国分寺建立の詔を出しました。"],"koji":[],"myth":"行基の開基は寺の伝え。庭の作者・作られた時期ははっきりしない。","img":["国分寺","聖武天皇","四国八十八箇所"],"wp":"阿波国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:2/25/Awakokbunji20210330_1.jpg",1600,1199,"阿波国分寺"],["c:4/46/Kokubun-ji%2C_Taishi-do_Hall_01.jpg",3264,2448],["c:6/61/Awakokubunji20210330_4.jpg",1600,1222],["c:a/a2/Awakokubunji_01.jpg",1600,1199],["c:a/a0/Awakokubunji20210330_6.jpg",1600,1199],["c:b/b9/Awakokubunji20210330_5.jpg",1600,1199],["c:b/bd/Awakokubunji20210330_9.jpg",1600,1165],["c:c/c0/Awakokubunji20210330_2.jpg",1600,933]]},{"id":"36_kokubun_niji","n":"阿波国分尼寺跡","yomi":"あわこくぶんにじあと","cat":"遺跡","rank":"B","y":750,"era":["nara"],"sh":"国指定史跡","ad":"名西郡石井町石井","st":"JR徳島線石井駅から歩いて約20分","la":34.0735,"lo":134.4467,"hook":"奈良時代、尼さんたちが国の平和を祈った寺。いまは草地に、金堂の土台の形だけが静かに浮かぶ。","lead":"阿波国分尼寺跡は、奈良時代に国ごとに建てられた «国分尼寺»（尼さんの寺）の阿波の国のあとです。建物は残っていませんが、発掘で金堂などの跡が見つかり、国の史跡になっています。いまは史跡公園として整えられています。","story":["741年、聖武天皇は、国ごとに «国分寺» と «国分尼寺» を建てるよう命じました。国分寺は男の僧の寺、国分尼寺は尼さんの寺です。尼寺の正式な名前は «法華滅罪之寺（ほっけめつざいのてら）»。人びとの罪を消し、国を平和にするよう祈る寺でした。","阿波の国分尼寺は、国分寺から西へ数キロの、いまの石井町に建てられました。この一帯は古代の阿波の中心で、国府や国分寺が近くに集まっていたのです。","時代がたつと、国分尼寺はいつのまにか姿を消し、跡地は畑になりました。«ここに尼寺があった» と伝える地名や言い伝えがわずかに残るだけでした。それが昭和の後半に行われた発掘で、金堂の土台や、まわりを囲む溝などが見つかり、ついにその姿が明らかになりました。","«尼さんたちは、ここでどんな暮らしをしていたの?» 記録はほとんど残っていません。けれど、発掘で見つかった土台の大きさから、しっかりとした建物が建っていたことがわかります。草地に立って、朝夕に響いたお経の声を想像してみてください。","全国の国分尼寺は、国分寺よりもさらに早く衰えたところが多く、場所がわからなくなった例も少なくありません。阿波国分尼寺跡は、その姿を具体的に知ることができる数少ない場所の一つとして大切にされています。","国分寺と国分尼寺は、ふつう少しはなれた場所に建てられました。男の僧と尼さんの寺をはっきり分けるためだと考えられています。阿波でも、国分寺と国分尼寺は同じ平野の中で、たがいに見わたせるほどの距離に置かれていました。二つの寺の跡を歩いて結ぶと、奈良時代の役人や僧たちが行き交った古代の道すじが見えてくるようです。"],"tl":[["741年","聖武天皇が国分寺・国分尼寺の建立を命じる"],["奈良時代","阿波国分尼寺が建てられる"],["平安時代以降","しだいに衰え、姿を消す"],["昭和時代後半","発掘調査で金堂跡などが見つかる"],["昭和時代","国の史跡に指定される"]],"who":[["聖武天皇","国分寺・国分尼寺の建立を命じた"],["光明皇后","聖武天皇の皇后。国分尼寺の建立を後押ししたといわれる"]],"deep":["国分尼寺の正式名 «法華滅罪之寺» は、『法華経』の力で罪を消すことを願った名前です。国分寺の正式名は «金光明四天王護国之寺» といいます。","発掘では、金堂とみられる建物の基壇（土台）や、寺の敷地を区切る溝などが確認されました。建物の配置から、寺の範囲を推定することができます。","国分尼寺の建立には、仏教を深く信仰した光明皇后の考えが大きく関わったといわれます。奈良の法華寺は «総国分尼寺» と呼ばれました。","阿波の国分寺・国分尼寺・国府は、吉野川の南の平野に集まっています。古代の役所と寺の配置を地図の上で見比べると、国の中心がどう作られたかがわかります。","史跡は公園として整えられていますが、目立つ建物はありません。説明板で当時の配置を確かめながら歩くのがおすすめです。"],"look":["金堂跡の基壇（土台の表示）","寺域を示す溝や区画の表示","史跡の説明板","近くの阿波国分寺・井戸寺とあわせた古代の国府めぐり"],"q":["国分尼寺の正式な名前は?","«法華滅罪之寺（ほっけめつざいのてら）»。人びとの罪を消し、国の平和を祈る寺でした。"],"koji":[],"myth":"寺の名前や細かな配置は、発掘の成果から推定されたもの。","img":["国分尼寺","聖武天皇","光明皇后"],"wp":"阿波国分尼寺跡","rel":{"ev":[],"grave":[]},"ph":[["c:9/95/Awakokubunnzi03.jpg",1173,574,"阿波国分尼寺跡"],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分尼寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"],["c:2/27/Empress_K%C5%8Dmy%C5%8D_by_simomura_kanzan.jpg",597,800,"光明皇后"]]},{"id":"36_jorokuji","n":"丈六寺（«阿波の法隆寺»）","yomi":"じょうろくじ","cat":"寺社","rank":"A","y":1500,"era":["asuka","muromachi","azuchi"],"sh":"国の重要文化財（本堂・三門・観音堂）","ad":"徳島市丈六町丈領","st":"JR徳島駅からバスで約30分、バス停から歩いて数分（本数に注意）","la":34.0118,"lo":134.5855,"hook":"古い堂が寄りそう静かな境内は «阿波の法隆寺»。その天井には、戦国の悲劇を伝える «血の跡» が残る。","lead":"丈六寺は徳島市の南にある曹洞宗のお寺です。室町時代の建物が多く残り、本堂・三門・観音堂が国の重要文化財になっています。古い建物が集まる落ち着いたたたずまいから «阿波の法隆寺» と呼ばれています。","story":["勝浦川の近く、田園の中に、大きな三門がそびえています。くぐると、苔むした石畳の先に、本堂や観音堂がしずかに寄りそうように建っています。まるで時間がゆっくり流れているような境内。人びとが «阿波の法隆寺» と呼ぶのもうなずけます。","寺の伝えでは、飛鳥時代の白雉元年（650年）、尼僧の宝蔵尼が草庵を結んだのが始まりといいます。寺の名 «丈六» は、仏像の大きさを表すことば。«一丈六尺（約4.8m）» の仏さまのことで、本尊の聖観音坐像がそれにちなむと伝わります。","室町時代の後半、阿波の守護・細川成之が寺を大きく建て直し、曹洞宗の寺として栄えました。三門や本堂は、その時代から江戸時代初めにかけての建物と考えられ、戦国の世を生きのびてきたのです。","境内の建物の一つには、«血天井» と呼ばれる天井板があります。戦国時代、長宗我部元親の阿波侵攻のころ、阿波の武将・新開道善（しんかいどうぜん）がこの寺で討たれ、そのときの血がしみた床板を、供養のため天井に張ったと伝わります。«なぜ床を天井に?» 足でふまないように、そして亡くなった人を忘れないように、という思いからだといわれます。","血天井の前で手を合わせると、この静かな寺にも、戦乱の時代があったことを思い知らされます。丈六寺は、美しい古建築と、戦国の記憶の両方を伝えるお寺です。","丈六寺の境内は広く、季節ごとに表情を変えます。春は桜、初夏は新緑、秋は紅葉が古い堂を彩り、写真を撮りに訪れる人も多い寺です。徳島の町の中心から少しはなれているため、にぎやかな観光地とはちがう、ゆったりとした時間が流れています。"],"tl":[["650年","尼僧の宝蔵尼が庵を結んだと伝わる"],["室町時代後半","阿波守護・細川成之が寺を再興したと伝わる"],["1582年ごろ","新開道善がこの寺で討たれたと伝わる"],["江戸時代","徳島藩主・蜂須賀家の保護を受ける"],["昭和時代","本堂・三門・観音堂が国の重要文化財に"]],"who":[["宝蔵尼","寺の始まりを開いたと伝わる尼僧"],["細川成之","阿波の守護。寺を再興したと伝わる"],["新開道善","阿波の武将。この寺で討たれたと伝わる"],["長宗我部元親","阿波に攻め入った土佐の大名"]],"deep":["三門は、上の階に仏像をまつる二階建ての門で、室町時代の禅宗様の特色をもつといわれます。四国でも古い三門の一つとされます。","«丈六» は仏像の標準的な大きさの一つで、立った姿で一丈六尺。坐像の場合は、その半分ほどの高さで «丈六» と呼びます。","新開道善の最期については、長宗我部方に誘い出されて討たれたとされますが、細部は史料によって異なり、はっきりしない点があります。","血天井は京都の養源院などにもあり、戦国の悲劇を伝える供養の形として知られています。丈六寺の血天井もその一つです。","«阿波の法隆寺» という呼び名は、法隆寺と同じ時代の建物という意味ではなく、古い建物がまとまって残る様子をたとえたものです。"],"look":["室町時代の三門","本堂と観音堂（国の重要文化財）","新開道善の悲劇を伝える血天井","苔むした石畳と、境内の静かな木立"],"q":["丈六寺の «丈六» とは何を表すことば?","仏像の大きさ «一丈六尺（約4.8m）» のこと。本尊がそれにちなむと伝わります。"],"koji":[],"myth":"650年の創建、宝蔵尼、新開道善の最期と血天井の由来は伝承・諸説。","img":["細川成之","長宗我部元親","血天井"],"wp":"丈六寺","rel":{"ev":[],"grave":[]},"ph":[["c:6/66/Zyourokuzi_01.jpg",1400,1035,"丈六寺"],["c:8/84/Jorokuji_05.JPG",2048,1362],["c:7/78/Jorokuji_02.JPG",2048,1362],["c:9/98/Jorokuji_01.JPG",2048,1362],["c:c/c4/Zyourokuzi_10.jpg",1600,1199],["c:3/3d/Zyourokuzi_08.jpg",1600,1199],["c:0/08/Zyourokuzi_09.jpg",1600,1199],["c:c/c4/Hosokawa_Shigeyuki.jpg",2206,5103,"細川成之"]]},{"id":"36_dogakuji","n":"童学寺（空海が学んだ寺）","yomi":"どうがくじ","cat":"寺社","rank":"A","y":780,"era":["nara","heian"],"sh":"","ad":"名西郡石井町石井","st":"JR徳島線石井駅から車で約10分（歩くと約40分）","la":34.0493,"lo":134.4406,"hook":"«いろはにほへと» はここで生まれた？ 少年時代の空海が学んだと伝わる、山すその学びの寺。","lead":"童学寺は、少年時代の空海がここで学んだという伝説のあるお寺です。«童（子ども）が学んだ寺» という名前もそこからきています。空海が «いろは歌» を作った場所という言い伝えもあり、学業成就を願う人びとが訪れます。","story":["石井町の南、山すそにたたずむ童学寺。寺の伝えによれば、奈良時代に行基が開いた寺で、のちに少年時代の空海がこの寺で学んだといいます。讃岐（香川県）で生まれた空海が、7歳から15歳ごろまでここで学問を修めたという話が伝わっています。","«いろはにほへと ちりぬるを…»。47の仮名を一度ずつ使ったこの歌は、昔の子どもたちが最初に習う歌でした。童学寺には、空海がここで «いろは歌» を作ったという言い伝えがあります。本当のところは? «いろは歌» の作者は、実際にはわかっていません。空海作という話は、のちの時代に広まった伝説と考えられています。","それでも、この寺が «学びの寺» として親しまれてきたことに変わりはありません。境内には、空海が学問のために用いたと伝わる «お大師さんの硯（すずり）の水» のような伝説の井戸があり、受験生や子どもの学業成就を願う家族が手を合わせます。","戦国時代、長宗我部元親の軍の兵火で寺は焼けたと伝わります。それでも仏像は守られ、江戸時代に蜂須賀家の保護で再興されました。平成になってからも火事で本堂を失いましたが、その後再建されました。何度焼けても立ち直る姿は、学び続ける心にも重なります。","«子どもの空海は、どんな気持ちで学んでいたのだろう?» 静かな境内で、そんな想像をしてみるのも楽しいものです。","童学寺のある石井町は、吉野川の南の豊かな平野と、山の緑が出会う町です。寺から少し歩けば、古代の阿波国分尼寺跡もあります。昔、学問を志した子どもたちは、この平野を見下ろしながら、いつか都へ出て学ぶ日を夢見たのかもしれません。童学寺は、そんな «学ぶ子どもたち» みんなの寺として、いまも大切にされています。"],"tl":[["奈良時代","行基が開いたと伝わる"],["780年代","少年時代の空海がここで学んだと伝わる"],["戦国時代","兵火で焼けたと伝わる"],["江戸時代","蜂須賀家の保護で再興"],["平成時代","火事で本堂を失い、のちに再建される"]],"who":[["空海（弘法大師）","少年時代に学んだと伝わる"],["行基","寺を開いたと伝わる"],["蜂須賀家（徳島藩主）","江戸時代に寺を保護した"]],"deep":["童学寺は四国八十八箇所ではなく、«四国別格二十霊場» の第2番札所です。八十八箇所とあわせてめぐる人も多い寺です。","寺には平安時代にさかのぼるとされる古い仏像が伝わり、兵火や火事のたびに人びとが守り抜いてきたといわれます。","«いろは歌» は平安時代中ごろ以降に成立したと考える研究者が多く、空海の時代とは合わないとする見方が有力です。","空海の少年時代の学問については、母方のおじ・阿刀大足（あとのおおたり）に学んだことが、空海自身の書いたものなどから知られています。童学寺での学問は寺の伝えです。","寺の周りは緑が多く、季節の花が美しいことでも知られます。学問の寺らしい落ち着いた雰囲気を楽しめます。"],"look":["本堂と大師堂","学問にまつわる伝説の井戸・水","«いろは歌» にちなむ碑などの展示","山すその静かな境内の緑"],"q":["童学寺に伝わる、空海が作ったといわれる歌は?","«いろは歌»。ただし本当の作者はわかっておらず、空海作は伝説と考えられています。"],"koji":[{"w":"いろは歌","m":"47の仮名を一度ずつ使って作られた歌。«色は匂へど散りぬるを» と続き、ものごとのはかなさを歌う"}],"myth":"空海が学んだ話、いろは歌を作った話は伝説。","img":["いろは歌","空海","四国別格二十霊場"],"wp":"童学寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/77/Dougakuji20210330_1.jpg",1600,1199,"童学寺"],["c:b/ba/Dougakuji_03.jpg",1600,1295],["c:9/9d/Dougakuji_20250422_1.jpg",2048,877],["c:e/e4/Dougakuji_20250422_2.jpg",1944,853],["c:c/cb/Dougakiji_20250422_1.jpg",2048,795],["c:4/42/Dougakuji_04.jpg",1280,959],["c:8/87/Dougakuji20210330_2.jpg",1600,645],["c:3/33/Brockhaus-Efron_Japanese_Characters_2.jpg",780,655,"いろは歌"]]},{"id":"36_hashikuraji","n":"箸蔵寺（金毘羅の奥の院）","yomi":"はしくらじ","cat":"寺社","rank":"A","y":828,"era":["heian","edo","meiji"],"sh":"国の重要文化財（本殿・護摩殿など）","ad":"三好市池田町州津","st":"JR土讃線箸蔵駅から歩いて約15分で箸蔵山ロープウェイ登山口、ロープウェイで約5分","la":34.0405,"lo":133.831,"hook":"こんぴらさんの神さまの «箸» をあずかる寺。寺なのに、本殿には神社のような彫刻がきらめく。","lead":"箸蔵寺は、徳島県の西、箸蔵山の中腹にある真言宗のお寺です。空海が開いたと伝わり、香川県の金刀比羅宮（こんぴらさん）の «奥の院» として信仰されてきました。江戸時代末から明治初めの、極彩色の彫刻で飾られた建物群が、国の重要文化財になっています。","story":["寺の伝えによれば、天長5年（828年）、空海がこの山に登ったとき、金毘羅大権現があらわれ、«この山に私をまつり、人びとを救え» と告げたといいます。空海はお堂を建て、金毘羅大権現をまつりました。","«箸蔵» という不思議な名前には、こんな言い伝えがあります。金毘羅の神さまは、人びとの食事の «箸» を運び、食べ物に困らないよう守ってくださる。その箸をおさめる «蔵» がこの山だ、というのです。そこから «こんぴら奥の院» とも呼ばれ、«こんぴら参りをしたら、箸蔵にもお参りしないと片参り» といわれました。","長い石段や参道を登ると、山の斜面にお堂が次々とあらわれます。本殿は、寺でありながら神社のような造りで、色あざやかな彫刻がすき間なくほどこされています。江戸時代まで日本では神と仏がいっしょにまつられていた、その «神仏習合» の姿をよく伝えています。","明治の神仏分離で、多くの寺と神社は分けられました。香川の金刀比羅宮は神社として歩みましたが、箸蔵寺は寺として金毘羅大権現をまつり続けました。«なぜ寺に権現さま?» それが、この寺ならではの魅力なのです。","いまはふもとからロープウェイで山の中腹まで上がることができます。春の桜、秋の紅葉のころは、山の緑とお堂の彩りがいっそう美しく映えます。"],"tl":[["828年","空海が金毘羅大権現をまつり、寺を開いたと伝わる"],["江戸時代","«こんぴら奥の院» として参拝者を集める"],["江戸時代末〜明治初め","本殿・護摩殿などの現在の建物が建てられる"],["昭和時代","箸蔵山ロープウェイが開業"],["平成時代","本殿・護摩殿など6棟が国の重要文化財に指定"]],"who":[["空海（弘法大師）","寺を開き、金毘羅大権現をまつったと伝わる"],["金毘羅大権現","海の守り神として知られる神。箸蔵寺の中心の信仰"]],"deep":["箸蔵寺は «四国別格二十霊場» の第15番札所です。八十八箇所の札所ではありませんが、山の寺として多くの参拝者を集めています。","本殿・護摩殿・方丈などの建物は、江戸時代末から明治初めに建てられたもので、神社風の本殿と寺の堂がならぶ珍しい構成が評価されています。","«箸蔵» の由来には、金毘羅の神が箸を運ぶという話のほか、山の形や地名に由来するとする説もあり、はっきりしません。","金刀比羅宮（香川県琴平町）との関係は、江戸時代の «こんぴら参り» の広がりとともに強まったと考えられています。","山の上は天気が変わりやすく、ロープウェイの運行時間も決まっています。帰りの時間を確かめてから登りましょう。"],"look":["極彩色の彫刻に飾られた本殿","護摩殿など国の重要文化財の建物群","山の斜面に続く石段と参道","ロープウェイから見る吉野川と池田の町"],"q":["箸蔵寺が «奥の院» とされる、香川県の有名な神社は?","金刀比羅宮（こんぴらさん）です。«こんぴらと箸蔵の両参り» がよいとされました。"],"koji":[{"w":"片参り","m":"対になる二つの寺社のうち、片方だけにお参りすること。ご利益が半分になるといわれた"}],"myth":"空海の開創、«箸蔵» の由来は伝承。","img":["金刀比羅宮","神仏習合","四国別格二十霊場"],"wp":"箸蔵寺","rel":{"ev":[],"grave":[]},"ph":[["c:8/86/Hasikurazi_%C3%B8a.jpg",1600,1038,"箸蔵寺"],["c:b/b1/Hasikuraji_20230413_1.jpg",1536,2048],["c:0/09/Kuratani_003.jpg",1800,1200],["c:c/c3/Kuratani_002.jpg",1800,1200],["c:a/ac/Kuratani_001.jpg",1800,1200],["c:6/6c/Hasikuraji_20191120_05.jpg",1600,1226],["c:b/b6/Hasilurazi_04.jpg",1600,1199],["c:1/1b/Hasikurazi_14.jpg",1600,1199]]},{"id":"36_ogeji","n":"大麻比古神社（阿波一宮）","yomi":"おおあさひこじんじゃ","cat":"寺社","rank":"A","y":900,"era":["kofun","heian","taisho"],"sh":"","ad":"鳴門市大麻町板東字広塚","st":"JR高徳線板東駅から歩いて約25分","la":34.1714,"lo":134.5028,"hook":"麻の種をまき、阿波の国を開いた神。千年の楠の奥には、ドイツ兵捕虜が架けた石の橋が残る。","lead":"大麻比古神社は、阿波の国でもっとも格の高い神社 «阿波国一宮» とされる神社です。地元では «おおあさはん» と親しまれ、初もうでには県内から多くの人が集まります。境内の奥には、第一次世界大戦のときドイツ兵の捕虜が造った石の橋が残っています。","story":["大鳥居をくぐり、長い参道を進むと、ひときわ大きな楠の木が迎えてくれます。樹齢は1000年をこえるともいわれ、太い幹は大人が何人も手をつながないと囲めないほど。見上げると、枝が空を覆うように広がっています。","まつられている大麻比古神（おおあさひこのかみ）は、はるか昔、阿波の国に麻の種をまき、人びとに布の作り方を教えたと伝わる神さまです。古代の阿波は麻や穀物づくりで知られ、朝廷の儀式に使う麻を納めた «忌部（いんべ）氏» という一族が活躍しました。«阿波» という国名も «粟（あわ）» から来たといわれ、実りの国だったのです。","平安時代の『延喜式』では、特に重んじられる «名神大社» に数えられています。阿波の人びとにとって、ここは国の守り神でした。","本殿の裏の方へ歩くと、小川に石の «ドイツ橋» と «めがね橋» がかかっています。第一次世界大戦のあと、近くの板東俘虜収容所にいたドイツ兵たちが造ったものです。«なぜ捕虜が橋を?» 収容所では捕虜たちが地元の人と交流し、音楽や技術を伝えました。この橋は、その友情のしるしとして残されています。","古代の神話の神さまと、100年前の国際交流。二つの時代が、同じ森の中で静かに出会う場所です。"],"tl":[["古代","大麻比古神がまつられたと伝わる"],["927年","『延喜式』神名帳に名神大社として記される（完成年）"],["中世","阿波国一宮とされる"],["1917〜1920年","近くに板東俘虜収容所が置かれる"],["1919年ごろ","ドイツ兵捕虜が境内にドイツ橋などを造る"]],"who":[["大麻比古神","麻を植え阿波の国を開いたと伝わる神"],["猿田彦大神","ともにまつられる道案内の神"],["忌部氏","古代、麻などを朝廷に納めた一族"],["板東俘虜収容所のドイツ兵たち","境内に石橋を造った"]],"deep":["大麻比古神は、天太玉命（あめのふとだまのみこと）と同じ神とする説があります。天太玉命は忌部氏の祖先とされる神です。","«阿波国一宮» の座については、徳島市の一宮神社（上一宮大粟神社）なども一宮とされ、時代によって変わったとする考え方があります。","ドイツ橋は石造りのアーチ橋で、1919年ごろに完成したとされます。捕虜たちが地元の石を使い、自分たちの技術で組み上げたといわれます。","板東俘虜収容所では、1918年にベートーヴェンの交響曲第九番が日本で初めて全曲演奏されました。近くの «鳴門市ドイツ館» で詳しく知ることができます。","境内の大楠は、神社の古さを象徴する木として大切にされています。根元を傷めないよう、柵の外から見学しましょう。","神社の裏山、大麻山の山頂には «奥宮峯神社» があり、登山道で登ることができます。"],"look":["樹齢1000年をこえるともいわれる大楠","ドイツ兵捕虜が造ったドイツ橋・めがね橋","大鳥居と長い参道","近くの鳴門市ドイツ館と霊山寺"],"q":["大麻比古神社の境内にある、第一次世界大戦の捕虜が造った橋は?","«ドイツ橋»（と «めがね橋»）。板東俘虜収容所のドイツ兵が造りました。"],"koji":[],"myth":"大麻比古神の正体、一宮の移り変わりは諸説。","img":["板東俘虜収容所","忌部氏","一宮"],"wp":"大麻比古神社","rel":{"ev":[],"grave":[]},"ph":[["c:1/1f/Oasahiko-jinja%2C_haiden-1.jpg",6010,3990,"大麻比古神社"],["c:5/58/Oasahiko-jinja%2C_torii.jpg",6014,3998],["c:7/78/Oasahiko-jinja%2C_otorii-2.jpg",5990,3960],["c:6/65/Oasahiko-jinja%2C_otabisho.jpg",5990,3960],["c:c/c3/Oasahiko-jinja%2C_okumiya.jpg",6010,3990],["c:a/a9/Oasahiko-jinja%2C_kusu.jpg",6016,4000],["c:f/f3/Oasahiko-jinja%2C_honden-2.jpg",6016,4000],["c:9/90/Oasahiko-jinja%2C_haiden-3.jpg",6016,4000]]},{"id":"36_yakurahime","n":"天石門別八倉比売神社（«卑弥呼の墓» 説の社）","yomi":"あめのいわとわけやくらひめじんじゃ","cat":"伝承","rank":"A","y":900,"era":["kofun","heian","myth"],"sh":"","ad":"徳島市国府町西矢野","st":"JR徳島線府中駅から車で約10分（歩くと約40分）。山道を少し登る","la":34.059,"lo":134.4618,"hook":"山の上の奥の院に、五角形の石積みの祭壇。«ここが卑弥呼の墓だ» ――そんな大胆な説が語られてきた神社。","lead":"天石門別八倉比売神社は、徳島市の気延山（きのべやま）のふもとにある古い神社で、平安時代の『延喜式』にも名前が出てきます。まつられているのは太陽の女神・天照大神とされます。奥の院の不思議な石積みの祭壇から、«卑弥呼の墓» ではないかという説が地元で語られ、話題になってきました。","story":["石段を登り、杉木立に囲まれた社殿を過ぎて、さらに山道を上ると、奥の院に着きます。そこにあるのは、石を積み上げた五角形の祭壇。上には小さな祠がまつられています。神社の人たちが大切に守ってきた、神秘的な場所です。","この神社の祭神は «大日孁女尊（おおひるめのみこと）»、つまり天照大神とされます。神社に伝わる由来書には、天照大神がこの地で葬られたかのように読める記述があるといわれ、一部の人びとの興味をひきつけてきました。","«天照大神は卑弥呼のことではないか» «だとすれば、卑弥呼の墓は阿波にある»。昭和の後半、郷土史家や研究者の一部から、そんな説がとなえられました。«邪馬台国は阿波にあった» という説とも結びつき、本やテレビで紹介されて、全国から見学者が訪れるようになりました。","けれど、ここで大事なことがあります。«卑弥呼の墓» 説は、歴史学や考古学の学界では認められていません。祭壇が卑弥呼の時代（3世紀）のものだと示す発掘の証拠もありません。«ロマンのある説» として楽しみつつ、確かな事実とは分けて考えることが大切です。","それでも、気延山のまわりには多くの古墳があり、古代の阿波に力のある人びとがいたことは確かです。『延喜式』に名前が残る古い神社であることも事実。«なぜ、こんな伝説が生まれたのか?» を考えることが、この神社を訪れるいちばんの楽しみかもしれません。"],"tl":[["古墳時代","気延山周辺に古墳が多く造られる"],["927年","『延喜式』神名帳に名神大社として記される（完成年）"],["江戸時代","阿波の古社として藩の崇敬を受けたと伝わる"],["昭和時代後半","«卑弥呼の墓» 説・«邪馬台国阿波説» が広まる"],["現在","古社として、また伝説の地として参拝者が訪れる"]],"who":[["大日孁女尊（天照大神）","神社の祭神とされる太陽の女神"],["卑弥呼","3世紀の邪馬台国の女王。墓とする説があるが学術的には認められていない"],["郷土史家たち","«邪馬台国阿波説» などをとなえた"]],"deep":["神社の名前は『延喜式』神名帳にある «天石門別八倉比売神社» にあたるとされますが、同じ名前にあたる神社はどれかについて、ほかの候補を挙げる説もあります。","奥の院の五角形の祭壇は石を積んだもので、いつ作られたかははっきりしていません。古墳の一部とみる説、神をまつる磐座（いわくら）とみる説などがあります。","«邪馬台国阿波説» は、邪馬台国の場所をめぐる数ある説の一つです。学界では九州説と畿内説が中心で、阿波説は少数説にとどまります。","気延山の周辺には «気延山古墳群» と呼ばれる古墳が多く、古墳時代の阿波の中心地の一つだったと考えられています。","«八倉比売» は、倉の神、つまり穀物をたくわえる神とする説明もあり、豊かな実りの国・阿波とのつながりが語られます。"],"look":["奥の院の五角形の石積み祭壇","杉木立の中の社殿と石段","気延山周辺の古墳（散策路）","近くの阿波国分寺・国分尼寺跡"],"q":["八倉比売神社の奥の院の祭壇が «卑弥呼の墓» だという説は、学界で認められている?","いいえ。郷土史家などがとなえた説で、学術的には認められていません。"],"koji":[],"myth":"«卑弥呼の墓»«邪馬台国阿波説» は学術的に認められていない少数説。祭壇の年代も不明。式内社の比定にも諸説。","img":["卑弥呼","邪馬台国","延喜式神名帳"],"wp":"天石門別八倉比売神社","rel":{"ev":[],"grave":[]},"ph":[["c:5/50/Yakurahimejinja_09.JPG",4288,2848,"天石門別八倉比売神社"],["c:0/05/Yakurahime_01.jpg",1600,1199],["c:d/d0/Ooizumizinzya_01.jpg",1600,1199],["c:c/c8/Engishiki_Jingi_cropped_Engishiki_Vol_2_Flame_37.jpg",2523,3524,"延喜式神名帳"]]},{"id":"36_kamiichinomiya","n":"上一宮大粟神社（阿波の国を開いた女神）","yomi":"かみいちのみやおおあわじんじゃ","cat":"寺社","rank":"A","y":800,"era":["nara","heian","muromachi"],"sh":"","ad":"名西郡神山町神領字西上角","st":"JR徳島駅から徳島バス神山方面で約1時間、神領付近で下車し歩いて山道を上る。車が便利","la":33.966,"lo":134.339,"hook":"«阿波» の名は «粟» から。その粟を伝えた女神が、馬に乗ってたどり着いたと伝わる山の神社。","lead":"神山町の山の中腹にある神社で、食べ物の女神 «大宜都比売命（おおげつひめのみこと）» をまつっています。阿波の国に粟などの作物を広めた神さまとされ、«阿波の国のいちばん大事な神社（一宮）» の一つといわれてきました。","story":["«古事記» には、四国を «ひとつの体に四つの顔がある島» として描く場面があります。その顔の一つ、粟の国（阿波）の名前が «大宜都比売»。つまり阿波の国そのものが、食べ物の女神だと書かれているのです。«なぜ国の名前が食べ物の神さまなの?» ――それだけ、この土地の人びとにとって実りが大切だったのでしょう。","神社の言い伝えでは、女神は伊勢の方から馬に乗って阿波に入り、神山の山あいに落ち着いて、人びとに粟の育て方を教えたといいます。粟がよく実る国だから «粟の国»、やがて «阿波» の字があてられた、という話は地名の由来としてよく語られています。","«古事記» にはもう一つ、少しこわい話があります。スサノオが大宜都比売にごちそうをねだると、女神は鼻や口からおいしいものを出して料理しました。«けがれたものを出すとは!» と怒ったスサノオは女神を斬ってしまいます。すると体から、蚕、稲、粟、小豆、麦、大豆が生まれた――命が失われたところから、作物が生まれるという物語です。","中世になると、山の上の本社にお参りするのは大変だということで、ふもとの平地にも «一宮» がまつられるようになったと伝わります。そこで山のほうが «上一宮（かみいちのみや）»、ふもとが今の徳島市の一宮神社、と呼び分けられるようになりました。","今の神山町は、山の自然と新しい働き方の町として知られています。けれど杉木立の石段をのぼると、何百年も «実りの女神» にお祈りしてきた村の時間が、静かに流れているのを感じられます。"],"tl":[["奈良時代（712年）","«古事記» が完成。阿波の国の名を «大宜都比売» と記す"],["平安時代","阿波の古い神社として信仰を集める"],["中世（南北朝のころと伝わる）","ふもとに一宮が移され、山の社が «上一宮» と呼ばれるように"],["江戸時代","徳島藩のもとで、神山の村々の信仰の中心となる"],["現在","上一宮大粟神社として、阿波開拓の女神をまつる"]],"who":[["大宜都比売命","まつられている女神。阿波に粟を広めたとされる"],["スサノオ（須佐之男命）","«古事記» で大宜都比売を斬り、体から作物が生まれる"],["一宮氏（小笠原氏）","中世の阿波で一宮の神職と城主を兼ねた一族"]],"deep":["«古事記» の «国生み» で、伊予之二名島（四国）の四つの顔は «愛比売（伊予）»«飯依比古（讃岐）»«大宜都比売（阿波）»«建依別（土佐）»。阿波だけが食べ物の女神の名です。","«阿波» の国名は、奈良時代に «粟» から好い字の «阿波» に改めたとされます。地名に良い二字を使うようにという奈良時代の命令との関係も指摘されます。","阿波国一宮は、上一宮大粟神社・一宮神社・大麻比古神社など複数の神社がそれぞれ名乗る、いわゆる «論社» の状態です。どこが本来の一宮かは諸説あります。","大宜都比売の体から作物が生まれる話は、«日本書紀» では月読命と保食神の話として出てきます。東南アジアなどにも似た «死体から作物» の神話があり、比較神話学でよく取り上げられます。","神山の «神領（じんりょう）» という地名は、神社の領地だったことに由来するといわれ、社と村の結びつきの深さを伝えています。","女神が馬に乗って来た話にちなみ、境内や周辺には馬にまつわる伝承が残るといわれます。"],"look":["杉木立の中の長い石段と社殿","境内から見下ろす神山の谷と鮎喰川（あくいがわ）の流れ","ふもとの «神領» の地名と棚田の風景","徳島市の一宮神社とあわせてめぐると «上» と «下» の意味がわかる"],"q":["«古事記» で、四国の中で «食べ物の女神» の名を持つ国はどこ?","阿波（粟の国）。名前は «大宜都比売»。粟がよく実る国だったことを物語ります。"],"koji":[],"myth":"女神が伊勢から馬で来た話、一宮が山からふもとへ移った時期・理由は伝承。一宮の本来の場所は諸説。","img":["大宜都比売","神山町","阿波国"],"wp":"上一宮大粟神社","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ooawa_shrine_20250918_4.jpg",2400,1679,"上一宮大粟神社"],["c:b/bb/Ooawa_shirine_20250918_3.jpg",2400,1799],["c:1/19/Ooawa_shrine_20250918_1.jpg",2400,1784],["c:d/d9/Ooawa_shirine_20250918_2.jpg",2400,1697],["c:1/11/Zinguuji_20260324_1.jpg",2400,1028],["c:d/d9/Singuuji_20260324_3.jpg",2400,1028],["c:a/ab/Singuuji_20260324_2.jpg",2400,1018],["c:e/e6/Ooawa_shrine_20250918_6.jpg",1400,1049]]},{"id":"36_ichinomiya_jinja","n":"一宮神社（徳島市一宮町）","yomi":"いちのみやじんじゃ","cat":"寺社","rank":"B","y":1338,"era":["muromachi","edo","meiji"],"sh":"","ad":"徳島市一宮町西丁","st":"JR徳島駅から徳島市営バス（一宮・神山方面）で約30分、«一宮札所前» 下車すぐ","la":34.0335,"lo":134.4585,"hook":"お遍路の札所と «神さま» が、明治までひとつだった場所。道をはさんだお寺と神社に、その名残がある。","lead":"鮎喰川（あくいがわ）ぞいにある、阿波の «一宮» を名乗る神社です。神山町の上一宮大粟神社から、ふもとにまつりを移したと伝わります。江戸時代までは四国八十八か所の «13番札所» もここにありました。","story":["一宮神社の前の道を渡ると、13番札所の大日寺があります。お遍路さんは今、大日寺でお参りをします。けれど江戸時代までは、札所はお寺ではなく «一宮» の神社そのものだったと伝わります。«え、神社が札所だったの?» ――昔の日本では、神さまと仏さまは一緒にまつられるのがふつうでした。","一宮の神さまの本当の姿は、十一面観音だと考えられていました。これを «本地仏（ほんじぶつ）» といいます。お遍路さんは神社に来て、観音さまを思いながら手を合わせていたのです。","ところが明治のはじめ、政府は «神と仏を分けなさい» と命じました（神仏分離）。一宮の十一面観音は向かいの大日寺に移され、札所もお寺のほうになりました。道一本をはさんで神社とお寺が向かい合う景色は、この大きな変化の記念碑のようなものです。","神社の裏の山には、中世に一宮氏が築いた一宮城があります。一宮氏は神社の神職と城主を兼ねた一族でした。神社を守ることが、そのまま土地を治めることでもあった時代です。","山奥の上一宮にお参りするのは大変――そこで人の集まる平地に «一宮» が置かれた、と伝わります。今でも初もうでや秋祭りには地元の人が集まり、阿波の «いちばんの神さま» の伝統を守っています。"],"tl":[["中世（南北朝のころと伝わる）","上一宮からふもとに一宮がまつられるようになる"],["戦国時代","裏山の一宮城をめぐり、長宗我部・羽柴の攻防"],["江戸時代","四国遍路の13番札所として多くのお遍路さんが訪れる"],["江戸時代","徳島藩主・蜂須賀家の保護を受け社殿が整えられる"],["明治時代はじめ","神仏分離。本地仏の十一面観音が大日寺に移り、札所も寺に"],["現在","向かいの大日寺とともに、一宮の町の中心として親しまれる"]],"who":[["大宜都比売命","まつられている食べ物の女神"],["一宮氏","神職と一宮城主を兼ねた中世の一族"],["蜂須賀家","江戸時代の徳島藩主。社殿を保護した"],["お遍路さん","明治まで神社そのものを13番札所として参拝した"]],"deep":["神仏習合の時代、四国遍路の札所には神社（またはその別当寺）が少なくありませんでした。明治の神仏分離で本尊が近くの寺に移された例は、一宮のほか各地にあります。","大日寺は札所番号の «13番» として知られますが、寺の本尊は大日如来、札所の本尊は十一面観音という、二つの顔を持っています。これも一宮から移った歴史の名残です。","本殿は江戸時代初めの建物と伝わり、徳島県の文化財に指定されています。蜂須賀家が建て直したとされます。","«一宮» を名乗る神社が阿波に複数あるのは、一宮の制度が中世の慣習にもとづくため。国の法律で決まったものではなく、時代によって呼び名がゆれました。","一宮神社・一宮城・大日寺が狭い範囲にまとまっていることから、ここは中世の一宮氏の «政治・宗教の中心» だったと考えられています。"],"look":["江戸時代の本殿（県指定文化財）","道路をはさんで向かい合う大日寺の山門","裏山の一宮城跡への登り口","鮎喰川の土手からの眺め"],"q":["一宮神社にあった本地仏の十一面観音は、明治のはじめどこに移された?","向かいの大日寺。神仏分離で、四国遍路13番札所の本尊として今もまつられています。"],"koji":[{"w":"神仏習合","m":"日本の神と仏を結びつけて一緒に信仰すること。明治のはじめまで長く続いた"}],"myth":"上一宮から一宮が移った年代・経緯は伝承。本殿の建築年は諸説。","img":["大日寺 (徳島市)","一宮城 (阿波国)","神仏分離"],"wp":"一宮神社 (徳島市)","rel":{"ev":[],"grave":[]},"ph":[["c:e/e2/Ichinomiya_Shrine%2C_Tokushima_03.jpg",4288,2848,"一宮神社 (徳島市)"],["c:d/dd/Ichinomiya_Shrine_22_July_2023_2.jpg",2048,1536],["c:1/1a/Ichinomiya_Shrine_10_September_2024_1.jpg",1910,1432],["c:6/61/Ichinomiya_Shrine%2C_Tokushima_10.jpg",1851,1373],["c:3/3b/Ichinomiya_Shrine_31_August_2021_2.jpg",1600,1199],["c:a/a2/Ichinomiya_Shrine_31_August_2021_3.jpg",1600,1199],["c:3/34/Ichinomiya_Shrine_31_August_2021_1.jpg",1600,1199],["c:6/6d/Dainitiji20210330_1.jpg",1600,1174,"大日寺 (徳島市)"]]},{"id":"36_inbe_jinja","n":"忌部神社（阿波忌部の祖神）","yomi":"いんべじんじゃ","cat":"寺社","rank":"A","y":807,"era":["nara","heian","meiji"],"sh":"","ad":"徳島市二軒屋町2丁目","st":"JR牟岐線 二軒屋駅から歩いて約10分","la":34.0625,"lo":134.55,"hook":"天皇が代わるときの儀式に、阿波の麻を届けた一族。その祖先の神さまは、明治に «どこにまつるか» で大論争になった。","lead":"眉山のふもとにある神社で、阿波忌部（あわいんべ）という一族の祖先の神 «天日鷲命（あめのひわしのみこと）» をまつっています。忌部は朝廷の祭りの道具を作った一族で、阿波では麻や穀物を育てたと伝わります。","story":["平安時代のはじめ、斎部広成（いんべのひろなり）という役人が «古語拾遺（こごしゅうい）» という本を天皇に差し出しました。«私たち忌部は、昔から朝廷の祭りを支えてきたのに、今は中臣氏ばかりが重んじられている!» ――そんな思いのこもった本です。","その中に、阿波忌部のことが書かれています。天日鷲命の子孫が阿波に住み、穀物や麻（あさ）を育てた。さらに天富命（あめのとみのみこと）が阿波の忌部を連れて、よい土地を求めて東へ向かい、房総半島に麻を植えた。だからその地を «安房（あわ）» と呼ぶのだ、と。千葉の «安房» と徳島の «阿波»、同じ読みなのはこのためだ、というのです。","阿波の国には «麻植（おえ）郡» という郡がありました。まさに «麻を植える» 土地。平安時代の «延喜式» には、麻植郡に «忌部神社» があり、特に格の高い «名神大社» とされたことが記されています。","ところが時代がたつうちに、本来の忌部神社がどこにあったのか、わからなくなってしまいました。明治になって神社の格付けが決められるとき、«うちこそ本物だ» という名乗りが複数の土地から上がり、激しい争いになりました。","最終的に、どこか一つを選ぶのではなく、県の中心・徳島の眉山のふもとに新しく社殿を建ててまつる、という形で決着しました。今の二軒屋町の忌部神社は、こうして生まれた «みんなの忌部神社» なのです。"],"tl":[["807年","斎部広成が «古語拾遺» を献上。阿波忌部の由来を記す"],["927年","«延喜式» 完成。麻植郡の忌部神社を名神大社と記す"],["中世〜江戸時代","本来の社地がわからなくなり、各地に論社が生まれる"],["明治時代","社地をめぐる論争が起きる"],["明治時代半ば","徳島市の眉山のふもとに社殿を建てて鎮座"],["現在","阿波忌部の祖神をまつる神社として、麁服（あらたえ）の歴史を伝える"]],"who":[["天日鷲命","まつられている阿波忌部の祖神"],["斎部広成","«古語拾遺» の著者。忌部の歴史を書き残した"],["天富命","阿波忌部を率いて東国（安房）へ渡ったと «古語拾遺» に記される"],["三木家","阿波忌部の子孫とされ、麁服を納めてきた家"]],"deep":["«忌部» は «けがれを忌み、身を清めて祭りに仕える» という意味といわれます。のちに «斎部» の字も使われました。","«古語拾遺» の安房（千葉県南部）の話は、地名の由来として有名です。千葉県館山市の安房神社は天太玉命をまつり、阿波とのつながりを伝えています。","忌部神社の論社には、吉野川市山川町の忌部山にある神社などがあります。旧麻植郡の中でも場所をめぐっては諸説があり、今も決着したわけではありません。","天日鷲命は、天岩戸の神話で神々が祭りの支度をしたとき、穀や木綿（ゆう）を作った神とされます。名前の «鷲» にちなみ、各地の鷲神社や酉の市とのつながりも語られます。","天皇即位後の «大嘗祭» で使われる麻の織物 «麁服（あらたえ）» は、阿波忌部の子孫とされる家が納めることで知られ、忌部の伝統が今も生きています。"],"look":["眉山のふもとの石段と社殿","天日鷲命をまつる本殿","周辺の二軒屋の町並みと眉山の眺め","吉野川市山川町の «阿波忌部» ゆかりの地と見くらべるのもおすすめ"],"q":["千葉県の «安房» の名は、どこから来たと «古語拾遺» は書いている?","阿波忌部が房総に渡って麻を植えたことから。«阿波» から «安房» になったという説明です。"],"koji":[],"myth":"本来の忌部神社の場所は諸説（論社が複数）。安房の地名由来は «古語拾遺» の記述で、史実かどうかは別。","img":["古語拾遺","天日鷲命","忌部氏","麻植郡"],"wp":"忌部神社","rel":{"ev":[],"grave":[]},"ph":[["c:0/02/Inbe_Shinto_shrine.jpg",854,480,"忌部神社"],["c:3/36/NDL772063_%E5%8F%A4%E8%AA%9E%E6%8B%BE%E9%81%BA.pdf",6495,5050,"古語拾遺"],["c:1/14/Amefutotamanomikoto-jinja%2C_haiden.jpg",5982,3952,"忌部氏"],["c:e/ec/Tokushima_Oe-gun.png",210,130,"麻植郡"]]},{"id":"36_mikike","n":"三木家住宅（天皇即位の麁服を織る家）","yomi":"みきけじゅうたく","cat":"伝承","rank":"A","y":1700,"era":["kamakura","edo","reiwa"],"sh":"国の重要文化財","ad":"美馬市木屋平貢","st":"JR徳島線 穴吹駅から車で約1時間。公共交通では行きにくく、車が必要","la":33.927,"lo":134.186,"hook":"天皇が代わるたび、この山奥の家から «麻の布» が都へ運ばれてきた。","lead":"剣山のふもと、標高の高い山の斜面に建つ古い農家です。三木家は阿波忌部の子孫とされ、天皇が即位したあとの大切な儀式 «大嘗祭（だいじょうさい）» に使う麻の布 «麁服（あらたえ）» を納めてきました。家は国の重要文化財です。","story":["曲がりくねった山道を車でのぼっていくと、急な斜面に、大きなかやぶき屋根の家が現れます。ここが三木家。«こんな山奥に、なぜ天皇の儀式にかかわる家が?» と、だれもが不思議に思うはずです。","天皇が位につくと、その年の新しいお米を神さまにささげる «大嘗祭» が一度だけ行われます。そのとき神さまのために用意される布が二つあり、絹の布を «繪服（にぎたえ）»、麻の布を «麁服（あらたえ）» といいます。麁服を用意するのは、昔から阿波忌部の役目とされてきました。","三木家には中世の古い文書が伝わり、鎌倉時代ごろに麁服を納めたことを示す記録があるとされます。南北朝の争いのころには、三木家は南朝の側についたといわれ、山深い土地で一族を守り続けました。","戦国の世や江戸時代を経て、麁服を納める仕事は長く途絶えていました。ふたたび三木家がかかわるようになったのは、大正天皇の大嘗祭からです。以後、昭和、平成、令和と、代替わりのたびに地元で麻を育て、糸をつむぎ、布を織って届けてきました。","麻を育てるには、今は特別な許可が必要です。地域の人たちが力を合わせて畑を守り、白い装束に身を包んで布を送り出す――その姿は、千年以上前の «古語拾遺» に描かれた忌部の仕事と、確かにつながっています。"],"tl":[["807年","«古語拾遺» に阿波忌部が麻を育てたと記される"],["鎌倉時代","三木家文書に麁服を納めた記録が残るとされる"],["南北朝時代","三木家は南朝方についたと伝わる"],["江戸時代","現在の主屋が建てられる（江戸時代前期ごろとされる）"],["1915年","大正天皇の大嘗祭。三木家が麁服の調進にかかわる"],["2019年","令和の大嘗祭。地元で育てた麻で麁服を織り納める"]],"who":[["三木家","阿波忌部の子孫とされる家。麁服を納める"],["天日鷲命","阿波忌部の祖先とされる神"],["斎部広成","«古語拾遺» で阿波忌部の麻づくりを記録"],["大正天皇","その大嘗祭で三木家による麁服調進が復活"]],"deep":["主屋は江戸時代前期の建築とされる、徳島県内でも古い民家の一つです。急斜面を削って石垣を築き、その上に建てています。","«三木家文書» は中世の地方の武士や山村の暮らしを伝える貴重な史料として、研究者にも注目されています。","大嘗祭の麁服は、麻の栽培から織りまで地元で行うのが特徴です。令和の調進では、麻は美馬市木屋平で育てられ、吉野川市山川町の «織殿» で織られたと報道されました。","«麁服» の «麁（あら）» は «あらい・目の粗い» という意味。絹の «繪服（にぎたえ）» の «にぎ» は «なめらか» の意味で、対になっています。","建物の見学は時期や曜日が限られることがあります。住宅は私有の文化財なので、訪れる前に美馬市などで公開状況を確かめましょう。","三木家の周辺は標高が高く、冬は雪も降ります。この厳しい山の暮らしが、麻や雑穀づくりの伝統を支えてきました。"],"look":["急斜面の石垣の上に建つ主屋","かやぶき屋根と土間の造り","三木家住宅の資料館（公開状況は事前に確認）","周辺の山村の段々畑と剣山方面の眺め"],"q":["大嘗祭で使われる麻の布を何という?","«麁服（あらたえ）»。絹の布は «繪服（にぎたえ）» といいます。"],"koji":[],"myth":"三木家が南朝方についた話、麁服を納め始めた時期は史料解釈に幅がある。","img":["麁服","大嘗祭","阿波忌部","木屋平村"],"wp":"三木家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:9/90/Dengai-omi-akusha_%28Reiwa_Daijokyu%29.JPG",2560,1920,"大嘗祭"],["c:8/87/Miki_Residence%2C_Mima_City%2C_Koyadaira.JPG",2048,1365,"木屋平村"],["c:f/f8/Turugisaan_20260509_4.jpg",2400,2336,"近く: 龍光寺 (美馬市)"]]},{"id":"36_kazurabashi","n":"祖谷のかずら橋（平家落人が架けた橋）","yomi":"いやのかずらばし","cat":"伝承","rank":"S","y":1185,"era":["heian","edo","showa"],"sh":"国の重要有形民俗文化財","ad":"三好市西祖谷山村善徳","st":"JR土讃線 大歩危駅から路線バスで約20分、«かずら橋» 下車すぐ","la":33.8765,"lo":133.835,"hook":"足もとのすき間から、はるか下の谷川が見える。追っ手が来たら切り落とせるように――そう伝わる «つる» の橋。","lead":"祖谷川の上にかかる、植物のつる（シラクチカズラ）で編んだつり橋です。長さ約45m、水面からの高さは約14m。平家の落人が追っ手から逃れるために造ったとも、弘法大師が架けたともいわれます。3年ごとに架け替えられています。","story":["一歩ふみ出すと、橋は «ゆらり» とゆれます。足もとの板はすき間だらけで、下には青い祖谷川。«こわい!» と声を上げる人も少なくありません。けれど、それこそがこの橋の魅力。昔の人は毎日、この橋を渡って谷を行き来していたのです。","言い伝えでは、壇ノ浦の戦いに敗れた平家の一族が、この深い谷に逃れてきたといいます。源氏の追っ手がいつ来るかわからない。«いざとなったら、すぐに切り落とせる橋を» ――そうして、丈夫で切りやすい «かずら» の橋が考え出された、と語られます。","一方で、祖谷を訪れた弘法大師が、谷を渡れず困っている村人のために架けた、という話もあります。どちらも確かめようのない言い伝えですが、深い谷で暮らす人びとにとって、橋がどれほど大事だったかは伝わってきます。","江戸時代の記録には、祖谷の谷にいくつものかずら橋があったことが書かれています。大水で流されるたび、村人たちは山からつるを集め、力を合わせて架け直しました。橋は村のみんなでつくり、守るものだったのです。","今のかずら橋は、安全のために中にワイヤーが入っていますが、見た目は昔ながらのつるの橋。3年に一度、村の人たちの手で架け替えられます。«昔の技を残したい» という思いが、この橋をつないでいます。"],"tl":[["1185年","壇ノ浦の戦い。平家の落人が祖谷に逃れたと伝わる"],["江戸時代","祖谷の谷に多くのかずら橋があったと記録される"],["昭和のはじめ","安全のためワイヤーで補強されるようになる"],["1955年","国の重要有形民俗文化財に指定される"],["現在","3年ごとに架け替え。奥祖谷には «二重かずら橋» も残る"]],"who":[["平家の落人","追っ手を防ぐため切り落とせる橋を造ったと伝わる"],["弘法大師（空海）","村人のために橋を架けたという別の言い伝えがある"],["祖谷の村人","つるを集め、代々橋を架け替えてきた"]],"deep":["材料のシラクチカズラは、マタタビ科のサルナシのつるのこと。丈夫でしなやかなため、橋の材料に選ばれました。1回の架け替えで大量のつるが必要になります。","長さ約45m、幅約2m、水面からの高さ約14m。床板の «さな木» はわざとすき間をあけて並べられ、渡る人の足がすくむのも特徴です。","東祖谷の «奥祖谷二重かずら橋» は、«男橋» と «女橋» の2本が並ぶ珍しい形。平家の馬場の近くにあったと伝わります。","江戸時代の徳島藩の記録には、祖谷の谷に数多くのかずら橋があったことが書かれているといわれます。道路や鉄の橋ができるまで、つるの橋は暮らしの道そのものでした。","かずら橋は、岩国の錦帯橋、山梨の猿橋とともに «日本三奇橋» の一つに数えられることがあります（数え方には諸説あり）。","平家落人の伝説は祖谷全体に広がっていますが、実際にいつ、だれが来たのかを示す確かな史料は見つかっていません。"],"look":["橋の上から見下ろす祖谷川の流れ","つるの編み方と、すき間のある床板","近くの «琵琶の滝»（平家が琵琶を弾いたと伝わる）","奥祖谷二重かずら橋（東祖谷・冬期は閉鎖あり）"],"q":["かずら橋の材料になっている植物は?","シラクチカズラ（サルナシのつる）。丈夫でしなやかなつるです。"],"koji":[],"myth":"平家落人・弘法大師が架けた話はいずれも伝承。三奇橋の数え方は諸説。","img":["祖谷","平家落人伝説","サルナシ","奥祖谷二重かずら橋"],"wp":"祖谷のかずら橋","rel":{"ev":[],"grave":[]},"ph":[["c:8/89/Iya_Valley_a.jpeg",2816,2112,"祖谷のかずら橋"],["c:1/18/Kazura_Bridge_in_Ikeda_Town.jpg",6121,4081],["c:6/68/KazuraBridge.JPG",4000,3000],["c:3/35/IyanoKohikibushi.jpg",1152,864],["c:2/2e/IyanoKazurabashiSide.jpg",1152,864],["c:1/1b/IyanoKazurabashiFloor.jpg",1152,864],["c:a/a8/Weiki02.jpg",1620,1215,"サルナシ"],["c:8/86/Okuiya2basi.jpg",800,1195,"奥祖谷二重かずら橋"]]},{"id":"36_ochiai","n":"東祖谷の落合集落と平家落人伝説","yomi":"ひがしいやのおちあいしゅうらく","cat":"町","rank":"A","y":1185,"era":["heian","edo","heisei"],"sh":"国の重要伝統的建造物群保存地区","ad":"三好市東祖谷落合","st":"JR土讃線 大歩危駅から路線バスで1時間余り。本数が少ないので車が便利","la":33.854,"lo":133.926,"hook":"山の斜面に、家と畑が階段のように積み重なる。谷の向かいから眺めると、まるで一枚の絵のような村。","lead":"祖谷川の谷の急な斜面に、江戸時代から昭和はじめごろの家々が点々と並ぶ山村です。集落のいちばん下と上の高さの差は約390m。平家の落人が隠れ住んだという伝説の残る «祖谷山» の暮らしを、今に伝えています。","story":["谷をはさんだ向かいの展望所に立つと、落合集落の全体が見わたせます。家々は斜面にしがみつくように建ち、そのあいだを石垣と畑がうめています。«なぜこんな急な所に村を?» ――平らな土地がほとんどない祖谷では、斜面こそが暮らしの場でした。","祖谷には、平家の落人伝説が数多く残ります。壇ノ浦で敗れた平家の一族が、安徳天皇を守って山深い祖谷に逃れてきた――そんな話が、村ごとに語り継がれてきました。東祖谷の阿佐家は平家の子孫と伝わり、平家の赤旗とされる旗を守ってきたことで知られます。","戦国時代が終わり、阿波に蜂須賀家が入ってくると、山の民の多くは新しい領主に従うことをこばみ、争いが起きたと伝わります。けわしい山は、よそからの支配をなかなか受けつけない土地だったのです。","落合の畑は、急な斜面を耕すため «さらえ» という独特の農具を使い、土が流れないように工夫して作物を育ててきました。ソバや雑穀、コンニャクなど、山の恵みが人びとの暮らしを支えました。","2005年、落合集落は国の重要伝統的建造物群保存地区に選ばれました。古民家を宿に生かす取り組みも進み、世界中から旅人が訪れる場所になっています。静かな山里を歩くときは、住む人の暮らしへの気づかいを忘れずに。"],"tl":[["1185年","壇ノ浦の戦い。平家の落人が祖谷に逃れたと伝わる"],["1585年ごろ","蜂須賀家の阿波入国。祖谷の山の民が抵抗したと伝わる"],["江戸時代","祖谷山は徳島藩の中でも独特な支配の地域とされる"],["江戸時代〜昭和はじめ","現在残る家々の多くが建てられる"],["2005年","国の重要伝統的建造物群保存地区に選定"],["現在","古民家の再生と山村景観の保存が進む"]],"who":[["安徳天皇","平家とともに祖谷に逃れたという伝説の天皇"],["阿佐家","東祖谷の旧家。平家の子孫と伝わり、赤旗を伝える"],["蜂須賀家政","阿波に入った大名。祖谷の支配をめぐり山の民と対立"],["落合の人びと","急斜面を耕し、村の景観を守ってきた"]],"deep":["落合集落の高低差は約390mといわれ、重伝建の山村集落の中でも急斜面が際立ちます。家の多くは等高線に沿って建てられています。","祖谷の家は、寄棟造りで平屋が多く、主屋のほかに納屋や蔵を並べる配置が特徴です。昔はかやぶきで、今はトタンでおおった家も多くあります。","東祖谷の «栗枝渡（くりしど）八幡神社» には、安徳天皇を火葬した所という伝説が残ります。祖谷には安徳天皇が生きのびたという話がいくつもあります。","«祖谷山» では江戸時代、地元の有力者 «名主» たちが村を治め、藩の支配はゆるやかだったといわれます。落人伝説と «よそ者を寄せつけない土地» のイメージが結びついて語られてきました。","急斜面の畑では、土が下に流れるのを防ぐため、毎年土を上へかき上げる作業がありました。«祖谷の傾斜地農法» として世界農業遺産（にし阿波の傾斜地農耕システム）にも関係しています。","平家落人伝説は四国・九州などの山深い土地に広く見られ、祖谷の話もどこまで史実かはわかっていません。"],"look":["谷の向かいの展望所から見る集落の全景","等高線に沿って並ぶ古民家と石垣","急斜面の段々畑","東祖谷の阿佐家（平家屋敷）や栗枝渡八幡神社"],"q":["落合集落のいちばん下と上の高さの差は、およそ何m?","約390m。東京タワー（333m）より大きな差の斜面に村があります。"],"koji":[],"myth":"平家落人・安徳天皇が祖谷に来た話は伝承。阿佐家の赤旗の由来も伝承による。","img":["祖谷","三好市東祖谷落合伝統的建造物群保存地区","平家落人伝説","安徳天皇"],"wp":"祖谷山","rel":{"ev":[],"grave":[]},"ph":[["c:9/91/Iyayama_20191130_01.jpg",4309,1113],["c:5/54/Iyayama20220528_1.jpg",4309,1073],["c:6/61/Emperor_Antoku.jpg",1520,1204,"安徳天皇"]]},{"id":"36_tsurugisan","n":"剣山（安徳天皇の剣と «ソロモンの秘宝» 伝説）","yomi":"つるぎさん","cat":"伝承","rank":"B","y":1185,"era":["heian","edo","showa"],"sh":"","ad":"三好市東祖谷・美馬市木屋平・那賀町の境","st":"JR徳島線 貞光駅から路線バスで «見ノ越» まで約2時間（運行期間あり）。見ノ越からリフトと登山道で山頂へ","la":33.8535,"lo":134.0945,"hook":"安徳天皇の剣が納められた山? いや、古代イスラエルの秘宝が眠る山? 西日本で2番目に高い山には、ふしぎな話がつきない。","lead":"剣山は標高1955m、西日本では石鎚山に次ぐ高い山です。昔から修験者が修行する霊山で、平家の安徳天皇が剣を納めたという伝説から名がついたともいわれます。昭和には «ソロモンの秘宝» が埋まっているという説で、発掘騒ぎまで起きました。","story":["山頂近くには «宝蔵石（ほうぞういし）» と呼ばれる大きな岩があります。言い伝えでは、祖谷に逃れた安徳天皇が、平家の宝である剣をこの岩のそばに納めた――それで «剣山» と呼ばれるようになった、というのです。","もちろん、壇ノ浦で海に沈んだとされる安徳天皇が祖谷に来たという話は、確かめようのない伝説です。けれど平家の落人伝説が色濃い祖谷の人びとにとって、剣山はその物語の «聖地» になりました。","江戸時代、剣山は修験道の山として栄え、白い装束の行者たちが列をなして登りました。山頂の大剣神社のそばには、剣のようにそそり立つ «御塔石（おとういし）» という岩があり、信仰の対象になっています。","昭和のはじめ、ある研究家が «旧約聖書» の «契約の箱（アーク）» が剣山に隠されている、と言い出しました。«古代イスラエルの人びとが日本に来たのでは?» ――そんな大胆な説に、元海軍大将まで加わって山頂付近が掘られたといわれます。","けれど何も見つからないまま、発掘は終わりました。今この話は、学問的な根拠のない «伝説・ロマン» として語られています。山頂の広い笹原に立ち、雲の海を見下ろせば、人がこの山にいろいろな夢を見たくなる気持ちも、少しわかる気がします。"],"tl":[["1185年","壇ノ浦の戦い。安徳天皇が剣を納めたという伝説の起点"],["江戸時代","修験道の霊山として多くの行者が登る"],["1936年ごろ","«ソロモンの秘宝» 説にもとづく発掘が行われたと伝わる"],["1964年","剣山が国定公園の一部となる（剣山国定公園）"],["現在","見ノ越からのリフトで気軽に登れる人気の山"]],"who":[["安徳天皇","剣を納めたという伝説の天皇"],["修験者","剣山を霊山として修行した"],["高根正教","剣山に «契約の箱» があると唱えた研究家とされる"],["山本英輔","発掘に加わったといわれる元海軍大将"]],"deep":["標高1955m。四国では石鎚山（1982m）に次ぐ高さで、西日本第2位の高峰とされます。山頂一帯は «平家の馬場» と呼ばれる笹原です。","山名の由来には、安徳天皇の剣の話のほか、大剣神社の «御塔石» が剣の形に見えるからという説もあります。","«ソロモンの秘宝» 説は、日本人とユダヤ人の祖先が同じだとする «日ユ同祖論» と結びついて広まりました。考古学・歴史学では認められていません。","見ノ越には «劔山本宮劔神社» があり、山頂部の «宝蔵石神社»、«大剣神社» とあわせて剣山信仰の中心となっています。","剣山周辺は、キレンゲショウマなど珍しい高山植物の生える場所としても知られ、宮尾登美子の小説 «天涯の花» の舞台にもなりました。"],"look":["山頂近くの «宝蔵石» と宝蔵石神社","大剣神社と剣のような «御塔石»","山頂の笹原 «平家の馬場» と雲海","夏に咲くキレンゲショウマ（群生地）"],"q":["剣山は西日本で何番目に高い山?","2番目（1955m）。1番は愛媛県の石鎚山（1982m）です。"],"koji":[],"myth":"安徳天皇の剣の話は伝説。«ソロモンの秘宝» は学問的根拠のない説で、発掘の年や参加者は資料により異なる。","img":["安徳天皇","日ユ同祖論","剣山国定公園"],"wp":"剣山","rel":{"ev":[],"grave":[]},"ph":[["c:2/29/Mt.Tsurugisan.jpg",2304,1728,"剣山"],["c:0/08/Turugisan_20260509_24.jpg",4465,3281],["c:d/d8/Tsurugisan_and_Ichinomori.JPG",3872,2592],["c:1/17/Turugisan_20260509_29.jpg",4032,1728],["c:3/38/Turugisan_20220528_1.jpg",4004,1689],["c:f/f4/Tsurugiyama-meteorological_-station.jpg",2304,1728],["c:7/76/Turugisan_20260509_25.jpg",2400,1657],["c:7/71/Turugisan_20260509_22.jpg",2400,1536]]},{"id":"36_shibuno_maruyama","n":"渋野丸山古墳（四国最大級の前方後円墳）","yomi":"しぶのまるやまこふん","cat":"遺跡","rank":"A","y":430,"era":["kofun"],"sh":"国指定史跡","ad":"徳島市渋野町","st":"徳島市中心部から車で約25分。バスは本数が少ないので車が便利","la":34.002,"lo":134.579,"hook":"全長約105m。四国でも指折りの大きさの前方後円墳が、田んぼの中に静かに横たわる。","lead":"徳島市の南、勝浦川の近くにある5世紀前半ごろの前方後円墳です。全長は約105mで徳島県最大、四国でも最大級の大きさです。まわりには堀（周濠）がめぐり、斜面には石がしきつめられていました。","story":["田んぼの中に、こんもりとした緑の丘があります。近づいてみると、前が四角、後ろが丸い «前方後円墳» の形。«こんな大きなお墓を、だれが、何のために?» ――それが渋野丸山古墳です。","古墳が造られたのは5世紀前半ごろ。このころ、大阪平野では仁徳天皇陵とされる大山古墳のような巨大な古墳が造られていました。ヤマト王権の力が大きくなり、各地の豪族は «王権の仲間» であることを示すように、前方後円墳を築いたと考えられています。","渋野丸山古墳の主は、紀伊水道に面した阿波の南東部を治めた有力者だったのでしょう。海の道で紀伊や近畿と結ばれた土地です。«海をおさえる者が、力を持つ» ――古墳の大きさが、その力を物語っています。","発掘調査では、古墳が3段に築かれ、斜面に葺石（ふきいし）がしきつめられていたことや、円筒埴輪が並べられていたことがわかりました。周りを囲む堀の跡も確かめられています。できたばかりの古墳は、白い石が光る、目立つ «人工の山» だったはずです。","長く田畑と森に囲まれてきたこの古墳は、調査の結果、その大切さが改めて認められ、国の史跡になりました。今は整備も進められ、古代の阿波の力を感じられる場所として注目されています。"],"tl":[["5世紀前半","渋野丸山古墳が築かれる"],["江戸時代〜近代","丘として地域の人に知られ、周りは田畑になる"],["平成時代","発掘調査で墳丘の規模・周濠・葺石などを確認"],["令和時代","国の史跡に指定され、保存と整備が進む"]],"who":[["古墳の被葬者（不明）","阿波南東部を治めた有力な首長と考えられる"],["ヤマト王権","前方後円墳という形を各地に広めた中央の政権"],["徳島市の調査担当者","発掘で古墳の姿を明らかにした"]],"deep":["全長約105mは徳島県で最大。四国全体では香川県の富田茶臼山古墳（約139m）に次ぐ規模とされ、«四国最大級» と呼ばれます。","墳丘は3段築成で、くびれ部に «造り出し» と呼ばれる張り出しがあると考えられています。造り出しは祭りを行う場所だったという説があります。","埴輪の形や土器から、築造は5世紀前半と考えられています。この時期、阿波では大型古墳が少なく、この古墳の突出ぶりが目立ちます。","古墳の近くを流れる勝浦川の河口は紀伊水道に通じ、紀伊・和泉と海で結ばれていました。被葬者は海上交通を押さえた首長とみる説が有力です。","埋葬施設（石室や棺）はまだ詳しくわかっておらず、だれが葬られたかも不明です。","前方後円墳の «前方部» と «後円部» のどちらに主な埋葬があったかは古墳によって違いますが、一般には後円部の中心に首長が葬られました。渋野丸山古墳でも後円部の調査が今後の課題とされています。","徳島県内の古墳は吉野川流域に多く分布しますが、渋野丸山古墳は県南東部の勝浦川流域にあり、この地域に大きな力を持つ首長がいたことを示す点でも注目されています。"],"look":["前方後円の墳丘の形（外から一周すると大きさがわかる）","周濠の跡","墳丘斜面の葺石","解説板と、整備された見学ルート","古墳のまわりの田園風景（古墳の大きさが実感できる）"],"q":["渋野丸山古墳は、徳島県でいちばん大きい何?","前方後円墳（古墳）。全長約105mで、四国でも最大級です。"],"koji":[],"myth":"被葬者は不明。造り出しの有無・性格は調査の解釈による。","img":["前方後円墳","富田茶臼山古墳","勝浦川","古墳時代"],"wp":"渋野丸山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:0/0f/Shibuno_Maruyama_Kofun%2C_zenkei.jpg",5996,3970,"渋野丸山古墳"],["c:7/7d/Shibuno_Maruyama_Kofun%2C_kouenbu.jpg",6016,4000],["c:c/c8/Shibuno_Maruyama_Kofun%2C_funkyu.jpg",6016,4000],["j:b/bd/%E6%B8%8B%E9%87%8E%E4%B8%B8%E5%B1%B1%E5%8F%A4%E5%A2%B3_%E5%BD%A2%E8%B1%A1%E5%9F%B4%E8%BC%AA%E7%89%87.JPG",5448,3622],["j:6/6e/%E6%B8%8B%E9%87%8E%E4%B8%B8%E5%B1%B1%E5%8F%A4%E5%A2%B3_%E7%AC%8A%E5%BD%A2%E5%9C%9F%E5%99%A8%E3%83%BB%E5%B0%8F%E5%9E%8B%E4%B8%B8%E5%BA%95%E5%A3%BA.JPG",4872,3242],["j:5/5d/%E6%B8%8B%E9%87%8E%E4%B8%B8%E5%B1%B1%E5%8F%A4%E5%A2%B3_%E5%86%86%E7%AD%92%E5%9F%B4%E8%BC%AA.JPG",5030,3352],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:8/82/Tomida_Chausuyama_Kofun%2C_zenkei-1.jpg",6016,4000,"富田茶臼山古墳"]]},{"id":"36_dan_no_tsukaana","n":"段の塚穴（美馬の巨石横穴式石室）","yomi":"だんのつかあな","cat":"遺跡","rank":"A","y":575,"era":["kofun"],"sh":"国指定史跡","ad":"美馬市美馬町坊僧","st":"JR徳島線 穴吹駅から車で約15分。公共交通では行きにくい","la":34.0535,"lo":134.071,"hook":"石を少しずつ内側にずらして積み、天井をドームのように閉じた «石の部屋»。1400年以上前の技に息をのむ。","lead":"吉野川の北側の段丘にある、6世紀後半ごろの2つの円墳（太鼓塚・棚塚）です。どちらにも大きな石で造った «横穴式石室» があり、中に入ることができます。天井がドームのように高いのが特徴です。","story":["入口から身をかがめて中に入ると、ひんやりとした空気。ライトで照らすと、壁の石が上へ行くほど内側にせり出し、天井がすぼまっています。«どうやって崩れないの?» ――石を少しずつずらして積む «持ち送り» という技で、ドームのような空間が作られているのです。","大きい方の «太鼓塚» の石室は、奥の部屋（玄室）の天井の高さが4mをこえ、四国でも最大級です。もう一つの «棚塚» には、奥の壁ぎわに «棚» のような石が張り出しています。名前は、その形から来ています。","このようなドーム形の石室は、美馬や吉野川の中流に多く見られ、«段の塚穴型石室» と呼ばれます。ほかの地域ではあまり見られない、この土地だけの造り方です。«地元の技術者集団がいたのでは?» と考える研究者もいます。","古墳の主は、吉野川中流を治めた豪族でしょう。近くには7世紀に建てられた郡里廃寺（こおざとはいじ）もあります。古墳から寺へ――豪族が力を示す方法が、お墓からお寺へ移っていった流れが、この美馬の地で見られるのです。","静かな石室の中で目をこらすと、石と石のすき間に、古代の人たちの工夫と手の跡が見えるようです。"],"tl":[["6世紀後半","太鼓塚・棚塚が築かれる"],["7世紀後半","近くに郡里廃寺が建てられる"],["江戸時代","石室が開いた状態で知られ «塚穴» と呼ばれる"],["1942年","国の史跡に指定"],["現在","石室の内部を見学できる史跡として公開"]],"who":[["古墳の被葬者（不明）","吉野川中流域を治めた豪族と考えられる"],["石室を築いた工人","持ち送りの技でドーム形の石室を造った"],["郡里廃寺を建てた一族","古墳の主の子孫とみる説がある"]],"deep":["太鼓塚は直径約37mの円墳とされ、玄室の天井の高さは4mをこえます。玄室の平面は胴張り（壁がふくらむ形）です。","«段の塚穴型石室» は、玄室の壁を持ち送りで積み上げ、天井石を少なくしたドーム状の構造が特徴。美馬市・つるぎ町など吉野川中流域に集中します。","棚塚の奥壁の «棚» は、石棚（いしだな）と呼ばれる張り出しで、紀伊（和歌山）の岩橋千塚古墳群にも見られる構造です。海を越えた交流を考えるヒントとされます。","このあたりは古代の «美馬郡» の中心で、のちに郡の役所（郡家）が置かれたともいわれます。«郡里（こおざと）» の地名もその名残と考えられます。","石室には照明がないので、見学には懐中電灯があると便利です。足もとが悪いので注意しましょう。","«塚穴» は、石室の入口が開いて中に入れる古墳を、昔の人がそう呼んだ言葉です。江戸時代にはすでに穴として知られ、地域の目じるしになっていました。","横穴式石室は、あとから家族を追加で葬ることができる «家族の墓» の性格を持ちます。太鼓塚・棚塚にも、複数の人が葬られた可能性が考えられています。"],"look":["太鼓塚の石室のドーム状天井","棚塚の奥壁の «石棚»","石の積み方（持ち送り）","近くの郡里廃寺跡とあわせて見学"],"q":["石を少しずつ内側にずらして積み、天井をすぼめる技を何という?","«持ち送り»。段の塚穴の石室はこの技でドームのような形になっています。"],"koji":[],"myth":"被葬者や石室の技術の由来は不明で、紀伊とのつながりは研究上の説。","img":["横穴式石室","岩橋千塚古墳群","美馬市","郡里廃寺跡"],"wp":"段の塚穴","rel":{"ev":[],"grave":[]},"ph":[["c:8/8b/Dan-no-tsukaana_Kofun_Group%2C_zenkei.jpg",6016,4000,"段の塚穴"],["c:8/82/Dan-no-tsukaana_Kofun_Group%2C_Tanazuka_Kofun%2C_sendou-2-2.jpg",5568,3712],["c:b/bf/Dan-no-tsukaana_Kofun_Group%2C_Tanazuka_Kofun%2C_sendou-1-2.jpg",5568,3712],["c:b/b5/Dan-no-tsukaana_Kofun_Group%2C_Tanazuka_Kofun%2C_ishidana.jpg",6016,4000],["c:0/0d/Dan-no-tsukaana_Kofun_Group%2C_Tanazuka_Kofun%2C_genshitsu-3-2.jpg",5568,3712],["c:d/db/Dan-no-tsukaana_Kofun_Group%2C_Tanazuka_Kofun%2C_genshitsu-1-2.jpg",5568,3712],["c:8/8c/Dan-no-tsukaana_Kofun_Group%2C_Tanazuka_Kofun%2C_entrance-3.jpg",5568,3712],["c:8/8a/Dan-no-tsukaana_Kofun_Group%2C_Tanazuka_Kofun%2C_entrance-2.jpg",5568,3712]]},{"id":"36_satono_haiji","n":"郡里廃寺跡（阿波の古代寺院）","yomi":"さとのはいじあと","cat":"遺跡","rank":"A","y":675,"era":["asuka","nara"],"sh":"国指定史跡","ad":"美馬市美馬町（郡里）","st":"JR徳島線 穴吹駅から車で約15分","la":34.056,"lo":134.088,"hook":"いまは草地に礎石が残るだけ。けれどここには、1300年前、阿波でいちばん早い時期の立派な寺が建っていた。","lead":"吉野川の北岸、美馬町にある飛鳥時代後半（7世紀後半）の寺の跡です。塔や金堂の土台（基壇）が見つかり、阿波で最も古いお寺の一つと考えられています。建物はもうなく、跡だけが残る «廃寺» です。","story":["仏教が日本に伝わってから100年あまり。都の近くでは飛鳥寺や法隆寺が建ち、やがて地方の豪族たちも、自分の土地に寺を建てはじめました。«寺を建てることは、力と教養のあかし» ――そんな時代です。","郡里廃寺も、そうした流れの中で、美馬の豪族が建てた寺だと考えられています。すぐ近くには、6世紀後半の段の塚穴古墳があります。古墳を築いた一族の子孫が、今度はお寺を建てたのではないか、という見方があります。","発掘調査では、塔と金堂の土台が見つかりました。土台のまわりは石で固められ、瓦がたくさん出てきました。瓦の模様は都の寺のものに似ていて、美馬の豪族が中央とつながっていたことがうかがえます。","寺はいつしか廃れ、建物は失われました。けれど地元では昔から «立光寺（りっこうじ）の跡» などと呼ばれ、ここに寺があったことが語り継がれてきたといわれます。","今は草地の中に土台の跡が整備されています。«ここに塔が立っていたら、吉野川の向こうからも見えたかな?» ――そう想像しながら歩くと、古代の美馬の風景が浮かんできます。","寺の跡に立つと、南には吉野川、その向こうには四国山地の山なみが見えます。古代の人びとも、この同じ景色の中で、瓦屋根の塔を見上げていたはずです。"],"tl":[["6世紀後半","近くに段の塚穴古墳が築かれる"],["7世紀後半","郡里廃寺が建てられる"],["奈良時代","寺として続く。阿波国分寺が徳島市国府町に建てられる"],["平安時代以降","しだいに廃れる"],["昭和時代","国の史跡に指定"],["現在","基壇が整備され、史跡公園として公開"]],"who":[["美馬の豪族（名は不明）","寺を建てた地域の有力者と考えられる"],["段の塚穴の被葬者","寺を建てた一族の祖先ではないかという説がある"],["瓦を作った工人","都の寺に似た模様の瓦を作った"]],"deep":["伽藍配置は、東に塔、西に金堂を並べる形と考えられ、«法起寺式» とする説があります（調査の解釈による）。","出土した瓦のうち古いものは7世紀後半の特徴を持ち、阿波の寺院の中でも古い段階に位置づけられます。","«郡里（こおざと）» は、古代の郡の役所 «郡家（ぐうけ）» があった場所に由来する地名とされます。寺は郡の役所と並ぶ地域の中心だった可能性があります。","奈良時代には国府のある徳島市国府町に阿波国分寺・国分尼寺が建てられます。郡里廃寺はそれより前、地方豪族が自ら寺を建てた時代の貴重な例です。","現地の案内板と、近くの段の塚穴をあわせて見ると、6〜7世紀の美馬の豪族の歩みがまとめてわかります。","古代の瓦は、屋根の軒先をかざる «軒丸瓦»«軒平瓦» の模様から年代や系統がわかります。郡里廃寺の瓦の研究は、阿波の古代寺院の年代を決める物差しの一つになっています。"],"look":["整備された塔跡・金堂跡の基壇","解説板の伽藍配置図","古墳から寺への流れがわかる段の塚穴","吉野川の北岸の段丘の地形"],"q":["郡里廃寺跡の近くにある、6世紀後半の巨石の古墳は?","段の塚穴（太鼓塚・棚塚）。古墳の主の一族が寺を建てたという見方があります。"],"koji":[],"myth":"«立光寺» の名、伽藍配置の型式、建立者は諸説。","img":["廃寺","段の塚穴","法起寺式伽藍配置","美馬市"],"wp":"郡里廃寺跡","rel":{"ev":[],"grave":[]},"ph":[["c:6/66/Kozato-haiji%2C_zenkei.jpg",6016,4000,"郡里廃寺跡"],["c:d/d6/Kozato-haiji%2C_tou-ato.jpg",6016,4000],["c:6/6d/Kozato-haiji%2C_icho.jpg",4000,6016],["c:e/e4/Kamiyodo_Haiji%2C_zenkei.jpg",6016,4000,"廃寺"],["c:8/8b/Dan-no-tsukaana_Kofun_Group%2C_zenkei.jpg",6016,4000,"段の塚穴"],["c:0/0f/Wakimati_minamimati_20250828_4.jpg",3773,2749,"美馬市"]]},{"id":"36_hagiwara","n":"萩原墳墓群（弥生の積石墳丘墓）","yomi":"はぎわらふんぼぐん","cat":"遺跡","rank":"A","y":230,"era":["yayoi","kofun"],"sh":"","ad":"鳴門市大麻町萩原","st":"JR高徳線 池谷駅から車で約5分","la":34.172,"lo":134.524,"hook":"前方後円墳が生まれる直前、阿波の人たちは石を積んだ «丸いお墓» に «出っぱり» をつけていた。","lead":"鳴門市の山すそにある、弥生時代の終わりごろ（3世紀前半ごろ）のお墓の集まりです。石を積んで造った丸い墳丘に、細長い突き出た部分がついた形をしていて、のちの前方後円墳のもとになった形ではないか、と注目されています。","story":["前方後円墳は、どうやって生まれたのでしょう。奈良の箸墓古墳のような巨大な古墳が、ある日いきなり現れたわけではありません。その前に、各地で «新しいお墓の形» が試されていました。萩原墳墓群は、そのヒントを持つ遺跡の一つです。","萩原1号墓は、石を積み上げて造った丸い墳丘に、細長い «突出部» がついています。上から見ると、ホタテ貝のような、あるいは小さな前方後円墳のような形。そして中からは、中国で作られた «画文帯神獣鏡» という鏡が見つかりました。","さらに注目されたのが、2号墓の埋葬施設です。木の棺を木の部屋で囲み、そのまわりを石で囲む «石囲い木槨（もっかく）» という造り方。これが、奈良県桜井市の «ホケノ山古墳» の埋葬施設とよく似ていたのです。","ホケノ山古墳は、邪馬台国の候補地としても知られる纒向（まきむく）遺跡にある、最初期の古墳の一つです。«阿波のお墓の造り方が、ヤマトの王の墓に取り入れられたのでは?» ――そんな可能性が議論されるようになりました。","もちろん、どちらが先か、どう伝わったのかは、まだ研究の途中です。けれど、吉野川の河口に近いこの地の人びとが、古墳の誕生にかかわっていたかもしれない――そう考えると、小さな石積みの墓がぐっと大きく見えてきます。"],"tl":[["3世紀前半ごろ","萩原1号墓・2号墓が造られる"],["3世紀中ごろ","奈良の纒向でホケノ山古墳・箸墓古墳などが築かれる"],["1970年代〜","発掘調査で積石の墳丘や鏡が見つかる"],["2000年代","2号墓の調査で «石囲い木槨» が確認される"],["現在","古墳の成立を考える重要遺跡として研究が続く"]],"who":[["萩原墳墓群の被葬者（不明）","吉野川下流域を治めた弥生時代の首長と考えられる"],["ホケノ山古墳の被葬者（不明）","埋葬施設の構造が萩原2号墓と似ている"],["研究者たち","阿波と纒向のつながりを議論してきた"]],"deep":["1号墓は、円形の積石墳丘に突出部がつく形で、«前方後円形の弥生墳丘墓» の一つとされます。規模は全長20数mほどと小型です。","出土した画文帯神獣鏡は、中国の後漢の終わりごろに作られた鏡の種類です。弥生の墓からの出土は多くなく、被葬者が広い交流を持っていたことを示します。","«石囲い木槨» は、木で作った部屋（槨）の外側を石で囲む埋葬施設。ホケノ山古墳のものと構造が似ていることから、阿波と纒向の関係が注目されました。","阿波は弥生時代、若杉山遺跡などで赤い顔料 «朱（辰砂）» を産出していました。朱の交易が、阿波とヤマトを結びつけたのではないかという説もあります。","周辺の鳴門市大麻町には、阿波一宮の一つ大麻比古神社や、古墳時代の古墳も多く、古代の重要な地域だったことがわかります。"],"look":["積石で造られた墳丘の跡","丸い墳丘と突出部の形（案内板の図と見くらべる）","山すそから見下ろす吉野川下流の平野","近くの大麻比古神社"],"q":["萩原2号墓の埋葬施設と似ているとして注目された、奈良の古墳は?","ホケノ山古墳（奈良県桜井市・纒向遺跡）。«石囲い木槨» という造りが似ています。"],"koji":[],"myth":"阿波の墓制がヤマトに伝わったかどうかは学説の段階で、諸説ある。","img":["ホケノ山古墳","纒向遺跡","画文帯神獣鏡","墳丘墓"],"wp":"萩原墳墓群","rel":{"ev":[],"grave":[]},"ph":[["j:5/51/%E8%90%A9%E5%8E%9F1%E5%8F%B7%E5%A2%93_%E5%87%BA%E5%9C%9F%E5%93%81.JPG",4637,3664],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:9/91/Hokenoyama_Kofun%2C_funkyu-2.jpg",5568,3712,"ホケノ山古墳"],["c:0/08/Makimuku_Site%2C_tatemonogun.jpg",6002,3978,"纒向遺跡"],["c:4/45/Gamla_uppsala.jpg",837,368,"墳丘墓"]]},{"id":"36_miyadani","n":"宮谷古墳（三角縁神獣鏡の古墳）","yomi":"みやだにこふん","cat":"遺跡","rank":"A","y":290,"era":["kofun"],"sh":"","ad":"徳島市国府町西矢野","st":"JR徳島線 府中駅から歩いて約30分、または車で約10分","la":34.06,"lo":134.47,"hook":"«卑弥呼の鏡» とも呼ばれる三角縁神獣鏡が、阿波の小さな古墳から出てきた。","lead":"気延山（きのべやま）のふもとにある、古墳時代のはじめごろ（3世紀後半〜4世紀はじめ）の前方後円墳です。全長は約37mと小さめですが、中から «三角縁神獣鏡» という鏡が見つかり、全国的に注目されました。","story":["三角縁神獣鏡は、ふちの断面が三角形になった大きな銅の鏡で、裏に神さまや不思議な動物が描かれています。«魏の皇帝が卑弥呼に贈った «銅鏡百枚» ではないか?» と考える人もいて、古代史ファンにはおなじみの鏡です。","宮谷古墳は、阿波の国府が置かれた国府町の西、気延山のふもとにあります。調査で、前方後円墳の後円部の埋葬施設から三角縁神獣鏡が見つかりました。阿波でこの鏡がきちんとした調査で出てきたのは、とても珍しいことでした。","«なぜ阿波の小さな古墳に、この鏡が?» ――三角縁神獣鏡は、ヤマト王権が各地の豪族に配ったのではないかとも考えられています。宮谷古墳の主は、ヤマトと早くから結びついた、阿波の最初期の首長だったのかもしれません。","気延山のまわりには、弥生時代の矢野遺跡や、たくさんの古墳が集まっています。のちにこの地域に国府が置かれたのも偶然ではなく、古くから阿波の中心だったことを物語ります。","古墳そのものは小さな丘ですが、ここから出た鏡は、阿波が古墳時代のはじめからヤマトの動きの中にいたことを教えてくれる、大切な証拠なのです。"],"tl":[["3世紀後半〜4世紀はじめ","宮谷古墳が築かれる"],["古墳時代","気延山周辺に多くの古墳が造られる"],["7〜8世紀","近くに阿波国府が置かれる"],["平成時代","発掘調査で三角縁神獣鏡などが出土"],["現在","出土品は徳島市立考古資料館などで紹介される"]],"who":[["宮谷古墳の被葬者（不明）","阿波の最初期の首長と考えられる"],["卑弥呼","魏から «銅鏡百枚» を贈られたと «魏志倭人伝» に記される"],["ヤマト王権","三角縁神獣鏡を各地に配ったとする説がある"]],"deep":["三角縁神獣鏡は全国で数百面が見つかっていますが、中国ではほとんど出土しないため、日本で作られたとする説もあり、論争が続いています。","宮谷古墳からは三角縁神獣鏡が複数面出土したとされ、四国の古墳としては注目すべき例です。","全長約37mの前方後円墳で、古墳時代前期の中でも古い時期に位置づけられます。阿波で最も古い段階の前方後円墳の一つとされます。","気延山の周辺には «気延山古墳群» と呼ばれる多くの古墳があり、弥生時代から古墳時代への移り変わりを追える地域です。","近くの徳島市立考古資料館では、矢野遺跡や周辺の古墳の出土品が展示され、この地域の歴史をまとめて学べます。","鏡は、古墳の中で被葬者の頭や体のまわりに置かれることが多く、魔よけや権威のしるしだったと考えられています。","古墳は山の尾根の上に築かれ、ふもとの平野からよく見える場所が選ばれています。首長が自分の治める土地を見下ろす «見せる墓» だったのかもしれません。"],"look":["気延山ふもとの古墳の墳丘","墳丘から見下ろす鮎喰川流域の平野","徳島市立考古資料館の展示","周辺の気延山古墳群・矢野遺跡","古墳のある尾根への道（足もとに注意）"],"q":["三角縁神獣鏡の «三角縁» とは何のこと?","鏡のふち（縁）の断面が三角形になっていること。"],"koji":[],"myth":"三角縁神獣鏡が «卑弥呼の鏡» かどうかは諸説で未解決。出土面数は資料で確認を。","img":["三角縁神獣鏡","気延山","卑弥呼","前方後円墳"],"wp":"宮谷古墳","rel":{"ev":[],"grave":[]},"ph":[["c:6/64/Miyadani_Kofun%2C_funkyu-1.jpg",5562,3702,"宮谷古墳"],["c:7/7e/Miyadani_Kofun%2C_zenpoubu.jpg",5568,3712],["c:c/ca/Miyadani_Kofun%2C_kouenbu.jpg",5568,3712],["c:7/77/Miyadani_Kofun%2C_hori.jpg",5568,3712],["c:8/81/Miyadani_Kofun%2C_funkyu-2.jpg",5568,3712],["c:a/ac/Miyadani_Kofun%2C_funcho.jpg",5568,3712],["j:3/3a/%E5%AE%AE%E8%B0%B7%E5%8F%A4%E5%A2%B3_%E4%BA%8C%E9%87%8D%E5%8F%A3%E7%B8%81%E5%A3%BA.JPG",3249,3248],["j:c/c5/%E5%AE%AE%E8%B0%B7%E5%8F%A4%E5%A2%B3_%E5%89%AF%E8%91%AC%E5%93%81.JPG",5001,3330]]},{"id":"36_oshiro_kofun","n":"大代古墳（鳴門の前方後円墳）","yomi":"おおしろこふん","cat":"遺跡","rank":"B","y":390,"era":["kofun"],"sh":"","ad":"鳴門市大津町大代","st":"JR高徳線 池谷駅から車で約10分","la":34.164,"lo":134.578,"hook":"高速道路の工事で見つかった古墳。中の石棺は、はるか九州から運ばれた石で作られていたかもしれない。","lead":"鳴門市の山すそにある、古墳時代中ごろ（4世紀末ごろ）の前方後円墳です。全長は約54m。高速道路の建設にともなう調査で詳しいことがわかり、道路のルートを工夫して古墳が残されました。","story":["高速道路をつくる前、予定地では必ず «遺跡がないか» を調べます。鳴門の山すそでも調査が行われ、そこで見つかったのが大代古墳でした。«壊してしまうのか、残すのか?» ――話し合いの末、古墳は残されることになりました。","調査で、墳丘には葺石がしきつめられ、埴輪が並んでいたことがわかりました。後円部の中心には、舟の形をした石の棺 «舟形石棺» が納められていました。","この石棺の石が、九州・熊本の阿蘇の噴火でできた石（阿蘇溶結凝灰岩）ではないか、という研究があります。«そんな重い石を、海を越えて運んだの?» ――もしそうなら、大代古墳の主は、瀬戸内海の船の道を通じて九州ともつながる力を持っていたことになります。","鳴門は、瀬戸内海と紀伊水道を結ぶ海の要所です。古墳の主は、渦潮の海を行き来する船を見守り、海上交通を押さえた首長だったのかもしれません。","今、古墳は整備され、墳丘の形を見ることができます。すぐそばを高速道路が通る風景は、«古代の道» と «現代の道» が同じ場所で出会っているようです。","古墳の上に立つと、北には鳴門の山なみ、南には吉野川の下流の平野が見えます。海と川と山が出会うこの場所は、昔から人とモノが行き交う «交差点» でした。"],"tl":[["4世紀末ごろ","大代古墳が築かれる"],["1990年代","高速道路建設にともなう発掘調査"],["調査後","古墳を残す形で工事が進められる"],["現在","整備された古墳として見学できる"]],"who":[["大代古墳の被葬者（不明）","鳴門の海上交通を押さえた首長と考えられる"],["石棺を運んだ人びと","遠くから石材を運び、棺を作った"],["発掘調査の担当者","古墳の構造を明らかにし、保存につなげた"]],"deep":["全長約54mの前方後円墳で、鳴門市域では規模の大きい古墳です。葺石と埴輪を備えた、ヤマト風の古墳の形をしています。","舟形石棺の石材が阿蘇溶結凝灰岩であれば、九州から四国への石棺の運搬を示す例となります。同じ石の石棺は、近畿や瀬戸内の古墳でも見つかっています。","4世紀末〜5世紀は、ヤマト王権が朝鮮半島とも深くかかわった時期で、瀬戸内の海の道の重要性が高まりました。","近くの萩原墳墓群（弥生時代の終わり）から大代古墳（古墳時代中ごろ）へと、鳴門の山すその首長墓の移り変わりをたどることができます。","古墳の保存は、道路計画を工夫して遺跡を残した例として、文化財保護の面でも語られます。","葺石は、墳丘の斜面を川原石などでおおって、土が流れるのを防ぐとともに、古墳を目立たせる役目がありました。","舟形石棺は、ふたと身がともに舟のような形をした石の棺で、古墳時代前期から中期にかけて、各地の有力者の墓に使われました。"],"look":["整備された墳丘の前方部・後円部","葺石の復元部分","解説板の石棺の説明","近くを通る高速道路と古墳の位置関係"],"q":["大代古墳の舟形石棺の石は、どこの石と考えられている?","九州・阿蘇の火山の石（阿蘇溶結凝灰岩）とする研究があります。"],"koji":[],"myth":"石棺の石材の産地や築造年代は研究による推定。","img":["舟形石棺","阿蘇溶結凝灰岩","前方後円墳","鳴門市"],"wp":"大代古墳","rel":{"ev":[],"grave":[]},"ph":[["c:f/f6/Oshiro_Kofun_%28Naruto%29%2C_zenkei.jpg",5622,3652,"大代古墳"],["j:f/f0/%E5%A4%A7%E4%BB%A3%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E8%88%9F%E5%BD%A2%E7%9F%B3%E6%A3%BA_%28%E8%A4%87%E8%A3%BD%29.JPG",5310,3559],["c:7/7f/Hodota-kofungun_Hachimanzuka-kofun_sekishitsu.JPG",5770,3588,"舟形石棺"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:6/6f/Naruto_Whirlpools_taken_4-21-2008.jpg",3456,2304,"鳴門市"]]},{"id":"36_wakasugiyama","n":"若杉山遺跡（弥生の «辰砂» 採掘場）","yomi":"わかすぎやまいせき","cat":"遺跡","rank":"A","y":100,"era":["yayoi","kofun"],"sh":"国指定史跡","ad":"阿南市水井町","st":"JR牟岐線 阿南駅から車で約40分。公共交通では行きにくい","la":33.862,"lo":134.523,"hook":"古代の人びとが山を掘り、手に入れたのは «赤» ――まつりやお墓をいろどった朱の原料だった。","lead":"那賀川の中流、山の斜面にある弥生時代後期から古墳時代はじめごろの遺跡で、赤い鉱物 «辰砂（しんしゃ）» を掘り出し、くだいて朱（しゅ）の粉を作っていた場所です。弥生時代の辰砂の採掘遺跡として、日本でただ一つ確認されている貴重な遺跡です。","story":["山道を登った先の急斜面。ここで、今から約2000年前、人びとが赤い石を掘っていました。石の名は «辰砂»。水銀と硫黄でできた鉱物で、くだくと鮮やかな赤い粉 «朱» になります。","«なぜ赤がそんなに大切だったの?» ――古代の人びとにとって、赤は太陽や血の色、命や魔よけの色でした。お墓の中の棺やなきがらに朱をまいたり、土器を赤くぬったりしたのです。有力者のお墓ほど、たくさんの朱が使われました。","若杉山遺跡からは、辰砂をくだくための石臼（いしうす）や石杵（いしきね）が、数多く見つかりました。さらに調査で、山の斜面を掘りこんだ «採掘坑» の跡も確認されました。«山で掘り、その場でくだいて粉にする» 仕事場だったのです。","ここで作られた朱は、どこへ運ばれたのでしょう。阿波の朱が、近畿のヤマトの有力者の墓に使われたのではないか、という説もあります。赤い粉は、古代の «宝物» として、海を越えて運ばれたのかもしれません。","山の中の小さな遺跡ですが、古代日本の «赤の歴史» を解くカギをにぎる場所として、国の史跡に指定されています。"],"tl":[["1世紀ごろ〜3世紀","辰砂の採掘と朱の生産が行われる"],["古墳時代はじめ","しだいに採掘が終わる"],["1980年代","発掘調査で石臼・石杵などが多数出土"],["2010年代後半","再調査で採掘坑が確認される"],["2019年","国の史跡に指定"]],"who":[["朱を作った人びと","辰砂を掘り、石臼と石杵で粉にした"],["朱を使った首長たち","墓やまつりで朱を用いた各地の有力者"],["阿南市・徳島県の調査担当者","採掘坑を確かめ、遺跡の性格を明らかにした"]],"deep":["辰砂は硫化水銀（HgS）の鉱物。粉にすると朱色の顔料になり、のちには水銀の原料にもなりました。","弥生時代の辰砂の採掘遺跡が確認されているのは、国内では若杉山遺跡だけとされ、«日本最古の鉱山» ともいわれます。","出土した石杵・石臼には朱がこびりついたものがあり、ここで粉にしていたことがわかります。","朱の産地を調べるため、硫黄の同位体の分析が行われています。墓の朱と産地の朱を比べることで、どこの朱がどこへ運ばれたかを探る研究が進んでいます。","徳島県南部の阿南市周辺には、古代の朱や水銀にかかわる遺跡・地名が点在し、«丹（に）» の文化とのつながりが注目されています。","遺跡は山中の急斜面にあり、見学には足もとの準備が必要です。見学会などの機会を利用するのがおすすめです。","朱は、古墳時代の石室や石棺の内側をぬるのにも使われました。朱を大量に使うことは、首長の力を見せることでもありました。"],"look":["山の斜面の採掘坑の跡（公開状況は事前に確認）","阿南市の資料館などに展示される石臼・石杵","朱の付いた石器","那賀川中流の山あいの風景","朱の赤色と、辰砂の原石（展示があれば）"],"q":["若杉山遺跡で掘られていた赤い鉱物は?","辰砂（しんしゃ）。水銀と硫黄でできた鉱物で、くだくと朱の顔料になります。"],"koji":[],"myth":"阿波の朱がヤマトの墓に運ばれたかは研究途上の説。","img":["辰砂","朱","那賀川","阿南市"],"wp":"若杉山遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:9/9e/Cinnabar_on_Dolomite.jpg",1763,1254,"辰砂"],["c:d/d7/%E9%82%A3%E8%B3%80%E5%B7%9D%EF%BC%88%E5%BE%B3%E5%B3%B6%E7%9C%8C%E9%98%BF%E5%8D%97%E5%B8%82%EF%BC%89.JPG",3264,2448,"那賀川"],["c:4/49/Kamodamisaki_Lighthouse.jpg",2400,1600,"阿南市"]]},{"id":"36_yano_iseki","n":"矢野遺跡（銅鐸が出た弥生のムラ）","yomi":"やのいせき","cat":"遺跡","rank":"B","y":-100,"era":["jomon","yayoi"],"sh":"","ad":"徳島市国府町矢野","st":"JR徳島線 府中駅から歩いて約20分","la":34.065,"lo":134.48,"hook":"土の中から、まるで «埋めたそのまま» の姿で、大きな銅鐸が現れた。","lead":"徳島市国府町にある、縄文時代から弥生時代にかけての大きなムラの跡です。弥生時代の大きな銅鐸が、埋められた状態のまま見つかったことで知られ、この銅鐸は国の重要文化財になっています。","story":["1990年代のはじめ、道路工事の前の発掘調査で、土の中から銅の鐘のようなものが顔をのぞかせました。弥生時代のまつりの道具 «銅鐸（どうたく）» です。しかも、わざわざ穴を掘って、ていねいに埋めた状態のままでした。","銅鐸は、弥生の人びとがお米の実りを祈るまつりで使ったと考えられています。はじめは鳴らす «鐘» でしたが、だんだん大きく、飾りが多くなり、«見るための銅鐸» へと変わっていきました。矢野遺跡の銅鐸は、その後期の大きなものです。","«なぜ大切な銅鐸を、土に埋めたの?» ――これは弥生時代の大きななぞの一つです。ふだんは埋めておいて、まつりのときだけ掘り出したという説。ムラを守るために境に埋めたという説。新しい時代が来て、いらなくなったから埋めたという説。答えはまだ出ていません。","矢野遺跡では、銅鐸だけでなく、縄文時代の竪穴住居の跡もたくさん見つかっています。気延山のふもとは、何千年も人が住み続けた、住みやすい土地だったのです。","やがてこの地域には古墳が築かれ、さらに阿波の国府が置かれます。矢野遺跡は、阿波の «都» の地の、いちばん古いページといえるでしょう。"],"tl":[["縄文時代後期","竪穴住居が建てられ、ムラができる"],["弥生時代","大きなムラとなり、銅鐸を使ったまつりが行われる"],["弥生時代の終わりごろ","銅鐸が土に埋められる"],["1990年代はじめ","発掘調査で銅鐸が埋められた状態で見つかる"],["現在","銅鐸は国の重要文化財。周辺は徳島市立考古資料館で紹介"]],"who":[["矢野のムラの人びと","縄文・弥生時代にここで暮らし、まつりを行った"],["銅鐸を作った工人","型に銅を流しこんで大きな銅鐸を作った"],["調査担当者","銅鐸を埋められた状態のまま記録した"]],"deep":["矢野遺跡の銅鐸は、高さ約1mにせまる大型の «突線鈕式（とっせんちゅうしき）» と呼ばれるタイプで、弥生時代後期のものです。","銅鐸が «埋められた状態のまま» 発掘された例は多くなく、埋め方を調べられた点で学術的な価値が高いとされます。","徳島県は銅鐸の出土が多い県の一つで、吉野川流域や県南の各地から見つかっています。阿波の弥生文化の豊かさがうかがえます。","縄文時代後期の住居跡がまとまって見つかり、四国の縄文のムラを知るうえでも大切な遺跡です。","近くの徳島市立考古資料館では、矢野遺跡や気延山周辺の出土品を見ることができます。","銅鐸の表面には、流水文や袈裟襷文（けさだすきもん）などの文様が描かれ、時代とともに飾りが細かくなっていきます。","銅鐸は古墳時代に入ると作られなくなり、まつりの道具の中心は鏡へと移っていきます。矢野遺跡から宮谷古墳へ、同じ地域で «銅鐸から鏡へ» の変化が見られるのは興味深い点です。"],"look":["徳島市立考古資料館の展示（銅鐸のレプリカや出土品）","気延山のふもとの地形","周辺の宮谷古墳・阿波国分尼寺跡","鮎喰川の流れと平野"],"q":["銅鐸は、弥生時代の人びとが何に使ったと考えられている?","お米の実りなどを祈るまつり。はじめは鳴らす道具、のちに見せる道具になりました。"],"koji":[],"myth":"銅鐸を埋めた理由は諸説。","img":["銅鐸","徳島市立考古資料館","気延山","弥生時代"],"wp":"矢野遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:b/b4/Epoca_yaoi_finale%2C_campana_rituale_dotaku%2C_da_shizuoka%2C_III_sec.JPG",1008,2076,"銅鐸"],["c:a/a3/Tokushima_Koko_Shiryokan.JPG",800,480,"徳島市立考古資料館"],["c:c/ca/Kinobeyama.jpg",1600,960,"気延山"]]},{"id":"36_kannonji_iseki","n":"観音寺遺跡と阿波国府跡（«論語» 木簡が出た国府の地）","yomi":"かんのんじいせきとあわこくふあと","cat":"遺跡","rank":"S","y":650,"era":["asuka","nara","heian"],"sh":"","ad":"徳島市国府町観音寺","st":"JR徳島線 府中駅から歩いて約15分","la":34.0665,"lo":134.4745,"hook":"«子曰く、学びて時に之を習う…»。1300年以上前の阿波の役人が、木の札に «論語» を書いて勉強していた。","lead":"徳島市国府町は、奈良・平安時代に阿波の国の役所 «国府» が置かれた場所です。観音寺遺跡からは、文字を書いた木の札 «木簡» がたくさん見つかり、中には中国の古典 «論語» の一節を書いたものがありました。国府の建物は残っておらず、場所も «このあたり» と考えられている段階です。","story":["«子曰く、学びて時に之を習う、亦た説ばしからずや»。学校の教科書にも出てくる «論語» の最初の言葉です。これとほぼ同じ文が、1300年以上前の木の札に墨で書かれて、徳島の土の中から出てきました。","見つかったのは観音寺遺跡。昔の川の跡から、たくさんの木簡が見つかりました。木簡は、紙が貴重だった時代に、役所の記録や荷札、手紙、そして文字の練習に使われた木の札です。«論語» 木簡は7世紀ごろのものと考えられ、全国でも最も古い «論語» の木簡の一つとされます。","«なぜ地方で、論語?» ――当時、朝廷は中国にならって法律（律令）で国を治める仕組みを作ろうとしていました。役人になるには、漢字を読み書きし、中国の古典を学ぶことが必要だったのです。阿波の役人たちも、木の札に論語を書いて、一生けんめい勉強していたのでしょう。","やがてこの地に阿波の国府が置かれ、国司が都からやって来ました。近くには、聖武天皇の命令で建てられた国分寺・国分尼寺が並びます。«国府（こう）» の地名や «府中（こう）» 駅の名前が、ここが阿波の都だったことを今に伝えています。","国府の建物の正確な場所は、まだはっきりしていません。けれど観音寺遺跡の木簡は、この地に文字を使いこなす人びとが集まっていた確かな証拠。田園の中を歩けば、足の下に «阿波の都» が眠っていると感じられるはずです。"],"tl":[["7世紀","«論語» を書いた木簡が使われる"],["8世紀","阿波国府が名方郡（今の国府町周辺）に置かれる"],["741年","聖武天皇が国分寺建立の詔を出す。やがて阿波国分寺・国分尼寺が建つ"],["平安時代","国府が阿波の政治の中心として続く"],["1967年","名西郡国府町が徳島市に合併"],["1990年代〜","観音寺遺跡の発掘で多くの木簡が出土"]],"who":[["孔子","«論語» に言葉を残した古代中国の思想家"],["阿波の役人たち","木簡に文字を書き、論語で学んだ"],["国司","都から派遣され、国府で阿波を治めた"],["聖武天皇","国分寺・国分尼寺の建立を命じた"]],"deep":["«論語» 木簡には、学而篇の冒頭がほぼそのまま書かれています。字句がところどころ現在の本と違っており、当時どんな本で学んだかを考える材料になっています。","観音寺遺跡の木簡には、役所の記録や荷札のほか、«難波津の歌» の習書など、文字の練習らしいものも含まれるとされます。","阿波国府の中心施設（国庁）はまだ見つかっておらず、観音寺遺跡の周辺と考えられています。国府の範囲を探る調査が続いています。","«国府町» は1967年に徳島市に合併するまで独立した町でした。JR徳島線の «府中» 駅は «こう» と読み、国府に由来する地名です。","近くには四国遍路の15番札所・国分寺、16番札所・観音寺、17番札所・井戸寺が集まり、古代の国府の地が中世以降は信仰の道の要所になりました。","阿波国分尼寺跡は国の史跡に指定されており、国府周辺の古代の姿を知る手がかりになっています。"],"look":["観音寺遺跡周辺の田園と解説板","16番札所・観音寺と15番札所・国分寺","阿波国分尼寺跡（国指定史跡）","徳島県立埋蔵文化財総合センター（板野町）などでの木簡展示（展示状況は確認を）"],"q":["観音寺遺跡の木簡に書かれていた中国の古典は?","«論語»。«子曰く、学びて時に之を習う…» の冒頭の部分です。"],"koji":[{"w":"学びて時に之を習う、亦た説ばしからずや","m":"学んだことを折にふれて復習すると、身について楽しい、という «論語» の最初の言葉"}],"myth":"国府の中心施設の位置は未確定。木簡の年代は研究による推定。","img":["論語","木簡","阿波国分尼寺","阿波国"],"wp":"国府町 (徳島県)","rel":{"ev":[],"grave":[]},"ph":[["c:2/25/Awakokbunji20210330_1.jpg",1600,1199,"国府町 (徳島県)"],["c:5/50/Yakurahimejinja_09.JPG",4288,2848],["c:a/a5/Kanonji%2C_Tokushima_02.JPG",4288,2848],["c:5/5f/Awa_Kokubunji_02.JPG",4288,2848],["c:5/51/Idoji_Nio-mon.jpg",1280,960],["c:3/35/JR_Shikoku_Ko_stn_1.jpg",960,720],["c:7/73/Awa-siseki-koen.jpeg",828,615],["c:a/a3/Tokushima_Koko_Shiryokan.JPG",800,480]]},{"id":"36_shiroyama_kaizuka","n":"城山貝塚（徳島城山の縄文貝塚）","yomi":"しろやまかいづか","cat":"遺跡","rank":"B","y":-2000,"era":["jomon","azuchi"],"sh":"","ad":"徳島市徳島町城内（徳島中央公園）","st":"JR徳島駅から歩いて約10分","la":34.076,"lo":134.556,"hook":"お城の山は、4000年前は «海に浮かぶ島» だった。縄文人が食べた貝がらが、その証拠。","lead":"徳島城跡のある城山（しろやま）に残る、縄文時代の貝塚です。今は町の真ん中ですが、縄文時代には海がすぐそばまで入りこみ、城山は海に面していました。人びとが食べた貝がらや道具が見つかっています。","story":["徳島駅のすぐ裏にある緑の山、城山。戦国時代の終わりに蜂須賀家政が徳島城を築いた山です。けれど、この山の歴史はもっとずっと古く、縄文時代までさかのぼります。","縄文時代、地球は今より暖かく、海面が高かった時期がありました。徳島の平野の多くは海の底で、城山は海に浮かぶ島か、海に突き出た岬のようだったと考えられています。«駅のあたりが海?» と想像すると、驚きますね。","城山のふもとや岩かげからは、縄文人が食べた貝のからが積み重なった «貝塚» が見つかりました。ハマグリやカキなどの貝がら、動物の骨、土器や石器。人の骨も見つかり、ここで暮らし、ここに葬られた人がいたことがわかります。","城山貝塚の調査には、徳島出身の人類学者・鳥居龍蔵もかかわったとされます。世界を旅して «日本人のルーツ» を探した鳥居にとって、ふるさとの貝塚は大切な研究の場でした。","今、城山は徳島中央公園として市民の散歩道です。石垣の上の天守跡をめざして登る途中、足もとの岩かげに «縄文人の台所» があったと思うと、4000年の時間が一度に見わたせる気がします。"],"tl":[["縄文時代後期（約4000年前）ごろ","城山のまわりに貝塚が作られる"],["1586年","蜂須賀家政が城山に徳島城を築く"],["大正時代","貝塚の調査が行われる（鳥居龍蔵らがかかわったとされる）"],["2006年","徳島城跡が国の史跡に指定される"],["現在","徳島中央公園の中で見学できる"]],"who":[["縄文の人びと","城山の岩かげに住み、貝や魚をとって暮らした"],["鳥居龍蔵","徳島出身の人類学者・考古学者。城山貝塚の調査にかかわったとされる"],["蜂須賀家政","城山に徳島城を築いた大名"]],"deep":["城山には複数の貝塚があるとされ、岩かげを利用した住まいの跡とも考えられています。","貝の種類から、当時の城山のまわりは海水の入る入り江や干潟だったと推定されます。縄文時代の «海進» の様子を知る手がかりです。","鳥居龍蔵（1870〜1953）は徳島市出身。中国東北部やシベリア、台湾などを調査した人類学者で、徳島市の «徳島県立鳥居龍蔵記念博物館»でその業績が紹介されています。","城山は、徳島城の本丸などがあった山で、城の石垣には青い «阿波の青石（緑色片岩）» が使われています。縄文と戦国、二つの時代の遺跡が同じ山に重なっています。","貝塚の場所には説明板があり、公園の散策路から見学できます。","貝塚は «ごみ捨て場» ですが、そこからは食べ物の種類、季節、道具、ときには埋葬の様子までわかり、«縄文人のくらしの記録簿» と呼ばれます。","徳島平野は、吉野川が運んだ土砂でしだいに陸地が広がってできました。城山貝塚は、その海岸線の移り変わりを知る目印の一つです。"],"look":["城山の散策路にある貝塚の説明板","岩かげの地形","青石で積まれた徳島城の石垣","徳島城博物館と旧徳島城表御殿庭園"],"q":["縄文時代、城山のまわりはどんな場所だった?","海。海面が高く、城山は海に面した島や岬のようだったと考えられています。"],"koji":[],"myth":"調査の年や鳥居龍蔵のかかわり方は資料で確認が必要。","img":["徳島城","鳥居龍蔵","貝塚","縄文海進"],"wp":"城山貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:d/d8/Shiroyama_Kaizuka_%28Tokushima%29%2C_gaikan.jpg",6016,4000,"城山貝塚"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:1/1a/Tokushima_castle_22.JPG",2048,1362,"徳島城"],["c:9/99/Ryuzo_Torii_01.jpg",500,590,"鳥居龍蔵"],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["c:1/1d/Post-Glacial_Sea_Level.png",1813,1088,"縄文海進"]]},{"id":"36_tosadomari","n":"土佐泊（紀貫之が «土佐日記» で泊まった港）と土佐泊城","yomi":"とさどまり","cat":"伝承","rank":"A","y":935,"era":["heian","azuchi"],"sh":"","ad":"鳴門市鳴門町土佐泊浦","st":"JR鳴門駅から鳴門公園方面のバスで約15分、途中下車。車が便利","la":34.228,"lo":134.625,"hook":"«土佐» の名を持つ阿波の港。土佐から帰る船で、ある女性がその名に胸をつまらせた。","lead":"鳴門海峡の近くにある港町です。平安時代、紀貫之が土佐の国司の仕事を終えて京へ帰る旅を書いた «土佐日記» に、«土佐の泊（とまり）» という港が出てきます。戦国時代には、長宗我部元親に屈しなかった土佐泊城がありました。","story":["934年の暮れ、紀貫之は4年の任期を終え、土佐（高知）の国府を船で出発しました。海賊をおそれ、荒波を心配しながら、船は四国の東の海をゆっくり進みます。その旅の日記が、ひらがなで書かれた «土佐日記» です。","京へ向かう途中、船は阿波の «土佐の泊» という所にさしかかりました。船には、昔しばらく土佐という所に住んでいた女性が乗っていました。«昔住んでいた所と同じ名前だわ» ――彼女は胸がいっぱいになって、歌を詠みます。«年ごろを すみし所の 名にしおへば 来寄る波をも あはれとぞ見る»。","«ずっと住んでいた所と同じ名だから、寄せてくる波までいとおしく見える» という意味です。この «土佐の泊» が、今の鳴門市の土佐泊だと考えられています。«なぜ阿波に土佐の名?» ――土佐へ向かう船が泊まった港だから、という説があります。","それから600年あまりのち、戦国時代。土佐の長宗我部元親が阿波に攻めこみ、多くの城を落としました。その中で、土佐泊城の森村春（もりむらはる）は屈せず、城を守り続けたと伝わります。«土佐» の名の城が、土佐の軍に最後まで抵抗したのです。","やがて豊臣秀吉が四国を平定すると、森氏は阿波の大名・蜂須賀家に仕え、水軍の役目を担いました。鳴門の渦潮を知りつくした海の一族らしい活躍です。今は静かな漁港の町に、貫之と戦国の海の武士の記憶が重なっています。"],"tl":[["934年12月","紀貫之が土佐を出発し、京へ向かう"],["935年","京に帰る。途中 «土佐の泊» に立ち寄ったことを «土佐日記» に記す"],["戦国時代","森氏が土佐泊城を拠点とする"],["1582年ごろ","長宗我部元親が阿波の大半を制圧。土佐泊城は抵抗を続けたと伝わる"],["1585年","豊臣秀吉の四国平定。森氏は蜂須賀家に仕える"],["江戸時代","森氏は徳島藩の水軍として活躍"]],"who":[["紀貫之","«土佐日記» の作者。土佐から京への旅を記した"],["森村春","土佐泊城の城主。長宗我部に屈しなかったと伝わる"],["長宗我部元親","土佐から阿波に攻めこんだ戦国大名"],["蜂須賀家政","秀吉の四国平定後に阿波の大名となる"]],"deep":["«土佐日記» は男性の貫之が女性のふりをして、ひらがなで書いた日記文学。«男もすなる日記といふものを、女もしてみむとて、するなり» という書き出しが有名です。","«土佐の泊» の場所は、鳴門の土佐泊とする説が有力ですが、日記の記述だけでは細かく決められず、諸説あります。","土佐泊の地名の由来は、土佐への船が風待ちをした港だから、など諸説あります。","森氏は阿波水軍の一族で、江戸時代には徳島藩の船手（水軍）を務めました。阿南市の椿泊（つばきどまり）も森氏ゆかりの地として知られます。","土佐泊城の跡は山の上にあり、遺構は多くありません。見学する場合は足もとに注意し、私有地に立ち入らないようにしましょう。"],"look":["土佐泊の漁港と鳴門海峡の眺め","土佐泊城跡のある山（遺構は少ない）","近くの大鳴門橋と鳴門の渦潮","港の周辺にある «土佐日記» ゆかりの案内"],"q":["«土佐日記» はどんな文字で書かれている?","ひらがな。作者の紀貫之は女性のふりをして書きました。"],"koji":[{"w":"男もすなる日記といふものを、女もしてみむとて、するなり","m":"男の人が書くという日記を、女の私も書いてみようと思って書くのです、という «土佐日記» の書き出し"}],"myth":"«土佐の泊» の位置、地名の由来、森村春が最後まで抵抗した話の細部は諸説・伝承。","img":["土佐日記","紀貫之","鳴門海峡","長宗我部元親"],"wp":"土佐泊城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/3e/Tosa_nikki_copied_by_Teika.JPG",559,561,"土佐日記"],["c:6/6e/Ki_no_Tsurayuki.jpg",1068,1075,"紀貫之"],["c:5/53/Tyousokabe_Mototika.jpg",470,658,"長宗我部元親"]]},{"id":"36_muya_jo","n":"撫養城（岡崎城・阿波九城）","yomi":"むやじょう","cat":"城","rank":"A","y":1585,"era":["azuchi","edo"],"sh":"","ad":"鳴門市撫養町林崎（妙見山公園）","st":"JR鳴門線 鳴門駅から歩いて約20分","la":34.179,"lo":134.609,"hook":"海と塩田を見下ろす小山。阿波の大名が «海の入口» を守るため置いた、九つの城の一つ。","lead":"鳴門市の妙見山にあった城で、岡崎城とも呼ばれました。1585年に阿波の大名となった蜂須賀家が、国を守るため各地に置いた «阿波九城» の一つです。江戸時代のはじめに廃城となり、今は公園になっています。","story":["1585年、豊臣秀吉の四国攻めのあと、阿波の国は蜂須賀家政にあたえられました。まだ戦国の気配が残る時代。家政は、本拠の徳島城のほかに、国のあちこちに城を置き、家臣を城番（守り役）として送りこみました。これが «阿波九城» です。","撫養城は、その中で «海の入口» を守る城でした。撫養は、淡路島や大坂へ渡る船の港。«海から敵が来たら、まずここで食い止める» ――妙見山の上からは、海も港も一望できました。","江戸時代になると、世の中は落ち着いていきます。幕府の方針もあって、阿波九城は役目を終え、1638年ごろまでにすべて廃城となりました。撫養城も建物が取りこわされ、山は静かな丘にもどりました。","けれど撫養の町は、そこから大きく発展します。遠浅の海を利用した塩田が広がり、«撫養の塩» は船で全国へ運ばれました。城が守った «海の道» は、今度は町をうるおす «商いの道» になったのです。","今の妙見山公園には、城をイメージした建物が建っていますが、これは昔の天守を復元したものではありません。本当の城の姿は、山の地形や石垣のかけらに探すことになります。"],"tl":[["1585年","蜂須賀家政が阿波に入り、阿波九城の一つとして撫養城を置く"],["江戸時代はじめ","城番が置かれ、海の守りを担う"],["1638年ごろ","阿波九城が廃止され、撫養城も廃城"],["江戸時代","撫養の塩田が栄え、港町として発展"],["昭和時代","妙見山が公園として整備され、城風の建物が建つ"],["現在","妙見山公園として鳴門の町と海を見わたす展望地"]],"who":[["蜂須賀家政","阿波の初代大名。阿波九城を置いた"],["撫養城の城番","家政の家臣として城を守った"],["撫養の塩田の人びと","江戸時代に塩づくりで町を栄えさせた"]],"deep":["«阿波九城» は、一宮・撫養・西条・川島・脇・大西・牛岐・仁宇・海部の九つとされ、徳島城を中心に国の要所を押さえる配置でした。","岡崎城の名は、城のある地の名（岡崎）にちなむといわれます。","阿波九城の廃止は、1615年の «一国一城令» からしばらくたった1638年ごろとされ、ほかの藩より遅かったことが特徴です。","撫養の塩田は «斎田塩（さいたじお）» などの名で知られ、阿波の «藍» と並ぶ重要な特産品でした。","城が置かれる前、戦国時代にもこの山には砦があったとする説がありますが、詳しいことはわかっていません。","妙見山の名は、山にまつられる妙見神社に由来します。","阿波九城の城番は «城代» とも呼ばれ、城の守りに加えて周辺の村々の治安や年貢の取りまとめにもかかわったと考えられています。","撫養は、鳴門海峡をはさんで淡路島と向かい合う位置にあり、江戸時代には阿波と大坂を結ぶ船の出入りの港として重要でした。"],"look":["妙見山公園からの鳴門の町と海の眺め","城をイメージした建物（復元天守ではない）","妙見神社","山のまわりの地形や石垣の名残","山頂からの撫養川と塩田跡周辺の町並み"],"q":["蜂須賀家政が阿波の国に置いた城のまとまりを何という?","«阿波九城»。撫養城はその一つで、海の守りを担いました。"],"koji":[{"w":"一国一城令","m":"1615年に江戸幕府が出した命令。大名の城を一つの国に一つだけにさせた"}],"myth":"戦国期の砦の有無、城名の由来は諸説。","img":["阿波九城","蜂須賀家政","鳴門市","一国一城令"],"wp":"撫養城","rel":{"ev":["tosanikki"],"grave":[]},"ph":[["c:4/48/Tori-i_kinen_hakubutsukan.jpg",400,300,"撫養城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:5/54/Tride_Naruto.jpeg",1440,1080],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:d/d5/Hachisuka_Iemasa.jpg",2897,5437,"蜂須賀家政"],["c:6/6f/Naruto_Whirlpools_taken_4-21-2008.jpg",3456,2304,"鳴門市"],["c:5/5e/MEIN%26SMALL_CASTLE_TOWER_%2CMATSUYAMA_CASTLE%28IYO%29.JPG",2816,2112,"一国一城令"]]},{"id":"36_kizu_jo","n":"木津城（長宗我部と三好の攻防）","yomi":"きづじょう","cat":"城","rank":"A","y":1585,"era":["azuchi"],"sh":"","ad":"鳴門市撫養町木津","st":"JR鳴門線 撫養駅から歩いて約20分、または車で約5分","la":34.169,"lo":134.6,"hook":"水の手を断たれ、城兵はついに門を開いた。秀吉の四国攻め、阿波での最初の大きな戦いの場。","lead":"鳴門市の小高い山にあった戦国時代の城です。はじめは三好氏の家臣・篠原氏の城でしたが、長宗我部元親の阿波攻めで長宗我部方の城になりました。1585年、豊臣秀吉の四国攻めで羽柴秀長の軍に囲まれ、落城しました。","story":["戦国時代の阿波は、三好氏の国でした。三好氏は一時は京都まで支配するほどの力を持ちましたが、やがて力が弱まり、土佐から長宗我部元親が攻めこんできます。木津城は、三好氏の家臣・篠原自遁（しのはらじとん）が守った城でした。","長宗我部の勢いはすさまじく、1582年の中富川の戦いで三好方は大敗。阿波の城は次々と長宗我部方に下ります。木津城も長宗我部の城となり、東条関兵衛（とうじょうせきのひょうえ）が守りにつきました。","1585年、今度は豊臣秀吉が四国に大軍を送ります。阿波には秀吉の弟・羽柴秀長と甥の秀次が上陸しました。最初の標的の一つが、海の入口を押さえる木津城です。","秀長は、城に水を運ぶ道を断つ作戦に出たと伝わります。«水がなければ、城は守れない»。城兵はのどのかわきに苦しみ、ついに城を明け渡しました。木津城が落ちると、長宗我部方の城は次々に崩れていきます。","その年のうちに元親は降伏し、四国は秀吉のものとなりました。木津城は、四国の戦国時代が終わる «はじまりの場所» の一つといえます。今は山の上に曲輪の跡がわずかに残り、静かに往時をしのばせています。"],"tl":[["戦国時代","三好氏の家臣・篠原氏が木津城を拠点とする"],["1582年","中富川の戦い。長宗我部元親が阿波の大半を制圧"],["1582年ごろ","木津城が長宗我部方の城となる"],["1585年6月ごろ","羽柴秀長・秀次が阿波に上陸し、木津城を攻める"],["1585年","木津城が開城。同年、長宗我部元親が降伏"],["その後","廃城となる"]],"who":[["篠原自遁","三好氏の家臣。木津城を拠点とした"],["東条関兵衛","長宗我部方として木津城を守った武将"],["長宗我部元親","土佐の戦国大名。阿波に攻めこんだ"],["羽柴秀長","秀吉の弟。四国攻めの総大将として木津城を攻めた"]],"deep":["四国攻めで秀吉方は、阿波・讃岐・伊予の三方から攻めこみました。阿波方面の主力は秀長・秀次の軍で、兵の数は数万といわれます。","篠原自遁は、三好氏の重臣・篠原長房の一族（弟とも）とされますが、関係には諸説あります。","木津城の攻略では、水の手（城の水源）を断つ作戦がとられたと伝わります。山城にとって水の確保は最大の弱点でした。","東条関兵衛は開城ののち土佐へもどりましたが、城を明け渡したことをとがめられたとも伝わります。","木津城のあとの秀長軍は、一宮城・岩倉城・脇城などを攻め、長宗我部方の阿波の拠点を次々に落としていきました。","木津城のある撫養の地は、淡路島への渡し口にあたり、秀吉方の上陸地点に近いことから最初の攻撃目標になったと考えられます。","中富川の戦い（1582年）は、勝瑞城の三好方（十河存保）と長宗我部元親の大軍が戦った、阿波の戦国史で最大級の合戦です。"],"look":["城山に残る曲輪（くるわ）の平らな地形","山の上からの撫養の町と海の眺め","城の水の手と考えられる場所の地形","麓の案内板（あれば）"],"q":["木津城を攻めたとき、秀長の軍がとった作戦は?","城の水の手（水源）を断つ作戦と伝わります。水が尽きた城兵は開城しました。"],"koji":[],"myth":"篠原自遁と長房の関係、水の手を断った話、東条関兵衛のその後は諸説・伝承。","img":["四国攻め","羽柴秀長","長宗我部元親","中富川の戦い"],"wp":"木津城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/95/Hidenaga_Toyotomi.jpg",560,658,"羽柴秀長"],["c:5/53/Tyousokabe_Mototika.jpg",470,658,"長宗我部元親"],["c:7/76/Shozuijo09.jpg",1831,1348,"中富川の戦い"]]},{"id":"36_ichinomiya_jo","n":"一宮城（阿波九城の要）","yomi":"いちのみやじょう","cat":"城","rank":"A","y":1585,"era":["muromachi","azuchi","edo"],"sh":"","ad":"徳島市一宮町","st":"JR徳島駅から徳島市営バス（一宮・神山方面）で約30分、«一宮札所前» 下車。登り口から本丸まで山道を歩いて約30分","la":34.029,"lo":134.453,"hook":"水を断たれ、城を明け渡した武将は、主君に «降伏を» と説いた。四国の戦国の終わりを決めた山城。","lead":"一宮神社の裏山にある、阿波でも大きな山城の跡です。南北朝時代に小笠原氏（のちの一宮氏）が築いたと伝わり、戦国時代には長宗我部と豊臣の激しい攻防の場になりました。1585年からは «阿波九城» の一つとなり、江戸時代のはじめに廃城となりました。建物はなく、石垣や曲輪が残ります。","story":["一宮神社の横の登り口から、木の根と石の山道を登ります。やがて現れるのは、苔むした石垣。本丸は山のてっぺんにあり、眼下には鮎喰川と徳島の平野が広がります。«ここを取れば阿波が見わたせる» ――まさに要の城です。","城を築いたのは、南北朝時代に阿波の守護として来た小笠原氏の一族と伝わります。一族は «一宮» の神社の神職も兼ね、«一宮氏» を名乗りました。神社と城がひとつになって、土地を治めていたのです。","戦国時代の終わり、土佐の長宗我部元親が阿波を制圧すると、一宮城は長宗我部方の重要な城になり、谷忠澄（たにただずみ）らが守りました。1585年、豊臣秀吉の弟・羽柴秀長の大軍がこの城を囲みます。","秀長は城の水の手を断ち、城兵を追いつめたと伝わります。長い籠城のすえ、谷忠澄は城を明け渡しました。そして土佐にもどると、元親に «上方の軍勢はけた違い。とても勝てません、降伏を» と説いたといわれます。元親はやがて降伏を決めました。","阿波の大名となった蜂須賀家政は、はじめこの一宮城に入り、翌年に徳島城ができると本拠を移しました。一宮城は «阿波九城» の一つとして残りましたが、1638年ごろ廃城に。山の中の石垣は、戦国と江戸のはざまの記憶を今に伝えています。"],"tl":[["南北朝時代（1338年ごろと伝わる）","小笠原氏（一宮氏）が一宮城を築く"],["1582年","長宗我部元親が阿波を制圧。一宮城は長宗我部方に"],["1585年","羽柴秀長が一宮城を攻める。谷忠澄らが開城"],["1585年","蜂須賀家政が阿波に入り、一時この城に入る"],["1586年ごろ","徳島城が完成し、家政が本拠を移す。一宮城は阿波九城の一つに"],["1638年ごろ","阿波九城の廃止により廃城"]],"who":[["一宮氏（小笠原氏）","一宮城を築き、一宮神社の神職も兼ねた一族"],["谷忠澄","長宗我部方の武将。開城後、元親に降伏をすすめた"],["羽柴秀長","秀吉の弟。四国攻めの総大将として城を攻めた"],["蜂須賀家政","阿波の大名。はじめ一宮城に入った"]],"deep":["本丸には石垣が残りますが、これは蜂須賀家が阿波九城として使った時期に手が加えられたものと考えられています。","一宮城は、本丸を中心に尾根づたいに多くの曲輪を連ねた大規模な山城で、県内でも屈指の規模です。","谷忠澄は長宗我部家の重臣で、もとは土佐の神職の家の出とされます。降伏をすすめたことで元親の怒りを買ったとも伝わりますが、細部は軍記物によります。","一宮城の攻防の期間は、数週間にわたったとされます。秀長軍は付近に陣を張り、長期戦になりました。","«阿波九城» の城番には蜂須賀家の重臣が任じられ、一宮城は徳島城の西の守りとして重視されました。","登り口は一宮神社の近く。山道は急で、雨のあとはすべりやすいので、歩きやすい靴で行きましょう。"],"look":["本丸の石垣","尾根に連なる曲輪や堀切","本丸からの鮎喰川と徳島平野の眺め","ふもとの一宮神社と13番札所・大日寺"],"q":["一宮城を開城したあと、元親に降伏をすすめたと伝わる長宗我部方の武将は?","谷忠澄（たにただずみ）。秀吉方の大軍の力を見て、降伏を説いたといわれます。"],"koji":[],"myth":"築城年、谷忠澄の進言の内容は伝承・軍記物による。","img":["谷忠澄","羽柴秀長","阿波九城","一宮神社 (徳島市)"],"wp":"一宮城 (阿波国)","rel":{"ev":[],"grave":[]},"ph":[["c:5/53/Itimayajo01.jpg",1536,2048,"一宮城 (阿波国)"],["c:5/57/Itimayajo28.jpg",2048,1536],["c:0/0f/Itimayajo27.jpg",2048,1536],["c:a/ad/Itimayajo24.jpg",2048,1536],["c:0/06/Itimayajo23.jpg",2048,1536],["c:8/82/Itimayajo22.jpg",2048,1536],["c:c/c4/Itimayajo21.jpg",2048,1536],["c:f/fc/Itimayajo20.jpg",2048,1536]]},{"id":"36_kawashima_jo","n":"川島城","yomi":"かわしまじょう","cat":"城","rank":"B","y":1585,"era":["azuchi","edo","showa"],"sh":"","ad":"吉野川市川島町川島","st":"JR徳島線 阿波川島駅から歩いて約10分","la":34.061,"lo":134.323,"hook":"吉野川に突き出た岩の上。«阿波九城» の一つがあった場所に、今は白い天守風の建物が立つ。","lead":"吉野川の南岸、川に突き出した岩山にあった城です。1585年に阿波の大名となった蜂須賀家が置いた «阿波九城» の一つで、江戸時代のはじめに廃城となりました。今ある天守風の建物は昭和に建てられたもので、昔の城の復元ではありません。","story":["阿波川島駅から少し歩くと、吉野川の流れの上に白い天守がそびえています。«昔のお城がそのまま残っているの?» ――いいえ。これは昭和に建てられた天守風の建物です。でも、ここに城があったのは本当です。","城のあった岩山は «岩の鼻» と呼ばれ、吉野川に向かって突き出しています。川を行き来する舟を見張るのにぴったりの場所。吉野川は、阿波の西と東を結ぶ大切な «水の道» でした。","戦国時代にも、このあたりには地元の武士の城があったといわれます。1585年、秀吉の四国攻めのあと阿波に入った蜂須賀家政は、ここを «阿波九城» の一つとし、家臣を城番として置きました。","江戸時代になって世の中が落ち着くと、城の役目は小さくなり、1638年ごろ阿波九城は廃止されます。川島城も取りこわされ、城下の町は吉野川の舟運と藍の商いで栄えていきました。","今、岩の鼻の上は公園と展望台になっています。すぐ下を流れる «四国三郎» 吉野川の大きさを感じながら、城番たちが見張った川の景色を想像してみましょう。","川島の町を歩くと、古い商家や土蔵が点々と残っています。城がなくなったあとも、吉野川の水の道は町に人とモノを運び続けました。城の山は、その町の歩みを見守ってきた目じるしなのです。"],"tl":[["戦国時代","地元の武士の城があったといわれる"],["1585年","蜂須賀家政が阿波九城の一つとして川島城を置く"],["江戸時代はじめ","城番が置かれ、吉野川の守りを担う"],["1638年ごろ","阿波九城の廃止により廃城"],["昭和の終わりごろ","天守風の建物が建てられ、観光施設となる"],["現在","岩の鼻展望台とともに吉野川の眺めの名所"]],"who":[["蜂須賀家政","阿波の初代大名。川島城を九城の一つとした"],["川島城の城番","蜂須賀家の家臣。林氏が務めたといわれる"],["吉野川の舟運の人びと","城下の川島の町を栄えさせた"]],"deep":["川島城の城番は、蜂須賀家の家臣・林能勝（はやしよしかつ）が務めたといわれます。","天守風の建物は昭和に観光施設として建てられたもので、戦国・江戸時代にこの形の天守があったことを示す資料はありません。","«岩の鼻» は、吉野川の南岸に突き出た岩山で、川の流れを見わたせる要害でした。川の対岸は旧麻植郡の平野が広がります。","吉野川は «四国三郎» と呼ばれ、利根川（坂東太郎）・筑後川（筑紫次郎）と並ぶ暴れ川として知られます。","江戸時代の吉野川流域は藍の一大産地で、川島にも藍商人の町並みが発達しました。","阿波九城の城番には、蜂須賀家の信頼の厚い家臣が選ばれました。九つの城は、それぞれ川や街道、海の出入口を押さえる位置にあります。"],"look":["岩の鼻展望台からの吉野川の眺め","天守風の建物（昭和の建築）","岩山の地形","川島の町並み"],"q":["吉野川は «四国○○» と呼ばれる。○○に入る言葉は?","«三郎»。«坂東太郎»（利根川）、«筑紫次郎»（筑後川）と並ぶ呼び名です。"],"koji":[],"myth":"戦国期の城主、城番の人物名は諸説。天守風建物は史実の復元ではない。","img":["吉野川","阿波九城","蜂須賀家政","吉野川市"],"wp":"川島城","rel":{"ev":[],"grave":[]},"ph":[["c:2/26/Kawasimajo02.jpg",1489,2008,"川島城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/9e/Yoshinogawa%28Tokushima%29.jpg",1230,916,"吉野川"],["c:d/d5/Hachisuka_Iemasa.jpg",2897,5437,"蜂須賀家政"],["c:d/da/Huziidera12.jpg",1600,1064,"吉野川市"]]},{"id":"36_kamizakura_jo","n":"上桜城（篠原長房の最期）","yomi":"かみざくらじょう","cat":"城","rank":"B","y":1573,"era":["muromachi"],"sh":"","ad":"吉野川市川島町桑村","st":"JR徳島線 阿波川島駅から車で約10分。山道を登る","la":34.045,"lo":134.305,"hook":"三好家を支え、法律まで作った名臣。その最期は、主君に攻められる悲しい戦いだった。","lead":"吉野川市の山の上にあった戦国時代の城で、三好氏の重臣・篠原長房（しのはらながふさ）の居城でした。1573年、長房は主君の三好長治らに攻められ、この城で最期をとげました。今は建物がなく、山の中に城の跡が残ります。","story":["篠原長房は、三好長慶の弟・三好実休（じっきゅう）に仕えた家臣でした。実休が戦で亡くなると、幼い息子・長治を支え、阿波の政治を任されます。長房は «新加制式（しんかせいしき）» という法律をまとめ、国を治める決まりを整えました。","長房は戦でも活躍しました。三好一族が織田信長と戦ったとき、長房は阿波の大軍を率いて海を渡り、摂津で信長と向かい合いました。«三好に篠原あり» ――その名は畿内にも知られていたのです。","ところが、長治が成長すると、主君と重臣のあいだにすき間ができていきます。«長房は力を持ちすぎた» と、うわさや中傷があったとも伝わります。やがて長治は、細川真之とともに、長房の上桜城を攻めることを決めました。","1573年、上桜城は大軍に囲まれました。長房は最後まで戦い、城とともに最期をとげたと伝わります。三好家を支えた柱を、三好家自身が倒してしまったのです。","長房を失った阿波三好家は、その後まとまりを失い、やがて長宗我部元親の攻撃を受けて力を失っていきます。«忠臣を失った国は弱くなる» ――上桜城の山は、その教訓を静かに語っているようです。"],"tl":[["1562年","三好実休が久米田の戦いで戦死。長房が幼い長治を支える"],["1560年代","長房が分国法 «新加制式» をまとめる"],["1570年","長房が阿波の軍を率いて摂津へ渡り、織田信長と対峙"],["1573年","三好長治・細川真之に攻められ、上桜城で長房が最期をとげる"],["1582年","長宗我部元親が阿波を制圧。阿波三好家は衰える"]],"who":[["篠原長房","三好家の重臣。«新加制式» を作った。上桜城の城主"],["三好長治","阿波三好家の当主。長房を攻めた"],["細川真之","阿波の守護家。長治とともに長房を攻めた"],["三好実休","長治の父。長房の主君"]],"deep":["«新加制式» は三好氏（阿波）の分国法で、全22か条とされます。鎌倉幕府の «御成敗式目» を補う形で作られました。","長房が摂津に渡ったのは、1570年の野田・福島の戦いのころ。三好三人衆とともに信長と戦い、その後の和睦にもかかわったとされます。","長房が攻められた理由には、長治側近の讒言（ざんげん）説、宗教をめぐる対立説などがあり、はっきりしません。","城跡は山の尾根にあり、曲輪の跡などが残るとされます。整備状況はかぎられるので、訪れる前に地元の情報を確認しましょう。","長房の子の一部は落ちのびたとも伝わり、篠原氏の系譜には諸説があります。","三好長慶は畿内を支配し «天下人» とも呼ばれた人物で、その弟の実休は阿波を本拠として兄を支えました。阿波は三好政権のふるさとでした。","長房の死後、長治は勝瑞城を拠点に国を治めましたが、国内の反発を受け、1577年に細川真之らとの戦いの中で命を落としたとされます。"],"look":["山上の曲輪の跡","尾根からの吉野川平野の眺め","ふもとの案内板（あれば）","近くの川島城跡とあわせてめぐる"],"q":["篠原長房がまとめた、三好氏の法律の名前は?","«新加制式（しんかせいしき）»。三好氏（阿波）の分国法です。"],"koji":[],"myth":"長房が攻められた理由、最期の様子は諸説。","img":["篠原長房","三好長治","新加制式","三好実休"],"wp":"上桜城","rel":{"ev":[],"grave":[]},"ph":[["c:b/be/Uesakura03.jpg",1785,1512,"上桜城"],["c:7/7a/Uesakura04.jpg",2776,1728],["c:b/b9/Uesakura10.jpg",2048,1536],["c:0/08/Uesakura09.jpg",2048,1536],["c:3/3c/Uesakura08.jpg",2048,1536],["c:a/a1/Uesakura06.jpg",2048,1536],["c:b/bc/Uesakura05.jpg",1918,1454],["c:b/bc/Uesakura01.jpg",1867,1392]]},{"id":"36_iwakura_jo","n":"岩倉城（美馬の三好一族の城）","yomi":"いわくらじょう","cat":"城","rank":"A","y":1585,"era":["muromachi","azuchi"],"sh":"","ad":"美馬市脇町岩倉","st":"JR徳島線 穴吹駅から車で約15分","la":34.07,"lo":134.13,"hook":"吉野川中流を見張る山城。三好一族、長宗我部、そして秀吉の軍――城の主は目まぐるしく変わった。","lead":"美馬市脇町の西、吉野川を見下ろす山にあった戦国時代の城です。三好一族の城として知られ、長宗我部元親の阿波攻め、豊臣秀吉の四国攻めの舞台となりました。すぐ東の脇城とならぶ、吉野川中流の守りの要でした。","story":["吉野川の中流は、阿波の西と東、そして讃岐（香川）へ抜ける道が交わる大切な場所です。そこを押さえるのが、岩倉城と脇城。二つの城は、並んで川の上流と下流をにらんでいました。","戦国時代、岩倉城は三好一族の城でした。三好康長（笑岩）の子・三好康俊が城主だったと伝わります。けれど土佐の長宗我部元親が阿波に攻めこむと、吉野川中流の武士たちは、三好につくか長宗我部につくか、厳しい選択をせまられました。","康俊は長宗我部方に通じたともいわれ、1579年ごろ、この近くで三好方と長宗我部方の戦いが起きたと伝わります（脇城外の戦い）。味方と思っていた者が敵になる――戦国の阿波は、そんな疑いとかけひきの世界でした。","1585年、秀吉の四国攻めで、羽柴秀次の軍が岩倉城に迫りました。長宗我部方の武将が城を守りましたが、秀吉方の大軍の前に城を明け渡したと伝わります。","戦のあと、阿波の大名となった蜂須賀家政は、すぐ隣の脇城を «阿波九城» の一つとし、岩倉城は使われなくなりました。今は山の上に曲輪の跡が残り、脇町の町並みとあわせて戦国の吉野川をしのぶことができます。","山の上から見下ろすと、吉野川の広い河原と、対岸の穴吹の町が見えます。ここを行き交う舟や人を見張ることが、城のいちばんの役目でした。"],"tl":[["戦国時代","三好一族の城となる"],["1579年ごろ","近くで三好方と長宗我部方が戦う（脇城外の戦いと伝わる）"],["1582年","長宗我部元親が阿波を制圧。岩倉城も長宗我部方に"],["1585年","羽柴秀次の軍が攻め、城が明け渡される"],["1585年以降","脇城が阿波九城となり、岩倉城は廃城"]],"who":[["三好康俊","三好康長の子。岩倉城主と伝わる"],["三好康長（笑岩）","三好一族の重鎮。のちに秀吉に仕えた"],["長宗我部元親","阿波に攻めこんだ土佐の戦国大名"],["羽柴秀次","秀吉の甥。四国攻めで岩倉城を攻めた"]],"deep":["三好康長は、信長・秀吉に仕えて三好家の生き残りをはかった人物で、一時は秀吉の甥（のちの秀次）を養子にしたともいわれます。","岩倉城と脇城は約2km離れた «ならびの城» で、吉野川中流の渡しや道を押さえる役割がありました。","«脇城外の戦い» の経過（だれがだれを裏切ったか）は軍記物によって書き方が異なり、諸説があります。","1585年の岩倉城攻めでは、秀吉方が櫓を組んで城を攻めたとも伝わりますが、細部は確かめられていません。","城跡は山の上にあり、曲輪や堀切の跡が残るとされます。整備は限られるので、足もとに注意して訪れましょう。","戦国時代の吉野川中流には、岩倉・脇のような山城が点々と築かれ、川の渡しや街道を押さえていました。","美馬市脇町の周辺は、古代から吉野川中流の中心で、段の塚穴や郡里廃寺など、古い時代の遺跡も多く残る地域です。"],"look":["山上の曲輪と堀切の跡","吉野川中流の眺め","東にある脇城跡との位置関係","ふもとの脇町うだつの町並み","城跡の登り口の案内（事前に地元で確認）"],"q":["岩倉城と並んで吉野川中流を守った、すぐ東の城は?","脇城。蜂須賀家政が «阿波九城» の一つにしました。"],"koji":[],"myth":"城主の顔ぶれ、脇城外の戦いの経過、1585年の攻城の細部は諸説・軍記物による。","img":["三好康長","羽柴秀次","脇城","四国攻め"],"wp":"岩倉城 (阿波国)","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:1/1d/Toyotomi_Hidetsugu-cropped.jpg",850,1000,"羽柴秀次"]]},{"id":"36_waki_jo","n":"脇城（脇町を見下ろす阿波九城）","yomi":"わきじょう","cat":"城","rank":"A","y":1585,"era":["azuchi","edo"],"sh":"","ad":"美馬市脇町脇町","st":"JR徳島線 穴吹駅から車で約10分。脇町のうだつの町並みから歩いて約20分","la":34.0725,"lo":134.1555,"hook":"城はなくなっても、城番が育てた町は残った。«うだつ» の上がる脇町の出発点。","lead":"美馬市脇町の北の山にあった城で、1585年から蜂須賀家の «阿波九城» の一つとなり、重臣の稲田植元（いなだたねもと）が城を守りました。1638年ごろ廃城となりましたが、城下に整えられた町は、藍の商いで栄える «うだつの町並み» へと育ちました。","story":["脇町の «うだつの町並み» を歩くと、立派な瓦屋根の商家が並びます。家と家の境に張り出した壁が «うだつ»。火事の延焼を防ぐためのものですが、お金持ちの商家ほど立派なうだつを上げたので、«うだつが上がらない» という言葉まで生まれました。この町の始まりをたどると、北の山の脇城にたどりつきます。","戦国時代、脇城は三好方の城でした。長宗我部元親が阿波に攻めこむと、吉野川中流の城々は争いの的になり、脇城のまわりでも戦いが起きたと伝わります。«虎伏せ城» とも呼ばれるこの城は、山の形が虎の伏せた姿に見えるからだといわれます。","1585年、阿波の大名となった蜂須賀家政は、脇城を «阿波九城» の一つとし、重臣の稲田植元を城番に置きました。植元は城の守りだけでなく、城下の町づくりに力を入れ、商人を集めて市を開いたと伝わります。","1638年ごろ、阿波九城が廃止され、脇城も役目を終えます。けれど植元が育てた町は、吉野川の舟運と、阿波の特産品 «藍» の取引で大いに栄えました。商人たちは競って立派な家を建て、うだつを上げたのです。","稲田家はその後、淡路島の洲本に移り、城代として蜂須賀家を支えました。そして明治のはじめ、稲田家の家臣たちは遠く北海道の静内へ渡り、開拓に取り組むことになります。脇城から始まった物語は、海を越えて北の大地にまで続いているのです。"],"tl":[["戦国時代","三好方の城として使われる"],["1579年ごろ","脇城のまわりで三好方と長宗我部方が戦ったと伝わる"],["1585年","蜂須賀家政が阿波九城の一つとし、稲田植元を城番とする"],["江戸時代はじめ","植元が城下町を整え、脇町が発展する"],["1638年ごろ","阿波九城の廃止により廃城"],["1988年","脇町の町並みが国の重要伝統的建造物群保存地区に選ばれる"]],"who":[["稲田植元","蜂須賀家の重臣。脇城の城番となり、脇町の町づくりを進めた"],["蜂須賀家政","阿波の初代大名。脇城を阿波九城の一つとした"],["長宗我部元親","阿波に攻めこんだ土佐の戦国大名"],["脇町の藍商人","藍の取引で栄え、うだつの上がる商家を建てた"]],"deep":["稲田植元は蜂須賀正勝（小六）の時代からの盟友とされ、蜂須賀家の筆頭家老の家柄となりました。","稲田家はのちに淡路の洲本城代となり、明治初年の «庚午事変（稲田騒動）» をきっかけに、家臣団が北海道の静内などへ移住しました。この話は小説・映画 «北の零年» の題材にもなりました（作品は創作を含む）。","脇町の «うだつの町並み» は1988年に国の重要伝統的建造物群保存地区に選ばれました。町並みの近くには、昭和初期の芝居小屋 «オデオン座（脇町劇場）» もあります。","«虎伏せ城» の名は山の形に由来するといわれ、別名として地元で伝えられています。","城跡は脇町の北の山にあり、曲輪や堀切の跡が残るとされます。城跡からは脇町の町並みと吉野川が見わたせます。","«うだつが上がらない» の語源には諸説あり、うだつ（梲）を上げられない＝出世できない、という説明がよく知られます。"],"look":["城跡からの脇町と吉野川の眺め","山上の曲輪・堀切の跡","ふもとのうだつの町並み（重伝建）","脇町劇場（オデオン座）"],"q":["脇町の商家に見られる、家の境に張り出した防火の壁を何という?","«うだつ»。立派なうだつは商家の豊かさのしるしでした。"],"koji":[{"w":"うだつが上がらない","m":"なかなか出世できない、ぱっとしないこと。うだつを上げられない家から、という説がある"}],"myth":"脇城外の戦いの経過、«虎伏せ城» の由来、植元の町づくりの細部は伝承を含む。","img":["脇町","稲田植元","庚午事変","うだつ"],"wp":"脇城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:b/b8/Wakimachi_Minami-machi_in_Mima_Tokushima_pref01.jpg",2304,1536,"脇町"],["c:c/c6/Inada_Tanemoto.jpg",2125,4694,"稲田植元"]]},{"id":"36_hakuchi_jo","n":"白地城（長宗我部元親の四国統一の拠点）","yomi":"はくちじょう","cat":"城","rank":"S","y":1577,"era":["muromachi","azuchi"],"sh":"三好市指定史跡","ad":"三好市池田町白地","st":"JR阿波池田駅から車で約15分（宿泊施設 «あわの抄» の南どなりの児童公園に碑）","la":34.0156,"lo":133.781,"hook":"西へ行けば伊予、北へ行けば讃岐、川を下れば阿波、さかのぼれば土佐。«四国の十字路» に立つ山城こそ、長宗我部元親が天下ならぬ «四国» を夢見た場所だった。","lead":"白地城は、吉野川が大きく曲がる山あいにあった戦国時代の城です。四国の4つの国へ道が通じる場所にあったため、土佐の長宗我部元親がここを奪い、四国じゅうへ攻め込む拠点にしました。いまは城の跡がほとんど残っておらず、公園の一角に石碑と小さな神社があります。","story":["地図を広げて、四国のまん中あたりに指を置いてみてください。三好市池田町の白地は、ちょうどそのあたり。西の境目峠をこえれば伊予（愛媛）、北の猪ノ鼻峠をこえれば讃岐（香川）、吉野川を下れば徳島平野、川をさかのぼれば土佐（高知）。まるで四国の «交差点» です。なぜこんな山の中に城があったのか? 答えはこの «道» にありました。","城を開いたのは、この地の荘官だった近藤氏と伝わります。南北朝時代の1335年ごろに城を構え、のちに土地の名をとって «大西氏» を名のりました。大西氏は阿波の守護・細川氏、そして戦国時代には三好氏に従いながら、阿波の西のはしを200年以上治めたといわれます。","戦国の終わり、土佐から一人の武将がこの交差点に目をつけます。長宗我部元親です。天正5年（1577年）ごろ、元親は白地城を攻め、城主の大西覚用は讃岐へのがれました。『元親記』には、元親が «この大西さえ手に入れば、阿波・讃岐・伊予の三国の辻だから、どこへでも自由に攻め出せる» と満足した、と書かれています。","それからの元親は、白地を足場に阿波、讃岐、伊予へと兵を送り出しました。四国の «まん中» を押さえたことが、四国のほとんどを勢力下に置く大きな力になったのです。けれども天正13年（1585年）、豊臣秀吉の大軍が四国に攻め寄せます。白地城は長宗我部方の守りの城として使われましたが、元親が降伏して土佐一国に戻されると、城はその役目を終えて廃城になりました。","城の跡には昭和の終わりごろまで曲輪や堀などが残っていましたが、宿泊施設の建設でその多くがこわされてしまいました。いま残るのは、わずかな土塁や切岸、そして «白地城址» の石碑と大西神社だけ。«ここが四国の十字路か» と思いながら山や川の流れをながめると、元親がこの場所をほしがった理由が、体で感じられるはずです。"],"tl":[["1335年","近藤京帝が城を構えたと伝わる。のち大西氏を名のる"],["戦国時代","大西氏が三好氏に従い、阿波西部を治める"],["1577年ごろ","長宗我部元親が攻め取り、大西覚用は讃岐へのがれる（1578年説もある）"],["1578年ごろ以降","元親の四国攻めの拠点となる"],["1585年","豊臣秀吉の四国攻め。長宗我部氏が土佐へ退き、廃城"],["昭和後期","宿泊施設の建設で遺構の多くが失われる"]],"who":[["長宗我部元親","土佐の戦国大名。白地城を四国制覇の拠点にした"],["大西覚用","白地城の城主。元親と和議を結んだり離れたりしたのち、城を追われた"],["近藤京帝","城を開いたと伝わる人物。大西氏の祖とされる"],["谷忠澄","元親の家臣。攻略後の白地城に入ったとされる"]],"deep":["«四国の十字路»: 白地のすぐ近くで、吉野川が北へ流れを変え、祖谷や土佐方面への谷も分かれます。現在も徳島道・国道32号・国道192号が集まり、交通の要であることは変わりません。","『元親記』の «阿讃伊予三ヶ国の辻» という言葉は、元親の戦略眼を示す一文としてよく引かれます。ただし『元親記』は家臣の子孫が江戸時代初めに書いた軍記で、せりふがそのまま本人の言葉かはわかりません。","大西覚用のその後ははっきりしません。元親に降ったのち、十河存保の反撃で亡くなったとも、1578年に討死したとも伝わり、確かな史料がないとされます。","大西氏は «近藤氏» が改姓した一族といわれ、鎌倉時代にこの地へ入った小笠原氏（のちの三好氏）とも深くつながっていました。","白地城のあと、この地域の中心の役割は近くの大西城（池田城）が引きつぎ、江戸時代には徳島藩の «阿波九城» の一つとなりました。","近くの雲辺寺（四国八十八箇所66番）は、元親が住職と問答したという伝説で知られます。«四国を取るのは無理だ» と言われたという話ですが、後世の伝説と考えられています。"],"look":["白地児童公園の一角にある «白地城址» の石碑","城の守り神とされる大西神社","わずかに残る土塁・切岸（見分けるのは難しいので案内板を手がかりに）","吉野川が大きく曲がる地形。«十字路» の意味が一目でわかる"],"q":["長宗我部元親が白地城を «三国の辻» と呼んだ、その三国とは?","阿波・讃岐・伊予。土佐から来た元親にとって、残りの三国すべてに通じる場所でした。"],"koji":[],"myth":"城を開いた年や人物、落城の年（1577年か1578年か）には諸説。雲辺寺の問答は伝説。","img":["長宗我部元親","大西覚用","雲辺寺"],"wp":"白地城","rel":{"ev":[],"grave":[]},"ph":[["c:1/11/Hakuchi_Castle%2C_enkei.jpg",6002,3978,"白地城"],["c:2/22/Hakuchi_Castle%2C_setsumeiban.jpg",5984,3950],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:e/ea/Hakutizyou01.jpg",1600,1199],["c:c/c9/Hakutizyouato02.jpg",1600,1172],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:5/53/Tyousokabe_Mototika.jpg",470,658,"長宗我部元親"],["c:4/43/Unpenji20211106_1.jpg",1600,1199,"雲辺寺"]]},{"id":"36_onishi_jo","n":"大西城（池田城）","yomi":"おおにしじょう","cat":"城","rank":"B","y":1221,"era":["kamakura","muromachi","edo"],"sh":"","ad":"三好市池田町ウエノ","st":"JR阿波池田駅から歩いて約10〜15分","la":34.0308,"lo":133.8089,"hook":"町の小学校と幼稚園のあたりが、じつは鎌倉時代から続く城の跡。石垣のかけらが、阿波のいちばん西の «守り» を今に伝える。","lead":"大西城は、阿波池田の町の北側、吉野川を見下ろす台地の上にあった城です。鎌倉時代に阿波の守護となった小笠原氏が築いたと伝わり、江戸時代の初めには徳島藩の «阿波九城» の一つになりました。いまは学校や神社の敷地になり、幼稚園に石垣が残っています。","story":["阿波池田駅から北へ歩くと、町のうしろに高さ30メートルほどの台地が見えてきます。«上野（うえの）» と呼ばれるこの台地の上に、かつて大西城がありました。なぜ «大西» なのでしょう? このあたりは阿波の国のいちばん西。だから «大西» と呼ばれていたのです。","話は鎌倉時代にさかのぼります。1221年の承久の乱で手がらを立てた小笠原長清が阿波の守護になり、その子の長経が阿波へやってきました。長経は大西城を築き、朝廷側についた前の守護・佐々木氏の城を攻め落としたと伝わります。«国の西のはしに本拠を置くなんて変だ» と思うかもしれません。でもここは讃岐・伊予・土佐と接する四国の «まん中»。«やがては四国全体を» という見通しがあったのでは、という見方もあります。","小笠原氏はのちに «三好» と名を変え、勝瑞（藍住町）へ移っていきます。これが、戦国時代に天下を動かす三好氏のルーツです。大西城には一族の大西氏が入り、近くの白地城とあわせて阿波西部を治めました。","戦国の終わり、長宗我部元親に白地城が奪われ、さらに豊臣秀吉の四国攻めのあと、1585年に蜂須賀家政が阿波の領主になります。家政は国のあちこちに «阿波九城» と呼ばれる支城を置き、大西城もその一つとして整えられました。城代には牛田一長や中村重勝が入ったとされます。","しかし1615年の «一国一城令» の流れの中で、阿波では1638年に支城がいっせいに廃城となりました。大西城もこのとき姿を消します。いまは諏訪神社や池田の幼稚園・小中学校のあたりが城の範囲だったと考えられ、幼稚園には石垣が残っています。子どもたちの声がひびく場所が、かつての城だった ── そんな時の流れを感じられる城跡です。"],"tl":[["1221年","承久の乱。のちに小笠原長経が大西城を築いたと伝わる"],["南北朝時代","小笠原氏が細川氏に従う"],["室町〜戦国時代","小笠原氏は三好氏となり勝瑞へ。大西城には大西氏"],["1585年","蜂須賀家政が阿波に入り、«阿波九城» の一つとして整備"],["1638年","一国一城令により廃城"]],"who":[["小笠原長経","鎌倉時代、阿波に入り大西城を築いたと伝わる"],["小笠原長清","長経の父。承久の乱の功で阿波守護になった"],["蜂須賀家政","徳島藩の初代藩主。大西城を支城に整備した"],["牛田一長・中村重勝","江戸時代初めの城代とされる蜂須賀家の家臣"]],"deep":["«阿波九城» は、蜂須賀家政が国内の要所に置いた9つの支城のこと。一宮・撫養・川島・脇・大西・牛岐・仁宇・海部・西条の各城が挙げられ、家老クラスの重臣が城代として配置されました。","城の形は、台地の上の方形の区画だったと考えられています。天守のある近世城郭のようなものではなく、政庁と守りをかねた «陣屋» に近い姿だったと想像されます。","池田は吉野川の水運と、土佐・伊予・讃岐への陸路が交わる町。江戸時代には «刻みたばこ» の産地として栄えたことでも知られます。","小笠原氏→三好氏という流れは、戦国時代の三好長慶につながる重要な系譜です。阿波の «三好郡» が三好氏の名の由来と考えられています。","白地城は大西氏の戦国期の拠点、大西城はそれ以前と江戸初期の拠点、という関係にあります。二つをセットで歩くと阿波西部の歴史が見えてきます。"],"look":["池田幼稚園に残る石垣","城の範囲とされる諏訪神社周辺の台地のへり","台地の上から見下ろす吉野川と池田の町並み","近くの白地城跡もあわせて訪ねる"],"q":["大西城がある場所が «大西» と呼ばれたのはなぜ?","阿波の国のいちばん西のはしにあったからです。"],"koji":[{"w":"一国一城令","m":"1615年に江戸幕府が出した、大名の領地（国）ごとに城を一つに限る命令。阿波では1638年に支城がまとめて廃城になった"}],"myth":"築城者を小笠原長経とする説は伝承の要素がある。城代の名も史料により異同あり。","img":["蜂須賀家政","小笠原長清","白地城"],"wp":"大西城","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/Daisai_castle.jpg",3902,2614,"大西城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:d/d5/Hachisuka_Iemasa.jpg",2897,5437,"蜂須賀家政"],["c:8/81/Ogasawara_Nagakiyo.jpg",1704,1334,"小笠原長清"],["c:1/11/Hakuchi_Castle%2C_enkei.jpg",6002,3978,"白地城"]]},{"id":"36_ushiki_jo","n":"牛岐城（阿南・富岡城）","yomi":"うしきじょう","cat":"城","rank":"A","y":1582,"era":["muromachi","azuchi","edo"],"sh":"","ad":"阿南市富岡町","st":"JR牟岐線 阿南駅から歩いて約7分","la":33.9209,"lo":134.6581,"hook":"«浮亀城» とも呼ばれた駅前の小山。長宗我部元親にだまし討ちにされた城主の悲劇と、LEDの光が同じ丘に重なる。","lead":"牛岐城は、阿南駅のすぐ近くの小山にあった城です。戦国時代には新開氏の城でしたが、城主の新開道善は長宗我部元親に討たれました。江戸時代には徳島藩の支城となり «富岡城» と呼ばれ、1638年に廃城。いまは «牛岐城址公園» になっています。","story":["阿南駅を出て北西へ500メートルほど歩くと、住宅にかこまれた小さな丘があります。ここが牛岐城の跡。昔このあたりは «牛牧荘（うしまきのしょう）» と呼ばれ、牛や馬が飼われていた土地だったと考えられています。«牛岐» という名も、そこから来ているといわれます。別名は «浮亀城»。湿地の中にぽっかり浮かぶ小山が、亀の甲羅のように見えたのかもしれません。","城を築いたのは、室町時代に細川氏に従って阿波に来た新開実重という説が有力です。新開氏は代々この地を治め、戦国時代の城主・新開実綱は «道善» の名で知られました。道善は三好方の武将として、土佐から攻めてくる長宗我部元親と戦います。","1582年、中富川の戦いで三好方が大敗すると、道善は元親に降りました。ところが元親は、降った阿波の武将の中に «裏切るかもしれない者» がいると疑います。道善は丈六寺に招かれ、そこで討たれたと伝わります。«降参した者をだまして討つとは» ── 丈六寺に残る «血天井» は、このときの血のあとだという言い伝えがあります。","豊臣秀吉の四国攻めのあと、1585年に蜂須賀家政が阿波の領主になると、牛岐城は «阿波九城» の一つとなり、家老の賀島主水政慶が1万石で城代として入りました。政慶は «牛岐» の地名を «富岡» と改めたので、城も «富岡城» と呼ばれるようになります。いまの阿南市富岡町の名は、ここから来ているのです。","1638年、一国一城令によって城は取りこわされました。大正時代の道路工事で丘は南北に分かれ、残った南半分が公園に。頂上には八角形の展望室があり、発掘では徳島城と同じ «野面積み» の石垣も見つかっています。冬には青色LEDの町・阿南らしい光のイルミネーションが丘をいろどります。"],"tl":[["1384〜1386年ごろ","新開実重が築城したとする説が有力"],["1582年","中富川の戦いののち、城主・新開道善が長宗我部元親に討たれる。香宗我部親泰が入る"],["1585年","蜂須賀氏の «阿波九城» に。賀島政慶が城代となり «富岡» と改名"],["1638年","一国一城令により廃城"],["1913年","道路工事で城山が南北に分かれる"],["2010年","江戸時代の «牛岐・富岡城絵図» が阿南市の文化財に"]],"who":[["新開道善（実綱）","戦国時代の城主。長宗我部元親に降ったのち討たれた"],["長宗我部元親","土佐の大名。阿波攻略の中で道善を謀殺した"],["香宗我部親泰","元親の弟。道善のあと牛岐城に入った"],["賀島主水政慶","蜂須賀家の家老。城代となり地名を «富岡» に改めた"]],"deep":["丈六寺（徳島市）の «血天井» は新開道善の最期と結びつけて語られますが、伝承であり、史料で確かめられたものではありません。","«阿波九城» の城代は、それぞれ蜂須賀家の重臣。牛岐城の賀島家は1万石を与えられ、のちも徳島藩の家老家として続きました。","城山は «ひょうたん型» の小山で、まん中のくぼみを越えて人が行き来していたといわれます。南は湿地、北は «多門が淵» という深い川で、天然の堀になっていました。","発掘調査で見つかった石垣は、自然石をほぼそのまま積む «野面積み»。江戸初期の徳島城と同じ技術で、蜂須賀時代の改修を物語ります。","北半分の丘には新開道善をまつる神社があり、討たれた城主が地元でしのばれてきたことがわかります。","阿南市は青色LEDを開発した日亜化学工業の本社がある町。城址公園は «光のまちづくり» の舞台にもなっています。"],"look":["頂上の八角形の展望室","発掘で確かめられた野面積みの石垣（案内板で位置を確認）","北側の丘にある新開道善ゆかりの神社","冬のLEDイルミネーション"],"q":["牛岐城が江戸時代に «富岡城» と呼ばれるようになったのはなぜ?","城代の賀島政慶が地名の «牛岐» を «富岡» に改めたからです。"],"koji":[],"myth":"築城者・築城年は諸説。丈六寺の血天井が道善のものという話は伝承。","img":["長宗我部元親","香宗我部親泰","丈六寺"],"wp":"牛岐城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:5/53/Tyousokabe_Mototika.jpg",470,658,"長宗我部元親"],["c:6/66/Zyourokuzi_01.jpg",1400,1035,"丈六寺"]]},{"id":"36_kaifu_jo","n":"海部城（阿波南部の海の城）","yomi":"かいふじょう","cat":"城","rank":"A","y":1577,"era":["muromachi","azuchi","edo"],"sh":"海陽町指定史跡","ad":"海部郡海陽町奥浦（城山）","st":"阿佐海岸鉄道 海部駅から歩いて約10分","la":33.5944,"lo":134.3579,"hook":"嵐をさけて入ってきた一そうの船。それを襲ったことが、長宗我部元親の怒りに火をつけた。","lead":"海部城は、海部川の河口にある «城山» にあった城です。戦国時代の城主・海部氏が、嵐で逃げこんできた長宗我部元親の弟を討ったことから、元親に攻められました。江戸時代には徳島藩の支城となり、1638年に廃城。別名を «鞆城» といいます。","story":["海部川が太平洋にそそぐ河口に、こんもりとした丘があります。地元で «城山» と呼ばれるこの丘は、昔は川にかこまれた «島» のような場所でした。海と川の両方を見張れるこの丘に、戦国時代の海部城がありました。室町時代の海部・宍喰は、畿内へ運ばれる木材の一大積み出し地。«海の城» は、港と富を守る城でもあったのです。","城を築いたのは、永禄年間（1558〜1570年）の海部友光とされます。事件が起きたのは元亀2年（1571年）。土佐の長宗我部元親の弟・島親益の船が、突風をさけて海部の入江に入ってきました。«土佐の船だ!» 友光はこの船を襲い、親益を討ってしまったのです。","なぜ友光は、嵐をさけてきた船を襲ったのでしょう? 当時の阿波南部は、三好氏の勢力と、東へのびてくる長宗我部氏とがにらみ合う «境目»。土佐の武将が自分の港に入ってきたことを、敵の偵察や侵入と受けとったのかもしれません。しかし弟を殺された元親は激しく怒り、天正5年（1577年）、海部城を攻め落としました。ここから長宗我部氏の本格的な阿波侵攻が始まったともいえます。","豊臣秀吉の四国攻めのあと、阿波の領主となった蜂須賀家政は、海部城を «阿波九城» の一つとして土佐との国境を守らせました。1638年の廃城後も、この地には海部郡の «代役所» が置かれ、1807年に今の美波町へ移るまで、南阿波の政治の中心として栄えました。","いまの城山は、戦後の埋め立てで «島» ではなくなりましたが、登ってみると海部川と港、太平洋が一望できます。弟の船を失った元親の怒り、国境を守った蜂須賀の武士たち ── 海と川のあいだの小さな丘に、南阿波の戦国と江戸がつまっています。"],"tl":[["1558〜1570年","海部友光が城を築いたとされる"],["1571年","長宗我部元親の弟・島親益の船が入江に入り、海部友光に討たれる"],["1577年","元親が海部城を攻め落とす"],["1585年","蜂須賀家政の «阿波九城» の一つとなる"],["1638年","一国一城令により廃城。のち海部郡の代役所が置かれる"],["1807年","代役所が今の美波町へ移る"]],"who":[["海部友光","城を築いたとされる城主。島親益を討った"],["島親益","長宗我部元親の弟。海部の入江で討たれた"],["長宗我部元親","弟のかたきとして海部城を攻略した"],["蜂須賀家政","江戸時代初め、海部城を国境の支城とした"]],"deep":["室町時代中期の «兵庫北関入船納帳»（1445年）には、阿波から畿内へ運ばれた大量の木材が記録され、そのうち海部・宍喰からの船が大きな割合を占めていたとされます。","海部川流域では中世に «海部刀» と呼ばれる刀がつくられました。海陽町立博物館には海部刀のコレクションがあり、この地の豊かさを物語ります。","城山が «いつ» 城になったのかは、はっきりした根拠がなく諸説あります。海部友光の築城も «とされる» という伝えです。","島親益の事件の年や経緯は、主に『元親記』などの軍記物によるもので、細かい部分は史料によって違いがあります。","廃城後の «代役所» は、郡の年貢や行政を担当した徳島藩の出先機関。城が役所に姿を変えた例として興味深いものです。"],"look":["城山からの海部川河口と太平洋の眺め","城跡を示す碑や案内板","城山のまわりの地形（かつては川にかこまれた島だった）","海陽町立博物館の海部刀の展示"],"q":["長宗我部元親が海部城を攻めたきっかけは?","嵐をさけて入江に入った弟・島親益の船を、城主の海部友光が襲って討ったことです。"],"koji":[],"myth":"築城者・築城年、島親益事件の細部は軍記による部分があり諸説。","img":["長宗我部元親","海陽町","海部刀"],"wp":"海部城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:5/53/Tyousokabe_Mototika.jpg",470,658,"長宗我部元親"],["c:3/3a/Todoroki_Watefalls_02.JPG",2848,4288,"海陽町"]]},{"id":"36_hiwasa_jo","n":"日和佐城","yomi":"ひわさじょう","cat":"城","rank":"B","y":1577,"era":["azuchi","showa"],"sh":"","ad":"海部郡美波町日和佐浦","st":"JR牟岐線 日和佐駅から歩いて約20分","la":33.7298,"lo":134.5361,"hook":"海を見下ろす天守は昭和生まれの «模擬天守»。その足もとに、城を捨てて土佐へ渡り、やがて故郷へ帰った一族の物語がある。","lead":"日和佐城は、ウミガメの浜で知られる美波町日和佐の城山にあった城です。戦国時代に日和佐氏が長宗我部元親に備えて築いたとされます。いまの天守は1978年につくられた展望台で、昔の建物を再現したものではありません。","story":["日和佐の港町を歩くと、海に突き出た山の上に白い天守が見えます。«りっぱなお城!» と思うかもしれませんが、じつはこれは1978年に建てられた «模擬天守»。戦国時代の日和佐城に、こんな天守はありませんでした。では、本当の日和佐城はどんな城だったのでしょう?","元亀年間（1570〜1573年）、阿波の細川真之に仕えていた日和佐肥前守が、土佐から迫る長宗我部元親を防ぐためにこの城を築いたとされます。海沿いの道を東へ進む土佐勢にとって、日和佐は阿波南部の入り口。«ここで食い止める» ── 小さな山城は、そんな覚悟の城でした。","1577年11月、元親の弟・香宗我部親泰の大軍が海部から攻め寄せます。肥前守は降伏しましたが、そのとき討死したとも伝わり、弟の権藤が家をついで肥前守を名のりました。その後、日和佐氏は長宗我部方に協力します。敵に降り、生きのびて家を守る ── 戦国の小さな領主にとって、それも大切な選択でした。","ところが1585年、豊臣秀吉の四国攻めで長宗我部氏は土佐一国に戻され、阿波には蜂須賀氏がやってきます。日和佐氏は城を去り、大坂で浪人となりました。やがて元親に招かれて土佐の赤岡へ移り、«浜五郎兵衛» と名を変えて庄屋をつとめたといいます。","物語には続きがあります。のちに徳島藩主・蜂須賀家政が、この一族に «阿波へ帰ってこないか» とすすめたのです。五郎兵衛は家を次男にゆずり、三男を連れて故郷へ戻り、50石の武士に取り立てられたと伝わります。城は消えても、一族は海をはさんで行き来しながら生きのびた ── 展望台から海をながめながら、そんな旅路を思いうかべてみてください。"],"tl":[["1570〜1573年","日和佐肥前守が城を築いたとされる"],["1577年11月","香宗我部親泰の軍に降伏。肥前守は討死し、弟が跡をつぐと伝わる"],["1585年","蜂須賀氏の阿波入り。日和佐氏は城を去り大坂で浪人に"],["1596年","元親に招かれ土佐の赤岡へ。このころ廃城とみられる"],["1978年","城山に模擬天守（展望台）が建てられる"]],"who":[["日和佐肥前守","城を築いたとされる城主。長宗我部軍に降った"],["香宗我部親泰","元親の弟。阿波南部攻めの大将"],["長宗我部元親","土佐の大名。のちに日和佐氏を土佐へ招いた"],["蜂須賀家政","徳島藩主。日和佐氏に阿波への帰国をすすめたと伝わる"]],"deep":["模擬天守は «勤労者野外活動施設» として建てられたもので、いまは展望台として公開されています。石垣も当時のものではなく、戦国期の遺構はほとんど確認されていません。","別名は «渭津城»。同じ «渭津» の名は徳島城の城下の古い呼び名にも使われるので、混同に注意が必要です。","日和佐氏が土佐・赤岡で庄屋になり、のち阿波へ戻ったという流れは、家に伝わる記録などによるもので、細部は確かめにくい部分があります。","日和佐は四国八十八箇所23番・薬王寺の門前町。阿波の «発心の道場» の最後の札所で、ここから遍路は土佐へ向かいます。","大浜海岸はアカウミガメの産卵地として国の天然記念物。城山の展望台からその浜を見下ろせます。"],"look":["城山の展望台からの日和佐湾と大浜海岸","模擬天守（昭和の建物であることを意識して）","城山のふもとの港町","近くの薬王寺とうみがめ博物館カレッタ"],"q":["日和佐城の天守はいつ建てられた?","1978年です。昔の城を再現したものではなく、展望台として建てられた «模擬天守» です。"],"koji":[],"myth":"築城者・年代は «とされる»。肥前守の討死や日和佐氏の土佐移住・帰国の細部は伝承を含む。","img":["美波町","薬王寺 (徳島県美波町)","香宗我部親泰"],"wp":"日和佐城","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/Hiwasa_castle_%282015%29.JPG",2938,1656,"日和佐城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:6/62/%C5%8Chama_Beach_02.jpg",3648,2736,"美波町"],["c:6/64/Yakuouji_20240402_1.jpg",2400,1724,"薬王寺 (徳島県美波町)"]]},{"id":"36_kuwano_jo","n":"桑野城（東条氏の城）","yomi":"くわのじょう","cat":"城","rank":"B","y":1577,"era":["muromachi","azuchi"],"sh":"","ad":"阿南市桑野町（萬福寺のあたり）","st":"JR牟岐線 桑野駅から東へ歩いてすぐ","la":33.8733,"lo":134.6152,"hook":"甲斐の武田の流れをくむと伝わる一族が、遠い阿波で築いた城。長宗我部元親の «身内» となった城主の運命は、あまりに苦かった。","lead":"桑野城は、阿南市桑野町の船岡山にあった城で、いまは萬福寺が建っています。城主の東条氏は甲斐（山梨県）の武田氏の分かれと伝わり、戦国時代には長宗我部元親に味方して阿波攻めの拠点になりました。寺の南西と東側に、城の切岸が残っています。","story":["桑野駅を降りて東へ少し歩くと、小高い丘の上に萬福寺があります。ここがかつての桑野城。「甲斐の武田」と聞くと武田信玄を思いうかべますが、この城の主・東条氏は、その武田氏の分かれの一族だったと伝わります。なぜ山梨の武士が、遠い阿波の海辺に?","家に伝わる系図によると、室町時代の文明年間、甲斐の戦乱に敗れた東条常忠の一行が阿波へ流れつき、阿波守護の細川成之に仕えたといいます。やがて桑野に移って8つの村を治め、子の代に船岡山へ城を築きました。一族は近くの新開氏と主導権を争い、畿内の戦にも出るなど、阿波の有力な武士になっていきます。","戦国時代の終わり、土佐の長宗我部元親が阿波へ攻めこんできます。天正3年（1575年）ごろ、城主の東条関之兵衛は元親に従いました。元親は養女を関之兵衛にとつがせ、身内として迎えます。桑野城は、元親の阿波攻めの前線基地になりました。","1577年夏、三好方の矢野駿河守と篠原自遁らが3000の兵で桑野城に攻め寄せます。«土佐に寝返った城を落とせ!» しかし長宗我部方の一宮成助が三好軍のうしろをおびやかし、篠原はすぐに引き上げ、矢野の軍も勝浦川の近くで土佐勢に追われて大きな損害を出したと伝わります。1582年の中富川の戦いでも、関之兵衛は長宗我部方として戦功を立てました。","けれども1585年、豊臣秀吉の四国攻めが始まると、関之兵衛がまもっていた木津城は降伏して開城します。関之兵衛は土佐へのがれましたが、元親の怒りを買い、弟とともに処刑されたとされます。«身内» として迎えられた武将の、あまりに悲しい最期でした。桑野城もこのころ役目を終えたと考えられます。"],"tl":[["1469〜1487年（文明年間）","甲斐から来た東条常忠が阿波に住みついたと伝わる"],["室町時代後期","船岡山に桑野城が築かれる"],["1575年ごろ","城主・東条関之兵衛が長宗我部元親に従う"],["1577年夏","三好方の矢野・篠原勢が桑野城を攻めるが退けられる"],["1582年","中富川の戦いに長宗我部方として参戦"],["1585年","秀吉の四国攻め。木津城開城。このころ桑野城も廃城か"]],"who":[["東条関之兵衛","戦国時代の城主。元親の身内となったが、最後は処刑されたとされる"],["長宗我部元親","土佐の大名。桑野城を阿波攻めの拠点にした"],["東条常忠","甲斐から阿波に来て一族の基を開いたと伝わる"],["篠原自遁","三好方の武将。桑野城を攻めたが退いた"]],"deep":["東条氏の出自（甲斐武田氏の庶流・甘利系）は «桑野東條系図» など家の系図によるもので、確かめにくい部分があります。","関之兵衛の妻は、元親の重臣・久武内蔵助の娘を元親の養女としたものと伝わります。婚姻で国衆を取りこむのは長宗我部氏がよく使った方法でした。","1577年の戦いで、三好方は丈六寺に逃げこもうとして200人余りを討たれたとする記録があります。","関之兵衛の最期は、土佐の浦戸城で元親の子・信親によって処刑されたとする説がありますが、土佐へのがれた経緯も含めて諸説あります。","城は丘の上の寺の境内になっており、南西と東側の «切岸»（人工的に削った急斜面）が当時の名残です。"],"look":["萬福寺の境内（城の中心部とされる）","寺の南西と東側に残る切岸","丘の上から見る桑野川ぞいの平野","桑野駅からの近さ（駅前の城跡）"],"q":["桑野城の東条氏は、どこの武士の流れをくむと伝わる?","甲斐（山梨県）の武田氏の分かれと伝わります。"],"koji":[],"myth":"東条氏の甲斐武田出自、関之兵衛の最期は家伝・軍記によるもので諸説。","img":["長宗我部元親","中富川の戦い","木津城"],"wp":"桑野城","rel":{"ev":[],"grave":[]},"ph":[["c:0/03/Kuwano-manpukuji-temple_1.jpg",3840,2537,"桑野城"],["c:9/99/Kuwano-manpukuji-temple_2.jpg",2931,3840],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:5/53/Tyousokabe_Mototika.jpg",470,658,"長宗我部元親"],["c:7/76/Shozuijo09.jpg",1831,1348,"中富川の戦い"]]},{"id":"36_nakatomigawa","n":"中富川の戦い古戦場（長宗我部が阿波を制す）","yomi":"なかとみがわのたたかいこせんじょう","cat":"古戦場","rank":"S","y":1582,"era":["azuchi"],"sh":"国指定史跡（勝瑞城館跡）","ad":"板野郡藍住町勝瑞（勝瑞城館跡の周辺）","st":"JR高徳線 勝瑞駅から歩いて約10分","la":34.1103,"lo":134.514,"hook":"本能寺の変のわずか3か月後。信長という «重し» が消えた四国で、長宗我部元親は2万の大軍で三好の都・勝瑞へなだれこんだ。","lead":"1582年、土佐の長宗我部元親と、勝瑞城を本拠とする十河存保（三好方）が、中富川をはさんで戦いました。大雨で平野が湖のようになるなか約20日間の攻防が続き、三好方が降伏。長宗我部氏が阿波をほぼ手に入れ、阿波の «三好の時代» が終わりました。","story":["1582年6月、京都の本能寺で織田信長が倒れました。じつはこのとき、信長の三男・信孝を大将とする大軍が、四国へ渡る準備をしていました。ねらいは長宗我部元親。元親は «もう終わりか» と思ったかもしれません。ところが信長の死で四国攻めは立ち消えに。三好方の後ろだてだった三好康長も阿波から退きました。元親にとって、これ以上ないチャンスが訪れたのです。","元親は土佐の岡豊城で作戦会議を開きます。『長元物語』によると、城持ちの家老たちと、半農半兵の «一領具足» たちから別々に意見を聞いたといいます。慎重論もあるなか、元親は «今こそ出るべし» という一領具足の声を取りあげ、出陣を決めました。","8月28日の昼ごろ、元親の弟・香宗我部親泰の隊が中富川を渡りはじめ、嫡男・信親らの主力が続きます。長宗我部方は2万をこえる大軍。対する十河存保は、勝瑞城を本陣に5000あまりの兵で守りました。はじめは三好方の反撃に押されましたが、長宗我部軍はしだいに勝瑞城まで追いつめ、城をぐるりと取り囲みます。","ところが9月5日から大雨が5日間降りつづき、吉野川と中富川があふれて、板野の平野は湖のようになりました。長宗我部の兵は民家の屋根や木の上に逃げ、三好方は小舟でこぎ出して長い槍で突いた、と伝わります。水が引くと再び激しい戦いとなり、双方に多くの死者が出ました。存保は «最後の決戦を» と敵陣に突っこもうとしましたが、側近にいさめられて城へ戻ったといいます。","9月21日、存保はついに降伏し、勝瑞城を明けわたして讃岐へ去りました。この戦いで両軍の死者は1500人をこえたとされ、三好方の名だたる城主の多くが命を落としました。いま勝瑞城館跡は国の史跡となり、見性寺の境内には三好氏歴代の墓があります。静かな田園に立ち、ここで命を落とした人びとをしのびたい場所です。"],"tl":[["1582年5月","織田信孝を大将とする四国攻めの準備が進む"],["1582年6月2日","本能寺の変。四国攻めが中止に"],["1582年8月28日","長宗我部軍が中富川を渡り総攻撃"],["1582年9月5日ごろ","大雨が5日続き、平野が水びたしに"],["1582年9月21日","十河存保が降伏し、勝瑞城を明けわたす"],["1583年","木津城の篠原自遁も敗走し、阿波の大半が長宗我部氏のものに"],["1585年","豊臣秀吉の四国攻め。元親は土佐一国に"]],"who":[["長宗我部元親","土佐の大名。この戦いで阿波をほぼ手に入れた"],["十河存保","三好方の総大将。勝瑞城で戦い、降伏して讃岐へ去った"],["香宗我部親泰","元親の弟。先陣として中富川を渡った"],["長宗我部信親","元親の嫡男。主力を率いた"],["一宮成助","一宮城主。長宗我部方として加わったが、戦後に謀殺された"]],"deep":["兵の数は史料によってまちまちで、長宗我部方は «2万3千» などとも伝わります。軍記物の数字はふくらみやすいので、目安と考えるのが安全です。","«両軍の死者1503人» という細かい数字が伝わっていますが、出典は後世の記録で、確かな数字とはいえません。","戦後、元親は降った阿波の武将のうち一宮成助や新開道善を «裏切りの疑い» で謀殺しました。阿波の人びとの反感を買い、のちの秀吉の四国攻めのとき長宗我部方の結束を弱めたともいわれます。","中富川は当時、勝瑞の南を流れていた吉野川の分流の一つとされます。吉野川はその後も流路を大きく変えたため、当時の川筋の正確な位置には諸説あります。","勝瑞城館跡の発掘では、大きな堀や庭園跡、たくさんのかわらけ（素焼きの皿）が見つかり、三好氏の本拠がまさに «阿波の都» だったことが確かめられています。","平島公方の足利義助は、長宗我部方に家臣を積極的に参加させたとされ、阿波の中にも三好氏から離れた勢力がいたことがわかります。"],"look":["見性寺境内の勝瑞城跡と三好氏の墓所","勝瑞城館跡の発掘で確かめられた堀・庭園の復元展示","吉野川と旧吉野川にはさまれた平らな地形（洪水の起きやすさを実感）","近くの藍住町歴史館 «藍の館» もあわせて"],"q":["中富川の戦いの最中、戦場の平野が湖のようになったのはなぜ?","9月に大雨が5日間降りつづき、吉野川と中富川があふれたからです。"],"koji":[{"w":"一領具足","m":"長宗我部氏の半農半兵の兵士。ふだんは田を耕し、鎧一領をそばに置いて、呼ばれればすぐ戦に出た"}],"myth":"兵数・死者数は軍記による数字。洪水中の戦いの描写や存保の突撃の話も軍記に基づく。","img":["勝瑞城","十河存保","長宗我部元親","本能寺の変"],"wp":"中富川の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:7/76/Shozuijo09.jpg",1831,1348,"中富川の戦い"],["c:6/6f/Oko_Castle_06.JPG",2848,4288],["c:a/af/Shozuijo10.jpg",2048,1536],["c:5/53/Tyousokabe_Mototika.jpg",470,658,"長宗我部元親"],["c:e/e3/Honnoj.jpg",3200,1565,"本能寺の変"]]},{"id":"36_hiraiso_kubo","n":"平島館跡（«阿波公方» 足利家の屋敷）","yomi":"ひらじまやかたあと","cat":"大名屋敷","rank":"A","y":1534,"era":["muromachi","edo"],"sh":"","ad":"阿南市那賀川町古津","st":"JR牟岐線 阿波中島駅から歩いて約15分（阿波公方・民俗資料館へ）","la":33.959,"lo":134.653,"hook":"将軍になれなかった足利家が、阿波の田んぼの中で270年。藩主より «格上» の一家は、マムシよけのお札で暮らしを支えた。","lead":"平島館は、室町幕府の将軍家・足利氏の一族 «平島公方（阿波公方）» が、1534年ごろから1805年まで住んだ屋敷です。この家からは14代将軍・足利義栄が出ました。いまは田んぼの区画に名残がとどまるだけですが、近くの資料館で歴史を知ることができます。","story":["阿南市の那賀川町古津。のどかな田んぼの中に、かつて «将軍家» の屋敷がありました。«なぜ足利将軍の一族が阿波に?» ── 話は戦国時代の京都の、将軍の座をめぐる争いから始まります。","室町時代の終わり、将軍家は二つに分かれて争っていました。足利義維（よしつな）は、将軍・足利義晴と対立する細川晴元・三好元長にかつがれ、堺に拠点を構えて «堺公方» と呼ばれます。ところが晴元は途中で義晴側に乗りかえ、三好元長は自害に追いこまれました。義維は阿波へのがれ、1534年、阿波守護の細川持隆に迎えられて平島荘に住みます。これが «平島公方» の始まりです。","チャンスは30年後にめぐってきます。1565年、三好三人衆らが13代将軍・足利義輝を討ち（永禄の変）、義維の子・義栄が次の将軍にかつがれました。1568年、義栄はついに14代将軍に。しかし京都に入れないまま、同じ年に織田信長が足利義昭を連れて上洛し、義栄はまもなく病で亡くなります。«阿波の将軍» は、一度も京の都に入れなかったといわれています。","江戸時代、阿波の領主となった蜂須賀氏は、この «将軍の血すじ» の扱いに困りました。領地は取り上げ、与えたのはわずか100石の «茶料»。それでも阿波の人びとは、平島公方を藩主よりも尊い家として敬いました。館の床下でマムシが死んでいたことから «公方様の威光でヘビも死ぬ» とうわさが立ち、公方家の出す «マムシよけのお札» が大人気に。これが家の大事な収入になったといいます。","やがて待遇はよくなり、8代義宜のころには京都から学者を招き、平島館は漢詩文の «サロン» になりました。しかし1805年、9代義根は藩の許しを得て阿波を去り、船で京都へ向かいます。約270年続いた平島公方の歴史は、ここで幕を閉じました。いまは館の建物は残っていませんが、一部が小松島市の地蔵寺に移され、子孫をしのぶ資料が «阿波公方・民俗資料館» に伝わっています。"],"tl":[["1527年","足利義維が細川晴元らにかつがれ «堺公方» となる"],["1532年","三好元長が自害。義維は阿波へのがれる"],["1534年","平島荘に入る（のち永禄年間に平島館へ）"],["1565年","永禄の変。将軍・足利義輝が討たれる"],["1568年2月","義維の子・足利義栄が14代将軍に。同年に病没"],["1585年","蜂須賀氏の阿波入り。所領を取り上げられ100石に"],["1805年","9代義根が阿波を去り京都へ"]],"who":[["足利義維","平島公方の初代。«堺公方» から阿波に移った"],["足利義栄","義維の子。14代将軍となったが京に入れず病没した"],["足利義助","義栄の弟。家を継ぎ、蜂須賀時代を迎えた"],["足利義根","9代。1805年に阿波を去り京都へ移った"],["三好元長","義維を支えた三好氏の当主。三好長慶の父"]],"deep":["«公方» と呼ばれても、平島の家から実際に将軍になったのは義栄ひとり。ほかの当主は «将軍家の一族» という意味で公方と呼ばれました。","義栄は将軍宣下を受けたのちも摂津にとどまり、京都に入れなかったとされます。在職は1年に満たず、死因は腫れ物の悪化などといわれます。","マムシよけの守札には «阿州足利家» と書かれ «清和源氏之印» が押されました。この札には蜂須賀家をマムシにたとえる意味があったともいわれ、藩はたびたび禁止しています。","阿波を去った理由ははっきりせず、蜂須賀家との確執説や、子の紀州藩仕官の約束説などがあります。","館は那賀川町古津の «平島塁» を修築したもの。いまは水田の区画に縄張りの名残があるだけで、建物の一部（玄関と書院）が小松島市の地蔵寺に伝わり、県の文化財になっています。","平島公方の家は京都に移ったのち «足利» の姓に戻り、明治以降も家名が伝えられました。"],"look":["阿波公方・民俗資料館（那賀川町）の足利家ゆかりの資料","館跡周辺の水田の区画","平島公方の墓所がある西光寺","小松島市の地蔵寺に移された玄関と書院"],"q":["平島公方の家から将軍になったのは誰?","14代将軍の足利義栄です。ただし京都に入れないまま、同じ年に亡くなったといわれます。"],"koji":[],"myth":"マムシよけ札の由来は言い伝え。阿波退去の理由は諸説。義維の周防下向説は否定的な見方が強い。","img":["足利義維","足利義栄","平島館"],"wp":"平島公方","rel":{"ev":[],"grave":[]},"ph":[["c:0/09/%E3%83%9E%E3%83%A0%E3%82%B7%E3%82%88%E3%81%91%E6%9C%AD.jpg",3024,4032],["c:e/ea/Ashikaga_Yoshitsuna.jpg",2929,2196,"足利義維"],["c:9/90/Ashikaga_Yoshihide.jpg",2662,2275,"足利義栄"]]},{"id":"36_shibo_jo","n":"芝生城跡（三好長慶の生まれた地）","yomi":"しぼうじょうあと","cat":"城","rank":"B","y":1522,"era":["muromachi"],"sh":"","ad":"三好市三野町芝生","st":"JR徳島線 江口駅または阿波加茂駅から車で約10分（車が便利）","la":34.058,"lo":133.966,"hook":"織田信長より早く «天下» をにぎった男は、吉野川のほとりの小さな館で生まれた ── と伝わる。","lead":"芝生城は、三好市三野町芝生にあった三好氏の館（城）です。1522年、ここで三好長慶が生まれたと伝わります。長慶はのちに京都と畿内を支配し、«信長より前の天下人» とも呼ばれる人物です。目立った遺構はほとんど残っていません。","story":["吉野川の中流、三好市の三野町。川ぞいの静かな集落に、戦国時代の三好氏の館があったと伝わります。ここで1522年2月13日に生まれたとされるのが、三好長慶。«三好長慶って誰?» と思う人も多いでしょう。でも長慶は、織田信長が京都に入る十数年も前に、京都と畿内を支配した «天下人» だったのです。","三好氏は、鎌倉時代に阿波へ来た小笠原氏の流れをくみ、三好郡に根を張ったことから «三好» を名のるようになったと考えられています。長慶の父・三好元長は、細川晴元の重臣として畿内で活やくしました。この地には、長慶の母が身ごもったとき、館の南を流れる吉野川の瀬に立って «天下の英雄を» と祈った、という言い伝えも残っています。","けれども長慶の少年時代は苦しいものでした。1532年、父・元長は主君の晴元に見捨てられ、一向一揆に攻められて自害します。長慶はまだ10歳ほど。«父のかたきは、主君その人だった» ── そんな複雑な思いをかかえて、長慶は成長していきます。","大人になった長慶は、晴元の家臣として力をたくわえ、やがて晴元を追い落とします。1549年の江口の戦いに勝つと、将軍や管領をしのぐ力をにぎり、«三好政権» と呼ばれる時代を開きました。弟の三好実休（阿波）、安宅冬康（淡路）、十河一存（讃岐）がそれぞれの国をかため、兄弟で四国と畿内をまたぐ大きな勢力を築いたのです。","長慶は連歌をこよなく愛した教養人でもありました。1564年、飯盛山城で43歳の生涯を閉じます。その後、三好氏は内紛で力を失い、天下は信長のものになりました。芝生の地に立つと、この川ぞいの小さな館から «天下» へと続いた長い道のりに驚かされます。"],"tl":[["1522年2月13日","三好元長の嫡男として芝生城で生まれたと伝わる"],["1532年","父・三好元長が自害"],["1549年","江口の戦いに勝ち、畿内の実権をにぎる"],["1553年","将軍・足利義輝を近江へ追う"],["1564年","飯盛山城で病没"]],"who":[["三好長慶","芝生城で生まれたと伝わる戦国武将。«三好政権» を開いた"],["三好元長","長慶の父。細川晴元の重臣。1532年に自害"],["慶春院","長慶の母。吉野川で英雄の誕生を祈ったと伝わる"],["三好実休","長慶の弟。阿波を治めた"],["十河一存","長慶の弟。讃岐の十河氏をついだ"]],"deep":["長慶の生まれた場所を芝生城とするのは地元の伝承と後世の記録によるもので、確かな同時代史料があるわけではありません。","«芝生» は «しぼう» と読みます。三好氏歴代の館があった地と伝わり、三好郡が一族の名の由来と考えられています。","長慶は将軍を追い出しても自分が将軍になろうとはせず、将軍を立てる形を保ったり外したりしながら畿内を治めました。この «将軍抜きの政権» の試みが、近年の研究で注目されています。","長慶は連歌の名手で、合戦の最中にも連歌会を開いたという逸話が残ります（逸話であり、細部は確かではありません）。","長慶の墓所とされる場所は、京都の大徳寺聚光院、大阪府大東市の飯盛山周辺など複数あります。"],"look":["芝生の集落と吉野川の流れ（母が祈ったと伝わる川の瀬）","三好氏ゆかりを伝える碑や案内板（現地で確認を）","近くの三好市の山城群（白地城・大西城）とあわせて"],"q":["三好長慶の «三好» という名字は何に由来すると考えられている?","阿波の «三好郡» です。一族がこの地に根を張ったことから三好を名のったと考えられています。"],"koji":[],"myth":"芝生城での出生や、母が吉野川で祈った話は伝承。館の正確な位置もはっきりしない。","img":["三好元長","三好氏","飯盛山城"],"wp":"三好長慶","rel":{"ev":[],"grave":[]},"ph":[["c:a/ab/Portrait_of_Matsunaga_Hisahide.jpg",3575,7138],["c:2/2b/Miyoshi_Yoshitugu.jpg",1976,3182],["c:8/8d/Tyoukei2.jpg",1776,2700],["c:5/53/Ashikaga_Yoshiteru.jpg",1455,3087],["c:5/54/%E4%B8%89%E5%A5%BD%E9%95%B7%E6%85%B6.jpg",1291,2818],["c:6/69/Syariji7.jpg",2048,1536],["c:1/14/Mjitukyuu1.jpg",2048,1536],["c:0/03/Iimoriyama1.jpg",2048,1215]]},{"id":"36_yoshitsune_awa","n":"源義経の阿波上陸と «屋島への道»（勝浦・旗山）","yomi":"みなもとのよしつねのあわじょうりく","cat":"古戦場","rank":"A","y":1185,"era":["heian"],"sh":"","ad":"小松島市芝生町（旗山）","st":"JR徳島駅から車で約20分。旗山は小松島みなと付近","la":34.0035,"lo":134.581,"hook":"«3日の船旅を4時間で»。嵐の海をつっきった150騎が上陸したのは «勝浦»。義経は «縁起がいい» と笑った。","lead":"1185年2月、源義経は嵐の中、わずか5そうの船で大阪湾から阿波へ渡り、いまの小松島市のあたり «勝浦» に上陸しました。そこから阿波を一気にかけぬけ、讃岐の屋島にいた平家の本陣を背後から攻めました。上陸地とされる小松島には «旗山» と義経の騎馬像があります。","story":["1185年（元暦2年）2月、摂津の渡辺の港。空は荒れ、強い風がふいていました。«こんな嵐に船は出せません» としぶる船頭に、義経は «向かい風なら無理もないが、これは追い風が少し強いだけだ» と言い、それでも出さないなら射殺してしまえ、と家来に命じた ── 『平家物語』はそう伝えます。船は5そう、兵はわずか150騎ほど。ねらうは讃岐の屋島に陣を構える平家でした。","ふつうなら3日かかる海を、船はわずか数時間で渡ったといいます。着いた浜で義経が «ここは何というところか» とたずねると、«勝浦と申します»。義経は «わしの機嫌をとるための作り話か» と笑いましたが、本当にそういう名だと知ると «戦に勝つ浦とは、めでたい» と喜んだ ── 『平家物語』はそんな場面を描いています。この «勝浦» は、いまの小松島市のあたりと考えられています。","上陸した義経を助けたのが、阿波の武士・近藤六親家でした。親家から «屋島の平家は兵を各地に分けていて、守りは手うす» と聞いた義経は、まず平家方の桜間（桜庭）良遠の館を攻め落とします。そして休む間もなく北へ。阿波と讃岐の境の大坂峠（大坂越）をこえ、夜通しかけて屋島をめざしました。","平家はまさか陸から来るとは思っていません。«源氏が背後から!» 義経軍は民家に火を放って大軍に見せかけ、あわてた平家は船で海へのがれました。こうして屋島の戦いが始まり、那須与一が扇の的を射た名場面も生まれます。平家が西へ追われ、壇ノ浦で滅びるのは、このわずか1か月あまり後のことでした。","小松島の «旗山» は、義経が源氏の白旗を立てた場所と伝わる小山です。山頂近くには大きな義経の騎馬像が立ち、港を見下ろしています。嵐の夜明けに浜へ乗り上げた船、ぬれた馬、«勝浦» の名に笑う若き大将 ── そんな場面を思いうかべながら歩いてみましょう。"],"tl":[["1183年","都を落ちた平家が、阿波の田口成良に迎えられ讃岐の屋島に拠点を置く"],["1184年2月","一ノ谷の戦い。敗れた平家は屋島に戻る"],["1185年2月16日夜","義経、摂津の渡辺から嵐の中を出航"],["1185年2月17日朝","阿波の勝浦に上陸。桜間良遠の館を攻める"],["1185年2月18〜19日","大坂越をこえ、屋島の平家を背後から攻撃"],["1185年3月24日","壇ノ浦の戦いで平家が滅びる"]],"who":[["源義経","源氏の大将。少数で阿波に上陸し、屋島を奇襲した"],["近藤六親家","阿波の武士。義経に平家の様子を伝え、道案内をした"],["桜間（桜庭）良遠","平家方の阿波の武士。義経に館を攻められた"],["田口（粟田）成良","阿波の有力者。平家を屋島に迎えた"]],"deep":["«3日の道を4時間ほどで» という話は『平家物語』の描写にもとづくもので、実際の所要時間は確かめられません。","上陸地 «勝浦» は、今の勝浦郡勝浦町ではなく、小松島市の旧勝浦川河口付近と考えるのが一般的です。ただし正確な地点には諸説あります。","義経が屋島へ向かった道は大坂越が有力ですが、美馬の清水越、上板の大山越とする説もあり、大山寺などに義経の言い伝えが残ります。","『源平盛衰記』には、義経一行が金泉寺（板野町）に立ち寄り、観音講のごちそうを食べて腹ごしらえしたという話があります。","平家を屋島に迎えた田口成良は、阿波の在庁官人・粟田氏の一族とする研究があり、阿波の中にも平家派と反平家派の争いがあったことがわかります。","義経の渡海を助けた阿波の反平家勢力との連絡があらかじめあった、とする見方もあります。少数で渡って現地で兵を集め、梶原景時の水軍が海から攻める、という二段構えの作戦だったとも考えられています。"],"look":["旗山と山上の義経騎馬像","旗山からながめる小松島の港（上陸の情景を想像）","近くの «義経ドリームロード» の案内","板野町の金泉寺、大坂峠など «屋島への道» をたどる"],"q":["義経が上陸した浜の名を聞いて喜んだのはなぜ?","浜の名が «勝浦» で、«戦に勝つ» に通じる縁起のよい名だったからです。"],"koji":[{"w":"逆櫓（さかろ）論争","m":"屋島へ向かう前、梶原景時が «船に逆櫓をつけて退却もできるように» と言い、義経が «はじめから逃げる用意などするな» と退けたと『平家物語』が伝える話"}],"myth":"上陸地点・進軍路には諸説。旗山で白旗を立てた話や会話の細部は伝承・物語による。","img":["源義経","平家物語"],"wp":"屋島の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/Battle_of_Yashima_Folding_Screens_Kano_School.jpg",10969,4896,"屋島の戦い"],["c:1/12/Battlefield_of_Yashima.jpg",6016,4000],["c:3/33/%E6%AD%8C%E5%B7%9D%E5%9B%BD%E8%8A%B3%E3%80%8C%E6%BA%90%E7%BE%A9%E7%B5%8C%E6%A2%B6%E5%8E%9F%E9%80%86%E6%AB%93%E4%BA%89%E8%AB%96%E5%9B%B3%E3%80%8D.jpg",3811,1963],["c:f/f4/Battle_of_Yashima_Artwork.jpg",1803,1153],["c:2/2e/SakaronoMatsu-ato01.jpg",600,400],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"],["c:7/73/%E5%B9%B3%E5%AE%B6%E7%89%A9%E8%AA%9E%EF%BD%A5%E7%A5%87%E5%9C%92%E7%B2%BE%E8%88%8E%E3%82%B5%E3%83%B3%E3%83%97%E3%83%AB.png",974,732,"平家物語"]]},{"id":"36_jurobei","n":"阿波十郎兵衛屋敷（«傾城阿波の鳴門» の舞台）","yomi":"あわじゅうろうべえやしき","cat":"事件","rank":"A","y":1698,"era":["edo"],"sh":"","ad":"徳島市川内町宮島本浦","st":"JR徳島駅から徳島バス川内循環線で «阿波十郎兵衛屋敷前» 下車すぐ","la":34.0916,"lo":134.584,"hook":"«ととさんの名は阿波の十郎兵衛、かかさんはお弓と申します»。日本中を泣かせた巡礼の娘のせりふの、その «十郎兵衛» が住んだ屋敷。","lead":"阿波十郎兵衛屋敷は、江戸時代の庄屋・板東十郎兵衛の屋敷跡です。十郎兵衛は藩の罪に問われて処刑され、その名は人形浄瑠璃 «傾城阿波の鳴門» の主人公に使われて有名になりました。いまは徳島県立の施設として、毎日人形浄瑠璃が上演されています。","story":["吉野川の河口近く、徳島市川内町。江戸時代、このあたり宮島浦の庄屋をつとめていたのが板東十郎兵衛でした。村をまとめる、しっかり者の庄屋だったといわれます。ところが元禄のころ、十郎兵衛は «抜け荷»（藩にかくれた密貿易）の罪に問われ、1698年に処刑されたと伝わります。","«本当に十郎兵衛がやったのか?» 地元では昔から、無実の罪を着せられた、あるいは誰かの罪を一身に引き受けたのだ、と語りつがれてきました。はっきりしたことはわかりません。けれども人びとの同情が、十郎兵衛の名を忘れさせなかったのです。","それから70年ほどたった1768年、大坂の竹本座で人形浄瑠璃 «傾城阿波の鳴門» が初演されます。主人公の名は «阿波の十郎兵衛»。といっても物語は本物の十郎兵衛とは別のお話で、主君の家を救うために盗賊に身をやつした十郎兵衛と、妻のお弓、そして娘のおつるの悲劇です。","いちばん有名なのが «巡礼歌の段»。幼いころ別れた両親をさがして巡礼の旅をする娘・おつるが、母お弓の家にたずねてきます。«ととさんの名は阿波の十郎兵衛、かかさんはお弓と申します»。お弓は «わが子だ» と気づきながら、夫が追われる身であるため名のることができず、泣く泣く娘を帰してしまう ── 客席の涙をさそう名場面です。物語はさらに、十郎兵衛がそれと知らずにおつるの命をうばってしまう悲劇へと進みます。","いま屋敷跡の劇場では、この «巡礼歌の段» が毎日上演されています。庭には十郎兵衛の時代をしのばせる木々が残り、館内には阿波の人形浄瑠璃で使われる大きな木偶（でこ）が並びます。近くの宝生寺には十郎兵衛の墓があり、実在の庄屋と物語の主人公、二人の «十郎兵衛» をしのぶことができます。"],"tl":[["1698年","板東十郎兵衛が処刑されたと伝わる"],["1768年","人形浄瑠璃 «傾城阿波の鳴門» が大坂・竹本座で初演"],["江戸後期〜明治","阿波の人形浄瑠璃が農村舞台などで盛んに上演される"],["明治〜昭和","阿波各地の人形座が農村舞台や町で上演を続ける"],["現在","県立の施設として毎日上演が行われる"]],"who":[["板東十郎兵衛","宮島浦の庄屋。罪に問われて処刑されたと伝わる実在の人物"],["お弓","浄瑠璃の中の十郎兵衛の妻"],["おつる","浄瑠璃の中の十郎兵衛の娘。巡礼姿で母をたずねる"],["近松半二","«傾城阿波の鳴門» の作者の一人とされる浄瑠璃作者"]],"deep":["«傾城阿波の鳴門» は近松半二らの合作とされ、もとは阿波徳島藩のお家騒動を題材にした全10段の長い作品。今日よく上演されるのは «十郎兵衛住家の段»（巡礼歌の段）です。","実在の十郎兵衛の罪状や処刑の事情については、確かな史料が少なく諸説あります。«冤罪» や «身代わり» の話は地元の伝承です。","阿波の人形浄瑠璃の人形（木偶）は、屋外の農村舞台でも遠くから見えるように大きく作られるのが特徴といわれます。","阿波には «天狗久» などの名人の人形師が出て、木偶づくりが盛んでした。すぐ近くの阿波木偶人形会館では、人形の頭（かしら）づくりを知ることができます。","徳島県警が考えた «オレオレ詐欺の段» という新作が上演されたこともあり、伝統芸能が今の話題を取りこむ例として話題になりました。"],"look":["館内の劇場での «巡礼歌の段» の上演（土・日・祝は太夫・三味線の生演奏）","展示室の阿波木偶の頭（かしら）","十郎兵衛の時代をしのばせる庭","近くの宝生寺にある十郎兵衛の墓"],"q":["巡礼の娘おつるが名のった «ととさん» と «かかさん» の名前は?","父は «阿波の十郎兵衛»、母は «お弓» です。"],"koji":[],"myth":"実在の十郎兵衛の処刑年・罪状・冤罪説は伝承を含み諸説。浄瑠璃の筋は創作。","img":["傾城阿波の鳴門","人形浄瑠璃","近松半二"],"wp":"阿波十郎兵衛屋敷","rel":{"ev":[],"grave":[]},"ph":[["c:e/ed/Awadeko201811_7.jpg",3031,4041],["c:a/ae/Awadeko201811_6.jpg",4041,3031],["c:b/b2/Awadeko20181106.jpg",4041,3031],["c:2/22/Awadeko201811_4.jpg",3864,1434],["c:4/49/%E9%98%BF%E6%B3%A2%E5%8D%81%E9%83%8E%E5%85%B5%E5%B1%8B%E6%95%B7.jpg",854,480],["c:f/fb/%E6%96%87%E6%A5%BD%E4%BA%BA%E5%BD%A2%EF%BC%88%E6%96%B0%E5%A4%A7%E9%98%AA%E9%A7%85%EF%BC%89.jpg",3648,2736,"人形浄瑠璃"]]},{"id":"36_dai_ju_zeki","n":"第十堰（江戸時代の吉野川の石の堰）","yomi":"だいじゅうぜき","cat":"産業","rank":"A","y":1752,"era":["edo","heisei"],"sh":"","ad":"名西郡石井町藍畑第十／板野郡上板町第十新田","st":"JR徳島線 石井駅から車で約10分","la":34.1089,"lo":134.4561,"hook":"270年前に青い石を組んで造られた堰が、いまも «四国三郎» 吉野川の水を分けている。","lead":"第十堰は、吉野川の水を旧吉野川へ分けるために江戸時代の1752年に造られた石の堰です。«第十» は近くにあった村の名前。青石を組んだ当時の姿をいまも残し、平成には «可動堰にするかどうか» をめぐって住民投票が行われたことでも知られます。","story":["徳島市の中心から吉野川を15キロほどさかのぼると、川の幅いっぱいに、白い水しぶきをあげる段差が見えてきます。これが第十堰。コンクリートのダムとちがい、斜めの石の坂の上を水がさらさらと流れ落ちていきます。«なぜこんなところに石の堰が?» その理由は、江戸時代の «川の付けかえ» にありました。","1672年、徳島藩は城の守りなどのために、吉野川と別宮川という川をつなぐ水路を掘りました（«新川掘抜»）。ところが洪水のたびにこの水路はけずられて広がり、やがて吉野川の水の大部分が新しい流れ（今の吉野川本流）へ流れこむようになってしまいます。","困ったのは、もとの吉野川（いまの旧吉野川）ぞいの村々でした。«水が来ない。田んぼが干上がる!» そこで1752年、川に石を積んで水位を上げ、旧吉野川へ水を送る堰が造られました。場所は第十村。こうして «第十堰» の名が生まれたのです。この工事は吉野川での藩の最大の土木工事だったといわれ、徳島藩がその少し前に命じられた大井川の工事の経験が役立ったと考えられています。","その後も堰は何度も継ぎ足され、青石を組んだ当時の姿を残したまま、今も水を分ける役目を果たしています。ところが1990年代、国は «洪水の時に水をせき止めてしまう» として、下流に «可動堰» を造る計画を進めました。«川の自然を守りたい»«巨額の工事費は本当に必要か» ── 住民の反対の声が広がります。","2000年1月、徳島市で可動堰化の是非を問う住民投票が行われ、反対が9割をこえました。計画はその後、事実上白紙に。江戸の石の堰は、平成の «住民が川の未来を決める» 出来事の舞台にもなったのです。堰の上をすべり落ちる水の音を聞きながら、人と川の270年を思ってみてください。"],"tl":[["1672年","徳島藩が吉野川と別宮川をつなぐ «新川掘抜» を行う"],["1752年","第十村に堰が造られる（第十堰の始まり）"],["江戸後期","新川の拡大にあわせ、堰が継ぎ足される"],["1932年","別宮川が «吉野川»、もとの吉野川が «旧吉野川» と改名"],["1998年","審議委員会が可動堰化を «妥当» と答申"],["2000年1月23日","徳島市で住民投票。可動堰化反対が9割をこえる"]],"who":[["蜂須賀綱通","徳島藩主。1672年の新川掘抜の時代の藩主"],["旧吉野川流域の農民","水不足に苦しみ、堰を求めた人びと"],["徳島藩の普請役人","堰づくりを進めた藩の技術者たち"],["徳島市民","2000年の住民投票で川の未来を選んだ"]],"deep":["第十堰は河口から約14キロ上流にあり、«河口堰» と呼ばれることがありますが正確ではありません。","徳島藩は1736年、幕府から遠江の大井川の «御手伝普請»（工事の負担）を命じられました。その経験が第十堰の石組みに生かされたと考えられています。","吉野川は «四国三郎» と呼ばれる暴れ川。上流の高知県で大雨が降ると、徳島で雨がなくても洪水になることがあり «土佐水» などと呼ばれました。","第十堰は斜めの石の面を水が越えていく «斜め堰»。魚がのぼりやすく、堰の下には独特の生きものの環境があると指摘されています。","住民投票は «投票率50％未満なら開票しない» という条件付きでしたが、投票率は約55％で開票されました。","平成の議論では、石の堰の «歴史的価値» も論点の一つでした。現在も国の管理のもとで補修が続けられています。"],"look":["堤防の上から見る、川幅いっぱいの堰と水の流れ","斜めに組まれた青石の石組み（増水時は近づかない）","旧吉野川へ水が分かれていく様子","周囲に広がる藍や田畑の平野"],"q":["«第十堰» の «第十» とは何の名前?","堰が造られた場所にあった «第十村» という村の名前です。"],"koji":[],"myth":"大井川普請の技術が生かされたという点は推定。","img":["吉野川","旧吉野川","別宮川"],"wp":"第十堰","rel":{"ev":[],"grave":[]},"ph":[["c:7/70/Yoshinogawa_Daijuzeki.jpg",640,480,"第十堰"],["c:6/6b/Yoshino_River_Daiju-zeki_weir_Aerial_photograph.1974.jpg",4061,2939],["c:9/9e/Yoshinogawa%28Tokushima%29.jpg",1230,916,"吉野川"],["c:e/e5/%E6%97%A7%E5%90%89%E9%87%8E%E5%B7%9D_%E6%9D%BE%E8%8C%82%E7%94%BA.jpg",800,600,"旧吉野川"]]},{"id":"36_ai_no_yakata","n":"藍の館（藍商・奥村家の屋敷）","yomi":"あいのやかた","cat":"産業","rank":"S","y":1800,"era":["edo","meiji"],"sh":"国の重要有形民俗文化財（阿波藍栽培加工用具）","ad":"板野郡藍住町徳命字前須西","st":"JR徳島駅から車で約25分（路線バスもある）","la":34.1156,"lo":134.4823,"hook":"«ジャパン・ブルー» の源は、吉野川の洪水だった。暴れ川がくれた肥えた土が、阿波を日本一の藍の国にした。","lead":"藍の館は、江戸時代から続いた大きな藍商・奥村家の屋敷を使った藍の博物館です。阿波の藍は «阿波藍» として全国に知られ、藍商たちは大もうけしました。館では藍づくりの道具や古文書が見られ、藍染めの体験もできます。","story":["江戸時代の日本人の着物は、藍色だらけでした。のれん、ゆかた、作業着……。明治に来日した外国人が «日本はブルーの国だ» と驚いたほどです。その藍の «染料» の多くを作っていたのが、阿波でした。では、なぜ阿波だったのでしょう?","答えは吉野川です。«四国三郎» と呼ばれる吉野川は、毎年のように洪水を起こす暴れ川でした。大水は田をおし流しますが、同時に上流から肥えた土を運んできます。しかも藍は、台風がやってくる前の夏に刈り取ることができます。«米より藍を» ── 吉野川の下流一帯は、一面の藍畑になっていきました。","刈った藍の葉は、そのままでは染料になりません。«寝床（ねどこ）» と呼ばれる土間に積み、水をかけては切り返し、100日ほどかけて発酵させます。こうしてできる黒い土のようなかたまりが «すくも»。阿波のすくもは質がよく、全国の紺屋（染め物屋）がこぞって買い求めました。","この藍を売って大もうけしたのが «藍商» です。奥村家もその一つで、藍住町の屋敷には、母屋や藍の «寝床»、大きな蔵が並びます。11代の当主が1987年に屋敷を町に寄付し、1996年に «藍の館» として開館しました。展示される «奥村家文書» からは、藍商が全国に商いを広げていた様子がうかがえます。","けれども明治の終わりになると、インドから安い藍が入り、さらにドイツで化学合成された藍が広まって、阿波藍は急におとろえました。それでも «すくも» づくりの技は、わずかな藍師たちによって守られてきました。館で藍染めを体験すると、液から引き上げた布が空気にふれて、みるみる緑から青に変わっていきます。その青の向こうに、吉野川と人びとの長い歴史が見えてくるはずです。"],"tl":[["16世紀末","蜂須賀家政が阿波に入り、のちに藍作りが藩の保護で広がったといわれる"],["江戸時代","阿波藍が全国の染料市場を広く占め、藍商が栄える"],["明治30年代ごろ","阿波の藍作りが最も盛んになる"],["明治末〜大正","インド藍や化学合成藍におされ、急速におとろえる"],["1987年","奥村家の11代当主が屋敷を藍住町に寄付"],["1996年","«藍の館» として開館"]],"who":[["奥村家","江戸時代から続いた藍商。屋敷が藍の館になった"],["奥村武夫","奥村家11代当主。屋敷を町に寄付した"],["蜂須賀家政","徳島藩の初代藩主。藍の生産を奨励したと伝わる"],["藍師","すくもを作る職人。今も技を受けついでいる"]],"deep":["«阿波藍栽培加工用具» は、種まきから刈り取り、すくもづくりまでの道具一式として国の重要有形民俗文化財に指定されています。","すくもづくりは «寝せ込み» から約100日。水をかけて切り返す作業をくり返し、発酵の温度を人の手で管理します。","阿波藍の生産は、明治の中ごろから30年代にかけて最盛期をむかえたといわれ、その後、合成藍の普及で激減しました。","藍住町の名は «藍» のまち。町名そのものが産業の歴史を物語っています。","藍の館の奥村家住宅の主屋と蔵は国の登録有形文化財。藍商の屋敷の «構え» を知るうえで貴重です。","東京2020オリンピック・パラリンピックのエンブレムの «藍色の市松模様» をきっかけに、阿波藍もあらためて注目を集めました。"],"look":["藍の «寝床» があった建物と大きな蔵","国の重要有形民俗文化財の藍づくりの道具","奥村家文書など藍商の商いを伝える資料","藍染め体験（布が緑から青に変わる瞬間）"],"q":["藍の葉を発酵させて作る、阿波藍の染料のもとを何という?","«すくも» です。100日ほどかけて発酵させて作ります。"],"koji":[],"myth":"蜂須賀家政が藍作を奨励した話は伝承の要素を含む。","img":["藍染","阿波藍","藍住町"],"wp":"藍の館","rel":{"ev":[],"grave":[]},"ph":[["c:4/44/Aizumi_Ai_no_Yakata.jpg",640,480,"藍の館"]]},{"id":"36_awa_washi","n":"阿波和紙の里（山川町・忌部氏ゆかりの紙すき）","yomi":"あわわしのさと","cat":"産業","rank":"B","y":1989,"era":["nara","edo","heisei"],"sh":"","ad":"吉野川市山川町川東","st":"JR徳島線 阿波山川駅から歩いて約15分","la":34.0459,"lo":134.231,"hook":"神話の時代、麻とカジノキを植えて阿波を開いたとされる一族がいた。その «忌部» の里で、今も紙がすかれている。","lead":"吉野川市山川町は、古くから手すき和紙づくりが続く «阿波和紙» の里です。紙の原料になる植物を植えて阿波を開いたと伝わる «忌部氏» ゆかりの土地で、1989年に開館した阿波和紙伝統産業会館では、紙すきの見学や体験ができます。","story":["吉野川の南岸、山川町。川の水と山の木々にめぐまれたこの町では、昔から紙がすかれてきました。«なぜここで紙づくりが?» ── その答えは、はるか神話の時代にさかのぼるといいます。","平安時代の初めに書かれた『古語拾遺』には、朝廷の祭りをつかさどった «忌部氏» の祖・天日鷲命（あめのひわしのみこと）の子孫が阿波の国に移り、穀（カジノキ）や麻を植えた、と記されています。カジノキは紙や布の原料。阿波の «麻植（おえ）郡» という古い郡の名も «麻を植える» ことから来たといわれます。山川町はその麻植郡の中にありました。","忌部氏は、祭りに使う布や木綿（ゆう）を朝廷にささげる役目を持っていました。いまでも天皇が即位するときの «大嘗祭» には、阿波の忌部氏の流れをくむ家が織った麻の布 «麁服（あらたえ）» が納められています。紙や布をつくる技と、神に仕える心。阿波和紙は、そんな古い歴史の上に立っているのです。","江戸時代になると、徳島藩は紙づくりを保護し、阿波の紙は藩の大事な産物になりました。山あいの村々では、冬になるとコウゾやミツマタの皮をはいで煮て、たたいて、清らかな水の中ですきました。けれども明治以降、機械でつくる洋紙が広まり、手すきの工房はどんどん減っていきます。","その流れにあらがうように、1989年、山川町に «阿波和紙伝統産業会館» が開かれました。ここでは職人が紙をすく様子を見られ、自分で紙すきを体験することもできます。藍で染めた和紙は、阿波ならではの色。薄い一枚の紙に、神話の時代から続く里の記憶がすきこまれています。"],"tl":[["807年","『古語拾遺』が成立。忌部氏が阿波で穀・麻を植えたと記す"],["古代","阿波に麻植郡が置かれる"],["江戸時代","徳島藩の保護のもと、紙づくりが盛んになる"],["明治以降","洋紙の普及で手すき和紙の工房が減る"],["1976年","阿波和紙が国の伝統的工芸品に指定"],["1989年5月","阿波和紙伝統産業会館が開館"]],"who":[["天日鷲命","忌部氏の祖とされる神。阿波忌部の祖神としてまつられる"],["阿波忌部氏","朝廷の祭りに使う布などをささげた一族。阿波を開いたと伝わる"],["斎部広成","『古語拾遺』を書いた人物。忌部氏の出身"],["紙すき職人","今も山川で手すき和紙の技を伝えている"]],"deep":["『古語拾遺』の記事は忌部氏の立場から書かれた伝承で、そのまま歴史的事実とはいえません。ただ、古代の阿波が麻や木綿（ゆう）の産地だったことは、ほかの記録からもうかがえます。","大嘗祭の麁服は、美馬市木屋平の三木家が中心となって調進してきたもので、阿波忌部の伝統を今に伝える例として知られます。","山川町には天日鷲命をまつる忌部神社（山崎）があり、阿波忌部の信仰の中心地の一つとされます。","阿波和紙の原料は、コウゾ・ミツマタ・ガンピなど。会館では原料の処理からすき上げまでの流れを学べます。","阿波和紙は1976年に国の伝統的工芸品に指定されました。藍染めの和紙や、大判の紙などが特色とされます。"],"look":["職人が紙をすく作業スペース","自分で紙をすく体験コーナー（予約の確認を）","藍染めの和紙など作品の展示","近くの忌部神社（山崎）"],"q":["阿波の古い郡の名 «麻植（おえ）» は何に由来するといわれる?","«麻を植える» ことに由来するといわれます。忌部氏が麻を植えたという伝承と結びついています。"],"koji":[],"myth":"忌部氏が阿波を開いた話は『古語拾遺』などの伝承。忌部神社の所在地は近代に論争があった。","img":["忌部氏","古語拾遺","天日鷲命"],"wp":"阿波和紙伝統産業会館","rel":{"ev":[],"grave":[]},"ph":[["c:1/14/Amefutotamanomikoto-jinja%2C_haiden.jpg",5982,3952,"忌部氏"],["c:3/36/NDL772063_%E5%8F%A4%E8%AA%9E%E6%8B%BE%E9%81%BA.pdf",6495,5050,"古語拾遺"],["c:d/db/Uesakura_Park.jpeg",1242,810,"近く: 山川町 (徳島県)"],["c:0/01/JR_Awa-Yamakawa_sta_001.jpg",978,648,"近く: 阿波山川駅"],["c:f/f6/Myououin_20200329_01.jpg",1600,795,"近く: 明王院 (吉野川市)"]]},{"id":"36_otani_yaki","n":"大谷焼の窯元（鳴門・日本最大級の登り窯）","yomi":"おおたにやき","cat":"産業","rank":"A","y":1780,"era":["edo"],"sh":"","ad":"鳴門市大麻町大谷","st":"JR鳴門線 阿波大谷駅から歩いて約10分","la":34.162,"lo":134.552,"hook":"一人が寝ころんで足でろくろを回し、もう一人が土をのばす。二人の息が合わなければ生まれない、人の背丈ほどの大がめ。","lead":"大谷焼は、鳴門市大麻町大谷で江戸時代から作られている焼きものです。藍染めに使う大きな «藍がめ» づくりで栄え、寝ころんで足でけって回す «寝ろくろ» という独特の技が伝わります。窯元には、日本最大級といわれる登り窯が残っています。","story":["鳴門市の大麻町大谷。山すそに窯元が集まり、あちこちに大きなかめや壺が並んでいます。中には人がすっぽり入れそうなほどの大がめも。«どうしてこんなに大きなかめを?» ── その答えは、阿波のもう一つの名産 «藍» にありました。","始まりは江戸時代の1780年ごろ。四国遍路にやってきた豊後（大分県）の焼きもの職人・文右衛門が、大谷村でろくろ細工を見せたのがきっかけといわれます。村の庄屋が素焼きの窯をきずき、地元の赤土で火消しつぼなどを焼きはじめました。","翌年には徳島藩が藩の窯を開き、染付の磁器をつくりましたが、わずか3年ほどで閉じてしまいます。«このままでは終わらせない» ── 1784年、藍商人の賀屋文五郎らが窯を立て直し、信楽（滋賀県）の職人の力も借りて、藍染めに使う大きなかめを焼くようになりました。藍の国・阿波にとって、藍がめはいくらあっても足りない大事な道具だったのです。","大がめづくりに欠かせないのが «寝ろくろ» です。ろくろの下に一人が寝ころび、足でけって回します。上ではもう一人が粘土のひもを積み上げ、形をととのえていきます。二人の息がぴったり合わないと、大がめは生まれません。窯元には、山の斜面にそって階段のように部屋が続く大きな «登り窯» があり、日本最大級といわれています。","明治になり化学染料が広まると、藍がめの注文は激減しました。それでも大谷の人びとは大がめづくりをやめず、つぼや皿、とっくりなど暮らしの器にも力を入れて、今に伝えてきました。2003年には国の伝統的工芸品に指定。毎年秋の «窯まつり» には多くの人が訪れます。ざらりとした土のはだに、藍の時代の記憶が焼きこめられています。"],"tl":[["1780年ごろ","豊後の職人・文右衛門がろくろ細工を伝えたといわれる"],["1781年","徳島藩が藩の窯を開き、染付磁器を焼く（3年ほどで閉じる）"],["1784年","藍商人の賀屋文五郎らが再興。藍がめなど大物づくりへ"],["明治時代","化学染料の普及で藍がめの需要が激減"],["2003年","国の伝統的工芸品に指定"]],"who":[["文右衛門","豊後から来た焼きもの職人。大谷焼の始まりにかかわったといわれる"],["賀屋文五郎","藍商人。窯を再興し、大がめづくりの基礎をきずいた"],["森是助","大谷村の庄屋。最初の素焼き窯をきずいたと伝わる"],["信楽の陶工","大がめづくりの技を伝えた職人たち"]],"deep":["«黒焼き物由来記» などの記録が大谷焼の始まりを伝えています。ただし東林院にある «文右衛門の墓» とされてきた墓は、調査で «萬七» の墓とわかり、陶祖は萬七とする見方もあります（文右衛門と同一人物かは不明）。","大谷焼は、陶器と磁器の中間の性質を持つ «炻器（せっき）» に分類されます。","寝ろくろで作る大がめは、高さが1メートルをこえるものもあり、今も一部の窯元で技が受けつがれています。","登り窯は、斜面に焼成室を階段状に連ね、下から順に炎を送って焼く窯。大谷の登り窯は «日本最大級» と紹介されることが多いですが、比べ方によって順位は変わります。","近年はアニメ作品とのコラボ商品が完売するなど、伝統工芸の新しい見せ方にも取り組んでいます。"],"look":["窯元の敷地にある大きな登り窯","人の背丈ほどもある大がめ・藍がめ","寝ろくろの実演（時期・予約を確認）","秋の «大谷焼窯まつり»"],"q":["大谷焼の大がめづくりで使う «寝ろくろ» は、どうやって回す?","ろくろの下に人が寝ころび、足でけって回します。上の人と二人で息を合わせて作ります。"],"koji":[],"myth":"陶祖が文右衛門か萬七かは諸説。«日本最大級の登り窯» は紹介上の表現。","img":["登り窯","藍染"],"wp":"大谷焼","rel":{"ev":[],"grave":[]},"ph":[["c:4/46/Shigaraki_climbing_kiln_01.JPG",3801,2846,"登り窯"],["c:3/31/%E7%AB%8B%E9%81%93%E9%A7%85.jpg",2592,1944,"近く: 立道駅"],["c:5/51/Awa-%C5%8Ctani_Station.jpg",2592,1944,"近く: 阿波大谷駅"],["c:2/2d/Naruto_junction_2024_-_aerial.jpg",2400,1600,"近く: 鳴門ジャンクション"],["c:1/1a/Naruto_City_Horiekita_Elementary_School.jpg",4800,3200,"近く: 鳴門市堀江北小学校"],["c:1/10/Tourinin_20250311_1a.jpg",2048,1159,"近く: 東林院 (鳴門市)"],["c:7/76/Ushihiko_shrine%2C_Tokushima.jpg",2592,1936,"近く: 宇志比古神社"]]},{"id":"36_naruto_enden","n":"撫養の塩田（阿波の «斎田塩»）","yomi":"むやのえんでん","cat":"産業","rank":"B","y":1599,"era":["edo","showa"],"sh":"","ad":"鳴門市撫養町斎田","st":"JR鳴門線 鳴門駅から歩いて約10〜15分（塩田の遺構は少ない）","la":34.176,"lo":134.602,"hook":"鳴門の渦潮のすぐそばで、370年あまり «白い宝» がつくられつづけた。町の名 «斎田（さいた）» は、その塩田から来たともいう。","lead":"鳴門市の撫養（むや）一帯には、江戸時代の初めから昭和まで、海水から塩をつくる «塩田» が広がっていました。ここでつくられた塩は «斎田塩» と呼ばれ、阿波の大事な産物でした。1970年代に塩田は姿を消し、今は町の名や一部の跡にその記憶が残ります。","story":["鳴門駅のまわりを歩くと、まっすぐな道や水路が規則正しく続いていることに気づきます。«なぜこんなに平らで、まっすぐなの?» それは、このあたり一面が、かつて塩をつくる田んぼ ── «塩田» だったからです。","江戸時代の初め、阿波の領主・蜂須賀家政は、撫養の浜に塩田を開かせました。『板野郡誌』には、慶長4年（1599年）に塩田を開き «財田（さいた）» と名づけた、と書かれています。播磨（兵庫県）から塩づくりの技術者を招いたとも伝わります。瀬戸内の雨の少ない気候と、遠浅の浜は、塩づくりにぴったりでした。","撫養の塩田は «入浜式» と呼ばれる方法でした。満ち潮のときに海水を塩田の中へ引き入れ、砂にしみこませます。太陽と風で砂をかわかすと、砂の表面に塩の結晶がつきます。この砂を集めて海水をかけ、こい塩水をつくり、釜で煮つめて塩をとるのです。夏の炎天下、砂をならし、運び、火をたく ── とてもきびしい仕事でした。","こうしてできた «斎田塩» は、船で大坂や江戸へ運ばれ、阿波藍とならぶ徳島藩の大きな収入源になりました。瀬戸内海ぞいの10か国の塩田は «十州塩田» と呼ばれ、阿波もその一つとして全国の塩をささえたのです。撫養の港は塩や藍を積んだ船でにぎわいました。","昭和になると、塩づくりは «流下式» という方法に変わり、さらに1970年代、海水から電気の力で塩を取り出す新しい方法（イオン交換膜法）が広まると、日本中の塩田が一斉に姿を消しました。撫養の塩田も住宅地や学校、商店街に変わりました。«斎田» という町の名に、白い塩と汗の歴史がひっそりと残っています。"],"tl":[["1599年","撫養に塩田が開かれたと『板野郡誌』が記す"],["江戸時代","斎田塩が大坂・江戸へ運ばれ、藩の重要な産物に"],["昭和20年代〜30年代","入浜式から流下式へ製塩法が変わる"],["1972年ごろ","イオン交換膜法への転換で、全国の塩田が廃止される"],["現在","塩田の跡地は市街地に。地名に名残をとどめる"]],"who":[["蜂須賀家政","徳島藩の初代藩主。撫養の塩田開発を進めた"],["播磨の塩づくり職人","塩田の技術を伝えたと伝わる人びと"],["浜子（はまこ）","塩田で働いた労働者たち"],["塩問屋","斎田塩を各地へ売りさばいた商人"]],"deep":["«斎田» の地名は、塩田を開いて «財田» と名づけたことに由来するという説がありますが、鎌倉時代にすでに «佐伊田» という記録があり、塩田より古い地名とする見方もあります。","入浜式塩田は、潮の満ち引きを利用して海水を砂にしみこませる方式。人手のかかる «揚浜式» より効率がよく、瀬戸内で大きく発達しました。","«十州塩田» は、播磨・備前・備中・備後・安芸・周防・長門・阿波・讃岐・伊予の瀬戸内10か国の塩田の総称とされます。","撫養は阿波の北の玄関口。塩と藍を積んだ船が行き来し、撫養街道で徳島の城下や吉野川流域と結ばれていました。","塩田をやめたあとも、鳴門では工場による製塩が続いており、«鳴門の塩» の名は今も生きています。"],"look":["撫養町斎田の地名と、まっすぐな道や水路の町割り","撫養川ぞいの港町の雰囲気","鳴門市内の資料館などで塩田の写真や道具を確認","近くの岡崎・撫養の港"],"q":["撫養の塩田でとられた塩を何と呼んだ?","«斎田塩（さいたじお）» です。"],"koji":[],"myth":"播磨から職人を招いた話や «財田» 命名は伝承・地誌の記述。地名の由来には諸説。","img":["入浜式塩田","塩田","鳴門市"],"wp":"撫養","rel":{"ev":[],"grave":[]},"ph":[["c:9/93/Marakkanam_Salt_Pans.JPG",4055,2693,"入浜式塩田"],["c:6/6f/Naruto_Whirlpools_taken_4-21-2008.jpg",3456,2304,"鳴門市"]]},{"id":"36_wakimachi","n":"脇町のうだつの町並み","yomi":"わきまちのうだつのまちなみ","cat":"町","rank":"S","y":1707,"era":["edo","meiji"],"sh":"国の重要伝統的建造物群保存地区","ad":"美馬市脇町大字脇町（南町）","st":"JR徳島線 穴吹駅から車で約5分。徳島自動車道 脇町ICからすぐ","la":34.0681,"lo":134.1466,"hook":"«うだつが上がらない» のうだつは、ここにある。藍でもうけた商人たちが、競うように屋根の上に掲げた «富のしるし»。","lead":"脇町南町は、江戸時代から明治にかけて藍の取引で栄えた商人の町です。2階の壁から突き出した防火の壁 «うだつ» をもつ家が約430メートルの通りに並び、1988年に国の重要伝統的建造物群保存地区に選ばれました。","story":["通りに立って見上げてみてください。白いしっくいの家々の2階の両はしに、屋根つきの小さな壁が突き出ています。これが «うだつ»。もともとは、となりの家からの火事の火が燃えうつらないようにする «防火壁» でした。でもここ脇町のうだつは、どれもりっぱで、かざりがついているものもあります。«どうしてこんなに豪華なの?»","1585年、徳島藩主の蜂須賀家政は、家老の稲田植元を脇城に入れました。植元は、この地が吉野川の舟運と、讃岐へ通じる街道、撫養へ向かう街道が交わる場所であることに目をつけます。各地から商人を呼び集め、藍づくりをすすめて、商人の町をつくったといわれます。","江戸時代、吉野川の中流で作られた藍は脇町に集められ、舟で川を下って徳島や大坂へ運ばれました。藍商たちは大もうけし、脇町は徳島・撫養につぐ «阿波第3の町» とまでいわれるほど栄えます。豪商たちは «うちはこんなに栄えているぞ» と示すように、競って豪華なうだつを上げました。","«うだつが上がらない» ということばを知っていますか? «いつまでたっても出世しない、ぱっとしない» という意味です。りっぱなうだつを上げられるのはお金持ちだけ。ここから、このことばが生まれたともいわれます。脇町の通りを歩くと、その意味が目に見えてわかるのです。","明治の終わり、化学染料におされて藍はおとろえ、町は養蚕や繭の取引でにぎわいました。やがて鉄道が吉野川の向こう岸を通ったため、町の中心はそちらへ移ります。«取り残された» ことが、かえって古い町並みを守ることになりました。いまは約50のうだつが並び、最も古い家には1707年の棟札が残っています。"],"tl":[["1585年","稲田植元が脇城に入り、城下町づくりを進める"],["1707年","町並みに残る最も古い家の棟札の年"],["江戸時代","藍の集散地として栄え、豪華なうだつが上がる"],["明治30年代以降","藍がおとろえ、養蚕・繭の町に"],["1986年","«日本の道100選» に選ばれる"],["1988年12月16日","国の重要伝統的建造物群保存地区に選定"]],"who":[["稲田植元","蜂須賀家の筆頭家老。脇城に入り町づくりを進めた"],["蜂須賀家政","徳島藩主。稲田氏を脇城に置いた"],["脇町の藍商","藍の取引で富をきずき、うだつを上げた商人たち"],["吉田家","1792年創業と伝わる藍商の家。住宅が公開されている"]],"deep":["保存地区は約5.3ヘクタール。江戸中期から昭和初期の伝統的建造物85棟ほどが、東西約430メートルの通りに並びます。","うだつの語源や «うだつが上がらない» の由来には諸説あり、«梲（うだち）» という柱の名から来たという説もあります。脇町が由来の地というわけではありません。","脇町の家々は、本瓦ぶき・しっくいの大壁造り。格子、蔀戸（しとみど）、虫籠窓（むしこまど）など、商家らしい意匠が見どころです。","稲田家はのちに淡路の洲本城代もつとめ、明治初めの «稲田騒動» で北海道の静内へ移住しました。脇町と北海道の静内町が姉妹都市だった縁はここにあります。","近くの «脇町劇場（オデオン座）» は昭和初期の芝居小屋で、映画 «虹をつかむ男» の舞台にもなりました。"],"look":["約430メートルの通りに並ぶうだつ（見上げて数えてみよう）","藍商の暮らしを伝える吉田家住宅","吉野川の船着場跡の公園","少し足をのばして脇町劇場（オデオン座）"],"q":["うだつは、もともと何のためのもの?","となりの家からの火事の延焼を防ぐための «防火壁» です。"],"koji":[{"w":"うだつが上がらない","m":"いつまでたっても出世しない、ぱっとしないこと。りっぱなうだつを上げるには財力が必要だったことから、といわれる"}],"myth":"«うだつが上がらない» の語源は諸説。稲田植元が商人を集めた話は «といわれる»。","img":["脇町南町","うだつ","稲田植元"],"wp":"脇町","rel":{"ev":[],"grave":[]},"ph":[["c:b/b8/Wakimachi_Minami-machi_in_Mima_Tokushima_pref01.jpg",2304,1536,"脇町"],["c:e/ea/Wakimati_minamimati_20250828_1.jpg",2048,1634,"脇町南町"],["c:c/c6/Inada_Tanemoto.jpg",2125,4694,"稲田植元"]]},{"id":"36_sadamitsu","n":"貞光の二層うだつの町並み","yomi":"さだみつのにそううだつのまちなみ","cat":"町","rank":"B","y":1870,"era":["edo","meiji"],"sh":"","ad":"美馬郡つるぎ町貞光","st":"JR徳島線 貞光駅から歩いて約15分","la":34.035,"lo":134.061,"hook":"1階にも2階にもうだつ。«二段がまえ» の防火壁が、剣山へ向かう谷口の町に商人の心意気を刻む。","lead":"つるぎ町貞光には、1階と2階の両方にうだつをもつ «二層うだつ» の家が並ぶ町並みがあります。明治の初めごろに整えられた商家が多く、うだつにはしっくいで描いた «鏝絵（こてえ）» のかざりも見られます。剣山への入り口の町として栄えました。","story":["脇町のうだつを見た人が、貞光に来ると «あれ?» と首をかしげるかもしれません。うだつが1階にも2階にもあるのです。これが «二層うだつ»。2段がまえの防火壁が、通りに面してずらりと並ぶ景色は、ほかではなかなか見られません。","貞光は、貞光川が吉野川に流れこむところにできた «谷口» の町です。山から運ばれる木材や葉たばこ、山の産物と、平野から来る品々が、ここで取り引きされました。また、四国で2番目に高い剣山へ登る道の入り口でもあり、多くの人が行き来しました。","«なぜうだつを2段にしたの?» 火事に強くするためという実用の理由に加え、«うちはこれだけの家だ» という見せる意味もあったと考えられます。うだつの正面には、しっくいをこてでぬり上げてつくる «鏝絵» がほどこされ、鶴や亀、恵比寿さまなど、家の繁盛や長寿を願う絵がえがかれています。","代表的な建物が «織本屋»。江戸時代のうだつの姿を残しつつ、明治の初めに酒造りの商家として建て直された家で、国の登録有形文化財になっています。また町なかには、庄屋をつとめた «旧永井家庄屋屋敷» も残り、町の人びとの暮らしを伝えています。","町を歩くと、2段のうだつの間から見える山の緑と、屋根のかわらの波が美しく重なります。鏝絵を一つずつ見くらべながら、«どの家がいちばん自慢したかったのかな?» と想像してみるのも楽しいでしょう。ガイドの案内で歩くこともできます。"],"tl":[["江戸時代","貞光が吉野川と剣山方面を結ぶ谷口の町として栄える"],["明治初期","二層うだつの商家が多く建てられる。織本屋もこのころ再建"],["1907年","貞光村が町制をしいて貞光町に"],["2005年","半田町・一宇村と合併し、つるぎ町となる"],["現在","«二層うだつの町並み» として保存・公開が進む"]],"who":[["織本屋の商家","明治初めに酒造りの店として家を建て直した"],["永井家","庄屋をつとめた家。屋敷が公開されている"],["左官職人","うだつや鏝絵をしっくいで仕上げた職人たち"],["剣山への旅人","貞光を入り口に山へ向かった人びと"]],"deep":["«二層うだつ» は、1階の屋根の両はしと2階の両はしの両方にうだつを設けたもの。防火の効果を高めるとともに、家の格を示す意匠でもあったと考えられます。","鏝絵は左官がこてだけで立体的にえがく装飾。地域の職人の腕くらべの場でもありました。","織本屋（旧折目家住宅）は国の登録有形文化財。旧永井家庄屋屋敷はつるぎ町指定有形文化財です。","貞光は剣山の北の登山口の一つで、剣山信仰の参拝者の宿場としての役割もあったといわれます。","貞光の町並みは、同じ美馬地方の脇町とよく比べられます。脇町は江戸の藍商の町、貞光は明治初めの二層うだつ、と見くらべると違いが見えてきます。"],"look":["1階・2階の二段のうだつ","うだつ正面の鏝絵（鶴・亀・恵比寿など）","織本屋（旧折目家住宅）","旧永井家庄屋屋敷"],"q":["貞光の町並みの «二層うだつ» とはどんなもの?","1階と2階の両方にうだつを設けたものです。"],"koji":[],"myth":"二層にした理由は «考えられる» 範囲。産物の種類は資料により異なる。","img":["二層うだつの町並み","うだつ","鏝絵"],"wp":"貞光町","rel":{"ev":[],"grave":[]},"ph":[["c:3/39/%EF%BC%B5%EF%BD%84%EF%BD%81%EF%BD%94%EF%BD%95%EF%BD%8D%EF%BD%81%EF%BD%94%EF%BD%89%EF%BD%8E%EF%BD%81%EF%BD%8D%EF%BD%89_%EF%BD%94%EF%BD%95%EF%BD%92%EF%BD%95%EF%BD%87%EF%BD%89.jpg",1600,1066,"貞光町"],["c:6/62/%E9%B3%B4%E6%BB%9D_-_panoramio.jpg",1067,1600],["c:1/1a/Quina_Saffron_Winery_02.jpg",5760,3840,"鏝絵"]]},{"id":"36_teshima_island","n":"出羽島（牟岐沖の漁村集落）","yomi":"てばじま","cat":"島","rank":"A","y":1850,"era":["edo","meiji","showa"],"sh":"国の重要伝統的建造物群保存地区","ad":"海部郡牟岐町牟岐浦（出羽島）","st":"牟岐港から連絡船で約15分（JR牟岐駅から港まで歩いて約10分）","la":33.6317,"lo":134.4242,"hook":"車の走らない島。港をぐるりと囲む家々の «ミセ» がぱたんと開けば、そこはもう漁師町の縁台になる。","lead":"出羽島は、牟岐町の沖約4キロにある小さな島です。江戸時代に徳島藩のすすめで人が移り住み、カツオ漁で栄えました。港のまわりに漁師の家々が馬のひづめの形に並ぶ集落は、国の重要伝統的建造物群保存地区に選ばれています。","story":["牟岐の港から小さな連絡船に乗って15分。島が近づくと、入江をぐるりと囲むように家々が並んでいるのが見えてきます。島には車がほとんど走っていません。細い路地を、荷物を積んだ手押し車がことことと行き来します。«時間がゆっくり流れている» ── 多くの人がそう感じる島です。","出羽島に本格的に人が住みはじめたのは江戸時代。徳島藩が海の開発のために移住をすすめたことで、漁師の村ができたといわれます。島のまわりの海はカツオの好漁場。江戸の後期から昭和の前期にかけて、カツオ漁の繁栄とともに集落は大きくなっていきました。","島の家々を見て «あれ、あの板は何?» と思うかもしれません。家の表にある «ミセ» と呼ばれる板の仕かけです。上下に開く板戸で、下の板をぱたんと倒せば縁台（ベンチ）に、上の板を上げればひさしになります。雨の日は閉じて戸じまり、晴れた日は開いて、魚をならべたり、おしゃべりしたりする場所に。せまい島の知恵がつまった仕かけです。","1830年の年明け、この島の近くにイギリスの船がやってきて、牟岐の人びとをおどろかせたという記録もあります（牟岐浦異国船漂着事件）。鎖国の時代、遠い海のかなたの世界が、ふいに島の前に現れたのです。","いまは人口がへり、小学校も閉じられましたが、漁師町の家並みは大切に守られています。島の北の入江を囲む約3.7ヘクタールの集落は、2017年に国の重要伝統的建造物群保存地区に選ばれました。島をひと回りする遊歩道を歩けば、灯台から太平洋と室戸の山々が見渡せます。"],"tl":[["江戸時代","徳島藩の移住奨励により漁村集落ができる"],["1830年1月","近くにイギリス船が停泊（牟岐浦異国船漂着事件）"],["江戸後期〜昭和前期","カツオ漁の隆盛とともに集落が広がる"],["昭和後期以降","人口減少が進み、小学校が閉校に"],["2017年","«牟岐町出羽島» が国の重要伝統的建造物群保存地区に選定"]],"who":[["徳島藩","島への移住をすすめ、漁村の基礎をつくった"],["出羽島の漁師たち","カツオ漁で島を栄えさせた"],["島の大工・職人","ミセ造りなど島の家並みをつくった"],["連絡船の人びと","牟岐と島を毎日結んでいる"]],"deep":["島の面積は約0.65平方キロ。約77％が林野で、人家は漁港の周りに馬蹄形（U字形）に集まっています。","選定理由は «徳島藩の移住奨励によって形成され、江戸後期から昭和前期まで鰹漁の隆盛に伴って拡大した漁村集落» で、規模や形式がそろった漁家の主屋が並ぶ景観が評価されました。","«ミセ造り» の板戸は、四国の古い町家や漁村に見られる «ばったり床几» の仲間。出羽島では今も多くの家に残ります。","島の大池は、シラタマモという珍しい藻の自生地で、国の天然記念物です。2005年には島の名前をつけた新種のスゲ «テバジマスゲ» も見つかりました。","島の郷土料理 «島そうめん» は、レンコダイの煮つけの煮汁をつゆに使うのが特徴です。"],"look":["港を囲む漁師町の家並み","家々の «ミセ»（開いていたら縁台に注目。住民の家なので勝手に座らない）","島一周の遊歩道と出羽島灯台からの眺め","国の天然記念物・大池のシラタマモ自生地"],"q":["出羽島の家の表にある、上下に開く板戸の仕かけを何という?","«ミセ» です。下の板を倒すと縁台に、上の板はひさしになります。"],"koji":[],"myth":"移住の始まりの年代ははっきりしない。住民の生活の場なので見学はマナーを守って。","img":["牟岐町","重要伝統的建造物群保存地区"],"wp":"出羽島","rel":{"ev":[],"grave":[]},"ph":[["c:6/68/Tebajima_1.jpg",1568,1176,"出羽島"],["c:1/11/Teba-jima_Island_Aerial_photograph.1975.jpg",2705,1957],["c:3/3f/Tebajima_2.jpg",1814,1354],["c:7/79/Morasukomugi20220524_1.jpg",1600,1096,"牟岐町"]]},{"id":"36_ishima","n":"伊島（阿南沖の «四国最東端» の島）","yomi":"いしま","cat":"島","rank":"B","y":1654,"era":["edo","meiji"],"sh":"","ad":"阿南市伊島町","st":"阿南市の答島港から連絡船で約30分（答島港へはJR牟岐線 阿波橘駅が最寄り）","la":33.85,"lo":134.8153,"hook":"四国の «いちばん東» の岬の、さらに6キロ先。紀伊水道にうかぶ小島は、江戸時代の開拓から始まった。","lead":"伊島は、四国最東端の蒲生田岬から東へ約6キロの紀伊水道にうかぶ島です。江戸時代の1654年に本格的な移住が始まったと伝わり、漁業の島として歩んできました。四国の島々の中でいちばん東にある島の一つで、豊かな自然が残っています。","story":["阿南市の答島港から、連絡船で約30分。四国のいちばん東の岬・蒲生田岬のさらに沖に、伊島はあります。晴れた日には、海の向こうに紀伊半島の山なみが見えることも。«ここが四国の東の果てか» ── そう思うと、ちょっと特別な気分になります。","島に本格的に人が住みついたのは、江戸時代の1654年と伝わります。この年、神野惣右衛門という人が、領主の森甚五兵衛の命令で島に移り住みました。森氏は徳島藩の水軍を率いた家。紀伊水道の見張りや漁場の開発のために、この島を大切に考えたのかもしれません。","島の集落は、となりの前島とのあいだの静かな水道に面した、わずかな平地にぎゅっと集まっています。島の面積の4分の3ほどは山林。人びとは海にこぎ出し、魚をとって暮らしてきました。けれども、家々が密集していたことが、ときに悲劇をまねきます。","幕末の元治元年（1864年）の暮れ、集落のほとんどを焼く大火が起こりました。人びとは力を合わせて村を建て直しましたが、明治の1883年にも再び大火に見まわれ、大半が焼けてしまったと伝わります。«それでも島で生きていく» ── 島の人びとは、そのたびに立ち上がってきたのです。","いまの伊島は、100人あまりが暮らす静かな島です。まわりの海と海岸は «日本の重要湿地500» にも選ばれ、初夏には島に自生するササユリが咲くことで知られます。當所神社や松林寺、灯台をめぐりながら、四国の東の端で海とともに生きてきた人びとの歴史にふれてみてください。"],"tl":[["1654年","神野惣右衛門が領主・森甚五兵衛の命で移り住む"],["1864年（元治元年）12月","集落のほとんどを焼く大火（新暦では1865年1月）"],["1883年","再び大火で大半を焼失"],["1990年","人口約280人"],["2001年","«伊島および周辺沿岸» が日本の重要湿地500に選ばれる"]],"who":[["神野惣右衛門","1654年に島へ移り住み、開拓を始めたと伝わる"],["森甚五兵衛","徳島藩の水軍をあずかった森家の当主。移住を命じた"],["伊島の漁師たち","紀伊水道の海で暮らしを立ててきた"],["島の人びと","2度の大火から村を立て直した"]],"deep":["四国本島の最東端は蒲生田岬ですが、伊島はそのさらに東にあり、四国の島々を含めた «東の果て» として紹介されることがあります。","森氏は戦国時代に阿波の水軍として活躍し、江戸時代には徳島藩の «御船手» として海の守りを担いました。","島の地質は砂岩が中心。集落は西側の前島との間の水道に面した約2ヘクタールの平地にあります。","西にある前島・棚子島はいまは無人島です。","伊島のササユリは地元で大切に守られている花で、季節には見学に訪れる人もいます（採取は厳禁）。","大火の日付は «元治元年12月20日» と伝わり、新暦に直すと1865年1月にあたります。資料によって «1864年» «1865年» と表記が分かれるのはこのためです。"],"look":["連絡船から見る島の全景と紀伊水道","前島との水道に面した集落の家並み","當所神社・松林寺","伊島灯台と島の東側の海の眺め","初夏のササユリ（採らずに見るだけ）"],"q":["伊島への移住が本格的に始まったのは何年と伝わる?","1654年です。神野惣右衛門が領主の命で移り住んだと伝わります。"],"koji":[],"myth":"«四国最東端» は本島では蒲生田岬。大火の年の表記に資料間のずれあり。","img":["蒲生田岬","紀伊水道"],"wp":"伊島","rel":{"ev":[],"grave":[]},"ph":[["c:4/49/Kamodamisaki_Lighthouse.jpg",2400,1600,"蒲生田岬"],["c:a/a8/%E4%BC%8A%E5%B3%B6_%E8%92%B2%E7%94%9F%E7%94%B0%E5%B2%AC%E3%82%88%E3%82%8A%E6%9C%9B%E3%82%80_-_panoramio.jpg",1755,1308,"近く: 伊島 (阿南市)"],["c:8/81/School_in_ishima_island_-_%E4%BC%8A%E5%B3%B6%E5%B0%8F%E5%AD%A6%E6%A0%A1_-_panoramio.jpg",3872,2592,"近く: 阿南市立伊島小学校"],["c:7/78/Anan_maejima_island_aerial_shot.jpg",2776,2082,"近く: 前島 (徳島県)"]]},{"id":"36_tomoura","n":"鞆浦（海部の港町と «大岩の碑»）","yomi":"とものうら","cat":"町","rank":"B","y":1605,"era":["edo"],"sh":"","ad":"海部郡海陽町鞆浦","st":"阿佐海岸鉄道 海部駅から歩いて約15分","la":33.589,"lo":134.364,"hook":"港のそばの大きな岩に、400年前の人びとが刻んだ «津波が来た» という記録。それは未来の私たちへの手紙だった。","lead":"鞆浦は、海陽町の海部川河口近くにある漁港の町です。港の近くの大岩には、江戸時代の慶長地震（1605年）と宝永地震（1707年）の津波の被害を刻んだ «大岩慶長宝永碑» があります。昔の人が残した津波の記録として、大切に守られています。","story":["海部川の河口に近い鞆浦は、漁船が並ぶ小さな港町です。家々の間の細い路地を抜けると、港のそばに大きな岩がどっしりと座っています。近づいてみると、岩の表面に文字が刻まれていることに気づくでしょう。«これは何が書いてあるの?» ── それは、津波の記録でした。","1605年2月（旧暦では慶長9年12月16日）、南海の海で大きな地震が起こりました。«慶長地震» です。その夜、鞆浦を大津波がおそいました。岩に刻まれた文には、高さ «十丈»（約30メートル）もの波が来た、と記されているといいます。この津波で、鞆浦では100人あまりの人が亡くなったと伝えられています。","«なぜ岩に刻んだのでしょう?» 紙の記録は火事や水で失われます。でも、大きな岩なら何百年も残る。«この浦に、また大きな波が来るかもしれない。忘れるな» ── 生き残った人びとは、そんな願いをこめて文字を刻んだのではないでしょうか。","その思いは現実になります。約100年後の1707年、宝永地震が起こり、再び鞆浦を津波がおそいました。人びとは同じ岩に、この津波のことも書きくわえたといわれます。一つの岩に二つの大津波の記録 ── だから «慶長宝永碑» と呼ばれるのです。","鞆浦のある海陽町は、将来の南海トラフ地震でも大きな津波が予想されている地域です。町には津波避難タワーもつくられています。岩に刻まれた文字は、400年前の人びとから今を生きる私たちへの «手紙»。亡くなった人びとに手を合わせながら、その言葉を受けとめたい場所です。"],"tl":[["1605年2月3日","慶長地震（旧暦・慶長9年12月16日）。鞆浦を大津波がおそう"],["慶長地震のあと","津波の記録を大岩に刻む"],["1707年10月28日","宝永地震（旧暦・宝永4年10月4日）。再び津波"],["宝永地震のあと","同じ岩に宝永の津波の記録が加えられたといわれる"],["1854年","安政南海地震。南阿波の沿岸に再び津波"],["2015年","海陽町の宍喰に津波避難タワーが完成"]],"who":[["鞆浦の人びと","津波で家族や仲間を失い、記録を岩に刻んだ"],["海部の漁師たち","港を拠点に海で暮らしてきた"],["宍喰の人びと","となりの浦で同じ慶長津波の被害を記録に残した"]],"deep":["«大岩慶長宝永碑» には、慶長の津波の高さを «十丈» と記しているといわれます。実際の波の高さは、研究では約10メートルと推定されることが多く、数字の受けとり方には注意が必要です。","慶長地震は、揺れのわりに大きな津波が起こった «津波地震» だった可能性が指摘されています。震源や規模にはまだ諸説があります。","となりの宍喰では、寺の古い記録（『円頓寺開山住持宥慶之旧記』など）に慶長津波の被害が書かれています。死者の数には大きな数字もありますが、当時の人口から見て過大とする意見もあります。","碑文はかなり読みにくくなっているため、内容の細部は資料によって読み方に違いがあります。","海陽町は南海トラフ巨大地震で最大12メートルほどの津波が予想されており、昔の碑が防災教育に生かされています。"],"look":["港のそばの大岩と刻まれた碑文（案内板で内容を確認）","漁港と入りくんだ路地の家並み","海部川の河口と海部城跡（城山）","津波避難の案内標識"],"q":["鞆浦の大岩に記録された二つの大津波は、何という地震によるもの?","1605年の慶長地震と、1707年の宝永地震です。"],"koji":[{"w":"天災は忘れたころにやってくる","m":"災害は人びとが前の災害を忘れたころにまた起こる、という戒め。物理学者・寺田寅彦のことばとして広まった"}],"myth":"碑文の細部（波高・死者数）は読み方・資料により異同あり。宝永の追刻の経緯も «といわれる»。","img":["慶長地震","宝永地震","海陽町"],"wp":"鞆浦","rel":{"ev":[],"grave":[]},"ph":[["c:0/0f/Tomoura-Oiwa-keicho-hoei.jpg",2592,1944,"慶長地震"],["c:3/3a/Todoroki_Watefalls_02.JPG",2848,4288,"海陽町"],["c:c/cc/Kaifu_Station%2C_ekisha.jpg",6016,4000,"近く: 海部駅"],["c:f/fe/Jomanji.jpg",980,735,"近く: 海部町"],["c:b/bb/Kaifu_Junior_High_School.jpg",3264,2448,"近く: 海陽町立海部中学校"],["c:7/73/Kaifu_Elementary_School.jpg",3264,2448,"近く: 海陽町立海部小学校"],["c:5/59/Kaifu_post-office.jpg",2006,1504,"近く: 海部郵便局"],["c:c/cc/Hokkeji_20240416_1.jpg",2400,1799,"近く: 法華寺 (徳島県海陽町)"]]},{"id":"36_osaka_toge","n":"大坂峠（讃岐への国境の峠）","yomi":"おおさかとうげ","cat":"街道","rank":"B","y":1185,"era":["heian","edo"],"sh":"","ad":"鳴門市北灘町碁浦／板野郡板野町（香川県東かがわ市との境）","st":"JR高徳線 板野駅から車で約20分（歩くならハイキングコースで）","la":34.1918,"lo":134.4439,"hook":"義経が夜の闇をかけぬけ、蜂須賀の兵が越え、お遍路さんが最後に下った ── 阿波と讃岐をつなぐ標高270メートルの «国ざかい»。","lead":"大坂峠は、徳島県と香川県の境にある標高約270メートルの峠です。古代の官道・南海道が通り、源義経が屋島へ向かうときに越えたと伝わります。江戸時代には徳島藩の番所が置かれ、国境を見張りました。いまは展望台からの眺めが人気です。","story":["徳島平野の北のはしから、讃岐山脈の山すそを見上げてみましょう。その尾根の低いところを越えて、昔から人びとは讃岐へと行き来してきました。そのいちばん東の越え道が «大坂峠»。«坂» といっても大阪とは関係なく、「大きな坂」の意味と考えられています。","古代、都と四国を結ぶ官道 «南海道» は、この峠を通っていたと考えられています。阿波の役人や旅人、税の品を運ぶ人びとが、息をきらして登った道です。","1185年2月、この峠を真夜中にかけぬけた一団がいました。源義経の軍勢です。阿波の勝浦に上陸した義経は、その日のうちに阿波を北へ走り、『平家物語』によれば «阿波と讃岐の境の大坂越» を越えて讃岐の引田へ下り、翌日、屋島の平家を背後からおそいました。«まさか陸から来るとは» ── 平家のおどろきが目に浮かぶようです。","江戸時代、阿波の徳島藩は峠道のふもと近くに «大坂口御番所» を置き、1644年から1872年まで、人と物の出入りをきびしく見張りました。一方で、四国遍路の人びとにとってもこの峠は大事な道。88番の大窪寺で結願したお遍路さんが、1番の霊山寺へ戻る «お礼参り» の道としても使われたといわれます。","明治には峠道が大きく改修され、大正時代には車の通れる道もできました。やがて鉄道はトンネルで山を抜け、国道は海ぞいへ移り、峠を越える人は少なくなりました。いまの展望台からは、鳴門の海や淡路島、晴れれば小豆島まで見渡せます。義経も見たかもしれない夜明けの海を想像しながら、国ざかいの風に吹かれてみてください。"],"tl":[["古代","南海道の官道が大坂越を通ったと考えられる"],["1185年2月","源義経が大坂越を越えて讃岐へ入り、屋島を攻める"],["1585年","秀吉の四国攻めで、蜂須賀勢を含む軍が讃岐から峠を越えて阿波へ入ったと伝わる"],["1644年","徳島藩が大坂口御番所を置く（1872年まで）"],["1874〜1875年","峠道の大改修"],["1935年","鉄道が大坂山トンネルで峠を抜ける"]],"who":[["源義経","屋島へ向かうため、夜通しこの峠を越えたと伝わる"],["近藤六親家","義経を案内した阿波の武士"],["蜂須賀家政","四国攻めののち阿波の領主となった。徳島藩は峠に番所を置いた"],["お遍路さん","結願後に1番札所へ戻る道として峠を使った"]],"deep":["大坂峠は、板野町と鳴門市の境の «大坂越» と、鳴門市と東かがわ市の県境の «大坂峠» の二つの峠からなり、まとめて呼ばれることもあります。","『平家物語』巻11には «阿波と讃岐とのさかひなる大坂越» という表現があり、義経の進軍路の手がかりになっています。ただし清水越や大山越を通ったとする説もあります。","『源平盛衰記』では、峠の手前の金泉寺で義経一行が観音講のごちそうを食べた、という話が語られます（物語上の逸話）。","大坂口御番所は峠から1キロあまり下った所にあり、約230年間、阿波の北の «関所» の役目を果たしました。","明治以降、峠道は国道22号にも指定されましたが、1964年に海ぞいの国道11号が整備され、峠の交通は大きく減りました。"],"look":["峠の展望台からの鳴門海峡・淡路島の眺め","旧道のハイキングコース","大坂口御番所の跡（案内板で確認）","ふもとの金泉寺（四国八十八箇所3番）"],"q":["源義経は大坂峠を越えて、どこにいた平家を攻めた?","讃岐の屋島です。阿波から陸路で背後にまわり、奇襲しました。"],"koji":[],"myth":"義経の通過ルート・日付には諸説。1585年の峠越えは «といわれる»。","img":["屋島の戦い","南海道","源義経"],"wp":"大坂峠","rel":{"ev":[],"grave":[]},"ph":[["c:7/73/Osakatoge.jpeg",4032,3024,"大坂峠"],["c:4/48/Battle_of_Yashima_Folding_Screens_Kano_School.jpg",10969,4896,"屋島の戦い"],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"]]},{"id":"36_inukai_butai","n":"犬飼農村舞台（阿波人形浄瑠璃の舞台）","yomi":"いぬかいのうそんぶたい","cat":"学び","rank":"A","y":1873,"era":["meiji"],"sh":"国の重要有形民俗文化財","ad":"徳島市八多町八屋（五王神社境内）","st":"JR徳島駅から徳島バス «五滝» 行きで終点下車、歩いて約10分","la":33.9859,"lo":134.5001,"hook":"ふすまが一枚、また一枚と入れかわり、舞台の奥へ奥へと広がっていく。村人が作った «からくり» の舞台が、今も秋に目をさます。","lead":"犬飼農村舞台は、徳島市八多町の五王神社の境内にある、人形浄瑠璃を上演するための野外の舞台です。1873年に建てられ、ふすま絵を次々と入れかえる «ふすまからくり» の仕かけが昔のままに残っています。国の重要有形民俗文化財で、毎年秋に上演が行われます。","story":["徳島市の山あい、八多町の五王神社。ふだんは静かな境内に、大きな屋根の古い建物が建っています。これが犬飼農村舞台。«農村舞台» とは、村の人びとが自分たちで建て、自分たちで芝居を楽しんだ舞台のことです。","全国の農村舞台の多くは、人が演じる歌舞伎のためのものでした。ところが徳島の農村舞台は、ほとんどが «人形浄瑠璃» のために作られました。なぜ徳島では人形だったのでしょう? 阿波では江戸時代から人形浄瑠璃が大人気で、村々に人形座がありました。藍でうるおった農村の人びとは、祭りのたびに人形芝居を楽しんだのです。","犬飼農村舞台が建てられたのは明治のはじめ、1873年。見どころは «ふすまからくり» です。舞台の奥にふすまが何枚も重ねてあり、それを次々に入れかえたり、開いたりすると、景色ががらりと変わります。最後にはふすまが奥へ奥へと遠近法で並び、はるか遠くまで続く大広間のような «千畳敷» の景色があらわれる ── 観客から «おお!» と歓声が上がる名場面です。","このふすまを動かすのは、村の人たちの仕事でした。舞台裏で息を合わせ、拍子木の合図で一気に入れかえる。人形遣いや太夫、三味線だけでなく、裏方もふくめた村じゅうの力で、一つの舞台ができあがっていたのです。","明治から昭和にかけて、テレビや映画が広まると、農村舞台での上演はだんだん少なくなりました。それでも犬飼の人びとは舞台を守りつづけ、1998年に国の重要有形民俗文化財に。翌年には «阿波の襖からくりの習俗» も国の選択無形民俗文化財になりました。秋の上演の日、かがり火のような明かりの中で人形が動き、ふすまが入れかわるとき、明治の村の熱気がよみがえります。"],"tl":[["江戸時代","阿波の村々で人形浄瑠璃が盛んになる"],["1873年","犬飼農村舞台が建てられる"],["1978年10月17日","徳島市の有形文化財に指定"],["1998年12月16日","国の重要有形民俗文化財に指定（«犬飼の舞台»）"],["1999年","«阿波の襖からくりの習俗» が国の選択無形民俗文化財に"],["現在","毎年秋に人形浄瑠璃の上演が行われる"]],"who":[["八多・犬飼の村人","舞台を建て、ふすまからくりを動かしてきた"],["阿波の人形座","農村舞台で人形浄瑠璃を演じた芝居の一座"],["太夫・三味線","浄瑠璃の語りと音楽を受けもつ"],["人形遣い","一体の人形を三人で遣う技を伝える"]],"deep":["徳島県の農村舞台は、かつて県内に200以上あったといわれ、その多くが人形浄瑠璃用でした。今も数十の舞台が残るとされます。","«ふすまからくり» は、数十枚のふすま絵を使って場面を変える仕かけ。犬飼の舞台は、その仕かけがよい状態で残る例として貴重です。","最後にあらわれる «千畳敷» は、ふすまを遠近法で並べ、実際よりはるかに奥行きがあるように見せる工夫です。","指定名称は «犬飼の舞台»。舞台本体だけでなく、ふすまからくりの操作の «習俗» も文化財として認められている点が特徴です。","阿波人形浄瑠璃は、大坂の文楽とルーツを同じくしながら、野外で上演されたため人形が大きめで、動きも大きいといわれます。"],"look":["舞台の建物（外観はいつでも見学可）","秋の上演日の «ふすまからくり»（日程を事前に確認）","客席となる神社の境内の斜面","五王神社の社殿"],"q":["徳島県の農村舞台の多くは、何を上演するための舞台だった?","人形浄瑠璃です。全国の農村舞台の多くが歌舞伎用だったのと対照的です。"],"koji":[],"myth":"県内の舞台の数は時期や数え方で異なる。","img":["阿波人形浄瑠璃","人形浄瑠璃","農村舞台"],"wp":"犬飼農村舞台","rel":{"ev":[],"grave":[]},"ph":[["c:f/fb/%E6%96%87%E6%A5%BD%E4%BA%BA%E5%BD%A2%EF%BC%88%E6%96%B0%E5%A4%A7%E9%98%AA%E9%A7%85%EF%BC%89.jpg",3648,2736,"阿波人形浄瑠璃"],["c:e/ef/Pasant_Theatre_from_seats.JPG",3008,2000,"農村舞台"]]},{"id":"36_bando_furyo","n":"板東俘虜収容所跡（«第九» アジア初演の地）","yomi":"ばんどうふりょしゅうようじょあと","cat":"近代","rank":"S","y":1918,"era":["taisho"],"sh":"国指定史跡","ad":"鳴門市大麻町桧（ドイツ村公園）","st":"JR高徳線 板東駅から歩いて約20分","la":34.1592,"lo":134.4964,"hook":"敵国の捕虜が、日本で初めて «歓喜の歌» を響かせた。1918年6月1日、四国の小さな町の収容所で。","lead":"板東俘虜収容所は、第一次世界大戦で捕虜になったドイツ兵などを1917年から1920年まで収容した施設です。所長の松江豊寿は捕虜を人道的に扱い、捕虜たちは音楽やスポーツ、ものづくりで地域の人びとと交流しました。1918年、ここでベートーヴェンの «第九» が日本で初めて全曲演奏されました。","story":["1914年、第一次世界大戦で日本はドイツに宣戦し、中国の青島にあったドイツの基地を攻め落としました。捕虜になったドイツ兵などは約4700人。彼らは日本各地の収容所に送られ、そのうち約1000人が、1917年に開かれた徳島県板東町の新しい収容所に集められました。","収容所の所長は、陸軍の松江豊寿。会津（福島県）の出身で、父から戊辰戦争で «敗れた側» の苦しみを聞いて育ったといわれます。«彼らも祖国のために戦った人たちだ» ── 松江は国際法を守り、捕虜にできるかぎりの自由を認めました。捕虜たちは所内で新聞を発行し、パンを焼き、農園で野菜を育て、スポーツや演劇を楽しみました。","捕虜の多くは、もとは家具職人、時計職人、パン屋、肉屋、印刷工などの民間人でした。彼らは技術を生かして品物を作り、近くの人びとに売ったり教えたりしました。大麻比古神社にはいまも、捕虜たちが造った石の «ドイツ橋» が残っています。地元の人びとは親しみをこめて彼らを «ドイツさん» と呼んだといいます。","1918年6月1日。収容所の講堂で、捕虜たちのオーケストラと合唱団が、ベートーヴェンの交響曲第9番を演奏しました。これが日本で初めての «第九» の全曲演奏です。敵国の地で、捕虜たちが歌う «すべての人は兄弟になる» という歌詞 ── その場にいた人たちは、どんな気持ちで聞いたのでしょうか。","1920年、戦争の終わりとともに捕虜たちは帰国し、収容所は閉じられました。町は «お葬式のようにさびしくなった» と伝わります。捕虜が建てた慰霊碑はその後、草にうもれていましたが、1948年に地元の女性が見つけ、手入れを続けたことから、ドイツとの交流がよみがえりました。収容所跡はいまドイツ村公園となり、2018年に国の史跡に指定されています。ここで亡くなった捕虜たちの慰霊碑に、静かに手を合わせてみてください。"],"tl":[["1914年11月","日本軍が青島を攻略。ドイツ兵らが捕虜となる"],["1917年4月","板東俘虜収容所が開かれる"],["1918年6月1日","捕虜たちが «第九» を日本で初めて全曲演奏"],["1919年8月","捕虜たちが亡くなった仲間の慰霊碑を建てる"],["1920年4月","収容所が閉鎖される"],["1948年","草にうもれた慰霊碑が地元の女性に発見される"],["2018年","収容所跡が国の史跡に指定"]],"who":[["松江豊寿","収容所長。捕虜を人道的に扱い、自主的な活動を認めた"],["ドイツ兵捕虜たち","音楽・スポーツ・ものづくりで地域と交流した約1000人"],["ヘルマン・ハンゼン","捕虜の楽団の指揮者。第九の初演を指揮したとされる"],["冨田弘","ドイツ文学者。第九初演の事実を掘り起こした"]],"deep":["«第九の日本初演» の事実は、1982年にドイツ文学者の冨田弘の研究で明らかにされました。それまで広く知られていなかったのです。","収容所内の謄写版・石版の印刷所では、週刊新聞 «ディ・バラッケ» や演奏会のプログラム、所内専用の «板東収容所切手» まで刷られていました。","捕虜の中にはオーストリア＝ハンガリーの兵士もいました。第一次世界大戦のドイツ兵捕虜は日本各地の12か所の収容所に入れられ、板東はそれらを統合する形で最後に作られた施設です。","2007〜2011年度の発掘調査で、兵舎（バラッケ）の基礎などの遺構がよく残っていることが確かめられ、2018年の国史跡指定につながりました。","2006年の映画 «バルトの楽園» はこの収容所を描いた作品です（映画なので脚色があります）。","戦後、バラッケの建物の一部は海外からの引き揚げ者の住宅として使われ、1978年までにすべて取りこわされました。"],"look":["ドイツ村公園に残る収容所の遺構（基礎・給水施設など）","捕虜たちが建てた慰霊碑と合同慰霊碑","大麻比古神社の «ドイツ橋»（保存のため渡れない）","すぐ近くの鳴門市ドイツ館の展示"],"q":["板東俘虜収容所で «第九» が日本で初めて全曲演奏されたのはいつ?","1918年6月1日です。捕虜たちのオーケストラと合唱で演奏されました。"],"koji":[],"myth":"松江豊寿の会津体験の話や «ドイツさん» の呼び名は伝え話。映画は脚色を含む。","img":["松江豊寿","日独戦ドイツ兵捕虜"],"wp":"板東俘虜収容所","rel":{"ev":[],"grave":[]},"ph":[["c:5/59/140712_German_Village_Park_Naruto_Tokushima_pref_Japan01s3.jpg",6000,4000,"板東俘虜収容所"],["c:0/06/140712_Michinoeki_Daiku_no_sato_Naruto_Tokushima_pref_Japan02bs5.jpg",6000,4000],["c:6/66/140712_German_Village_Park_Naruto_Tokushima_pref_Japan04s3.jpg",6000,4000],["c:6/62/140712_Baruto-no-niwa_in_Bando_Naruto_Tokushima_pref_Japan13n.jpg",6000,4000],["c:d/dc/Gate_of_German_Village_Park_20160505.JPG",3251,2439],["c:7/76/Lager_Bando_1919.png",2339,3276],["c:7/7b/Matsue_Toyohisa.jpg",306,463,"松江豊寿"],["c:8/8c/Barraquement_au_camp_de_Kurume.jpg",2217,1344,"日独戦ドイツ兵捕虜"]]},{"id":"36_german_house","n":"鳴門市ドイツ館","yomi":"なるとしどいつかん","cat":"近代","rank":"A","y":1972,"era":["taisho","showa","heisei"],"sh":"","ad":"鳴門市大麻町桧","st":"徳島バス鳴門大麻線 «ドイツ館» 下車すぐ。JR板東駅から歩いて約20分","la":34.1647,"lo":134.4991,"hook":"1000人の捕虜が残した楽譜、新聞、手作りの品。«敵» と «味方» が友だちになった3年間を、いまに伝える小さな博物館。","lead":"鳴門市ドイツ館は、第一次世界大戦のドイツ兵捕虜を収容した «板東俘虜収容所» の記念館です。1972年に初代の館が生まれ、1993年に今の建物になりました。捕虜と地元の交流や、«第九» 日本初演の様子を、資料と映像で紹介しています。","story":["板東駅から歩いて20分ほど。赤いレンガ色の建物の前に、ベートーヴェンの像が立っています。ここが鳴門市ドイツ館。«なぜ鳴門にドイツ?» と思った人は、ぜひ中へ入ってみてください。そこには、100年以上前に始まった、国をこえた友情の物語があります。","1917年から1920年まで、この近くに板東俘虜収容所があり、約1000人のドイツ兵捕虜が暮らしていました。所長の松江豊寿は捕虜たちを人道的に扱い、捕虜たちは音楽会や展覧会を開き、パンやハム作り、橋づくりなどで地元の人びとと交流しました。館内には、捕虜たちが作った品々や、所内で刷られた新聞、演奏会のプログラムなどが展示されています。","戦争が終わると捕虜たちは帰国し、交流の記憶もいったんは忘れられかけました。ところが1948年、草にうもれた捕虜の慰霊碑を地元の女性が見つけ、手入れを始めます。«遠い国で亡くなった人たちにも、家族がいたはず» ── その思いが新聞で報じられ、やがてドイツ大使の訪問、元捕虜と板東の人びとの再会へとつながりました。","こうして1972年、地元とドイツ側の協力で初代の «鳴門市ドイツ館» が開かれました。元捕虜から寄せられた資料も多く、館そのものが交流の結晶だったのです。1993年には今の建物が完成し、2階には «第九» 初演の場面を人形と映像で再現するシアターがあります。","鳴門では毎年6月ごろ、«第九» を歌う演奏会が開かれ、全国から歌い手が集まります。2018年の初演100周年には、館の前に松江豊寿の銅像も建てられました。«敵どうし» だった人たちが音楽で心を通わせた場所 ── 展示を見終えたら、ぜひ «歓喜の歌» を口ずさんでみてください。"],"tl":[["1917〜1920年","近くに板東俘虜収容所が置かれる"],["1918年6月1日","収容所で «第九» が日本初の全曲演奏"],["1948年","捕虜の慰霊碑が地元の女性に発見される"],["1972年","初代の鳴門市ドイツ館が開館"],["1993年","現在の建物が完成"],["2018年6月","第九初演100周年。松江豊寿の銅像が建てられる"]],"who":[["松江豊寿","板東俘虜収容所の所長。館の前に銅像がある"],["ドイツ兵捕虜たち","音楽やものづくりで地域と交流した"],["ベートーヴェン","交響曲第9番の作曲者。館の横に像が立つ"],["板東の人びと","捕虜と交流し、戦後に慰霊碑を守った"]],"deep":["現在の建物は2代目で、場所も初代から移っています。初代の建物は、元捕虜から寄せられた資料をもとに開かれました。","1階にはドイツのニーダーザクセン州のコーナーがあります。鳴門市はニーダーザクセン州のリューネブルク市と姉妹都市の関係を結んでいます。","第九初演の演奏には、男声合唱を中心とする編成で臨んだといわれ、女声パートの扱いなど演奏の細部については研究が続いています。","館の南どなりの «道の駅第九の里» には、収容所の建物の一部を移したと伝わる建物があり、国の登録有形文化財になっています。","第九の日本初演の日にちなみ、6月1日は «第九の日» とされることがあります。"],"look":["館の前のベートーヴェン像と松江豊寿像","2階の «第九シアター»（初演の場面の再現）","捕虜の手作りの品や収容所新聞の展示","となりの道の駅 «第九の里» と、歩いて10分のドイツ村公園"],"q":["鳴門市ドイツ館の初代の館が開かれたのは何年?","1972年です。今の建物は1993年に完成した2代目です。"],"koji":[],"myth":"第九初演時の編成の細部は研究途上。","img":["板東俘虜収容所","交響曲第9番 (ベートーヴェン)"],"wp":"鳴門市ドイツ館","rel":{"ev":[],"grave":[]},"ph":[["c:7/7b/140712_Naruto_German_House_Naruto_Tokushima_pref_Japan02s3.jpg",5880,3920,"鳴門市ドイツ館"],["c:9/94/140712_Michinoeki_Daiku_no_sato_Naruto_Tokushima_pref_Japan01n.jpg",6000,4000],["c:5/59/140712_German_Village_Park_Naruto_Tokushima_pref_Japan01s3.jpg",6000,4000,"板東俘虜収容所"]]},{"id":"36_moraes","n":"モラエスゆかりの地（ポルトガルの文人が愛した徳島）","yomi":"もらえすゆかりのち","cat":"近代","rank":"A","y":1913,"era":["taisho","showa"],"sh":"","ad":"徳島市伊賀町・西山手町（潮音寺）・眉山山頂（モラエス館）","st":"JR徳島駅から旧居跡のある伊賀町・潮音寺まで歩いて約15〜20分。モラエス館は眉山ロープウェイ山頂駅すぐ","la":34.0695,"lo":134.5445,"hook":"神戸の総領事の地位を捨て、亡き妻の故郷・徳島で «ひとりの日本人のように» 暮らしたポルトガル人がいた。","lead":"ヴェンセスラウ・デ・モラエスはポルトガルの海軍士官・外交官で、神戸の総領事までつとめた人です。妻おヨネが亡くなると職を辞め、1913年におヨネのふるさと徳島へ移り住みました。徳島での日々や阿波おどりを、ポルトガル語の本に書き残しています。","story":["1889年、ひとりのポルトガル海軍士官が初めて日本の土をふみました。名はモラエス。やがてマカオでの勤務をへて外交官となり、1899年に神戸にポルトガル領事館ができると、その初代の副領事として赴任します。のちに総領事となり、日本の政治や文化を本国の新聞に書き送りました。遠い東の国のようすを、ポルトガルの読者は彼の文章で知ったのです。","神戸でモラエスは、芸者だった福本ヨネと出会い、1900年にいっしょに暮らしはじめます。けれど1912年、ヨネは病気で亡くなりました。本国ではちょうど政変が起きて王政がたおれ、モラエスの心はからっぽになります。«もう外交官でいる意味はない» 。1913年、彼は総領事の職を辞め、ヨネのふるさと徳島へ向かいました。","徳島では伊賀町の長屋に住み、ヨネのめいの斎藤コハルと暮らしました。でもコハルも1916年に若くして亡くなってしまいます。背が180cmをこえ、長いひげをのばした西洋人は町ではとても目立ち、«とーじんさん» と呼ばれました。第一次世界大戦のころにはスパイではと疑われたり、心ない言葉を投げられたりしたこともあったといいます。","それでもモラエスは徳島を離れませんでした。毎日のように墓参りをし、町の人のくらしや祭りを見つめ、ポルトガル語で書き続けます。『徳島の盆踊り』『おヨネとコハル』などの本には、夏の夜に町じゅうが踊り出す熱気や、小さな家の縁側から見た季節のうつろいが、やさしく記されています。«なぜ彼はここまで徳島にひかれたのか?» 答えは、亡き人たちが眠る土地だったからかもしれません。","1929年、モラエスは自宅で転んで頭を打ち、亡くなりました。75歳でした。墓は潮音寺にあり、おヨネとコハルの墓とならんで立っています。生前は日本でほとんど知られていませんでしたが、死後に本が日本語に訳され、しだいに «徳島を世界に紹介した人» として慕われるようになりました。いまも命日の7月1日には法要が営まれています。"],"tl":[["1854年","リスボンに生まれる"],["1889年","初めて日本を訪れる"],["1899年","神戸にポルトガル領事館ができ、初代副領事となる（のちに総領事）"],["1912年","妻のおヨネが亡くなる"],["1913年","総領事を辞め、徳島市伊賀町に移り住む"],["1916年","コハルが亡くなる。同じ年『徳島の盆踊り』を刊行"],["1929年","徳島の自宅で亡くなる"],["1969年","徳島市とポルトガルのレイリア市が姉妹都市に"],["1976年","眉山山頂に «モラエス館» が開館"]],"who":[["ヴェンセスラウ・デ・モラエス","ポルトガルの軍人・外交官・文筆家。晩年の16年を徳島で過ごした"],["福本ヨネ（おヨネ）","モラエスの妻。徳島出身。神戸で共に暮らした"],["斎藤コハル","おヨネのめい。徳島でモラエスと暮らした"],["新田次郎","作家。モラエスを描いた小説『孤愁 サウダーデ』を書いたが未完に終わった"]],"deep":["モラエスは1902年から1913年にかけて、ポルトの新聞『コメルシオ・ド・ポルト』に日本のようすを書き送り、その記事は『日本通信』として本にまとめられた。","『徳島の盆踊り』（1916年）は、阿波おどりを外国人が本格的に書いた早い記録として知られる。当時は «阿波おどり» ではなく «盆踊り» と呼ばれていたことも、この題名からわかる。","ポルトガル語で書かれたため生前の日本ではほぼ無名。死後、花野富蔵らの翻訳で紹介され、昭和初めには «日本をたたえた外国人» として持ち上げられた面もある。","一方で、晩年は «地方都市で亡き女性の思い出を書き続けた孤独な人» だったという見方もあり、日本礼賛だけで語るのは一面的だとの指摘がある。","旧居の一部は、眉山山頂の «モラエス館» に移されて保存・展示されている。伊賀町かいわいの道は1975年に «モラエス通り» と名づけられた。","新田次郎の未完の遺作『孤愁 サウダーデ』は、次男の藤原正彦が書きついで完成させた。父子二代でモラエスを追ったことになる。"],"look":["潮音寺のモラエスの墓（おヨネ・コハルの墓とならぶ）","伊賀町の旧居跡と «モラエス通り» の案内板","眉山山頂のモラエス館（旧居の一部や遺品）","瑞巌寺の門前（モラエス通りの起点）"],"q":["モラエスが徳島の夏祭りを書いた本の題名は？","『徳島の盆踊り』。1916年に出た本で、今の阿波おどりのもとになった踊りのようすが書かれています。"],"koji":[{"w":"サウダーデ","m":"ポルトガル語で、失ったものや遠いものを恋しく思う気持ち。モラエスの徳島での心をあらわす言葉としてよく使われる"}],"myth":"«スパイと疑われた»«西洋乞食とさげすまれた» といった話は伝聞をふくむ。","img":["眉山 (徳島市)","瑞巌寺 (徳島市)"],"wp":"ヴェンセスラウ・デ・モラエス","rel":{"ev":[],"grave":[]},"ph":[["c:2/2f/Wenceslau_de_Moraes_em_Kobe%2C_1897.jpg",828,1096,"ヴェンセスラウ・デ・モラエス"],["c:a/af/Venceslau_Morais_birthplace.JPG",3968,2976],["c:8/8d/Moraes_Memorial_Museum02n3872.jpg",3872,2592],["c:e/e5/Wenceslau_Jos%C3%A9_de_Sousa_de_Moraes-Monument_in_Tokushima.jpg",854,480],["c:2/22/Mount_Bizan_from_Shimmachi_River_20200607.jpg",3620,2413,"眉山 (徳島市)"],["c:3/30/Zuiganji.jpeg",828,617,"瑞巌寺 (徳島市)"]]},{"id":"36_mikawa_ke","n":"三河家住宅（昭和初めの鉄筋コンクリート洋館）","yomi":"みかわけじゅうたく","cat":"近代","rank":"B","y":1929,"era":["showa"],"sh":"国の重要文化財","ad":"徳島市富田浜","st":"JR牟岐線 阿波富田駅から歩いて約5分（内部は非公開・外観のみ）","la":34.0655,"lo":134.5585,"hook":"ドイツ帰りの医師が «友情の証» に建てさせた、塔のある白い洋館。空襲の炎にも耐えた。","lead":"三河家住宅は、産婦人科の医師・三河義行の家として昭和の初めに建てられた、鉄筋コンクリート3階建ての洋館です。ドイツ風のデザインで、塔や波の形のテラスがあります。国の重要文化財ですが、中は公開されていないので外から見学します。","story":["大正から昭和へ移るころ、徳島で産婦人科病院を開いていた医学博士・三河義行は、ドイツに留学していました。そこで出会ったのが、徳島県立工業学校の建築科を出た建築家・木内豊次郎です。同じふるさと、同じくらいの年。遠い異国で二人はすっかり意気投合しました。","帰国した三河は木内に、自分の家の設計をたのみます。«友情の証に、君の思うとおりの家を» 。こうして昭和初めに生まれたのが、この洋館です。当時の徳島の住宅はほとんどが木造。鉄筋コンクリートの3階建てで、高い塔が立ちあがる家は、町の人の目をひいたことでしょう。","«なぜコンクリートだったのか?» 1923年の関東大震災では、多くの建物がたおれ、燃えました。その教訓から、木内はじょうぶで火に強い構造を選び、しかも飾りまでコンクリートで形づくりました。2階の波うつようなテラス、洞くつのような «岩屋» 、どれもコンクリートだからこそできた形です。","1945年7月の徳島大空襲では、市街の多くが焼けました。この洋館は焼け落ちずに残りましたが、壁には空襲のあとが残っているといわれます。戦争をこえて残った建物は、地方の町にも本格的な近代建築が生まれたことを伝える貴重な証人として、1997年に登録有形文化財、2007年に国の重要文化財になりました。今は徳島市が持ち、使い道を考えているところです。"],"tl":[["1920年代","三河義行がドイツ留学中に建築家・木内豊次郎と出会う"],["昭和初め（1920年代末ごろ）","三河家住宅が建てられる"],["1945年7月4日","徳島大空襲。洋館は焼失をまぬがれる"],["1997年","国の登録有形文化財になる"],["2007年","国の重要文化財に指定される"]],"who":[["三河義行","医学博士・産婦人科医。この家の施主"],["木内豊次郎","徳島県立工業学校出身の建築家。三河の友人で、この家を設計"]],"deep":["重要文化財の指定は主屋だけでなく、コンクリート製の倉庫 «岩屋» 、外便所、門と塀も «附（つけたり）» として含む。敷地815㎡も建物と一体で価値があるとして指定されている。","«岩屋» はヨーロッパのバロック庭園によく見られるグロット（人工洞くつ）を思わせる。住宅の庭にこれを置いた例は、国内でもめずらしい。","設計は耐震性も考えたものといわれ、関東大震災後の «燃えない・たおれない家» への関心の高まりを映している。","徳島空襲の跡は、この家のほか旧高原ビル（ひびの入った窓ガラス）などにも残る。市内の «空襲を生きのびた建物» をめぐる手がかりになる。","地方の開業医が、留学先の人脈を生かして最新の建築を取り入れた例として、近代の地方都市の文化の厚みを物語る。"],"look":["道路から見える塔屋（展望台として使えた）","2階の波形のテラス","門と塀のデザイン","近くの阿波富田駅から歩いて町並みとあわせて見る"],"q":["三河家住宅はどんな材料でできている？","鉄筋コンクリート。飾りまでコンクリートで作られた、当時としてはとてもめずらしい住宅です。"],"myth":"建築年は資料により昭和3〜4年ごろと幅がある。壁の空襲痕の位置は現地で確かめられない。","img":["徳島大空襲"],"wp":"三河家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:7/73/Residence_of_Mikawa_Family_20160505.JPG",3264,2448,"三河家住宅"],["c:2/29/Onaruto-bridge_and_Naruto_Channel%2CNaruto-city%2CJapan.JPG",3872,2592,"近く: 徳島県"],["c:5/58/Awa-Tomida_Station_20160505-1.JPG",3264,2448,"近く: 阿波富田駅"],["c:8/8e/Kachidokibashi_Bridge_on_Shimmachigawa_River.JPG",3264,2448,"近く: かちどき橋"],["c:8/8b/Tokushima_city_library01s3200.jpg",2142,3200,"近く: 徳島市中央公民館"],["c:b/b8/Tokushima_prefectural_youth_center01s3200.jpg",3200,2142,"近く: 徳島県青少年センター"],["c:4/43/Suou_Art_Museum.jpg",854,480,"近く: 菘翁美術館"]]},{"id":"36_kagawa_toyohiko","n":"賀川豊彦記念館（鳴門）","yomi":"かがわとよひこきねんかん","cat":"近代","rank":"B","y":1892,"era":["meiji","taisho","showa"],"sh":"","ad":"鳴門市大麻町桧","st":"JR高徳線 板東駅から歩いて約20分。高速バス «鳴門西» から歩いて約5分","la":34.1595,"lo":134.501,"hook":"«カガワ・ガンジー・シュヴァイツァー» と並び称された人は、鳴門の村で少年時代を送った。","lead":"賀川豊彦は、神戸のスラムに住みこんで貧しい人を助け、労働組合や農民組合、生活協同組合づくりに力をつくした人です。幼いころ両親を亡くし、鳴門（当時の板野郡堀江村）の本家で育ちました。記念館はその鳴門の地に2002年に開かれました。","story":["1888年、賀川豊彦は神戸で生まれました。ところが4歳のとき、父と母をあいついで亡くします。姉といっしょに引き取られたのは、徳島・鳴門の賀川家の本家でした。血のつながらない義母と祖母に育てられ、周りからは冷たい言葉を浴びせられることもあった、さびしい子ども時代だったといいます。","旧制徳島中学に通っていた1904年、豊彦は徳島の教会で洗礼を受けます。トルストイの本を読み、戦争のない世界を夢見ました。«貧しい人のそばで、イエスの教えを実行したい» 。そう思いつめた青年は、1909年のクリスマス・イブ、神戸の新川という貧しい人が集まる町に引っ越します。まだ20代のはじめでした。","スラムでの暮らしはきびしいものでした。病気がはやり、賀川自身も目の病気で何度も失明しかけます。それでも彼は、困った人を家に招き入れ、食べ物を分けました。やがて «一人ひとりを助けるだけでは足りない。しくみを変えなければ» と考え、労働組合や農民組合、そして «みんなでお金を出しあって安く品物を買う» 生活協同組合の運動を広げていきます。","賀川の名は海外でも知られ、戦前には «カガワ、ガンジー、シュヴァイツァー» と、同じ時代の «聖人» として並べて語られたほどでした。鳴門の記念館は、彼が育った土地のすぐそばに建てられています。«いじめられた子どもが、なぜ人を助ける人になったのか?» 展示を見ながら考えてみてください。"],"tl":[["1888年","神戸に生まれる"],["1892年ごろ","両親を亡くし、鳴門（板野郡堀江村）の本家に引き取られる"],["1904年","徳島の教会で洗礼を受ける"],["1909年","神戸・新川のスラムに住みこんで活動を始める"],["1920年代","労働組合・農民組合・協同組合の運動を広げる"],["1960年","東京で亡くなる"],["2002年","鳴門市賀川豊彦記念館が開館"]],"who":[["賀川豊彦","キリスト教社会運動家・作家。少年時代を鳴門で過ごした"],["賀川ハル","豊彦の妻。スラムでともに救済活動をした社会運動家"],["H・W・マヤス","アメリカ人宣教師。徳島で豊彦に洗礼をさずけた"]],"deep":["記念館の外観は、大正時代に板東俘虜収容所のドイツ人の設計で建てられた «船本牧舎» をモデルにしている。となりには鳴門市ドイツ館があり、共通券もある。","1920年に出した自伝的小説『死線を越えて』は大ベストセラーになり、その収入を社会運動に注いだといわれる。","主著の一つ『貧民心理之研究』（1915年）は、貧しい人の中に住んで観察した研究として評価される一方、被差別部落についての誤った見方をふくみ、のちに批判された。賀川を語るうえで避けられない点である。","神戸での生活協同組合づくりは、今の «コープこうべ» の源流の一つとされる。","周辺には板東俘虜収容所跡、阿波国一宮の大麻比古神社、四国遍路1番札所の霊山寺があり、近代と信仰の歴史を一度にめぐれる。"],"look":["記念館の展示（少年時代と鳴門のつながり）","となりの鳴門市ドイツ館","板東俘虜収容所跡（ドイツ村公園）","大麻比古神社のドイツ橋"],"q":["賀川豊彦が神戸のスラムに移り住んだのは何の日？","1909年12月24日、クリスマス・イブでした。"],"myth":"引き取られた年は資料により1892〜93年と幅がある。","img":["賀川豊彦","板東俘虜収容所"],"wp":"鳴門市賀川豊彦記念館","rel":{"ev":[],"grave":[]},"ph":[["c:f/fe/140712_Naruto_City_Kagawa_Toyohiko_Museum_Naruto_Tokushima_pref_Japan01s3.jpg",6000,4000,"鳴門市賀川豊彦記念館"],["c:c/c8/KAGAWA_Toyohiko_young.JPG",308,300,"賀川豊彦"],["c:5/59/140712_German_Village_Park_Naruto_Tokushima_pref_Japan01s3.jpg",6000,4000,"板東俘虜収容所"]]},{"id":"36_torii_ryuzo","n":"鳥居龍蔵記念博物館（徳島出身の人類学者）","yomi":"とりいりゅうぞうきねんはくぶつかん","cat":"学び","rank":"B","y":1870,"era":["meiji","taisho","showa"],"sh":"","ad":"徳島市八万町向寺山（文化の森総合公園）","st":"JR徳島駅から «文化の森» 行きバスで約25分、終点すぐ","la":34.0445,"lo":134.5295,"hook":"小学校になじめなかったたばこ屋の息子が、独学でアジアじゅうを歩く人類学者になった。","lead":"鳥居龍蔵は1870年に徳島で生まれた人類学者・考古学者です。ほとんど独学で学び、台湾・朝鮮・シベリア・モンゴル・中国などを歩いて、人びとのくらしや遺跡を調べました。記念博物館では、彼の生涯と調査の記録を見ることができます。","story":["1870年、徳島の新町橋の近くにあった裕福なたばこ問屋に、ひとりの男の子が生まれました。鳥居龍蔵です。小学校にはなじめず、家に逃げ帰ることもしばしば。けれど教科書に載っていた «世界のいろいろな人びと» の話だけは、強く心に残りました。これがのちに、アジアを歩く旅の原点になります。","龍蔵は先生について、また自分ひとりで、歴史や英語、ドイツ語を学びました。10代で人類学会に入り、東京帝国大学の坪井正五郎と知り合います。坪井は徳島まで来て講演をし、龍蔵に «東京で学びなさい» とすすめました。家族はしぶしぶ賛成し、たばこ屋をたたんで一家で上京。まずしい生活のなかで、彼は研究室の標本整理から学者の道を歩みはじめます。","1895年、龍蔵は遼東半島へ調査に出ます。本当は別の人が行くはずだったのが、急に行けなくなって回ってきた役目でした。そこで巨大な石の墓 «ドルメン» を見つけたことが、海外調査にのめりこむきっかけになります。翌年からは台湾へ。彼は調査に写真を取り入れ、人びとの姿を記録しました。","«飛行機のない時代に、どうやってそんなに遠くまで?» 龍蔵は船や馬、そして自分の足で、25歳から60代まで何度もアジアの奥地へ向かいました。のちには妻のきみ子や子どもたちも調査に加わっています。晩年は北京の大学で教え、1953年に東京で亡くなりました。ふるさと徳島は、この知の冒険者を博物館で顕彰しています。"],"tl":[["1870年","徳島のたばこ問屋に生まれる"],["1886年","人類学会に入会"],["1893年","東京帝国大学人類学教室で標本整理の仕事につく"],["1895年","遼東半島を調査。初の海外調査"],["1896年","台湾調査。写真を本格的に使う"],["1953年","東京で亡くなる"],["1964年","鳴門市の妙見山に «徳島県立鳥居記念博物館» 開館"],["2010年","文化の森に移転し、現在の名前で再開館"]],"who":[["鳥居龍蔵","徳島出身の人類学者・考古学者・民族学者"],["坪井正五郎","東京帝国大学の人類学者。龍蔵を見いだした師"],["鳥居きみ子","龍蔵の妻。モンゴルなどの調査に同行した"]],"deep":["龍蔵は晩年の自伝に «小学校を中途退学» と書いたが、記念博物館の資料から小学校（下等科）の卒業証書が見つかり、記憶ちがいだったと考えられている。","旧館（1964年開館）は鳴門の撫養城跡（妙見山）に三層の天守閣風の建物として建てられた。ただし撫養城にもともと天守はなかった。","2010年に文化の森へ移転。県立博物館ととなりあうが、組織としては別の博物館である。","台湾調査で写真乾板を使ったことは、日本の人類学で写真記録を取り入れた早い例とされる。調査写真は今も研究資料として重要。","調査地は台湾・朝鮮・シベリア・モンゴル・中国東北部や西南部・樺太などにおよび、植民地支配の広がりと重なっていた点も、現在では研究の論点になっている。"],"look":["展示 «鳥居龍蔵の見たアジア»（調査写真・資料）","生涯をたどる展示と、少年時代の徳島の資料","となりの徳島県立博物館とあわせて見学","文化の森の丘からの眺め"],"q":["鳥居龍蔵の実家は何のお店だった？","たばこ問屋。徳島は «阿波葉» と呼ばれるたばこの産地でした。"],"myth":"","img":["鳥居龍蔵","徳島県文化の森総合公園"],"wp":"徳島県立鳥居龍蔵記念博物館","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/Tokushima_21st_century_cultural_information_center02s3200.jpg",3600,2400,"徳島県立鳥居龍蔵記念博物館"],["c:9/91/Tokushima_Prefectural_Torii_Ryuzo_Memorial_Museum.JPG",3072,2304],["c:9/99/Ryuzo_Torii_01.jpg",500,590,"鳥居龍蔵"],["c:2/25/Tokushima_bunka-no-mori_park02s3872.jpg",3872,2592,"徳島県文化の森総合公園"]]},{"id":"36_awa_hakubutsukan","n":"徳島県立博物館（阿波の歴史の総まとめ）","yomi":"とくしまけんりつはくぶつかん","cat":"学び","rank":"B","y":1990,"era":["heisei"],"sh":"","ad":"徳島市八万町向寺山（文化の森総合公園）","st":"JR徳島駅から «文化の森» 行きバスで約25分、終点すぐ","la":34.044,"lo":134.53,"hook":"恐竜から銅鐸、藍、空襲まで。一日で «徳島まるごと» を旅できる場所。","lead":"徳島県立博物館は、文化の森総合公園の中にある県の博物館です。化石や動植物などの自然と、銅鐸・中世の武将・阿波藍・人形浄瑠璃・徳島大空襲などの歴史を、ひとつの展示室で見わたせます。2021年に大きくリニューアルしました。","story":["徳島の博物館の歴史は、1959年に今の «阿波おどり会館» の場所で開いた徳島県博物館から始まります。眉山のふもと、町の真ん中の小さな博物館でした。やがて資料がふえ、1990年、市街の南の丘に «文化の森» ができると、図書館や美術館、文書館とならんで新しい県立博物館が開館しました。","常設展のテーマは «徳島まるづかみ» 。入ってすぐに出会うのは、徳島で見つかった恐竜や、はるか昔の地層の化石です。«四国の山の中に恐竜?» と驚く人も多いはず。そこから弥生時代の銅鐸、古墳、そして中世へと、時代の道を歩いていきます。","中世のコーナーでは、阿波から畿内へ進出し、一時は «天下人» とも呼ばれる力を持った三好長慶の一族が登場します。近世に入ると、吉野川がはこんだ土で育った阿波藍が主役です。藍でもうけた商人たちは、人形浄瑠璃や盆踊りなどの芸能も支えました。","展示室のとちゅうには、阿波人形浄瑠璃や祭りのコーナーもあります。木でできた人形の頭（かしら）は、目や眉が動くしかけ入り。農村の舞台で、村人たちが夜おそくまで芝居を楽しんだ姿が目に浮かびます。«藍でもうけたお金が、どうして芸能に?» 藍商たちは大坂や淡路から芸人を呼ぶ «プロデューサー» の役目もはたしていたのです。展示の順番どおりに歩くと、お金と文化のつながりが自然と見えてきます。","近現代の展示には、1945年7月の徳島大空襲の資料もあります。焼夷弾で焼けた町、残された品々。«なぜ地方の町まで焼かれたのか?» アメリカ軍の記録と、徳島側に残った報告書を見くらべると、そのわけが見えてきます。楽しい恐竜から重い歴史まで、ここは徳島の «入口» です。"],"tl":[["1959年","徳島県博物館が、現在の阿波おどり会館の場所に開館"],["1990年3月","旧館が移転のため閉館"],["1990年11月3日","文化の森総合公園に徳島県立博物館が開館"],["2010年","となりに鳥居龍蔵記念博物館が移転してくる"],["2021年","開館30周年を機に全面リニューアル"]],"who":[["三好長慶","阿波出身の戦国大名。畿内で大きな力をもった（展示の中世の主役）"],["鳥居龍蔵","徳島出身の人類学者。となりに記念博物館がある"]],"deep":["常設展示は «徳島セクション» «コレクションセクション» «地球セクション» に分かれ、郷土と地球規模の資料を行き来できる構成になっている。","徳島大空襲の当日、工場の宿直者が書いた «工場罹災報告書» を所蔵。アメリカ軍の作戦記録とよく一致し、徳島側から見た数少ない一次資料とされる。","徳島は弥生時代の銅鐸が多く見つかる地域の一つで、青銅器のまつりを考えるうえで重要な資料がそろう。","屋外には «伝承の森» があり、昔の生活や植物にふれることができる。","同じ建物（通称 «四館棟»）に県立近代美術館・鳥居龍蔵記念博物館・21世紀館が入り、一日で複数の館をまわれる。"],"look":["入口近くの徳島の恐竜コレクション","弥生時代の銅鐸","阿波藍と藍商のコーナー","徳島大空襲の資料"],"q":["徳島県立博物館の前身の博物館は、どこにあった？","今の «阿波おどり会館» の場所（眉山のふもと）にありました。"],"myth":"","img":["徳島県文化の森総合公園","三好長慶"],"wp":"徳島県立博物館","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/Tokushima_21st_century_cultural_information_center02s3200.jpg",3600,2400,"徳島県立博物館"],["c:b/bb/Tokushima_Prefectural_Museum.JPG",3072,2304],["c:2/25/Tokushima_bunka-no-mori_park02s3872.jpg",3872,2592,"徳島県文化の森総合公園"]]},{"id":"36_tokushima_kuushu","n":"徳島大空襲の跡（市街地の6割あまりが焼けた夜）","yomi":"とくしまだいくうしゅうのあと","cat":"昭和","rank":"A","y":1945,"era":["showa"],"sh":"","ad":"徳島市中心部（東船場・寺町・徳島中央公園ほか）","st":"JR徳島駅から旧高原ビルまで歩いて約10分、寺町まで約15分","la":34.0715,"lo":134.553,"hook":"1945年7月4日未明、2時間近く焼夷弾が降り続けた。城下町の記憶は一夜で炎の中に消えた。","lead":"1945年7月4日の夜明け前、アメリカ軍のB-29爆撃機が徳島市に大量の焼夷弾を落としました。徳島市の発表では市の約6割が焼け、約1,000人が亡くなったとされます。いまも町のあちこちに、空襲の傷あとが静かに残っています。","story":["1945年7月3日の午後、マリアナ諸島の基地から、数百機のB-29が飛び立ちました。目標は高松・高知・姫路、そして徳島。そのうち徳島に向かった百機あまりは、紀伊水道をこえ、新町川の河口から市の上空に入ってきました。日付が変わった7月4日の午前1時すぎ、最初の焼夷弾が落ちます。","焼夷弾は、火事を起こすための爆弾です。先に来た飛行機が落とした火を目印に、後ろの飛行機が低い空から次々と落としていきました。空襲は午前3時すぎまで、2時間近くも続きます。木造の家がびっしり並んだ城下町は、あっという間に炎に包まれました。","人びとは火から逃れようと、眉山へ登ったり、吉野川の方へ走ったりしました。逃げおくれた人は、川や田んぼに飛びこみ、«どうか自分の上には落ちないで» と祈るしかなかったといいます。山の上からは、雨のように降る火と、燃える町が見えたそうです。朝が来ると、川には犠牲になった人の姿がありました。","«なぜ徳島が?» アメリカ軍は、徳島を大阪・神戸への食料の供給地であり、瀬戸内海の入口にあたる町、紡績などの工場がある町と見ていました。この空襲で徳島城の鷲の門、大滝山の三重塔、徳島駅、新町橋なども失われました。亡くなった一人ひとりに思いをはせながら、残された跡をたどってみてください。"],"tl":[["1945年6月1日","徳島市への最初のB-29による空襲（7月24日までに計7回）"],["1945年7月3日午後","マリアナの基地からB-29が出撃"],["1945年7月4日 1時24分ごろ","徳島市への焼夷弾投下が始まる"],["1945年7月4日 3時19分ごろ","投下が終わる。市街の大半が焼失"],["1989年","焼けた徳島城鷲の門が復元される"]],"who":[["徳島市の市民","犠牲者は約1,000人、被災者は7万人をこえたとされる"],["村崎サイ","社会運動家。この空襲で亡くなった"]],"deep":["被害の数字は資料で異なる。徳島市の発表は «市の約62%焼失、死者約1,000人» 、アメリカ軍の報告書は «破壊・焼失74%» としている。","アメリカ軍の記録では、徳島を爆撃したのは第314航空団の129機。投下した焼夷弾は1,000米トンをこえ、本数にすると35万本あまりと計算されている。","標的の中心点は、当時市内一の商店街だった元町付近とされた。町の中心そのものがねらわれたことがわかる。","旧高原ビルには、空襲でひびの入った窓ガラスが今も残る。寺町の東宗院の山門は焼け残り、焼け出された人がしばらく暮らしたという。","1942年に «幻の甲子園» で優勝した徳島商業の賞状も、この空襲で焼けてしまった。スポーツの記憶もまた奪われた。"],"look":["旧高原ビル（東船場）のひび割れた窓ガラス","寺町の東宗院の山門（焼け残った門）","徳島中央公園の鷲の門（戦後の復元）","徳島県立博物館の空襲関係の展示"],"q":["徳島大空襲があったのは、1945年の何月何日？","7月4日の未明（夜明け前）です。"],"myth":"犠牲者数・焼失率は資料で差がある。焼け跡の位置は現地の案内で確かめたい。","img":["徳島城","B-29 (航空機)"],"wp":"徳島大空襲","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:1/1a/Tokushima_castle_22.JPG",2048,1362,"徳島城"],["c:8/8c/B-29_Bomber_on_a_long_range_mission_in_late_1945.jpg",2048,1492,"B-29 (航空機)"]]},{"id":"36_tokushima_kokutai","n":"徳島海軍航空隊跡（松茂・特攻隊の基地）","yomi":"とくしまかいぐんこうくうたいあと","cat":"昭和","rank":"A","y":1945,"era":["showa"],"sh":"","ad":"板野郡松茂町（現在の徳島飛行場・海上自衛隊徳島航空基地一帯）","st":"徳島阿波おどり空港そば。JR徳島駅から空港行きバスで約30分。基地内は原則立入禁止","la":34.1363,"lo":134.5968,"hook":"練習機 «白菊» ――ゆっくりとしか飛べない飛行機で、若者たちは沖縄の海へ向かった。","lead":"徳島海軍航空隊は1942年、松茂村（今の松茂町）の徳島飛行場に作られた海軍の訓練部隊です。戦争の終わりには、練習機 «白菊» による特攻の部隊となり、多くの若者が沖縄の海で命を落としました。跡地は今、徳島阿波おどり空港と海上自衛隊の基地になっています。","story":["1941年、吉野川の河口に近い松茂の平地に飛行場が完成しました。翌1942年4月、ここで徳島海軍航空隊が生まれます。役目は、戦闘機に乗る若い搭乗員を育てること。茨城県の土浦から、予科練を終えたばかりの少年たちがやってきて、訓練にはげみました。","戦争の形勢が悪くなると、航空隊の役目も変わっていきます。1944年には偵察の搭乗員を育てる部隊に。使われたのが «白菊» という練習機でした。何人も乗りこんで、空の上で地図を読む練習をするための飛行機です。速さは戦闘機よりずっと遅いものでした。","1945年3月、航空隊は戦いに出る部隊に変えられ、夜間に特攻の訓練を始めます。5月には白菊のすべてが特攻機とされました。«練習機で、敵の艦隊に体当たりする» ――それがどれほど無理なことか、乗る人たちにもわかっていたはずです。部隊は鹿児島の鹿屋飛行場へ進み、5月24日、高知の航空隊とともに白菊の特攻隊が沖縄の海へ出撃しました。","出撃は6月まで続き、多くの機が帰ってきませんでした。特攻に出た若者の多くは10代後半から20代前半でした。いま空港の近くを歩くと、飛行機の音が聞こえます。そのすぐそばに、同じ空へ飛び立ち、戻らなかった人たちがいたことを、心にとめておきたい場所です。"],"tl":[["1941年","徳島飛行場が完成"],["1942年4月1日","徳島海軍航空隊が開隊。戦闘機搭乗員の訓練を始める"],["1944年2月","偵察専修の搭乗員の訓練が始まる"],["1945年3月1日","実戦部隊に改編。夜間の特攻訓練を開始"],["1945年5月24日","白菊の特攻隊が鹿屋から沖縄方面へ出撃"],["1945年6月","最後の白菊隊が出撃"],["戦後","連合軍の接収をへて、民間と海上自衛隊の共用飛行場に"]],"who":[["予科練の少年たち","土浦海軍航空隊などから来て訓練を受けた若い搭乗員"],["白菊特攻隊の隊員","徳島・高知の航空隊から出撃し、沖縄の海で亡くなった人たち"]],"deep":["白菊は機上作業練習機で、特攻に使われたのは本来の用途とはまったく異なる。遅く重い機体での出撃は、戦争末期の追いつめられた状況を示す。","白菊隊は高知海軍航空隊と合同で編成された。徳島・高知という四国の二つの航空隊が同じ作戦に組みこまれた。","記録では5月27日の出撃で駆逐艦を撃沈したとされるが、多くの出撃は戦果が確認されていない。","6月の段階で白菊隊はほぼ全滅し、徳島の本隊にも飛べる機はほとんど残らなかったとされる。","戦後の徳島飛行場は、海上自衛隊の教育部隊の訓練で離着陸回数が四国でもとくに多い飛行場として知られる。"],"look":["徳島阿波おどり空港周辺の地形（かつての飛行場の広さを想像する）","松茂町内の慰霊碑や資料（現地で所在を確認）","海上自衛隊徳島航空基地（見学はイベント時などに限られる）"],"q":["徳島海軍航空隊が特攻に使った飛行機の名前は？","«白菊»。本来は搭乗員の訓練に使う練習機でした。"],"myth":"慰霊碑・資料展示の場所や公開状況は時期で変わるため現地で要確認。","img":["白菊 (航空機)","徳島飛行場"],"wp":"徳島海軍航空隊","rel":{"ev":[],"grave":[]},"ph":[["c:f/fd/Tokushimama_Airfield%281947%29.jpg",1836,1377],["c:b/b3/Kyushu_K11W_Shiragiku_in_flight.jpg",650,446,"白菊 (航空機)"],["c:8/82/Tokushima_Airport_2019.jpg",2048,1536,"徳島飛行場"]]},{"id":"36_komatsushima_ko","n":"小松島港（関西航路の玄関口）","yomi":"こまつしまこう","cat":"近代","rank":"B","y":1913,"era":["meiji","taisho","showa"],"sh":"","ad":"小松島市小松島町（本港地区）","st":"JR牟岐線 南小松島駅から歩いて約15分","la":34.0065,"lo":134.5925,"hook":"船を降りたら、そのまま汽車へ。四国の旅は、かつてこの港から始まった。","lead":"小松島港は、明治から昭和にかけて大阪・和歌山と徳島を結ぶ船が発着した港です。1913年には港と徳島の町をつなぐ鉄道もでき、船と汽車を乗りつぐ «四国の玄関口» になりました。今は徳島港と一つになった «徳島小松島港» の一部です。","story":["徳島の町は吉野川の河口近くにあり、海が浅くて大きな船が入れませんでした。そこで目をつけられたのが、少し南の小松島の入り江です。1899年ごろから港の整備が始まり、大阪から来る汽船がここに着くようになりました。","さかのぼれば、この海辺は源平の時代の物語にも登場します。『平家物語』によると、1185年、源義経は嵐の夜に摂津から船を出し、わずかな時間で阿波の勝浦に着いたといいます。そこから陸路で讃岐の屋島へ攻めこみ、平家をおどろかせました。小松島の人びとは、この上陸を町の誇りとして語りついできました。上陸した場所がどこだったかは、今も諸説があります。","1913年、港と徳島の町を結ぶ小さな鉄道、小松島軽便線が開通します。«船を降りたら目の前が駅» 。大阪から船で来た人は、すぐに汽車に乗りかえて徳島へ、さらに吉野川ぞいの町々へ向かうことができました。徳島の鉄道と港が一本の線でつながったのです。","戦後もにぎわいは続きます。1956年には和歌山との間に航路が開かれ、急行や準急が高知方面まで走って船とつながりました。«関西から高知へ行くなら小松島経由» という時代もあったのです。しかし岡山経由の新幹線や瀬戸大橋、明石海峡大橋ができると、人の流れは変わっていきました。","1985年、小松島線は廃止されました。駅の跡は «小松島ステーションパーク» という公園になり、蒸気機関車が静かに置かれています。«なぜ港の町がこんなに大切だったのか?» 橋のない時代、四国は海でしか本州とつながっていなかったからです。港の風に、その記憶が残っています。"],"tl":[["1185年","源義経が屋島へ向かう途中、阿波の勝浦（今の小松島あたり）に上陸したと『平家物語』に語られる"],["1899年","小松島港の近代化が始まる"],["1913年","小松島軽便線が開通し、船と鉄道がつながる"],["1956年","和歌山との航路が開設"],["1964年","小松島港と徳島港が統合し «徳島小松島港» に"],["1985年","国鉄小松島線が廃止"],["1999年","和歌山航路が徳島港発着に変わる"]],"who":[["源義経","屋島の戦いの前、阿波の勝浦に上陸したと伝わる"],["船と汽車を乗りついだ旅人","関西と四国を行き来した人びと"]],"deep":["港が開港（1948年）・重要港湾（1951年）に指定されたのは、徳島港より先に小松島港だった。遠浅の徳島港の本格整備は戦後から。","小松島軽便線はのちの小松島線と、牟岐線の徳島〜中田間のもとになった。","高度成長期、準急（のち急行）«阿佐» などが小松島から高知まで走り、船と接続して関西〜高知を結ぶルートの一部を担った。","小松島は源義経の上陸伝承の地としても知られ、市内には義経ゆかりの場所や像がある。上陸地点については諸説。","本港地区の一部は «みなとオアシス» に登録され、交流施設 «kocolo» が拠点になっている。"],"look":["小松島ステーションパーク（旧小松島駅跡）と保存SL","本港地区の岸壁と港の眺め","義経ゆかりの伝承地・像"],"q":["小松島港と徳島の町を結ぶ鉄道が開通したのは何年？","1913年。小松島軽便線として開通しました。"],"myth":"義経の上陸地点は諸説あり、小松島市内の複数の場所が名のりをあげている。","img":["徳島小松島港","小松島線","源義経"],"wp":"小松島港","rel":{"ev":[],"grave":[]},"ph":[["c:e/e2/HEUNG_A_ULSAN_at_Tokushima_Komatsushima_Port_Container_Terminal.jpg",3249,2361,"小松島港"],["c:8/85/Trade_Image_of_Honsen11.png",5128,3069],["c:b/b7/RELIANCE_at_Tokushima_Komatsushima_Container_Terminal.jpg",4640,3480],["c:f/f5/SUNNY_PALM_at_Container_Terminal_of_Tokushima_Komatsushima_Port.JPG",2816,2112],["c:3/38/Diamond_princess_at_port_of_tokushimakomatsushima.jpg",2067,1476],["c:e/ea/Tokushima_port.jpg",640,480],["c:e/ee/JNR_komatsushimakou_yosinogawa.jpg",945,661,"小松島線"],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"]]},{"id":"36_awaodori","n":"阿波おどりの町・徳島（藍商が育てた盆踊り）","yomi":"あわおどりのまち・とくしま","cat":"町","rank":"S","y":1586,"era":["edo","taisho","showa"],"sh":"","ad":"徳島市新町橋（阿波おどり会館）ほか市中心部","st":"JR徳島駅から阿波おどり会館まで歩いて約10分","la":34.0703,"lo":134.5465,"hook":"«踊る阿呆に見る阿呆、同じ阿呆なら踊らな損々» ――400年、町はこのリズムで夏を迎えてきた。","lead":"阿波おどりは、徳島を代表するお盆の踊りです。毎年8月12日から15日、三味線や太鼓、笛、鉦の二拍子にのって «連» と呼ばれるグループが町を踊り歩きます。そのにぎわいを支えたのは、江戸時代に藍で富をきずいた商人たちでした。","story":["阿波おどりがいつ始まったのか、じつははっきりしていません。よく知られるのは、1586年ごろ、徳島城ができたお祝いに、藩祖の蜂須賀家政が «無礼講で踊ってよい» と許したのが始まりという説です。ほかにも、鎌倉時代の念仏踊りから続く先祖供養の盆踊りとする説、戦国時代の勝瑞城で行われた華やかな «風流踊り» とする説があり、どれか一つには決まっていません。","たしかなのは、江戸時代の徳島で盆踊りがとても盛んだったことです。その力の源は «藍» でした。吉野川ぞいで育てた藍を全国に売った藍商たちは、大きな富をたくわえ、淡路や大坂から芸人を呼んで興行をさせました。人形浄瑠璃も三味線も、商人たちがいわば «スポンサー» となって育てたのです。夏の夜、城下町は踊る人と見る人であふれました。","けれども明治になると、«文明開化にふさわしくない» として、県は踊りをきびしく取りしまりました。さらにインドの藍やドイツの化学染料が入ってきて藍の商売がおとろえ、踊りも元気をなくします。«藍が消えたら、踊りも消えるのか?» 町の人たちの不安は大きかったはずです。","流れを変えたのは大正時代でした。お祝いの行事で踊りがくり出されると、ふたたび町が熱をおびます。やがて商工会議所や新聞社が «徳島の盆踊りを観光に» と動き出し、県外にも踊り子を送りました。戦争で中断したあと、1946年には復活。いまでは東京・高円寺など全国で踊られ、徳島は毎夏、百万人をこえる人でにぎわう «踊りの都» になりました。","ポルトガル人のモラエスは、大正のころの徳島の盆踊りを見て本に書き残しました。彼の目には、身分も年齢も忘れて踊る人びとの姿が、何より徳島らしく映ったようです。«見る阿呆» でいるか、«踊る阿呆» になるか。会館で昼の公演を見れば、あなたもきっと手をあげたくなるでしょう。"],"tl":[["1586年ごろ","徳島城の完成祝いに蜂須賀家政が踊りを許したと伝わる（築城起源説）"],["江戸時代","藍商の富を背景に城下の盆踊りが盛んに"],["1868〜1870年","県が踊りの取締令を出す"],["1909年","新聞に «阿波踊» の名が初めて登場"],["1916年","モラエスが『徳島の盆踊り』を刊行。初の県外遠征も"],["1946年","戦後、阿波おどりが復活"],["1957年","東京・高円寺で阿波おどりが始まる"]],"who":[["蜂須賀家政","徳島藩の藩祖。築城起源説で踊りを許したとされる"],["藍商","藍で財をなした商人。芸能のスポンサーとして踊りを支えた"],["モラエス","徳島の盆踊りを本に書いたポルトガル人"],["林鼓浪","日本画家。昭和初めに «阿波踊り» という呼び名を広めることを提唱した"]],"deep":["起源は «築城起源説» «盆踊り起源説» «風流踊り起源説» の三つが有名。研究では、盆踊りを土台に組踊り・ぞめき踊り・俄などの民衆芸能が混ざって形づくられたと考えられている。","«阿波踊» という名前が文字で確かめられる最初は、1909年11月の新聞記事。それまでは «盆踊り» と呼ぶのがふつうだった。","有名な «踊る阿呆に見る阿呆» の歌は «よしこの» という節。実際の町では «ヤットサー、ヤットサー» のかけ声の方がよく聞かれる。","男踊りは腰を低く落として力強く、女踊りは編笠をかぶり下駄のつま先で立って優雅に。二拍子の同じリズムで対照的な踊りが生まれる。","県外への初遠征は1916年の和歌山・紀三井寺。1921年には神戸開港50年の祝いにも招かれた。観光としての «売り出し» は大正時代から始まっていた。","徳島市や徳島県の印刷物では «阿波おどり» とひらがなで書くのが一般的。"],"look":["阿波おどり会館（一年中、昼と夜に公演がある）","新町川ぞいの両国・新町かいわい（本番の演舞場の雰囲気）","眉山ロープウェイの山麓駅（会館と同じ建物）","8月12〜15日の本番（有名連の流し踊り）"],"q":["阿波おどりで踊るグループのことを何という？","«連（れん）»。有名連・企業連・学生連などがあります。"],"koji":[{"w":"踊る阿呆に見る阿呆、同じ阿呆なら踊らな損々","m":"見ているだけより、いっしょに楽しんだほうがいい、というよしこの節の歌詞"}],"myth":"1586年の築城起源説は伝承で、史料で確かめられていない。来場者数は年により異なる。","img":["阿波踊り","蜂須賀家政","阿波藍"],"wp":"阿波おどり","rel":{"ev":[],"grave":[]},"ph":[["c:9/94/Awa-odori_2008_Tokushima.jpg",2667,2000,"阿波おどり"],["c:2/20/Awa-odori_K%C5%8Denji_01.jpg",2848,4288],["c:e/e2/Awa-odori_2008_Tokushima_06.jpg",2661,1996],["c:d/d8/Awa-odori_2008_Tokushima_02.jpg",2652,1989],["c:0/0f/Awa-odori_2008_Tokushima_08.jpg",1973,2630],["c:2/2e/%E8%97%8D%E9%9F%BF%E9%80%A3%E3%81%AE%E6%BC%94%E8%88%9E%28%E5%8D%97%E8%B6%8A%E8%B0%B7%29.jpg",2800,1400],["c:c/c5/Awa-odori_2008_Tokushima_04.jpg",1704,2272],["c:4/4f/Awa_Odori-1.jpg",1781,1336]]},{"id":"36_naruto_uzu","n":"鳴門の渦潮と «阿波の鳴門»（歌舞伎と浮世絵の名所）","yomi":"なるとのうずしお","cat":"伝承","rank":"S","y":1768,"era":["edo","showa"],"sh":"国の名勝（鳴門公園一帯）","ad":"鳴門市鳴門町土佐泊浦（鳴門公園）","st":"JR鳴門駅からバスで約25分 «鳴門公園» 下車","la":34.2375,"lo":134.6415,"hook":"海が川のように流れ、うず巻く。江戸の人びとは、この景色を芝居と浮世絵で夢見た。","lead":"鳴門海峡は、徳島県の鳴門と淡路島の間にある幅1.3kmほどの狭い海です。潮の満ち引きの差で激しい流れが生まれ、大きな渦潮が巻きます。江戸時代には人形浄瑠璃『傾城阿波の鳴門』や歌川広重の浮世絵で «阿波の鳴門» の名が広く知られました。","story":["鳴門の海に立つと、ふしぎな光景が見えます。海なのに、川のように一方向へ流れ、ところどころでぐるぐると渦を巻いているのです。«なぜ海に渦ができるの?» 太平洋から来た潮は、紀伊水道で二手に分かれます。一方は鳴門海峡の南へ、もう一方は大阪湾から明石海峡を回って播磨灘へ。遠回りした潮が播磨灘で満ちるころ、鳴門の南側ではもう潮が引きはじめています。","そのため、せまい海峡の北と南で、水面の高さに1m以上の差ができることがあります。高いほうから低いほうへ、海水はいきおいよく流れ落ちます。速い流れと、まわりのゆっくりした流れがこすれあうところで、渦が生まれるのです。大きなものは直径15mにもなるといわれ、春や秋の大潮のころが見ごろとされます。","この荒々しい海は、昔から船乗りたちにおそれられてきました。利根川の河口などとならび «日本の海の三大難所» の一つとも呼ばれたといいます。いっぽうで江戸の人びとにとって «阿波の鳴門» は、一度は見てみたいあこがれの名所でもありました。","1768年、大坂の竹本座で人形浄瑠璃『傾城阿波の鳴門』が初演されます。阿波の国を出て大坂でくらす十郎兵衛とお弓の夫婦のもとに、国に残してきた娘・おつるが巡礼姿でたずねてくる――。«ととさんの名は十郎兵衛、かかさんはお弓と申します» というおつるのせりふは、多くの観客の涙をさそいました。この話はのちに歌舞伎でも演じられます。","さらに幕末の1857年ごろ、歌川広重は三枚続きの大画面『阿波鳴門之風景』に、白くくだける渦をダイナミックに描きました。昭和になると鳴門公園は国の名勝に、1985年には大鳴門橋がかかり、いまは橋の下の «渦の道» から真上に渦をのぞけます。芝居と絵と海。三つの «鳴門» を重ねて見ると、景色がいっそう深くなります。"],"tl":[["1768年","人形浄瑠璃『傾城阿波の鳴門』が大坂・竹本座で初演"],["1857年ごろ","歌川広重『阿波鳴門之風景』（雪月花の三部作の一つ）"],["1931年","鳴門公園一帯が国の名勝に指定"],["1950年","瀬戸内海国立公園に加わる"],["1985年","大鳴門橋が開通"],["2000年","大鳴門橋に遊歩道 «渦の道» が開設"]],"who":[["近松半二","『傾城阿波の鳴門』の作者の一人とされる浄瑠璃作者"],["歌川広重","鳴門の渦潮を大画面の浮世絵に描いた"],["阿波の十郎兵衛","浄瑠璃の主人公のモデルとされる人物。実在の板東十郎兵衛とする説がある"]],"deep":["海峡の一番せまいところは約1,340m。海底は中央がV字で深さ約90m、その南北には «海釜» と呼ばれる深みがあり、複雑な地形も渦の成り立ちにかかわる。","潮流は速いときで時速20kmにもなるといわれ、大型船も潮の止まる時間を待って通ることがある。","『傾城阿波の鳴門』の十郎兵衛は、実在の阿波の庄屋・板東十郎兵衛がモデルとされる。実在の十郎兵衛は藩に処刑されたが、その理由には諸説あり、芝居の筋とは大きく異なる。","徳島市川内町の «阿波十郎兵衛屋敷» では、『傾城阿波の鳴門』の «順礼歌の段» が人形浄瑠璃で上演されている。","広重の三部作は、雪＝木曽路、月＝金沢八景、花＝阿波の鳴門。鳴門は «花» にあたり、白い波しぶきを花に見立てたとも読める。","鳴門海峡の西には «小鳴門海峡» もあり、こちらは撫養の港町に面している。"],"look":["大鳴門橋の遊歩道 «渦の道»（海面から約45mの真上から渦を見る）","観潮船（渦のすぐ近くまで行ける）","鳴門公園の千畳敷・お茶園展望台","阿波十郎兵衛屋敷（徳島市）の人形浄瑠璃"],"q":["鳴門の渦潮ができる大きな理由は？","海峡の北と南で潮の満ち引きの時間がずれ、水面の高さに差ができて、速い流れが生まれるからです。"],"koji":[{"w":"ととさんの名は十郎兵衛、かかさんはお弓と申します","m":"『傾城阿波の鳴門』で巡礼の娘おつるが名のる有名なせりふ"}],"myth":"十郎兵衛のモデルや処刑の理由は諸説。«三大難所» の顔ぶれは資料で異なる。渦の大きさは潮の条件でかわる。","img":["大鳴門橋","傾城阿波の鳴門","歌川広重"],"wp":"鳴門海峡","rel":{"ev":[],"grave":[]},"ph":[["c:6/6f/Naruto_Whirlpools_taken_4-21-2008.jpg",3456,2304],["c:7/72/Naruto_strait_aerial_photo.jpg",2059,1544],["c:9/93/Naruto-Strait_1.png",1156,873],["c:f/f2/%E9%B3%B4%E9%96%80%E6%B5%B7%E5%B3%A1.jpg",640,480],["c:d/d3/Big_Naruto_Bridge04n3872.jpg",3872,2592,"大鳴門橋"],["c:f/f1/Memorial_Portrait_of_Hiroshige%2C_by_Kunisada.jpg",2631,3841,"歌川広重"]]},{"id":"36_bizan","n":"眉山（万葉集にうたわれた山）","yomi":"びざん","cat":"伝承","rank":"A","y":734,"era":["nara","edo","showa"],"sh":"","ad":"徳島市眉山町・新町橋ほか","st":"JR徳島駅から歩いて約10分の阿波おどり会館から眉山ロープウェイで約6分","la":34.0645,"lo":134.5335,"hook":"«眉のごと 雲居に見ゆる 阿波の山» ――1300年前、船の上から見た山のかたちは、今も変わらない。","lead":"眉山は徳島市の中心にそびえる標高290mの山です。どこから見てもまゆの形に見えることから名づけられたといわれます。奈良時代の万葉集にも «眉のような阿波の山» としてうたわれ、北のふもとには徳島藩主・蜂須賀家の墓所があります。","story":["734年の春、聖武天皇は難波の宮へ出かけました。そのお供をした船王（ふねのおおきみ）は、海の向こうにかすむ山を見て、歌をよみます。«眉のごと 雲居に見ゆる 阿波の山 かけて漕ぐ舟 泊り知らずも» 。まゆのように遠く雲の中に見える阿波の山、その山をめざしてこぐ舟は、どこの港に着くのだろう――。この «阿波の山» こそ眉山だとされています。","«なぜ «まゆ» なの?» 徳島の町から見上げると、山の稜線がなだらかな弓なりになっていて、たしかに眉の形。しかも東西南北どこから見ても同じように見えるといわれます。ふもとには寺町が広がり、山からわき出る水は «錦竜水» などの名水となって、人びとののどをうるおしてきました。","江戸時代、眉山は徳島藩の «聖地» にもなります。1766年、藩主の蜂須賀重喜は山の北側に一族の墓所 «万年山» をきずきました。歴代の藩主や家族がここにねむり、城下町を見下ろしています。興源寺の墓所とあわせ、徳島藩主蜂須賀家墓所として国の史跡になっています。","1945年の徳島大空襲の夜、たくさんの人が火から逃れて眉山へ登りました。山の上からは、燃える町と降りそそぐ焼夷弾が見えたといいます。このとき、中腹の大滝山にあった三重塔も焼けてしまいました。戦後、山頂には戦没者をなぐさめるミャンマー式の塔 «パゴダ» が建てられています。","いま山頂へはロープウェイで6分ほど。徳島の町並み、吉野川、晴れた日には淡路島や紀伊半島までが見わたせます。モラエス館や賀川豊彦の文学碑もあり、この山がいろいろな人の人生と結びついてきたことがわかります。万葉の旅人が船から見た山に、今度はあなたが立つ番です。"],"tl":[["734年","聖武天皇の難波行幸に従った船王が «阿波の山» をうたう（万葉集）"],["1585年ごろ","蜂須賀家政が眉山の北、城山に徳島城をきずく"],["1766年","蜂須賀重喜が北面に藩主一族の墓所 «万年山» をきずく"],["1945年7月4日","徳島大空襲。市民が眉山に避難し、大滝山の三重塔が焼失"],["1957年","眉山ロープウェイが開業"],["1976年","山頂にモラエス館が開館"],["2007年","映画『眉山 -びざん-』公開"]],"who":[["船王","奈良時代の皇族。万葉集で眉山をうたったとされる"],["蜂須賀重喜","徳島藩10代藩主。万年山墓所をきずいた"],["モラエス","徳島で晩年を過ごしたポルトガル人。山頂に記念館がある"]],"deep":["万葉集の歌は巻6におさめられ、題詞によると天平6年（734年）3月の難波行幸の折の作。«阿波の山» ＝眉山と考えるのが通説だが、特定の一山ではないとする見方もある。","最高地点は山の中ほどにある標高290mの峰。ふつう «山頂» と呼ばれてロープウェイ駅がある東の峰は約277m。","万年山墓所には、藩主や夫人の大きな墓が、儒教風の形式でならぶ。藩主の墓が神式・儒式の形をとる点は、蜂須賀家の墓所の特徴として注目される。","山頂にはNHKや民放のテレビ・FMの送信所が集まり、眉山は «徳島の電波塔» の役目もはたしている。","眉山の東のふもとの寺町・大滝山、南の伊賀町（モラエス旧居跡）など、山すそを一周すると徳島の歴史がほぼひとめぐりできる。"],"look":["山頂展望台からの徳島市街と吉野川","万葉集の歌碑","モラエス館・パゴダ（平和記念塔）","北のふもとの万年山墓所（国史跡。入れる範囲は現地で確認）"],"q":["万葉集で眉山は何にたとえられている？","人の «まゆ»（眉）です。«眉のごと雲居に見ゆる阿波の山» とうたわれました。"],"koji":[{"w":"眉のごと 雲居に見ゆる 阿波の山","m":"まゆのように雲のかなたに見える阿波の山。眉山の名の由来ともされる万葉集の一節"}],"myth":"«阿波の山» を眉山とするのは通説。墓所の史跡指定年は確認できなかったため記さない。","img":["眉山 (徳島市)","徳島藩主蜂須賀家墓所","眉山ロープウェイ"],"wp":"眉山 (徳島県)","rel":{"ev":[],"grave":[]},"ph":[["c:2/22/Mount_Bizan_from_Shimmachi_River_20200607.jpg",3620,2413,"眉山 (徳島県)"],["c:6/69/Tokushima_City_View_from_the_Top_of_Bizan_20200405.jpg",6960,4640],["c:4/4e/Bizan_Park_20200405.jpg",6960,4640],["c:1/1a/Sebu-Park1.JPG",3648,2736],["c:4/49/Bizan_Parkway.JPG",3648,2736],["c:2/26/Bizan_Tokushima02s3872.jpg",3872,2592],["c:7/7a/Shimmachigawa_River_and_Mount_Bizan_from_Kachidokibashi_Bridge.JPG",3241,2431],["c:3/32/Awa-dance_memorial_hall01s3200.jpg",3600,2400]]},{"id":"36_jigenji_tokushima","n":"瑞巌寺（徳島市・蜂須賀家ゆかりの庭）","yomi":"ずいがんじ","cat":"寺社","rank":"B","y":1614,"era":["azuchi","edo"],"sh":"","ad":"徳島市東山手町","st":"JR徳島駅から歩いて約15分","la":34.0685,"lo":134.5415,"hook":"眉山の斜面を借りた庭に、マリア像を地蔵に見せかけた «切支丹灯籠» がひっそりと立つ。","lead":"瑞巌寺は眉山のふもとにある臨済宗の寺です。もとは勝瑞城の城下にあり、1614年に徳島藩の蜂須賀至鎮が弟の菩提をとむらうため、今の場所に再興したと伝わります。山の斜面を生かした江戸時代初めの庭園で知られています。","story":["戦国時代、阿波の中心は吉野川の下流にあった勝瑞城でした。その城下にあった寺のひとつが瑞巌寺です。やがて豊臣秀吉の四国攻めのあと、蜂須賀家が阿波の主となり、新しく徳島城と城下町を作ります。勝瑞の寺々も、つぎつぎと徳島へ移されました。","1614年、徳島藩の初代藩主・蜂須賀至鎮は、弟の義英の菩提をとむらうため、この寺をいまの眉山のふもとに再興したといわれます。開山に招かれたのは一鶚という僧でした。大坂の陣が始まる年。«戦の時代の終わり» に、兄は弟のために静かな祈りの場を作ったのです。","寺の奥に広がる庭は、眉山の斜面をそのまま生かしています。山肌を流れ落ちる滝、その水をたたえる池、池をめぐる小道。江戸時代初めに作られた池泉回遊式の庭で、茶室や三重塔も配されています。小さな境内なのに、山ごと庭にとりこんだような奥行きを感じるのは、この地形のおかげです。","«なぜ地蔵の灯籠に、赤ちゃんを抱いた姿が?» 境内には、聖母マリアを地蔵菩薩に見せかけて刻んだといわれる «切支丹灯籠» があります。キリスト教が禁じられた江戸時代、ひそかに信仰を守った人がいたのかもしれません。また境内には阿波の名水の一つ «鳳翔水» もわき出ています。","庭をながめていると、耳に入るのは水の音だけ。眉山の森が背景となり、季節ごとに色を変えます。春は新緑、秋は紅葉が池にうつり、冬は木々のすき間から山の岩肌がのぞきます。«山を借りて庭をつくる» 。これは «借景» とよばれる日本の庭の知恵です。町の真ん中にいながら、山寺に来たような静けさを味わえるのは、この寺ならではです。","門前からは «モラエス通り» が南へのびています。ポルトガル人モラエスが晩年に歩いた道です。戦国の勝瑞、江戸の蜂須賀家、大正のモラエス――ひとつの寺の前に、いくつもの時代が重なっています。"],"tl":[["戦国時代","勝瑞城の城下にあったと伝わる"],["1585年","蜂須賀家が阿波に入る"],["1614年","蜂須賀至鎮が弟・義英の菩提のため眉山ふもとに再興"],["江戸時代初め","池泉回遊式の庭園がつくられる"],["1975年","門前からのびる道が «モラエス通り» と名づけられる"]],"who":[["蜂須賀至鎮","徳島藩初代藩主。弟のためにこの寺を再興した"],["蜂須賀義英","至鎮の弟。この寺で菩提がとむらわれた"],["一鶚","再興のとき開山として招かれた僧"]],"deep":["山号は鳳翔山、宗派は臨済宗妙心寺派、本尊は釈迦如来。","庭は眉山の斜面と自然の岩を生かし、滝組と池を組みあわせる。作られた時期は江戸初期とされ、桃山時代の気風を伝える庭と説明されることもある。","«切支丹灯籠» は、全国に点在する «織部灯籠» 型の灯籠を隠れキリシタンの遺物とみる説にもとづく呼び名。キリシタン遺物かどうかは研究者の間でも見方が分かれる。","境内の «鳳翔水» は阿波の名水の一つに数えられ、眉山のふもとに多い湧き水のひとつ。","瑞巌寺は «徳島二十四ヶ所地蔵霊場» の5番札所でもある。","徳島藩の菩提寺は興源寺だが、藩主一族の供養は城下のいくつもの寺に分けて営まれた。瑞巌寺もその一つで、眉山のふもとの寺々が藩の信仰の舞台だったことがわかる。"],"look":["眉山の斜面を生かした池泉回遊式庭園と滝","切支丹灯籠","湧き水 «鳳翔水»","門前から南へのびるモラエス通り"],"q":["瑞巌寺の «切支丹灯籠» は、何を何に見せかけていると言われる？","聖母マリアを、地蔵菩薩に見せかけていると言われます。"],"myth":"勝瑞城下からの移転の経緯、切支丹灯籠のキリシタン遺物説は伝承・諸説。庭の拝観方法は寺に要確認。","img":["蜂須賀至鎮","勝瑞城"],"wp":"瑞巌寺 (徳島市)","rel":{"ev":[],"grave":[]},"ph":[["c:3/30/Zuiganji.jpeg",828,617,"瑞巌寺 (徳島市)"],["c:d/d6/Zuiganji3.jpeg",828,621],["c:c/c9/Zuiganji2.jpeg",828,616],["c:c/c7/Hachisuka_Yoshishige.jpg",2661,4803,"蜂須賀至鎮"],["c:7/76/Shozuijo09.jpg",1831,1348,"勝瑞城"]]},{"id":"36_awaike_tabako","n":"阿波池田のたばこ産業（うだつの商家）","yomi":"あわいけだのたばこさんぎょう","cat":"産業","rank":"B","y":1860,"era":["edo","meiji"],"sh":"","ad":"三好市池田町マチ","st":"JR土讃線・徳島線 阿波池田駅から歩いて約5分","la":34.0275,"lo":133.8045,"hook":"山あいの町に100軒をこえるたばこ屋。黒い壁とうだつが、«阿波刻み» の繁栄を語る。","lead":"徳島県西部の山間部では、江戸時代から葉たばこ作りが盛んで、«阿波葉» と呼ばれました。その集まる町が阿波池田です。本町通りには «うだつ» のある商家がならび、その一つ・真鍋家住宅が «阿波池田うだつの家・たばこ資料館» として公開されています。","story":["吉野川の上流、四国のまんなかにある阿波池田。まわりの山の斜面では、江戸時代から葉たばこが作られていました。水はけのよい山の畑は、たばこ作りにぴったりだったのです。刈り取った葉は干され、町に運ばれて、細かく刻まれました。こうしてできた «阿波刻み» は、きせるでたばこを吸う時代、上等な品として知られました。","1860年、真鍋武蔵という人がこの町でたばこ作りを始めます。真鍋家の屋敷は、間口が約18m、奥行きが約58mもある広いものでした。明治になると義理の弟・真鍋利三郎とともに事業を大きくし、池田のたばこ産業の中心になります。いちばんさかんなころ、池田には刻みたばこの業者が100軒以上もあったといいます。","本町通りを歩くと、家と家の境の壁が屋根の上に少し突き出しているのに気づくでしょう。これが «うだつ» です。火事のとき、となりへ火が燃えうつるのを防ぐためのものですが、りっぱなうだつを上げられるのはお金持ちのしるしでもありました。«うだつが上がらない» という言葉は、ここから来たともいわれます。","«なぜ池田のたばこ屋は減ってしまったの?» 明治の終わりに、たばこは国が作って売る «専売» になり、町の商人たちは自由に作れなくなりました。さかえた商家は、やがて静かな町並みとして残ります。資料館の工場には、葉を刻んだ «かんな刻み機» や帳簿が展示され、職人たちの手の音が聞こえてきそうです。"],"tl":[["江戸時代","県西部の山間部で葉たばこ作りが広がる"],["1860年","真鍋武蔵がたばこ製造を始める"],["1894年","義弟・真鍋利三郎とともに事業を拡大"],["明治末","たばこの製造が国の専売となる"],["1996年","真鍋家住宅が池田町の有形文化財に"],["2000年","阿波池田うだつの家・たばこ資料館が開館"],["2016年","本町通り周辺のうだつの町屋5棟が国の登録有形文化財に"]],"who":[["真鍋武蔵","真鍋家のたばこ製造を始めた人"],["真鍋利三郎","武蔵の義弟。明治に事業を広げた"],["たばこ刻みの職人","葉を細く刻み、«阿波刻み» を作った人びと"]],"deep":["«阿波葉» は幕末から明治にかけて県西部産の葉たばこのブランド。刻んだ製品は «阿波刻み» として知られた。","真鍋家の主屋は黒漆喰ぬりの壁に袖うだつ、3つの虫籠窓、格子戸をそなえる。ほかに書院造の離れ、茶室、煙草蔵、工場が残る。","2016年には佐藤家・内田家・亀長家・宮本家・住吉家の住宅が国の登録有形文化財になり、町並みとしての価値も認められた。","池田は吉野川の水運と、讃岐・伊予・土佐へ通じる道が交わる場所。葉たばこが集まったのは、この «交通の十字路» だったから。","たばこの専売制は、日露戦争の戦費をまかなうことなども背景に、明治後期に段階的に進められた。"],"look":["たばこ資料館の工場（かんな刻み機・売渡帳）","真鍋家主屋の袖うだつと虫籠窓","本町通りのうだつの町並み","煙草蔵と中庭"],"q":["家の境に上がっている、火よけの壁を何という？","«うだつ»。«うだつが上がらない» ということばの語源ともいわれます。"],"koji":[{"w":"うだつが上がらない","m":"なかなか出世しない、ぱっとしないこと。うだつを上げられるのが裕福な家だったことに由来するといわれる"}],"myth":"«うだつが上がらない» の語源は諸説ある。","img":["阿波池田うだつの家・たばこ資料館","うだつ","阿波池田駅"],"wp":"阿波池田たばこ資料館","rel":{"ev":[],"grave":[]},"ph":[["c:2/23/Awa-Ikeda_Udatsu_House_omoya_ac_%281%29.jpg",5930,3943,"阿波池田たばこ資料館"],["c:0/06/Honmachi_Street_Miyoshi_ac_%287%29.jpg",6007,3994],["c:a/a3/Awa-Ikeda_Udatsu_House_shinzashiki_ac_%284%29.jpg",5932,3944],["c:f/fd/Awa-Ikeda_Udatsu_House_omoya_ac_%285%29.jpg",5952,3957],["c:9/91/Awa-Ikeda_Udatsu_House_hanare_ac_%285%29.jpg",5939,3949],["c:2/28/Awa-Ikeda_Udatsu_House_garden_ac_%281%29.jpg",5980,3976],["c:f/f1/Awa-Ikeda_Tabacco_Museum_ac_%288%29.jpg",5921,3937],["c:a/af/Awa-Ikeda_Tabacco_Museum_ac_%286%29.jpg",5990,3983]]},{"id":"36_ganshoji","n":"願勝寺（美馬の古刹）","yomi":"がんしょうじ","cat":"寺社","rank":"B","y":686,"era":["asuka","heian","muromachi"],"sh":"県指定名勝（願勝寺庭園）","ad":"美馬市美馬町","st":"JR徳島線 穴吹駅から車で約15分。徳島自動車道 美馬ICから車で約5分","la":34.0555,"lo":134.0215,"hook":"忌部氏の寺から、悲運の崇徳上皇の供養の寺へ。吉野川の北岸に、千年をこえる由緒が眠る。","lead":"願勝寺は吉野川の北岸、美馬市美馬町にある真言宗の寺です。寺に伝わる系譜では、古代の忌部氏が建てた寺に始まり、平安時代に崇徳上皇に仕えた阿波内侍によって «願勝寺» となったといわれます。室町時代の庭園は県の名勝です。","story":["吉野川中流の北岸、美馬の台地は、古くから人が住み、古墳や古い寺の跡が多く残る土地です。願勝寺は、この地で千年以上の由緒を語りついできた寺です。寺に伝わる «願勝寺歴代系譜» によれば、はじまりは飛鳥時代。阿波の豪族・忌部氏の一族で、都で学んで僧となった福明律師のために «維摩寺» が建てられたといいます。","律師が亡くなると、その名をのこそうと寺は «福明寺» と名を改めました。そして平安時代の終わり。保元の乱に敗れて讃岐へ流された崇徳上皇に仕えた女性、阿波内侍が登場します。上皇が亡くなったあと、内侍は上皇の菩提をとむらうため都に建てた «願勝寺» を、母のふるさとである阿波のこの寺へ移した――と伝わります。","«悲運の上皇をとむらう寺が、なぜ阿波の山里に?» 讃岐と阿波は山をはさんですぐとなり。内侍の母は忌部氏の出で、阿波とのつながりが深かったと系譜は語ります。どこまでが史実かはたしかめられませんが、上皇への思いが吉野川の谷まで運ばれてきた、という物語は心に残ります。","その後、寺は阿波の守護や徳島藩主の保護を受けて、美馬郡を代表する寺になりました。境内の庭は室町時代の作とされ、京都の天龍寺と同じ手法の滝の石組みが見どころです。明治時代の山門は国の登録有形文化財。境内には、県内でいちばん古い博物館とされる美馬市立郷土博物館もあります。"],"tl":[["飛鳥時代（伝）","忌部氏が福明律師のため «維摩寺» を建てたと伝わる"],["686年（伝）","福明律師が亡くなり、寺を «福明寺» と改めたとされる"],["平安時代末（伝）","阿波内侍が崇徳上皇の菩提のため «願勝寺» を移したと伝わる"],["室町時代","庭園がつくられる"],["明治時代","現在の山門が建てられる"],["1998年","願勝寺庭園が県の名勝に指定"],["2009年","山門が国の登録有形文化財に"]],"who":[["福明律師","寺伝で初代とされる僧。忌部氏の出身で、俗名は忌部五十麿と伝わる"],["阿波内侍","崇徳上皇に仕えた女性。寺を «願勝寺» にしたと伝わる"],["崇徳上皇","保元の乱に敗れ讃岐に流された上皇。その菩提をとむらう寺とされる"]],"deep":["寺の由緒の多くは『郡里町史』に収められた «願勝寺歴代系譜» による。系譜には安徳天皇が阿波の山奥に隠されたという話まで出てくるが、史実かどうかは確かめられない。","庭園は室町時代の作とされ、京都・天龍寺と同じ手法の滝組をもつと評価されて1998年に県の名勝になった。","近くには白鳳期の寺院跡・郡里廃寺跡（国史跡）や、横穴式石室をもつ段の塚穴（国史跡）があり、美馬が古代から阿波西部の中心の一つだったことがわかる。","本尊は阿弥陀如来。新四国曼荼羅霊場の68番、阿波西国三十三観音霊場の30番札所でもある。","美馬市立郷土博物館は境内にあり、県内最古の博物館とされる。"],"look":["室町時代の庭園（滝の石組み）","明治時代の山門（国登録有形文化財）","境内の美馬市立郷土博物館","近くの郡里廃寺跡・段の塚穴"],"q":["願勝寺の庭の滝組は、京都のどの寺と同じ手法といわれる？","天龍寺です。"],"myth":"創建・改名・阿波内侍の話は寺伝の系譜によるもので史実は未確認。庭園の拝観方法は寺に要確認。","img":["崇徳天皇","郡里廃寺跡"],"wp":"願勝寺","rel":{"ev":[],"grave":[]},"ph":[["c:5/53/Ganzyouzi01.jpg",1600,1008,"願勝寺"],["c:9/97/Emperor_Sutoku2.jpg",2500,2680,"崇徳天皇"],["c:6/66/Kozato-haiji%2C_zenkei.jpg",6016,4000,"郡里廃寺跡"]]},{"id":"36_ohtaki","n":"大滝山と徳島の寺町","yomi":"おおたきさんととくしまのてらまち","cat":"寺社","rank":"B","y":1600,"era":["azuchi","edo","showa"],"sh":"","ad":"徳島市寺町・眉山町大滝山","st":"JR徳島駅から歩いて約15分","la":34.0705,"lo":134.5395,"hook":"城下を守る «寺の壁»。20をこえる寺がならぶ坂道に、写楽の墓の伝説まで眠る。","lead":"眉山の東のふもとには、20をこえる寺が集まる «寺町» があります。徳島城をきずいた蜂須賀家政が、勝瑞などから寺を移して作った町です。そのすぐ上の大滝山には、滝や湧き水、名物の焼餅があり、昔から人びとのいこいの場でした。","story":["1585年、阿波の新しい主となった蜂須賀家政は、徳島城と城下町の建設にとりかかりました。そのとき、それまで阿波の中心だった勝瑞や、蜂須賀家のもとの領地・尾張から、たくさんの寺を移しました。はじめは寺島というところに集め、のちに眉山のふもとの今の場所へ移したといわれます。","«なぜ寺をひとところに集めたの?» 寺の大きな建物と広い境内は、いざ戦になれば兵をあつめる陣地になり、城下を守る «壁» の役目もはたしました。また寺は、藩士や町人の «だんな寺» として、家の記録や葬式をとりしきる大切な場所でした。寺町の坂を歩くと、宗派のちがう寺が門をならべているのがわかります。","その寺のひとつ、東光寺には «東洲斎写楽の墓» と伝わる墓があります。写楽は江戸で役者絵を描き、わずか10か月ほどで姿を消したなぞの絵師。その正体を、阿波藩おかかえの能役者・斎藤十郎兵衛とする説が有力で、そのためこの寺に墓の伝承が生まれました。本当に写楽の墓かどうかはわかっていません。","寺町の上の大滝山には、眉山からわき出る水が小さな滝となって流れ、名水 «錦竜水» もわいています。滝のそばでは昔から «滝の焼餅» が売られ、参拝客のたのしみでした。かつては三重塔もそびえていましたが、1945年の徳島大空襲で焼けてしまいました。寺町の東宗院の山門は焼け残り、焼け出された人がしばらく身を寄せたといいます。"],"tl":[["1585年","蜂須賀家政が阿波に入り、徳島城下の建設を始める"],["江戸時代初め","勝瑞などから移された寺が眉山のふもとに集まり寺町となる"],["1666年","蜂須賀至鎮の正室・敬台院が江戸の寺を移し敬台寺とする"],["1889年","徳島市の町名として «寺町» が正式に使われる"],["1945年7月4日","徳島大空襲。大滝山の三重塔などが焼失"]],"who":[["蜂須賀家政","徳島藩の藩祖。寺町を作った"],["敬台院","初代藩主・蜂須賀至鎮の正室。敬台寺を移した"],["東洲斎写楽","なぞの浮世絵師。東光寺に墓と伝わるものがある"]],"deep":["勝瑞から移されたと伝わる寺には、浄土宗の還国寺・浄智寺、真言宗の源久寺・東宗院、日蓮宗の本行寺・寿量寺などがある。","写楽＝斎藤十郎兵衛説は、江戸時代の書物『増補浮世絵類考』の記述などを根拠とする。十郎兵衛が阿波藩の能役者だったことから徳島との縁が語られる。","寺町と大工町の境あたりはかつて «法華寺町» 、敬台寺から西は «敬台前» と呼ばれ、寺が町の地名にまでなっていた。","錦竜水は眉山湧水群の一つで、今も水をくみに来る人がいる。滝の焼餅はこの水を使うといわれる。","大滝山には春日神社などもあり、寺町とあわせて眉山東麓の «聖地の帯» を作っている。"],"look":["寺町の坂道と寺の山門のならび","東光寺の «写楽の墓» と伝わる墓","大滝山の滝と名水 «錦竜水»","名物 «滝の焼餅»"],"q":["東光寺に墓があると伝わる、なぞの浮世絵師はだれ？","東洲斎写楽。正体は阿波藩の能役者・斎藤十郎兵衛とする説が有力です。"],"myth":"寺町への移転年代ははっきりしない。写楽の墓は伝承で、確証はない。","img":["東洲斎写楽","眉山 (徳島市)"],"wp":"寺町 (徳島市)","rel":{"ev":[],"grave":[]},"ph":[["c:5/57/Toko-jo.jpeg",4032,3024,"寺町 (徳島市)"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:d/d9/Kinryosui.jpeg",828,611],["c:e/ea/Tousyuin.jpg",854,480],["c:c/c2/Hannyain.jpg",854,480],["c:1/1f/Gansyo-ji.jpg",854,480],["c:0/0e/Toshusai_Sharaku-_Otani_Oniji%2C_1794.jpg",802,1200,"東洲斎写楽"],["c:2/22/Mount_Bizan_from_Shimmachi_River_20200607.jpg",3620,2413,"眉山 (徳島市)"]]},{"id":"36_kamiyama_ai","n":"吉野川の藍作とその洪水（«藍と水害»）","yomi":"よしのがわのあいさくとこうずい","cat":"産業","rank":"A","y":1700,"era":["edo","meiji"],"sh":"","ad":"板野郡藍住町徳命（藍の館）ほか吉野川下流域","st":"JR高徳線 勝瑞駅から車で約10分、または徳島駅からバス «東中富» 下車","la":34.1245,"lo":134.4925,"hook":"毎年のように暴れる川が、日本一の «ジャパン・ブルー» を育てた。","lead":"吉野川は «四国三郎» と呼ばれる大きな川で、昔はたびたび洪水を起こしました。けれど洪水が運ぶ肥えた土は、藍を育てるのにぴったり。江戸時代の徳島藩は藍作をすすめ、«阿波藍» は全国一の染料になりました。","story":["利根川の «坂東太郎» 、筑後川の «筑紫次郎» とならび、吉野川は «四国三郎» と呼ばれます。四国の山から流れ出す水は、秋の台風のころになるとあふれ、下流の平野をたびたび水びたしにしました。堤防の少なかった時代、田畑も家も水につかることは、めずらしくありませんでした。","«そんな土地で、なぜ藍が?» 秘密は季節にあります。藍は春に種をまき、夏のうちに葉を刈り取れます。台風で川があふれる前に収穫を終えられるのです。しかも洪水は上流から新しい肥えた土を運んできて、畑の土をよみがえらせてくれました。稲作には向かない水害の土地が、藍にはかえって好都合だったのです。","徳島藩は藍作に力を入れ、刈り取った葉を発酵させて染料の «すくも» にする技術がみがかれました。藍商たちは «すくも» を江戸や大坂、全国の紺屋に売りさばき、大きな富をきずきます。吉野川の下流には、藍の蔵がならぶ豪壮な屋敷が生まれました。その富は、阿波おどりや人形浄瑠璃など、徳島の芸能を支える力にもなりました。","しかし明治の後半、インドから安い藍が、つづいてドイツから化学で作った染料が入ってくると、阿波藍は急におとろえます。それでも一部の藍師たちは技を守りつづけ、今も «すくも» 作りは受けつがれています。藍住町の «藍の館» では、藍商の屋敷と藍染めの世界にふれることができます。暴れ川と人の知恵が作った青を、ぜひ自分の目で確かめてください。"],"tl":[["江戸時代初め","蜂須賀家が阿波に入り、藍作が保護・奨励される"],["1752年","吉野川に «第十堰» がきずかれる（のち改修が重ねられる）"],["江戸時代中期〜後期","阿波藍が全国の藍染め市場を広くおさえる"],["明治30年代","藍の作付けが最盛期を迎える"],["明治後期","インド藍・合成藍の輸入で阿波藍が急速に衰退"]],"who":[["藍師・藍商","藍を育て、すくもを作り、全国に売った人びと"],["蜂須賀家","徳島藩主。藍を藩の大切な産業として保護した"],["奥村家","藍住の藍商。屋敷が藍の館として公開されている"]],"deep":["«すくも» は藍の葉を刻んで乾かし、水をかけながら100日ほど寝かせて発酵させたもの。この工程を担う職人を藍師と呼ぶ。","藍作の中心は吉野川中下流の «北方（きたがた）» と呼ばれた地域。現在の藍住町・石井町・上板町などにあたる。","石井町の «田中家住宅» は藍商の屋敷として国の重要文化財。洪水にそなえて石垣を高く積んだ造りが特徴とされる。","吉野川の洪水対策は長く課題だった。第十堰は江戸時代に作られ、今も改修されながら使われている、全国でも古い堰の一つ。","藍の最盛期の作付面積は明治30年代とされるが、数字は資料によって幅がある。","藍住町は1955年に藍園村と住吉村が合併して生まれた町で、町名の «藍» にも藍作の土地の記憶が残っている。"],"look":["藍の館（旧奥村家の屋敷・藍染め体験）","吉野川の堤防と第十堰（石井町・上板町の境）","石井町の田中家住宅（藍商の屋敷。公開状況は要確認）","夏の藍畑（ようすは年により異なる）"],"q":["藍を発酵させて作る染料のもとを何という？","«すくも»。約100日かけて発酵させて作ります。"],"koji":[{"w":"青は藍より出でて藍より青し","m":"弟子が師よりすぐれることのたとえ。藍から取った青が、元の藍よりあざやかになることから"}],"myth":"藍作奨励の始まりを蜂須賀家政とする話は伝承をふくむ。最盛期の作付面積は資料により差がある。","img":["阿波藍","藍住町","第十堰"],"wp":"吉野川","rel":{"ev":[],"grave":[]},"ph":[["c:9/9e/Yoshinogawa%28Tokushima%29.jpg",1230,916,"吉野川"],["c:6/69/Tokushima_City_View_from_the_Top_of_Bizan_20200405.jpg",6960,4640],["c:6/62/Yosinogawagenryu02.jpg",1600,1199],["c:c/cb/Yosinogawagenryu01.jpg",1600,1199],["c:8/87/YoshinoGawa.jpg",1280,960],["c:7/70/Yoshinogawa_Daijuzeki.jpg",640,480],["c:4/44/Aizumi_Ai_no_Yakata.jpg",640,480,"藍住町"]]},{"id":"36_dainichiji","n":"大日寺（一宮城の麓の札所）","yomi":"だいにちじ","cat":"寺社","rank":"B","y":815,"era":["heian","muromachi","edo"],"sh":"","ad":"徳島市一宮町西丁","st":"JR徳島駅から徳島バス一宮線などで «一の宮札所前» 下車すぐ","la":34.0375,"lo":134.4585,"hook":"道一本をはさんで寺と一宮神社が向きあう。お遍路の十三番は、神と仏がいっしょだった時代の記憶を残す。","lead":"大日寺は四国八十八箇所の13番札所です。寺伝では815年に空海が開いたとされ、長く向かいの一宮神社の «別当寺»（神社を管理する寺）でした。すぐ東の山には、南北朝時代から戦国時代にかけて一宮氏の城がありました。","story":["鮎喰川の流れが山あいから平野へ出るあたりに、一宮の里があります。寺の言い伝えでは815年、空海がこの近くの «大師が森» で護摩をたいて祈っていると、大日如来が現れて «ここは霊地だから寺を建てよ» と告げました。空海はその姿を刻んで本尊とし、«大日寺» と名づけた――と伝わります。","道をはさんで向かいにあるのが一宮神社です。«なぜお寺と神社がこんなに近いの?» 江戸時代まで、日本では神と仏はいっしょにまつられるのがふつうでした。大日寺は一宮神社の «別当寺» として神社の仕事をとりしきり、お遍路さんには «一宮大明神» の名を書いて納経していました。そのため «一宮寺» とも呼ばれたといいます。","南北朝時代、寺の東にそびえる山に一宮城がきずかれました。城主の一宮氏は一宮神社の大宮司もかねる家で、神社と寺を深くうやまいました。ところが天正年間、土佐から攻めこんだ長宗我部元親の軍勢によって、一帯は焼けてしまいます。一宮氏も力を失いました。","江戸時代になると、徳島藩主の蜂須賀光隆が神社と寺を再建します。そして明治の神仏分離。神社にまつられていた行基作と伝わる十一面観音が寺の本堂に移され、今の本尊になりました。それまでの本尊の大日如来は脇にまつられています。«大日寺なのに本尊は観音さま» というふしぎは、この歴史から生まれたのです。","2008年には韓国出身の住職が就任し、八十八か所で初めての外国籍の住職として話題になりました。千年以上、いろいろな人を迎えてきた札所らしい出来事です。寺から歩いて数分の登り口から、一宮城の本丸まで山道をのぼることもできます。"],"tl":[["815年（伝）","空海が大日如来を刻んで寺を開いたと伝わる"],["平安時代末（伝）","一宮神社が今の地に分祀され、寺はその別当寺になったとされる"],["南北朝時代","東の山に一宮城がきずかれる"],["天正年間","長宗我部元親の兵火で一帯が焼失"],["江戸時代初め","徳島藩主・蜂須賀光隆が神社と寺を再建"],["明治初め","神仏分離。十一面観音が寺の本尊になる"],["2008年","韓国出身の住職が就任"]],"who":[["空海","寺を開いたと伝わる僧"],["一宮氏","一宮城の城主。一宮神社の大宮司もかねた"],["長宗我部元親","土佐の戦国大名。阿波に攻めこみ一帯を焼いた"],["蜂須賀光隆","徳島藩3代藩主。神社と寺を再建した"]],"deep":["山号は大栗山、院号は花蔵院。宗派は真言宗大覚寺派。四国三十三観音霊場の5番札所もかねる。","ご詠歌は «阿波の国一の宮とはゆうだすき かけて頼めやこの世のちの世» 。寺の歌なのに «一の宮» をよみこむところに、神仏習合の名ごりがある。","本尊の十一面観音は秘仏だったが、2014年以降は拝めるようになった。","向かいの一宮神社の本殿は国の重要文化財。祭神は大宜都比売命など。阿波国一宮の論社の一つとされる。","もとの寺地は東へ約1kmの國中寺の場所だったとされ、現在は新奥の院となっている。奥の院は西の西龍王山の建治寺。","一宮城は標高約144mの山城で、阿波でも有数の規模をもつ中世の城跡として知られる。"],"look":["本堂の十一面観音（拝観方法は寺で確認）","道をはさんだ一宮神社の本殿（重要文化財）","しあわせ観音（合掌した手の中の観音像）","一宮城跡への登城路"],"q":["大日寺は四国八十八箇所の何番札所？","13番札所です。"],"koji":[{"w":"同行二人","m":"お遍路さんは一人で歩いていても、いつも弘法大師（空海）がいっしょにいる、という考え"}],"myth":"空海の開創、一宮神社の分祀の時期は寺伝・伝承による。","img":["一宮神社 (徳島市)","一宮城 (阿波国)","四国八十八箇所"],"wp":"大日寺 (徳島市)","rel":{"ev":[],"grave":[]},"ph":[["c:6/6d/Dainitiji20210330_1.jpg",1600,1174,"大日寺 (徳島市)"],["c:9/90/Dainichi-ji%2C_Taishi-do_Hall_01.jpg",3264,2448],["c:c/c8/Ogurizan_Dainichiji_02.JPG",3761,2429],["c:8/8e/Dainichi-ji%2C_Shiawase-Kannon_01.jpg",3148,2361],["c:e/ef/Dainichi-ji%2C_Koyasu-Jiz%C5%8D-son_01.jpg",2901,2176],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:b/b7/Hunahatehime_01.jpg",2400,1782],["c:3/32/Hunahate_01.jpg",2041,1022]]},{"id":"36_omiwa_jinja","n":"大御和神社（阿波国の総社・国府の社）","yomi":"おおみわじんじゃ","cat":"寺社","rank":"B","y":927,"era":["nara","heian"],"sh":"","ad":"徳島市国府町府中","st":"JR徳島線 府中駅から歩いて約5分","la":34.0795,"lo":134.4815,"hook":"«府中» という地名が語る、阿波の «都» の跡。その真ん中に、国司がまいった社があったといわれる。","lead":"大御和神社は、徳島市国府町府中にある古い神社で、平安時代の『延喜式』にも名前がのる «式内社» です。かつて阿波国の役所（国府）があったと考えられる地域にあり、国内の神々をまとめてまつる «総社» だったともいわれます。地元では «府中宮（こうのみや）» と呼ばれています。","story":["奈良時代、日本の国々には «国府» という役所が置かれ、都から国司がやってきて政治をしました。阿波国の国府があったのは、いまの徳島市国府町のあたりと考えられています。«国府町» «府中» という地名そのものが、その記憶を伝えているのです。","国府の近くでは、1990年代から発掘が進み、観音寺遺跡から古代の木簡がたくさん見つかりました。なかには中国の古典『論語』を書き写した木簡もあり、«1300年前の阿波で、役人が漢字の勉強をしていた» ことがわかって話題になりました。阿波国分寺や国分尼寺の跡も近くにあり、この一帯はまさに古代阿波の «首都» でした。","そのまんなかにあるのが大御和神社です。祭神は大己貴神（おおなむちのかみ）。一説に、大和の三輪山の神を迎えてまつったといわれ、«大御和» の名もそれを思わせます。平安時代、国司は国内のたくさんの神社をまわってまいるのが仕事でしたが、それでは大変なので、国府の近くに «総社» をもうけ、そこでまとめて祈るようになりました。この神社は阿波国の総社だったといわれます。","«なぜ昔は «印鑰（いんやく）大明神» と呼ばれたの?» 印鑰とは、国司の印と倉のかぎのこと。国府の大切な品を守る神という意味だと説明されてきました。ただし、この由来は後世のこじつけで、じつは弁財天に仕える «印鑰童子» から来た名だ、という反論も古い案内書にあります。小さな境内に、学者どうしの議論まで眠っているのです。"],"tl":[["創建年代不詳","大和の三輪から神を迎えたと伝わる"],["927年","『延喜式』完成。神名帳に大御和神社の名がのる"],["平安時代（伝）","阿波国の総社として国司の信仰を集めたとされる"],["1872年","郷社になる"],["1936年","県社に昇格"]],"who":[["大己貴神","祭神。大国主神の別名とされる"],["阿波国司","都から来た国の長官。総社にまいったとされる"]],"deep":["『延喜式』神名帳に名をのせる «式内社» 。阿波国の式内社は50座あり、そのうちの一社。","神紋は «鍵の立合» 。«印鑰» の «鑰（かぎ）» とのつながりを思わせる。","«印鑰大明神» の由来について、国司の印と鍵を守る神とする説と、弁財天十五童子の «印鑰童子» に由来するという説がある。『阿波名勝案内』は前者を後の作り話としている。","近くの観音寺遺跡からは7世紀の『論語』木簡が出土し、地方の役人層にまで漢字文化が広がっていたことを示す重要資料とされる。","周辺には四国八十八箇所の15番国分寺、16番観音寺、17番井戸寺が集まり、古代の国府の区域と遍路道が重なっている。"],"look":["境内の本殿と、鍵をかたどった神紋","境内社の江之島神社・若宮神社","周辺の阿波国分寺・観音寺（遍路の札所）","国府の推定地を歩いて地名 «府中» を確かめる"],"q":["大御和神社がむかし呼ばれていた名前は？","«印鑰（いんやく）大明神»。国司の印と鍵に由来するという説と、別の説があります。"],"myth":"総社であったこと、三輪からの勧請、印鑰の由来はいずれも伝承・諸説。","img":["阿波国府","阿波国分寺","観音寺遺跡"],"wp":"大御和神社","rel":{"ev":[],"grave":[]},"ph":[["c:0/00/Omiwa_Shrine%2C_Tokushima%2C_Torii.jpg",1600,901,"大御和神社"],["c:e/ed/Omiwa_Shrine%2C_Tokushima%2C_entrance_sculpture_2023.jpg",1600,1199],["c:b/b6/Omiwa_Shrine%2C_Tokushima%2C_Shaden.jpg",1600,1199],["c:5/50/Omiwa_Shrine%2C_Tokushima%2C_Haiden.jpg",1600,1199],["c:4/4c/Omiwa_Shrine%2C_Tokushima%2C_Setsumatsusha_Torii_2023.jpg",1600,1173],["c:2/25/Awakokbunji20210330_1.jpg",1600,1199,"阿波国分寺"]]},{"id":"36_jo_hakubutsukan","n":"徳島城博物館（蜂須賀家と «阿波水軍» の資料）","yomi":"とくしまじょうはくぶつかん","cat":"学び","rank":"B","y":1585,"era":["azuchi","edo"],"sh":"国の重要文化財（徳島藩御召鯨船 千山丸）","ad":"徳島市徳島町城内（徳島中央公園）","st":"JR徳島駅から歩いて約10分","la":34.0745,"lo":134.5555,"hook":"日本でただ一つ残る大名の船 «千山丸» 。城の御殿の跡で、阿波水軍の波の音を聞く。","lead":"徳島城博物館は、徳島城の表御殿の跡に建つ徳島市の博物館です。蜂須賀家と徳島藩の歴史、城下町のくらし、阿波水軍の活躍を紹介しています。国の重要文化財の «千山丸» は、大名の船として現存するただ一つのものといわれます。","story":["1585年、豊臣秀吉の四国攻めで手柄をたてた蜂須賀家は、阿波一国をあたえられました。藩祖の蜂須賀家政は、吉野川の河口の «渭山（いのやま）» と呼ばれた小山に目をつけ、新しい城をきずきます。これが徳島城です。川と海に囲まれた城は、まさに «水の城» でした。","城の石垣には、この地でとれる青みがかった石がたくさん使われています。«なぜ石垣が緑色っぽいの?» これは «阿波の青石» とも呼ばれる結晶片岩で、城山の岩そのものを割って積んだのです。博物館のまわりを歩くと、その独特の色合いが目に入ります。","博物館はその城の表御殿の跡に建っています。展示の目玉は «千山丸» 。藩主が乗るために作られた豪華な船で、鯨をとる船の形をまねているので «鯨船» と呼ばれます。細長い船体に、たくさんのこぎ手が乗り、海の上をすべるように進んだといいます。大名の船が今に残るのはとてもめずらしく、国の重要文化財です。","徳島藩は、瀬戸内海と紀伊水道の入口をおさえる藩でした。藩の船をあずかる «阿波水軍» は、森家などが率いて、参勤交代の船旅や海の守りをにないました。大坂の陣でも活躍したと伝わります。展示を見ていると、«海の大名» としての徳島藩の顔が浮かんできます。","博物館のとなりには、国の名勝 «旧徳島城表御殿庭園» があります。石を大胆に組んだ桃山風の庭で、長さ10mほどの一枚岩の石橋がかかっています。明治になって城の建物はほとんどこわされましたが、石垣と庭、そして博物館の資料が、蜂須賀家の300年近い歴史を今に伝えています。"],"tl":[["1585年","蜂須賀家が阿波をあたえられ、徳島城の築城を始める"],["1615年","大坂の陣。阿波水軍も出陣したと伝わる"],["1869年","版籍奉還。蜂須賀家の支配が終わる"],["1875年ごろ","城の建物の大半が取りこわされる"],["1945年","徳島大空襲で鷲の門が焼失"],["1989年","鷲の門が復元される"],["平成初め","徳島城博物館が開館"]],"who":[["蜂須賀家政","徳島藩の藩祖。徳島城をきずいた"],["蜂須賀至鎮","初代藩主。大坂の陣で活躍した"],["森家","阿波水軍を率いた家"]],"deep":["«千山丸» は藩主の御座船として使われた鯨船。大名の船で現存するものは、これが唯一とされる。","旧徳島城表御殿庭園は、桃山風の枯山水と池泉の庭をあわせもつ国の名勝。作庭は茶人・上田宗箇と伝わる。","徳島城の石垣は、城山の緑色片岩（阿波の青石）を割って積んだもの。緑色の石垣は全国でも個性的。","徳島城は天守を本丸ではなく東二の丸に置いたとされる、めずらしい配置の城。","城跡は «徳島城跡» として国の史跡。城山には原生林が残り、自然の山と城の遺構がいっしょに楽しめる。","阿波水軍の森家は、戦国時代に三好氏に仕えた水軍の家とされ、蜂須賀家のもとでも海の仕事をになった。"],"look":["展示室の «千山丸»（重要文化財）","国の名勝 旧徳島城表御殿庭園と一枚岩の石橋","城山の緑色の石垣","復元された鷲の門"],"q":["徳島城博物館にある、大名の船として現存唯一といわれる船の名前は？","«千山丸»（せんざんまる）。鯨船の形をした藩主の船です。"],"myth":"大坂の陣での阿波水軍の活躍の細部、庭園の作庭者は伝承をふくむ。博物館の開館年は確認できなかったため «平成初め» とした。","img":["徳島城","旧徳島城表御殿庭園","蜂須賀家政"],"wp":"徳島市立徳島城博物館","rel":{"ev":[],"grave":[]},"ph":[["c:7/76/Tokushima_castle_museum02s3872.jpg",3872,2592,"徳島市立徳島城博物館"],["c:3/35/Tokushima_castle_museum.jpg",640,480],["c:1/1a/Tokushima_castle_22.JPG",2048,1362,"徳島城"],["c:1/17/Tokushima_Castle_lordly_Front_Palace_Garden01s3200.jpg",3200,2142,"旧徳島城表御殿庭園"],["c:d/d5/Hachisuka_Iemasa.jpg",2897,5437,"蜂須賀家政"]]},{"id":"36_shishikui","n":"宍喰の町並み（南海地震の津波碑が残る浦）","yomi":"ししくいのまちなみ","cat":"町","rank":"B","y":1854,"era":["muromachi","edo","showa"],"sh":"","ad":"海部郡海陽町宍喰浦","st":"阿佐海岸鉄道（DMV）宍喰駅から歩いて約10分","la":33.5645,"lo":134.3095,"hook":"何度も津波にのまれ、そのたびに立ち上がった浦。石に刻まれた文字が、次の世代へ «逃げよ» と語りかける。","lead":"宍喰は徳島県のいちばん南、高知県とのさかいにある海辺の町です。江戸時代には土佐との国境を守る関所が置かれました。この浦は南海地震の津波にくり返しおそわれ、その記録が古文書や石碑に残されています。","story":["宍喰は、徳島県のいちばん南のはし。すぐ先はもう高知県です。山が海までせまり、その間の小さな平地に家々が寄りそっています。«宍喰» という名は、もとは «あしくい» だったといわれ、古くから人びとがこの川ぞいの平地を開いてきました。","戦国時代、この地は土佐の長宗我部氏に攻められ、城はつぎつぎと落ちました。その後、阿波が蜂須賀家の領地になると、宍喰は土佐との国境の町になります。関所や、鉄砲を持った番人の小屋、のろし台が置かれ、旅人は宍喰で身元を調べられてから国境をこえました。","けれども宍喰の人びとにとって、いちばんおそろしいのは海でした。南海トラフの大地震が起きるたびに、津波がこの浦をおそいます。地元では津波を «震潮（なえしお）» と呼び、慶長（1605年）、宝永（1707年）、安政（1854年）の震潮の記録が残されています。村人が逃げ出してしまうほど、暮らしが苦しくなったこともあったといいます。","«なぜ昔の人は石に記録を刻んだのか?» 紙はいつか失われますが、石は何百年も残ります。«ここまで水が来た» «地震が来たらすぐ高いところへ» ――子や孫への切実な願いです。宍喰から北へ少し行った鞆浦には、1361年の地震津波を記したとされる «康暦碑» があり、日本でもっとも古い津波碑の一つといわれます。","昭和の南海地震（1946年）でも、宍喰は津波の被害を受けました。いま町には避難路や高台への案内がととのえられています。古い町並みを歩きながら、石碑の前で足を止め、そこに込められた先人の声に耳をすませてみてください。亡くなった多くの人びとへの祈りの場でもあります。"],"tl":[["1361年","正平の地震津波。鞆浦の康暦碑（1380年）に記されたとされる"],["1578年ごろ","長宗我部氏に攻められ、宍喰の城が落ちる"],["江戸時代","土佐との国境の関所が置かれる"],["1605年","慶長の地震津波（慶長の震潮）"],["1707年","宝永地震の津波"],["1854年","安政南海地震の津波"],["1946年","昭和南海地震の津波"],["2006年","海部町・海南町と合併し海陽町となる"]],"who":[["宍喰浦の人びと","何度も津波を受け、記録を残して町を立て直してきた"],["長宗我部元親","土佐の戦国大名。宍喰に攻めこんだ"],["鷲住王","古墳時代にこの地に来たと伝わる人物"]],"deep":["地元の古い記録では、津波を «震潮（なえしお）» と書く。«なえ» は地震をさす古いことば。","海陽町鞆浦の «康暦碑» は、1361年の正平地震の津波の犠牲者を供養した碑とされ、康暦2年（1380年）の年号をもつ。現存最古級の津波碑として知られる。","宍喰には、長宗我部氏との戦いで切腹した武将にちなむ «民部岩» の伝承も残る。","八坂神社の祇園祭では «関船» という船形の山車が曳かれる。中世の交易船をかたどったものとされる。","宍喰から高知県東洋町の甲浦へは、線路と道路の両方を走る阿佐海岸鉄道の «DMV» が走っている。"],"look":["宍喰浦の古い町並みと路地","町内や周辺の地震・津波の記念碑（場所は現地の案内で確認）","鞆浦の康暦碑（海陽町鞆浦）","高台への避難路の案内"],"q":["宍喰の古い記録で、津波のことを何と書く？","«震潮（なえしお）»。«なえ» は地震のことです。"],"koji":[{"w":"津波てんでんこ","m":"津波が来たら、家族を待たずにそれぞれがすぐ高台へ逃げよ、という三陸地方の教え。全国の津波の地で語られる"}],"myth":"宍喰の町なかの個々の碑の名称・年代は未確認のため記していない。«あしくい» 語源、鷲住王は伝承。","img":["南海地震","康暦碑","阿佐海岸鉄道"],"wp":"宍喰町","rel":{"ev":[],"grave":[]},"ph":[["c:0/09/Takegasima20220712_1.jpg",4032,1728,"宍喰町"],["c:4/44/Shishikui_Station_%282015%29_01.JPG",2938,2204,"近く: 宍喰駅"],["c:c/c9/Shishikui_Junior_High_School.jpg",3264,2448,"近く: 海陽町立宍喰中学校"],["c:3/3d/R55%E9%81%93%E3%81%AE%E9%A7%85%E5%AE%8D%E5%96%B0%E6%B8%A9%E6%B3%89.jpg",914,881,"近く: 道の駅宍喰温泉"],["c:1/1f/Shishikui_Elementary_School.jpg",3264,2448,"近く: 海陽町立宍喰小学校"]]},{"id":"36_awa_kainan_bunka","n":"阿波海南文化村（海部の考古と歴史）","yomi":"あわかいなんぶんかむら","cat":"学び","rank":"B","y":1400,"era":["kofun","muromachi"],"sh":"","ad":"海部郡海陽町四方原","st":"JR牟岐線 阿波海南駅から歩いて約15分。阿佐海岸鉄道DMV «阿波海南文化村» バス停すぐ","la":33.6145,"lo":134.3515,"hook":"7万枚の古銭と、南の刀工が打った «海部刀» 。山と海にはさまれた町に、中世の富が眠っていた。","lead":"阿波海南文化村は、徳島県南部の海陽町にある文化施設です。中の海陽町立博物館には、この地の刀工が作った «海部刀» のコレクションや、7万枚をこえる «大里出土銭» 、横穴式石室をもつ大里古墳の復元などがあります。","story":["徳島県の南の海岸を走り、海部川の河口に近づくと、山と海にはさまれた小さな平野が開けます。ここ海部は、中世に «海部刀» と呼ばれる刀が作られた土地でした。«なぜこんな南のはしで刀作りが?» 海部川の上流の山からは木炭が、海からは船で鉄や品物が運ばれ、刀を作って売るのに都合がよかったと考えられています。","海部刀は、実戦で使いやすいじょうぶな刀として知られ、船で各地へ運ばれたといわれます。武士だけでなく、海で働く人びとにも用いられたと伝わります。博物館の刀剣コレクションは、この地域ならではの海部刀を中心に、全国でも屈指の質と量といわれます。刃文や反りを見くらべると、同じ土地の刀工たちの «くせ» が少しずつ見えてきます。","もう一つの目玉が «大里出土銭» です。町内の大里で、土の中から大量の古い銭がまとめて見つかりました。その数7万88枚。中世に埋められたお金としては四国一の数です。«だれが、なぜ埋めたのか?» 戦乱からたくわえを守るため、あるいは神仏へのそなえとして――理由はなぞのままです。けれど、これだけのお金が集まるほど、海部の港が交易でにぎわっていたことはたしかでしょう。","さらにさかのぼれば、古墳時代の人びとの姿もあります。大里古墳は、石を積んで部屋を作った «横穴式石室» をもつ古墳で、文化村ではその石室が復元されています。中に入ると、ひんやりした石の空間に、この地の有力者がねむっていた時代を感じられます。","2021年からは、線路と道路の両方を走る阿佐海岸鉄道の «DMV» のバス停もでき、文化村はその起点になりました。古い刀とお金、そして新しい乗り物。南の町の過去と未来がここで出会っています。"],"tl":[["古墳時代","大里古墳がつくられる"],["鎌倉〜室町時代","海部川流域で «海部刀» が作られる"],["中世","大里に大量の銭が埋められる（大里出土銭）"],["2019年","DMVの車両3両がそろった記念行事が文化村の駐車場で開かれる"],["2021年12月25日","DMVの «阿波海南文化村» バス停が設けられ、起終点となる"]],"who":[["海部の刀工たち","海部川流域で海部刀を打った職人"],["大里古墳の被葬者","古墳時代の海部の有力者と考えられる人物"]],"deep":["大里出土銭は70,088枚。中世の埋納銭としては四国で最多の出土数とされる。多くは中国から輸入された銭と考えられる。","海部刀は室町〜戦国時代に最盛期をむかえた地方の刀剣で、氏吉などの刀工の名が知られる。","大里古墳は横穴式石室をもつ古墳。徳島県南部では古墳の数が少なく、この地方の古墳時代を知る貴重な例とされる。","文化村には海南文化館・工芸館・いきいき館・三幸館があり、藍染めや木工の体験もできる。","DMVは線路と道路を走り分けられる乗り物で、2021年に阿佐海岸鉄道で世界で初めて本格営業運行が始まった。"],"look":["海陽町立博物館の海部刀コレクション","大里出土銭の展示","復元された大里古墳の横穴式石室","DMVの発着のようす"],"q":["大里で見つかった古銭は、およそ何枚？","7万枚あまり（70,088枚）。中世の埋納銭では四国一です。"],"myth":"大里出土銭を埋めた目的は不明。海部刀の使われ方は伝承をふくむ。","img":["海部刀","阿佐海岸鉄道","DMV (鉄道車両)"],"wp":"阿波海南文化村","rel":{"ev":[],"grave":[]},"ph":[["c:9/99/Awakainan-bunkamura-bunkamura-20250823.jpg",5184,3456],["c:7/77/Awa-Kainan_station_building.jpg",4000,3000,"近く: 阿波海南駅"],["c:3/3a/Todoroki_Watefalls_02.JPG",2848,4288,"近く: 海南町"],["c:5/53/KaifuHighSchool.jpg",3264,2448,"近く: 徳島県立海部高等学校"],["c:8/80/Kainan_post-office_62120.jpg",1555,1166,"近く: 海南郵便局 (徳島県)"],["c:d/d2/Kaiyo_town_Asakawa_elem-sch.jpg",1555,1166,"近く: 海陽町立浅川小学校"]]},{"id":"36_muya_ko","n":"撫養港と岡崎の町（塩と藍の積出港）","yomi":"むやこうとおかざきのまち","cat":"町","rank":"B","y":1700,"era":["nara","muromachi","edo"],"sh":"","ad":"鳴門市撫養町岡崎・撫養町南浜ほか","st":"JR鳴門線 鳴門駅から歩いて約15分","la":34.1835,"lo":134.6205,"hook":"奈良時代の «牟夜戸（むやのと）»。四国の玄関口は、塩と藍の船でにぎわう港町になった。","lead":"撫養港は鳴門市にある港で、小鳴門海峡にのぞんでいます。奈良時代の風土記に «牟夜戸» として登場する古い港で、中世には阿波水軍の本拠地、江戸時代には塩田の塩や吉野川流域の藍・木材・たばこを積み出す阿波一の商業港として栄えました。","story":["鳴門の大きな渦潮で知られる鳴門海峡の西に、もう一つの細い海があります。小鳴門海峡です。その南側に開けた港が撫養港。古くは «牟夜戸（むやのと）» と呼ばれ、奈良時代の記録にもその名が残ります。当時、ここは阿波・讃岐・伊予・土佐へ向かう人がまず上陸する、四国の玄関口でした。","中世になると、この港は阿波水軍の本拠地となります。吉野川の水運で運ばれてきた品々は、ここから船に積みかえられ、大坂や瀬戸内の各地へ運ばれました。«なぜ徳島の町ではなく撫養だったの?» 吉野川の河口の徳島は遠浅で、大きな船が入りにくかったのです。潮の流れの速い海峡を知りつくした船乗りたちが、この港を守っていました。","江戸時代、撫養の海辺には広い塩田が開かれました。海水を砂にまいて天日で干し、濃い塩水をとって煮つめる――この地で作られた塩は、上質なことで知られました。塩に加えて、吉野川流域の藍、木材、たばこが撫養から積み出され、港は阿波一の商業港としてにぎわいます。岡崎の町には、商人の家や蔵がたちならびました。","塩田の仕事は、夏の強い日ざしの下での重労働でした。浜に砂をまき、海水をかけ、乾いた砂を集めてまた海水で洗い、濃い塩水をとる。それを釜で一昼夜煮つめて、ようやく白い塩ができあがります。浜で働く人たちの汗が、港から積み出される塩の一粒一粒にこもっていました。港には塩を運ぶ船が並び、商人たちが値段をかけあう声がひびいたことでしょう。","近くの妙見山には、蜂須賀家が阿波を治めはじめたころに置いた «撫養城（岡崎城）» があり、港を見下ろして守っていたとされます。やがて塩田は姿を消し、明石海峡大橋の開通で大阪・神戸への高速船もなくなりました。けれど港の路地を歩けば、船と商人がつくった町の骨格が、今もたしかに残っています。"],"tl":[["奈良時代","風土記に «牟夜戸» として登場"],["中世","阿波水軍の本拠地となり、吉野川の物資の積出港として栄える"],["1585年以降","蜂須賀家が阿波九城の一つとして撫養城を置く"],["江戸時代","塩田が開かれ、塩・藍・木材・たばこの積出港に"],["1991年","大阪・神戸への高速船が就航"],["1997年","明石海峡大橋開通を前に高速船が廃止"]],"who":[["阿波水軍","中世にこの港を本拠地とした水軍"],["撫養の塩田の人びと","浜で塩を作った人びと"],["蜂須賀家","徳島藩主。撫養城を置いた"]],"deep":["撫養港の港湾区域には、小鳴門海峡の南半分と撫養川の文明橋より下流の水面がふくまれる。","撫養の塩田の塩は «斎田塩» などの名で知られ、瀬戸内の塩の産地の一つだった（撫養町には «斎田» の地名が残る）。","撫養城は蜂須賀家の «阿波九城» の一つとされ、1638年ごろ一国一城令の流れで廃城になったといわれる。妙見山には後に三層の天守風の建物が建てられたが、城にもともと天守はなかった。","小鳴門海峡の最もせまいところは幅約110m。鳴門海峡（大鳴門）にくらべて水路のような細い海である。","撫養は、大坂方面から船で来た遍路が上陸し、1番札所の霊山寺へ向かう入口の一つにもなったとされる。"],"look":["岡崎・南浜かいわいの港町の路地","小鳴門海峡と撫養港の岸壁","妙見山（撫養城跡）からの眺め","撫養川ぞいの町並み"],"q":["撫養港の古い呼び名は？","«牟夜戸（むやのと）»。奈良時代の記録に出てきます。"],"myth":"撫養城の廃城年、港町岡崎の旧家の具体的な位置は未確認。«斎田塩» の呼び名の範囲は諸説。","img":["小鳴門海峡","撫養城","入浜式塩田"],"wp":"撫養港","rel":{"ev":[],"grave":[]},"ph":[["c:0/04/Muya_Port%2C_Naruto_city.jpg",2592,1936,"撫養港"],["c:9/96/Boat_Race_Naruto_from_Konarutobashi_Bridge.JPG",3221,2416,"小鳴門海峡"],["c:4/48/Tori-i_kinen_hakubutsukan.jpg",400,300,"撫養城"],["c:9/93/Marakkanam_Salt_Pans.JPG",4055,2693,"入浜式塩田"]]},{"id":"36_sanuki_kaido","n":"讃岐街道（阿波から讃岐への藩の道）","yomi":"さぬきかいどう","cat":"街道","rank":"B","y":1650,"era":["heian","edo"],"sh":"","ad":"板野郡板野町大坂（大坂峠）ほか徳島市〜東かがわ市","st":"JR高徳線 板野駅から大坂峠の登り口まで車で約10分。峠道は山道のため足ごしらえを","la":34.2,"lo":134.42,"hook":"義経も越えたという峠に、藩の番所。国境の坂道は、人と物と物語の通り道だった。","lead":"讃岐街道は、徳島藩が整えた «阿波五街道» の一つで、徳島城下から讃岐国（香川県）へ向かう道です。吉野川をわたり、板野の大寺から大坂峠をこえて讃岐の引田へ入りました。峠の阿波側には、人の出入りを取りしまる番所が置かれていました。","story":["江戸時代、徳島藩は城下町から国のすみずみへ向かう五つの街道を整えました。その一つが讃岐街道です。出発点は徳島城の鷲の門。佐古、蔵本を通り、吉野川は «徳命の渡し» で舟にのってわたります。さらに北へ進み、板野の大寺で東西に走る撫養街道と交わると、いよいよ山へ入ります。","目の前にそびえるのが大坂峠です。この峠をこえると、そこは讃岐国。阿波側には «大坂口御番所» という関所が置かれ、国を出入りする人や荷物がきびしく調べられました。«なぜそこまで調べたの?» 藩にとって、藍や塩などの大切な品がかってに持ち出されること、あやしい人が入りこむことは、大きな問題だったからです。","番所の前では、旅人が «往来手形» を差し出し、役人が名前や行き先を確かめました。金毘羅参りに向かう人、商いの荷を背負った人、里帰りの人。峠道は急で、荷を積んだ馬もあえぎながら登ったことでしょう。峠のてっぺんで一息つけば、北には瀬戸内の海が光って見えます。«ここから先は讃岐» 。旅人たちはこの景色で国ざかいをこえたことを実感したはずです。","この峠には、もっと古い物語もあります。『平家物語』によれば、1185年、阿波の勝浦に上陸した源義経は、夜どおし馬を走らせて大坂越えをし、讃岐の屋島にいた平家の背後をつきました。«まさか山をこえて来るとは» 。平家は海に逃れ、屋島の戦いは源氏の勝利に終わります。那須与一が扇の的を射たのは、このときのことです。","明治以降、海ぞいに国道11号ができると、大坂峠をこえる人はめっきり減り、街道はしずかな山道にもどりました。いまは県道の一部と重なり、峠道の一部を歩くこともできます。峠から見下ろす播磨灘と讃岐の平野は、昔の旅人が «いよいよ国を出る» と胸をふくらませた景色そのものです。"],"tl":[["1185年","源義経が大坂越えで屋島へ向かったと『平家物語』に語られる"],["江戸時代","徳島藩が阿波五街道の一つとして整える"],["江戸時代","大坂峠の阿波側に大坂口御番所が置かれる"],["明治以降","海ぞいの国道11号が主な道となり、峠越えの通行が減る"]],"who":[["源義経","屋島の戦いの前、大坂越えをしたと伝わる"],["番所の役人","大坂口御番所で人と荷物を調べた"],["街道を行く旅人・商人","藍や塩を運び、金毘羅参りなどに向かった人びと"]],"deep":["«阿波五街道» は、讃岐街道・撫養街道・伊予街道・土佐街道・淡路街道とされる。","ルートは徳島城鷲の門→佐古→蔵本→徳命の渡し（吉野川）→大寺（板野町）→大坂峠→馬宿（東かがわ市引田）。現在の県道1号徳島引田線と一部重なる。","大寺では、撫養と池田を結ぶ撫養街道（川北街道）と交差した。交通の十字路として宿場的な役割もあった。","義経の «大坂越え» が現在の大坂峠と同じ道かどうかは、はっきりしない。伝承として語られている。","«讃岐街道» という名前は各地にあり、伊予（愛媛）から讃岐へ向かう道も同じ名で呼ばれる。"],"look":["大坂峠からの播磨灘の眺め","大坂口御番所跡（案内板で確認）","旧街道の道標や地蔵","吉野川の徳命の渡しのあたり（藍住町）"],"q":["大坂峠の阿波側に置かれていた関所の名前は？","«大坂口御番所»。国を出入りする人や荷物を調べました。"],"koji":[{"w":"扇の的","m":"屋島の戦いで那須与一が、波にゆれる舟の上の扇を一矢で射落とした話"}],"myth":"義経の大坂越えのルートは伝承。番所の設置年は未確認。","img":["屋島の戦い","源義経"],"wp":"讃岐街道","rel":{"ev":[],"grave":[]},"ph":[["c:7/79/Hiramachi_-_panoramio_20250601_%283%29.jpg",4560,3040],["c:4/48/Battle_of_Yashima_Folding_Screens_Kano_School.jpg",10969,4896,"屋島の戦い"],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"]]},{"id":"36_kamikatsu","n":"上勝の山里（樫原の棚田と重文・田中家住宅）","yomi":"かみかつのやまざと","cat":"町","rank":"B","y":1685,"era":["edo","heisei"],"sh":"国の重要文化的景観（樫原の棚田及び農村景観）・国の重要文化財（田中家住宅）","ad":"勝浦郡上勝町生実（樫原）ほか","st":"JR徳島駅から車で約1時間。路線バスは本数が少なく、車でないと行きにくい","la":33.903,"lo":134.395,"hook":"200年前の絵図とほとんど同じ形の田んぼ。山の斜面に、江戸の村がそのまま生きている。","lead":"上勝町は徳島県の山あいにある、人口の少ない町です。樫原地区の棚田は、江戸時代の絵図とほとんど変わらない形で残り、国の重要文化的景観になっています。町には1685年に建てられた古い農家・田中家住宅（国の重要文化財）もあります。","story":["徳島市から勝浦川をさかのぼり、くねくねと山道をのぼっていくと、急な斜面に小さな田んぼが階段のように重なる景色が現れます。上勝町樫原の棚田です。標高は500〜700m。田んぼの数は546枚。一枚一枚は小さく、形もばらばら。等高線にそって、ゆるやかな曲線をえがいています。","«これは江戸時代と同じ形なの?» じつは、1813年に描かれた『勝浦郡樫原村分間絵図』という村の地図が残っています。それと今の棚田をくらべると、田んぼの配置や形がほとんど変わっていないのです。200年以上、村人たちが石を積み、土手を直し、水を引きつづけてきたからこそ、この景色は残りました。","棚田の一年は、春の水はりから始まります。山の上から引いた水を、上の田から下の田へ順に落としていく。一枚でも土手がくずれれば、下の田まで水がとどきません。だから村人たちは冬のあいだに石垣を積みなおし、畦を補修してきました。«田んぼは一人では守れない» 。棚田の景色は、村の協力のかたちそのものなのです。","上勝町には、もっと古い家もあります。田中家住宅は、1685年に建てられたと考えられる農家で、国の重要文化財です。寄棟造の屋根はもとは茅ぶき（今はトタンでおおわれています）。土間と二つの部屋が一列にならぶ、とても素朴な間取りです。300年以上前の山の暮らしが、家の形からそのまま伝わってきます。","けれども山里の暮らしは、いつも楽ではありません。若い人が町を出て、田んぼを守る人は少なくなっています。いっぽうで上勝町は、料理にそえる葉っぱを売る «葉っぱビジネス» や、ごみを出さない町づくり «ゼロ・ウェイスト» で、世界から注目されるようにもなりました。古い景色を守ることと、新しい知恵で生きること。上勝の山里は、その両方を見せてくれます。"],"tl":[["1685年","田中家住宅が建てられたとされる"],["1813年","『勝浦郡樫原村分間絵図』が描かれる"],["1976年","田中家住宅が国の重要文化財に指定"],["1999年","樫原の棚田が «日本の棚田百選» に選ばれる"],["2003年","上勝町が «ゼロ・ウェイスト宣言»"],["平成","«樫原の棚田及び農村景観» が国の重要文化的景観に選定"]],"who":[["樫原の村人たち","200年以上、棚田を守り続けてきた人びと"],["田中家","江戸時代前期から続く山村の農家"]],"deep":["«重要文化的景観» は、人が自然とかかわりながら作ってきた景色を守る制度。樫原は下樫原・中樫原・上樫原の三つの集落とあわせて選ばれた。","棚田の段差は、斜面を階段状に切った土手で作られ、ところどころ石積みで補強されている。畦は等高線にそってめぐらされている。","田中家住宅は «二間取り» の直屋で、四国山地の古い農家の姿を伝える例として評価されている。","樫原では棚田と同じ形の段々畑で、阿波晩茶やユコウ（かんきつ）も作られてきた。","上勝町は «日本で最も美しい村» 連合にも加盟している。"],"look":["樫原の棚田の全景（田植え後や稲刈り前が見ごろ）","棚田の石積みと曲線の畦","田中家住宅（公開状況は町に要確認）","山の斜面の段々畑と茶畑"],"q":["樫原の棚田とほとんど同じ形が描かれた、江戸時代の地図は何年のもの？","1813年の『勝浦郡樫原村分間絵図』です。"],"myth":"田中家住宅の詳しい所在地と公開状況、重要文化的景観の選定年は確認できていない。棚田百選の年は通説にもとづく。","img":["樫原の棚田","田中家住宅 (上勝町)"],"wp":"上勝町","rel":{"ev":[],"grave":[]},"ph":[["c:a/ae/Gecchozan_Jigenji_05.JPG",3872,2592,"上勝町"],["c:4/40/%E6%A3%9A%E7%94%B0_-_Tanada_-_Tokushima_Kamikatsu%2C_may_2011_%285767092654%29.jpg",2896,3861],["c:0/0b/%E6%A8%AA%E7%80%AC%E8%A5%BF%E5%81%9C%E7%95%99%E6%89%80%EF%BC%86%E7%94%BA%E5%96%B6%E3%83%90%E3%82%B9.JPG",3648,2736],["c:c/c9/Tsurugi-san_super_rindo.jpg",2576,1932],["c:f/f3/Kamikatsu_town_office.jpg",2464,1828],["c:d/dc/Kanjogataki.jpg",1536,2048],["c:c/ce/%E6%A8%AB%E5%8E%9F%E3%81%AE%E6%A3%9A%E7%94%B0.JPG",3648,2736,"樫原の棚田"]]},{"id":"36_tokushima_honsen","n":"徳島本線（明治の徳島鉄道が始まり）","yomi":"とくしまほんせん","cat":"近代","rank":"B","y":1899,"era":["meiji","taisho","showa"],"sh":"","ad":"徳島市寺島本町西（JR徳島駅）〜三好市池田町","st":"JR徳島駅（徳島線の列車はほぼすべて徳島駅発着）","la":34.0745,"lo":134.551,"hook":"藍と木材の吉野川に、民間の人びとが鉄の道をしいた。汽笛は1899年、徳島から鴨島へ向かって鳴った。","lead":"今のJR徳島線は、国鉄時代には «徳島本線» と呼ばれていました。始まりは、民間の会社・徳島鉄道が1899年に徳島〜鴨島間に開いた鉄道です。やがて国のものとなり、1914年に阿波池田までつながって、吉野川ぞいの町と徳島を結ぶ大動脈になりました。","story":["明治の徳島で、人や荷物を運ぶ主役は吉野川の舟でした。藍も木材も、川を下って運ばれます。けれど舟は川の水の量に左右され、上りは時間もかかります。«川にそって鉄の道を» ――そう考えた地元の人びとが作ったのが、民間の会社・徳島鉄道でした。","1899年2月16日、徳島〜鴨島間に最初の汽車が走りました。途中の駅は府中、石井、牛島。その年のうちに川島、さらに山崎へと線路はのび、翌1900年には船戸まで達します。吉野川の南岸の村々に、はじめて汽笛がひびきました。","1907年、国の方針で全国の大きな私鉄が買いとられ、徳島鉄道も国有になります。1913年には «徳島本線» と名前が変わり、翌1914年、ついに阿波池田まで線路がつながりました。さらに1913年には小松島港への鉄道もでき、大阪から船で来た人が汽車で吉野川の奥まで行けるようになったのです。","«なぜ «本線» だったのに今は «徳島線» なの?» 国鉄が民営化されてJR四国になったあと、1988年に «徳島線» に名前が変わり、«よしの川ブルーライン» という愛称もつきました。今は特急 «剣山» や、藍色の観光列車 «藍よしのがわトロッコ» が走っています。","その長い歴史の中には、悲しい事故もありました。1969年、下浦駅近くの踏切で急行 «よしの川» とダンプカーが衝突し、亡くなった人が出ています。安全への思いとともに、車窓の吉野川の景色を味わいたい路線です。"],"tl":[["1899年2月16日","徳島鉄道が徳島〜鴨島間を開業"],["1900年","船戸まで延伸"],["1907年9月1日","徳島鉄道が国有化される"],["1913年","線名を «徳島本線» に改称"],["1914年3月25日","川田〜阿波池田間が開通し、現在の区間が全通"],["1987年","国鉄分割民営化。JR四国の路線に"],["1988年","«徳島線» に改称"],["1996年","特急 «剣山» 運行開始"]],"who":[["徳島鉄道","徳島〜鴨島間を開いた民間の鉄道会社"],["吉野川ぞいの人びと","舟から汽車へ、移動と物流を変えた利用者"]],"deep":["徳島鉄道の開業時の駅は徳島・府中・石井・牛島・鴨島の5駅。","1914年の全通の際、川田〜船戸間は廃止され、ルートが付けかえられた。初代の «川田（かわだ）» 駅も廃止され、2代目は «川田（かわた）» と読む。","国鉄時代は佐古〜徳島間が高徳本線との重複区間だったが、民営化で高徳線に編入され、徳島線の起点・終点は書類上 «佃〜佐古» になった。","高度成長期には準急（のち急行）«阿佐» «よしの川» が小松島・徳島と高知を結び、関西からの船と接続していた。","«よしの川» は1999年に廃止されるまで、JR四国で最後まで残った定期急行列車だった。"],"look":["JR徳島駅（徳島線列車の実質的な起点）","鴨島駅（徳島鉄道の最初の終点）","車窓から見える吉野川と潜水橋","観光列車 «藍よしのがわトロッコ»（運行日は要確認）"],"q":["徳島鉄道が最初に開業した区間は？","1899年の徳島〜鴨島間です。"],"myth":"","img":["徳島線","徳島駅","鴨島駅","吉野川"],"wp":"徳島本線","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/JR%E5%9B%9B%E5%9B%BD3600%E7%B3%BB%E9%AE%8E%E5%96%B0%E2%86%92%E5%BA%9C%E4%B8%AD%E9%96%93.jpg",3648,2432,"徳島本線"],["c:e/ec/%E8%97%8D%E3%82%88%E3%81%97%E3%81%AE%E3%81%8C%E3%82%8F%E3%83%88%E3%83%AD%E3%83%83%E3%82%B3.jpg",5472,3648],["c:f/fe/%E7%89%B9%E6%80%A5_%E5%89%A3%E5%B1%B1.jpg",5472,3648],["c:5/56/JR_Shikoku_1502_and_Minoda_Bridge_20200718_1752_photo_by_Huminosato1019.jpg",5472,3648],["c:7/73/JRS_Kiha47-118.jpg",3675,2450],["c:2/2c/SL-shikoku-saburo.jpg",1464,1036],["c:5/51/Tokushima_JR_Sta_2020%2C9.jpg",4618,3464,"徳島駅"],["c:1/17/%E9%B4%A8%E5%B3%B6%E9%A7%85_%E9%A7%85%E8%88%8E%282026%E5%B9%B49%E6%9C%884%E6%97%A5%E6%92%AE%E5%BD%B1%EF%BC%89.jpg",4096,3072,"鴨島駅"]]}];
